void main() {
  runApp(const MolakhassatiApp());
}

const Color gold = Color(0xFFC5A66A);

class MolakhassatiApp extends StatelessWidget {
  const MolakhassatiApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: 'ملخصاتي',
      builder: (context, child) => Directionality(
        textDirection: TextDirection.rtl,
        child: child!,
      ),
      theme: ThemeData(
        useMaterial3: true,
        brightness: Brightness.dark,
        colorScheme: ColorScheme.fromSeed(
          seedColor: gold,
          brightness: Brightness.dark,
        ),
        scaffoldBackgroundColor: const Color(0xFF08090B),
        appBarTheme: const AppBarTheme(
          backgroundColor: Color(0xFF101114),
          centerTitle: true,
        ),
        cardTheme: CardThemeData(
          color: const Color(0xFF151619),
          elevation: 0,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
        ),
      ),
      home: const HomePage(),
    );
  }
}

class Section {
  final String title;
  final IconData icon;
  final String body;
  const Section(this.title, this.icon, this.body);
}

class Chapter {
  final String title;
  final List<Section> sections;
  const Chapter(this.title, this.sections);
}

const List<Chapter> chemistry = [
  Chapter('الفصل الأول: التركيب الذري للمادة', [
    Section('الملخص', Icons.notes, '''تطور النموذج الذري:
• دالتون: الذرة كرة صلبة غير قابلة للانقسام.
• ثومسون: كرة موجبة الشحنة تلتصق بها الإلكترونات السالبة، والذرة متعادلة.
• رذرفورد: البروتونات متمركزة في النواة (فيها معظم كتلة الذرة)، والإلكترونات تدور حولها، ومعظم حجم الذرة فراغ (النموذج الكوكبي).
• بور (1913): الإلكترونات تدور في مستويات طاقة محددة، لكل مستوى عدد كم رئيسي (n).
• النظرية الحديثة (نظرية الكم): يُحتمل وجود الإلكترون في حيز حول النواة يسمى الأوربيتال (السحابة الإلكترونية).

مستويات الطاقة الرئيسية:
• يرمز لها بالعدد n = 1، 2، 3، ... ولا يساوي صفراً أبداً.
• الرموز: K(1) L(2) M(3) N(4) O(5) P(6) Q(7).
• كلما زادت n زادت المسافة عن النواة وزادت الطاقة وقل الارتباط بالنواة.

مستويات الطاقة الثانوية:
• s: أوربيتال واحد كروي الشكل.
• p: ثلاثة أوربيتالات (px, py, pz) متعامدة.
• d: خمسة أوربيتالات، f: سبعة أوربيتالات.
• المستوى الرئيسي الثالث فيه 9 أوربيتالات.

الترتيب الإلكتروني:
• مبدأ أوفباو: تُملأ المستويات الثانوية من الأوطأ طاقة إلى الأعلى:
1s 2s 2p 3s 3p 4s 3d 4p 5s 4d 5p 6s 4f
• قاعدة هوند: لا يحدث ازدواج في المستوى الثانوي إلا بعد أن تشغل أوربيتالاته فرادى أولاً.
• عدد الإلكترونات = العدد الذري للذرة المتعادلة.
• المطلوب في الامتحان: العناصر التي عددها الذري لا يتجاوز 20.

رمز لويس:
• رمز العنصر محاطاً بنقاط تمثل إلكترونات غلاف التكافؤ (الغلاف الخارجي).
• لا يزيد عدد النقاط على 8، وتوضع في أربع جهات (نقطتان في كل جهة بحد أقصى).

الجدول الدوري:
• بلوك s: الزمرتان IA وIIA (عدا He).
• بلوك p: ست زمر (IIIA إلى VIIIA).
• بلوك d: العناصر الانتقالية في وسط الجدول.
• بلوك f: أسفل الجدول.
• العناصر الممثلة: عناصر بلوكي s وp.
• IA: الفلزات القلوية، IIA: فلزات الأتربة القلوية، VIIA: الهالوجينات، VIIIA (صفر): الغازات النبيلة.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• الذرة: الوحدة الأساسية لبناء المادة، ومعنى الكلمة (غير قابلة للانقسام).
• الأوربيتال (السحابة الإلكترونية): حيز حول النواة يُحتمل وجود الإلكترون فيه.
• غلاف التكافؤ: الغلاف الخارجي (المستوى الأخير) للذرة.
• إلكترونات التكافؤ: الإلكترونات الموجودة في مستويات الطاقة الخارجية.
• نصف القطر الذري: نصف المسافة بين نواتي ذرتين متماثلتين متحدتين كيميائياً.
• طاقة التأين: الطاقة اللازمة لنزع إلكترون واحد من المستوى الخارجي لذرة متعادلة في الحالة الغازية.
• الألفة الإلكترونية: قابلية الذرة المتعادلة في الحالة الغازية على اكتساب إلكترون واحد وتحرير طاقة.
• الكهرسلبية: قدرة الذرة على جذب إلكترونات التآصر نحوها في المركب.

التعاليل:
• فشل نموذج رذرفورد: لأن الإلكترون المتحرك يفقد طاقته تدريجياً فيتحرك لولبياً ويسقط في النواة فتنهار الذرة، والذرات لا تنهار.
• فشل نموذج بور: فسّر ذرة الهيدروجين فقط ولم يفسّر العناصر التي فيها إلكترونات أكثر.
• يقل نصف القطر في الدورة من اليسار لليمين: لزيادة قوة جذب النواة للإلكترونات بزيادة العدد الذري.
• يزداد نصف القطر في الزمرة من الأعلى للأسفل: لابتعاد الإلكترونات الخارجية عن النواة.
• تقل طاقة التأين في الزمرة للأسفل: لابتعاد الإلكترونات الخارجية عن النواة فيسهل فقدانها.
• تزداد طاقة التأين في الدورة: لزيادة الشحنة الموجبة للنواة مع بقاء الإلكترونات في المستوى نفسه.
• طاقة تأين N أكبر من O: لأن N مستواه الثانوي نصف مشبع (2p³).
• للغازات النبيلة أعلى طاقة تأين: لأنها لا تفقد إلكتروناتها بسهولة.
• للغازات النبيلة أقل ألفة إلكترونية: لصعوبة إضافة إلكترونات إليها.
• الفلور أعلى العناصر كهرسلبية (قيمتها 4): لصغر حجمه وقوة جذبه للإلكترونات.'''),
    Section('المسائل والأمثلة', Icons.calculate, '''الدورة والزمرة من الترتيب الإلكتروني:
• رقم الدورة = رقم آخر مستوى رئيسي.
• رقم الزمرة = إلكترونات آخر مستوى ثانوي (p أو s) + إلكترونات s التي قبله في المستوى نفسه.

أمثلة:
• 8O: 1s² 2s² 2p⁴ ← الدورة 2، الزمرة (4+2) = VIA.
• 17Cl: 1s² 2s² 2p⁶ 3s² 3p⁵ ← الدورة 3، الزمرة (5+2) = VIIA.
• 10Ne: 1s² 2s² 2p⁶ ← الدورة 2، الزمرة (6+2) = VIIIA (صفر).
• 19K: ينتهي بـ 4s¹ ← الدورة 4، الزمرة IA.

الترتيب الإلكتروني:
• 5B: 1s² 2s² 2p¹
• 8O: 1s² 2s² 2p⁴
• 10Ne: 1s² 2s² 2p⁶
• 12Mg: 1s² 2s² 2p⁶ 3s²
• 13Al: 1s² 2s² 2p⁶ 3s² 3p¹
• 15P: 1s² 2s² 2p⁶ 3s² 3p³
• 11Na: 1s² 2s² 2p⁶ 3s¹

عدد الإلكترونات (إلكترونات التكافؤ) ورمز لويس:
• H: 1 ، B: 3 ، Si: 4 ، Mg: 2 ، Ne: 8

أمثلة على المقارنة:
• Li وNa في زمرة واحدة (IA)، وNa وMg في دورة واحدة (الثالثة).
• Be وB وN في دورة واحدة (الثانية) لكن في زمر مختلفة.
• ترتيب نصف القطر في الدورة الثانية: Li > C > O > F

تدرج الخواص الدورية:
• نصف القطر: في الدورة يقل ←، وفي الزمرة يزداد ↓
• طاقة التأين: في الدورة تزداد ←، وفي الزمرة تقل ↓
• الكهرسلبية: في الدورة تزداد ←، وفي الزمرة تقل ↓
• الخواص الفلزية: في الدورة تقل ←، وفي الزمرة تزداد ↓
• الخواص اللافلزية: عكس الفلزية.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها (من أسئلة الفصل):
• مستوى الطاقة الرئيسي الثاني يتسع لـ 8 إلكترونات.
• المستوى الثانوي f فيه 7 أوربيتالات.
• المستوى الرئيسي الثالث فيه 9 أوربيتالات.
• ذرة ترتيبها 1s² 2s² 2p³ عددها الذري 7.
• ذرة تنتهي بـ 3s¹ عددها الذري 11.
• ذرة تنتهي بـ 2p⁵ تقع في الزمرة السابعة، الدورة الثانية.
• عنصر في الزمرة الخامسة والدورة الثالثة ينتهي بـ 3p³.
• عناصر بلوك d تقع في وسط الجدول، وبلوك p يمين الجدول.
• الهالوجينات: عناصر الزمرة VIIA.
• ينسب اكتشاف النواة إلى العالم رذرفورد.
• الطاقة اللازمة لنزع إلكترون من ذرة تسمى طاقة التأين.
• أعلى كهرسلبية: الفلور.
• رمز لويس للأرغون Ar: ثماني نقاط حول الرمز.

أسئلة للمراجعة:
1) اذكر تصور نموذج رذرفورد للبناء الذري ثم بيّن لماذا فشل.
2) ما مفهوم السحابة الإلكترونية؟
3) اكتب الترتيب الإلكتروني لـ 18Ar و14Si و9F.
4) ما الدورة والزمرة لكل من 13Al و6C و3Li؟
5) رتّب حسب زيادة نصف القطر: Mg, Ca, Be.
6) اكتب رمز لويس لـ 20Ca و18Ar و13Al.
7) عرّف طاقة التأين والألفة الإلكترونية والكهرسلبية.
8) اذكر مبدأ أوفباو وقاعدة هوند.'''),
  ]),
  Chapter('الفصل الثاني: الزمرتان الأولى والثانية (الصوديوم والكالسيوم)', [
    Section('الملخص', Icons.notes, '''عناصر الزمرتين:
• الزمرة IA (الفلزات القلوية): Li, Na, K, Rb, Cs, Fr. الفرانسيوم هو الفلز الوحيد فيها الذي يحضَّر صناعياً.
• الزمرة IIA (فلزات الأتربة القلوية): Be, Mg, Ca, Sr, Ba, Ra.
• تقعان في الطرف الأيسر من الجدول الدوري.

الصفات العامة:
• كهرسلبية واطئة وطاقة تأين واطئة.
• الغلاف الخارجي فيه إلكترون واحد (IA) أو إلكترونان (IIA).
• لا توجد حرة في الطبيعة لشدة فعاليتها.
• عناصر IIA أقل فلزية من IA، وطاقة تأينها أعلى بسبب نقصان الحجم الذري.
• تتناقص درجات الانصهار والغليان مع زيادة العدد الذري.
• كثافة Li وNa وK أقل من كثافة الماء.
• تفقد إلكترونات التكافؤ فتكوّن أيونات موجبة: M⁺ (IA) وM²⁺ (IIA).
• تتحد مع اللافلزات وتعطي أملاحاً مستقرة كثيرة الذوبان في الماء عدا الليثيوم (أقل ذوبانية لصغر حجمه).
• عوامل مختزلة قوية (تفقد إلكترونات التكافؤ بسهولة).
• محلول تفاعل الفلز مع الماء قاعدي (قلوي).

كشف اللهب (الكشف الجاف):
• الليثيوم: قرمزي.
• الصوديوم: أصفر براق (ذهبي).
• الكالسيوم: أحمر طابوقي.
• السترونتيوم: قرمزي.
• الباريوم: أخضر مصفر.

الصوديوم Na (العدد الذري 11، العدد الكتلي 23، الترتيب 2, 8, 1):
• لا يوجد حراً بل متحداً: كلوريد الصوديوم، كبريتات، سليكات.
• يُحفظ في النفط الأبيض (الكيروسين) أو البنزين النقي.
• فلز لين، بريقه فضي عند القطع حديثاً، كثافته أقل من الماء.
• ينصهر عند 97.81 °م ويغلي عند 882.9 °م.
• يستعمل: عامل مختزل قوي في بعض التفاعلات العضوية، إنتاج سيانيد الصوديوم لتنقية الذهب، التخلص من أوكسجين الهواء في عمليات التعدين.
• الكشف عنه: كشف اللهب (لون أصفر).

كلوريد الصوديوم NaCl (ملح الطعام):
• أكثر مركبات الصوديوم انتشاراً: صخور ملحية، ترسبات تحت الأرض، مياه البحار والبحيرات.
• استخراجه: من الترسبات بحفر آبار يُضخ إليها الماء ثم يُسحب المحلول ويُبخَّر. ومن ماء البحر بتبخيره في أحواض ضحلة بحرارة الشمس (مالحات الفاو في جنوب العراق).
• استعمالاته: تحضير كاربونات الصوديوم (صودا الغسيل) وهيدروكسيد الصوديوم وغاز الكلور، حفظ الأغذية (اللحوم والأسماك)، دباغة الجلود، صناعة الثلج للتبريد، تثبيت الأصباغ.
• NaCl مركب أيوني ولا يصح تسميته جزيئاً.

هيدروكسيد الصوديوم NaOH:
• صلب يتميأ في الهواء الرطب.
• قاعدة كثيرة الذوبان في الماء.
• يُستعمل في صناعة الصابون والمنظفات والنسيج والورق، ومادة أولية لتحضير مركبات صناعية.

الكالسيوم Ca (العدد الذري 20، العدد الكتلي 40، الترتيب 2, 8, 8, 2):
• لا يوجد حراً، بل: كاربونات (المرمر، حجر الكلس)، كبريتات (الجبس)، فوسفات، سليكات.
• يُستخلص بالتحليل الكهربائي لمنصهر كلوريد وفلوريد الكالسيوم.
• يدخل في تركيب الحليب والأسماك.

مركبات الكالسيوم:
• هيدروكسيد الكالسيوم Ca(OH)₂ (الجير المطفأ)، ومحلوله الصافي يسمى ماء الكلس.
• الجير الحي (النورة): CaO.
• الجبس: CaSO₄·2H₂O. جبس باريس: (CaSO₄)₂·H₂O يُستعمل في التجبير وصنع التماثيل والبناء.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• التميؤ: امتصاص المادة للرطوبة من الجو وتحولها إلى مادة مبتلة.
• إطفاء الجير: إضافة الماء إلى أوكسيد الكالسيوم (CaO) لتكوين هيدروكسيد الكالسيوم.
• ماء التبلور: جزيئات الماء المرتبطة بكبريتات الكالسيوم في الجبس (جزيئان).
• ماء الكلس الصافي: المحلول المائي الصافي لهيدروكسيد الكالسيوم.

التعاليل:
• لا توجد عناصر الزمرتين حرة في الطبيعة: لشدة فعاليتها.
• يُحفظ الصوديوم في النفط: لأنه يشتعل عند تعرضه للهواء ولا يتفاعل معه.
• يفقد قطع الصوديوم الحديث القطع بريقه بعد فترة: لاتحاده مع أوكسجين الهواء الرطب وتكوّن طبقة بيضاء.
• سميت عناصر IA بالفلزات القلوية: لأن محاليلها عالية القاعدية.
• سميت عناصر IIA بفلزات الأتربة القلوية: لأن بعض أكاسيدها عُرفت بالأتربة القلوية.
• الليثيوم أقل ذوبانية في أملاحه: لصغر حجمه وقوة جذب النواة لإلكتروناته.
• وضع Li وNa وK في زمرة واحدة: لأن لها إلكتروناً واحداً في الغلاف الخارجي رغم اختلاف أعدادها الذرية.
• يتميأ ملح الطعام العادي: لاحتوائه على شوائب من كلوريد الكالسيوم أو كلوريد المغنيسيوم.
• NaCl النقي لا يتميأ ولا يمتص الماء من الجو.
• عند ترك NaOH في الجو الرطب يتميأ أولاً ثم تتكون قشرة جافة: لتفاعل الطبقة المتميئة مع CO₂ وتكوّن Na₂CO₃ الذي لا يذوب في NaOH المركز.
• يكون الباريوم أكثر فلزية من البريليوم: لأن نصف قطره أكبر وكهرسلبيته أقل.
• البوتاسيوم أنشط من الليثيوم: لأن نصف قطر ذرته أكبر فيسهل فقدان إلكترون التكافؤ.
• يسهل انتزاع إلكتروني التكافؤ من الكالسيوم: لبعدهما عن النواة وقلة طاقة التأين.
• لا ينتمي الألمنيوم (13) إلى الزمرة الأولى: لأن غلافه الخارجي فيه 3 إلكترونات (2, 8, 3) وليس إلكتروناً واحداً.
• تعكر ماء الكلس عند إمرار CO₂: لتكوّن كاربونات الكالسيوم (راسب أبيض).
• استمرار إمرار CO₂ في ماء الكلس العكر يجعله صافياً: لتكوّن Ca(HCO₃)₂ كثير الذوبان في الماء.
• يُحفظ اللحم والسمك بالملح: لأن محلوله المركز يقتل البكتريا المسببة للتعفن.'''),
    Section('المسائل والمعادلات', Icons.calculate, '''تفاعلات الصوديوم:
• مع الأوكسجين: يزول بريقه ويكتسي بطبقة بيضاء.
• مع الكلور: 2Na + Cl₂ → 2NaCl
• مع الماء: 2Na + 2H₂O → 2NaOH + H₂↑
• مع الحوامض: 2Na + 2HCl → 2NaCl + H₂↑
• مع الأكاسيد: 2Na + MgO → Na₂O + Mg
• مع الكلوريدات: 3Na + AlCl₃ → 3NaCl + Al

تفاعل NaOH مع CO₂ في الهواء:
2NaOH + CO₂ → Na₂CO₃ + H₂O

مركبات الكالسيوم:
• إطفاء الجير: CaO + H₂O → Ca(OH)₂
• تعكر ماء الكلس: Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O
• زوال التعكر باستمرار إمرار CO₂: ينتج Ca(HCO₃)₂ الذائب.
• الجبس وجبس باريس (تفاعل انعكاسي):
2(CaSO₄·2H₂O) ⇌ (CaSO₄)₂·H₂O + 3H₂O
(تسخين الجبس ينتج جبس باريس، وعجينة باريس تلتقط الماء فتعود جبساً متجمداً مع تمدد في الحجم.)

ترتيب الصوديوم والكالسيوم:
• Na: 2, 8, 1 ← يكوّن Na⁺ بفقد إلكترون واحد.
• Ca: 2, 8, 8, 2 ← يكوّن Ca²⁺ بفقد إلكترونين.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• من عناصر الزمرة الأولى: الصوديوم.
• عنصر Mg تكافؤه في مركباته 2.
• ذرة الليثيوم عند فقدها إلكترون التكافؤ تتحول إلى أيون أحادي الشحنة الموجبة.
• البوتاسيوم أكثر فعالية من الليثيوم: لأن نصف قطر ذرته أكبر.

أسئلة للمراجعة:
1) اذكر الفرق بين الجبس الاعتيادي وجبس باريس.
2) لكلوريد الصوديوم أهمية صناعية كبرى، اذكر ثلاث فوائد له.
3) علل: الباريوم أكثر فلزية من البريليوم.
4) علل: لا ينتمي الألمنيوم 13Al إلى الزمرة الأولى.
5) علل: عند ترك حبيبات NaOH في الجو الرطب تتميأ أولاً ثم تتكون عليها قشرة صلبة.
6) علل: يحفظ الصوديوم في النفط.
7) علل: سميت عناصر الزمرة الأولى بالفلزات القلوية.
8) علل: اختفاء لمعان قطعة الصوديوم المقطوعة حديثاً بعد فترة.
9) وضح علمياً: سهولة انتزاع إلكتروني التكافؤ من الكالسيوم.
10) وضح لماذا وُضع Li وNa وK في زمرة واحدة رغم اختلاف أعدادها الذرية.
11) ما الفرق بين كلوريد الصوديوم النقي وغير النقي؟
12) ما لون اللهب لمركبات: Li, Na, Ca, Sr, Ba؟'''),
  ]),
  Chapter('الفصل الثالث: الزمرة الثالثة (الألمنيوم ومركباته)', [
    Section('الملخص', Icons.notes, '''عناصر الزمرة IIIA:
• البورون B (شبه فلز)، الألمنيوم Al، الكاليوم Ga، الإنديوم In، الثاليوم Tl (فلزات).
• وُضعت في زمرة واحدة لأن غلافها الخارجي يحتوي على 3 إلكترونات رغم اختلاف أعدادها الذرية.

الصفات العامة:
• جميع عناصرها فلزات عدا البورون فهو شبه فلز.
• طاقة تأينها أقل من طاقة تأين عناصر الزمرة الثانية، لأن إلكترونها الأخير في مستوى p بعد مستوى ثانوي مشبع (ns²) بينما غلاف الزمرة الثانية الخارجي هو ns² المشبع.
• تقل طاقة التأين عموماً من الأعلى للأسفل بسبب كبر حجوم الذرات.
• الحالة التأكسدية المتوقعة (+3) إضافة إلى حالات أخرى.
• تزداد الصفة القاعدية لأكاسيدها وهيدروكسيداتها وتقل الصفة الحامضية بزيادة العدد الذري: أكسيد البورون حامضي، أكسيد الألمنيوم أمفوتيري، وأكاسيد بقية العناصر قاعدية.

الألمنيوم Al (العدد الذري 13، العدد الكتلي 27، الترتيب 2, 8, 3):
• لا يوجد حراً لأنه فلز فعال.
• أوسع الفلزات انتشاراً في القشرة الأرضية، يلي الأوكسجين (46%) والسليكون (28%) ويؤلف نحو 8% من القشرة.
• الخام الرئيس: البوكسايت Al₂O₃·2H₂O (أوكسيد الألمنيوم المائي).
• مصدر مهم آخر: الكريوليت Na₃AlF₆ (فلوريد مزدوج من الصوديوم والألمنيوم).

استخلاصه (طريقة هول):
• يُنقى البوكسايت كيميائياً للحصول على الألومينا Al₂O₃ النقية.
• الألومينا لها درجة انصهار عالية، فتُذاب في منصهر الكريوليت الذي يخفض درجة انصهارها.
• يوضع المنصهر في خلية تحليل كهربائي بدرجة حرارة نحو 1000 °م وأقطاب من الكاربون.
• عند مرور التيار الكهربائي يتجمع الألمنيوم منصهراً في أسفل الخلية ويُسحب بين مدة وأخرى.

الخواص الفيزيائية:
• فلز فضي المظهر، جيد التوصيل للحرارة والكهرباء، قليل الكثافة.

الخواص الكيميائية:
• يتأكسد سطحه الخارجي فقط في الهواء فتتكون طبقة رقيقة جداً من أوكسيده شديدة الالتصاق تحمي الفلز من التآكل.
• مسحوقه يحترق بشدة ولهب ساطع محرراً طاقة عالية.
• عامل مختزل قوي (تفاعل الثرميت).
• يتفاعل مع HCl المخفف ويحرر H₂.
• لا يستمر تفاعله مع حامض النتريك المخفف أو المركز لتكوّن طبقة Al₂O₃ تعزل الحامض عن الفلز، فيُحفظ حامض النتريك وينقل في أوانٍ من الألمنيوم.
• يتفاعل مع محاليل القواعد (NaOH أو KOH) محرراً H₂، وهذا السلوك الأمفوتيري.

استعمالات الألمنيوم:
• أسلاك كهربائية (ضمن نطاق محدود)، صفائح لتغليف الأطعمة والأدوية والسكائر، قناني معدنية.
• أواني وقدور وملاعق (سبيكة الفافون)، شبابيك، مرايا التلسكوبات.
• هياكل الطائرات والقطارات الخفيفة وأجزاء السيارات.
• لحيم قضبان السكك الحديدية (الثرميت).
• استخلاص بعض الفلزات من أكاسيدها (عامل مختزل).

سبائك الألمنيوم:
• الديورالومين: نسبة عالية من الألمنيوم ونسبة قليلة من النحاس والمغنيسيوم (وقد يحتوي المنغنيز)، خفيفة وصلبة، تُستعمل في بناء بعض أجزاء الطائرات.
• برونز الألمنيوم: نسبة قليلة من الألمنيوم ونسبة عالية من النحاس، تقاوم التآكل، ويتغير لونها بتغير النسب من لون النحاس إلى الذهبي ثم الفضي، تُستعمل في أدوات الزينة.

مركبات الألمنيوم:
• هيدروكسيد الألمنيوم Al(OH)₃: مادة جيلاتينية بيضاء لا تذوب في الماء.
• أوكسيد الألمنيوم Al₂O₃: يوجد في الطبيعة غير نقي (يُستعمل في صقل المعادن وتلميعها) ويدخل في تركيب الأحجار الكريمة.
• الشب KAl(SO₄)₂·12H₂O (شب البوتاس): استعمالاته تعقيم الجروح الخفيفة (يساعد على تخثر الدم)، تثبيت الأصباغ على الأقمشة، تصفية مياه الشرب.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• السلوك الأمفوتيري: تفاعل المادة مع الحوامض والقواعد معاً.
• تفاعل الثرميت: تفاعل الألمنيوم مع أوكسيد الحديد (III) لإنتاج الحديد المنصهر وطاقة حرارية عالية.
• الشب: ملح مزدوج من كبريتات الألمنيوم وكبريتات البوتاسيوم مع ماء التبلور.
• الألومينا: أوكسيد الألمنيوم النقي Al₂O₃.
• البوكسايت: الخام الرئيس للألمنيوم Al₂O₃·2H₂O.
• الكريوليت: Na₃AlF₆، يخفض درجة انصهار الألومينا.

التعاليل:
• لا يوجد الألمنيوم حراً في الطبيعة: لأنه من الفلزات الفعالة.
• الألمنيوم لا يتآكل مثل الحديد: لتكوّن طبقة رقيقة صلدة من Al₂O₃ شديدة الالتصاق تمنع وصول الهواء إلى الفلز، بينما صدأ الحديد هش يتفتت فيسمح باستمرار التآكل.
• يُحفظ حامض النتريك في أوانٍ من الألمنيوم: لأن طبقة Al₂O₃ تعزل الحامض عن الفلز فيتوقف التفاعل.
• تُذاب الألومينا في الكريوليت: لأن الكريوليت يخفض درجة انصهار الألومينا العالية.
• لا تُصنع الأسلاك الكهربائية من الألمنيوم إلا ضمن نطاق محدود: لأنه أكثر تمدداً وتقلصاً من النحاس (بنسبة 39%).
• يتفاعل الألمنيوم مع الحوامض والقواعد: لأن سلوكه أمفوتيري.
• يذوب راسب Al(OH)₃ بإضافة زيادة من NaOH أو بإضافة حامض: بسبب السلوك الأمفوتيري.
• يُستعمل الشب في تعقيم الجروح: لأنه يرسّب Al(OH)₃ على الجرح فيوقف النزف.
• لا ينتمي Mg (12) إلى الزمرة الثالثة: لأن غلافه الخارجي فيه إلكترونان وليس ثلاثة.
• عناصر الزمرة الثالثة طاقة تأينها أقل من الثانية: لأن إلكترونها الأخير في مستوى p بعد مستوى ثانوي مشبع.'''),
    Section('المسائل والمعادلات', Icons.calculate, '''احتراق الألمنيوم:
4Al + 3O₂ → 2Al₂O₃ + طاقة

تفاعل الثرميت (Al عامل مختزل):
2Al + Fe₂O₃ → Al₂O₃ + 2Fe + طاقة حرارية عالية

مع حامض HCl المخفف:
2Al + 6HCl → 2AlCl₃ + 3H₂↑

مع القواعد (NaOH): يتحرر H₂ ويتكون ملح الألمنيوم.

تحضير هيدروكسيد الألمنيوم:
Al₂(SO₄)₃ + 6NaOH → 2Al(OH)₃↓ + 3Na₂SO₄

تحضير أوكسيد الألمنيوم (تسخين شديد):
2Al(OH)₃ → Al₂O₃ + 3H₂O

الكشف عن أيون Al³⁺:
• يُضاف محلول قاعدي (NaOH أو KOH) فيتكون راسب أبيض جيلاتيني هو Al(OH)₃.
• AlCl₃ + 3NaOH → Al(OH)₃↓ + 3NaCl
• يذوب الراسب بإضافة زيادة من NaOH (لتكوّن ألومينات الصوديوم الذائبة) أو بإضافة حامض.

صيغة الشب: KAl(SO₄)₂·12H₂O

الترتيب الإلكتروني: Al: 2, 8, 3 ← يكوّن Al³⁺ بفقد ثلاثة إلكترونات.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• الكاليوم Ga ينتمي إلى الزمرة الثالثة.
• الألمنيوم في عملية الثرميت يعمل عاملاً مختزلاً.
• سبيكة برونز الألمنيوم تحتوي نسبة قليلة من الألمنيوم.
• التسخين الشديد لهيدروكسيد الألمنيوم يعطي: Al₂O₃ وH₂O.
• ملح مكون من البوتاسيوم والألمنيوم يسمى الشب.
• تفاعل الألمنيوم مع الحوامض والقواعد يسمى السلوك الأمفوتيري.
• عند تفاعل Al مع الحوامض والقواعد يتحرر غاز الهيدروجين.
• من 5B, 12Mg, 13Al, 31Ga: العنصر الذي لا ينتمي للزمرة الثالثة هو Mg لأن له إلكترونين في الغلاف الخارجي.
• مطابقة: (1) الألمنيوم ← عنصر ذو سلوك أمفوتيري، (2) الثرميت ← تفاعل يسلك فيه Al عاملاً مختزلاً، (3) الألومينا ← أوكسيد الألمنيوم، (4) الشب ← ملح مزدوج من كبريتات البوتاسيوم والألمنيوم، (5) البورون ← عنصر شبه فلز.

أسئلة للمراجعة:
1) كيف يُستخلص الألمنيوم؟ (طريقة هول، مع رسم الخلية وتأشير أجزائها).
2) قارن بين عملية تأكسد الألمنيوم والحديد بتأثير الجو.
3) علل: لا يتآكل الألمنيوم كالحديد.
4) اذكر ثلاثة استعمالات للألمنيوم.
5) ما الفرق بين الديورالومين وبرونز الألمنيوم؟
6) كيف تكشف عن أيون الألمنيوم في محاليل مركباته؟
7) ما استعمالات الشب؟
8) قارن بين طاقتي تأين عنصر من الزمرة الثالثة والعنصر المجاور له من الزمرة الثانية.'''),
  ]),
  Chapter('الفصل الرابع: المحاليل والتعبير عن التركيز', [
    Section('الملخص', Icons.notes, '''المحلول:
• خليط متجانس من مادتين أو أكثر لا يحدث بينها تفاعل كيميائي.
• المذيب: المادة الموجودة بوفرة. المذاب: المادة الموجودة بقلة.
• محلول = مذيب + مذاب.

أنواع المحاليل:
• سائل في سائل: الكحول في الماء.
• صلب في سائل: ملح الطعام في الماء، NaOH في الماء (قاعدي).
• غاز في سائل: HCl في الماء (حامض الهيدروكلوريك، محلول حامضي).
• غاز في غاز: الهواء الجوي.
• صلب في صلب: السبائك، قطع النقود المعدنية.

طبيعة المحاليل:
• مشبع: يحتوي أكبر قدر ممكن من المذاب، والمذيب لا يذيب زيادة منه عند درجة حرارة وضغط محددين.
• غير مشبع: يحتوي مذاباً أقل من الكمية اللازمة للتشبع.
• فوق المشبع: كمية المذاب فيه أكبر مما يمكن للمذيب إذابته، وهو غير ثابت ويلفظ الزائد راسباً فيصير مشبعاً.

المحلول الإلكتروليتي:
• إلكتروليت قوي: تتأين جزيئاته تأيناً تاماً (مثل HCl).
• إلكتروليت ضعيف: تتأين جزيئاته جزئياً وتكون الأيونات في حالة توازن مع الجزيئات (مثل HF).
• غير إلكتروليتي: لا تتأين جزيئاته مطلقاً (السكر، الكحول الإثيلي).

قابلية الذوبان:
• أكبر كمية من المادة المذابة يمكن أن تذوب في حجم ثابت من مذيب معين لتكوين محلول مشبع عند درجة حرارة معينة.
• العوامل المؤثرة:
1) طبيعة المذاب والمذيب: المذيب القطبي يذيب المذاب القطبي (الشبيه يذيب شبيهه)، وكلما زاد سطح المذاب المعرض للمذيب زادت سرعة الذوبان (التحريك، مسحوق السكر أسرع من الحبيبات).
2) درجة الحرارة: ترتفع سرعة الذوبان بارتفاعها.
3) الضغط: يؤثر في المواد الغازية، وتزداد ذوبانيتها بزيادة الضغط.

التركيز:
• كمية المذاب في كمية معينة من المذيب أو المحلول.
• وصفياً: مخفف (مذاب قليل نسبياً) ومركز (مذاب كثير). يُحوَّل المركز إلى مخفف بإضافة مذيب.

طرائق التعبير عن التركيز:
1) النسبة المئوية الكتلية = (كتلة المكون ÷ كتلة المحلول) × 100
2) النسبة المئوية الحجمية = (حجم المكون ÷ حجم المحلول) × 100
3) التركيز بالكتلة/الحجم (غ/لتر) = كتلة المذاب (غ) ÷ حجم المحلول (لتر)

مفاتيح الرموز:
• m₁ كتلة المذاب، m₂ كتلة المذيب، mT كتلة المحلول = m₁ + m₂
• V₁ حجم المذاب، V₂ حجم المذيب، VT حجم المحلول = V₁ + V₂
• التحويل: 1 لتر = 1000 مل = 1000 سم³، و1 مل = 1 سم³
• الكثافة ρ = الكتلة ÷ الحجم (ماء: 1 غ/مل)'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• المحلول: خليط متجانس من مادتين أو أكثر لا يحدث بينها تفاعل كيميائي.
• المحلول المشبع: محلول يحتوي أكبر قدر ممكن من المذاب ولا يذيب المذيب زيادة منه عند درجة حرارة وضغط محددين.
• المحلول فوق المشبع: كمية المذاب فيه تفوق ما يمكن للمذيب إذابته في الظروف الاعتيادية، وهو غير ثابت.
• المحلول غير المشبع: يحتوي مذاباً أقل من الكمية اللازمة للتشبع.
• قابلية الذوبان: أكبر كمية من المادة المذابة يمكن أن تذوب في حجم ثابت من مذيب معين للحصول على محلول مشبع عند درجة حرارة معينة.
• المحلول الإلكتروليتي: محلول تتأين فيه جزيئات المذاب.
• المحلول المركز: يحتوي كمية كبيرة من المذاب. المخفف: كمية قليلة نسبياً.
• التركيز: كمية المادة المذابة في كمية معينة من المذيب أو المحلول.
• النسبة المئوية الكتلية: عدد غرامات المذاب في مئة غرام من المحلول.
• النسبة المئوية الحجمية: نسبة حجم المكون إلى الحجم الكلي للمحلول × 100.

الفرق بين:
• المحلول المخفف والمركز: المخفف مذابه قليل، والمركز مذابه كثير.
• المذاب الإلكتروليتي القوي والضعيف: القوي يتأين تأيناً تاماً، والضعيف جزئياً.
• فوق المشبع وغير المشبع: فوق المشبع فيه مذاب أكثر من قابلية الذوبان وغير ثابت، وغير المشبع فيه أقل من اللازم للتشبع.

التعاليل:
• يُحرَّك قدح الشاي بعد وضع السكر: لأن الذوبان ظاهرة تتعلق بالسطح المعرض للذوبان، والتحريك يزيد ملامسة المذيب للمذاب.
• مسحوق السكر يذوب أسرع من حبيباته: لأن سطحه المعرض للمذيب أكبر.
• يذوب السكر في الماء الساخن أسرع منه في البارد: لأن طاقة حركة جزيئات الماء تزداد عند ارتفاع الحرارة فتزداد تصادماتها بالبلورات.
• تقل ذوبانية CO₂ عند فتح قنينة المشروب الغازي: لأن الضغط ينخفض فيتصاعد الغاز على شكل فقاعات.
• تزداد ذوبانية الغاز بزيادة الضغط: لأن الضغط الجزئي للغاز فوق سطح المحلول يزداد.'''),
    Section('المسائل والمعادلات', Icons.calculate, '''القوانين:
• النسبة الكتلية للمذاب = (m₁ ÷ mT) × 100
• النسبة الكتلية للمذيب = (m₂ ÷ mT) × 100
• mT = m₁ + m₂
• النسبة الحجمية للمذاب = (V₁ ÷ VT) × 100
• التركيز (غ/لتر) = m ÷ V
• الكثافة: m = ρ × V

أمثلة محلولة من الكتاب:

1) 15.3 غ ملح طعام في 155 غ ماء:
mT = 15.3 + 155 = 170.3 غ
النسبة الكتلية للمذاب = (15.3 ÷ 170.3) × 100 = 8.98%
النسبة الكتلية للمذيب = (155 ÷ 170.3) × 100 = 91.02%

2) خل نسبته الكتلية 4% حامض خليك، كم نحتاج منه للحصول على 20 غ حامض؟
4% = (20 ÷ mT) × 100 ← mT = 2000 ÷ 4 = 500 غ

3) 20 مل حامض خليك + 30 مل ماء:
VT = 50 مل
النسبة الحجمية للمذاب = (20 ÷ 50) × 100 = 40%
النسبة الحجمية للمذيب = (30 ÷ 50) × 100 = 60%

4) حجم كحول إثيلي لتكون نسبته 40% في محلول حجمه 50 مل:
(V₁ ÷ 50) × 100 = 40 ← V₁ = 20 مل

5) 5 غ كبريتات النحاس في 0.5 لتر ماء:
التركيز = 5 ÷ 0.5 = 10 غ/لتر

6) 27.5 غ كحول مثيلي + 175 مل ماء (كثافة الماء 1 غ/مل):
كتلة الماء = 1 × 175 = 175 غ
mT = 27.5 + 175 = 202.5 غ
النسبة الكتلية للكحول = (27.5 ÷ 202.5) × 100 = 13.6%

تمارين الكتاب:
• 48.2 غ سكر في 498 غ ماء: mT = 546.2 غ، نسبة السكر = (48.2 ÷ 546.2) × 100 ≈ 8.8%.
• 20 غ HCl في 80 غ ماء: النسبة الكتلية لـ HCl = 20%، للماء = 80%.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• محلول صلب في صلب: قطعة نقدية.
• المذاب الإلكتروليتي الضعيف: الذي يتأين بدرجة غير كاملة في المذيب.
• السكر في الماء الساخن يذوب أسرع: لأن طاقة حركة جزيئات الماء تزداد عند ارتفاع الحرارة.
• لتحويل محلول مركز إلى مخفف: نضيف مذيباً أكثر.
• 5 غ كبريتات نحاس في 20 غ ماء: mT = 25 غ، النسبة الكتلية للمذاب = 20% وللمذيب = 80%.
• حجم الماء لإذابة 10 غ KOH للحصول على تركيز 2.5 غ/لتر: V = 10 ÷ 2.5 = 4 لتر.
• 25 مل HCl + 75 مل ماء: VT = 100 مل، النسبة الحجمية للحامض = 25% وللماء = 75%.
• 15.3 غ NaCl في 155.09 غ ماء: النسبة الكتلية لـ NaCl = (15.3 ÷ 170.39) × 100 ≈ 8.98%.

أسئلة للمراجعة:
1) بيّن بإيجاز المقصود بـ: المحلول، المحلول المشبع، قابلية الذوبان، المحلول الإلكتروليتي، المحلول المركز، التركيز بالنسبة المئوية الكتلية، التركيز بالنسبة المئوية الحجمية.
2) ما الفرق بين محلول مخفف ومركز؟
3) ما الفرق بين مذاب إلكتروليتي ضعيف وقوي؟
4) ما الفرق بين محلول فوق مشبع وغير مشبع؟
5) ما العوامل المؤثرة في قابلية الذوبان؟
6) ما كتلة هيدروكسيد الصوديوم اللازم إذابتها في لتر ماء للحصول على تركيز 0.5 غ/لتر؟ (الجواب: 0.5 غ)
7) احسب النسبة الحجمية لـ H₂SO₄ والماء عند إضافة 20 مل من H₂SO₄ إلى 80 مل ماء. (الجواب: 20% و80%)'''),
  ]),
  Chapter('الفصل الخامس: الزمرة الرابعة (السليكون ومركباته)', [
    Section('الملخص', Icons.notes, '''عناصر الزمرة IVA:
• الكاربون C، السليكون Si، الجرمانيوم Ge، القصدير Sn، الرصاص Pb.

الصفات العامة:
• أكثر الزمر اختلافاً وتعدداً في صفات عناصرها: ينتقل العنصر من اللافلزية إلى الفلزية كلما انتقلنا من أعلى الزمرة إلى أسفلها.
• الكاربون لافلز، والسليكون والجرمانيوم أشباه فلزات، والقصدير والرصاص فلزات حقيقية.
• تقل درجتا الغليان والانصهار بالانتقال من أعلى إلى أسفل الزمرة.
• لكل عنصر أربعة إلكترونات في الغلاف الخارجي، ولصعوبة فقدانها أو اكتسابها تميل إلى المشاركة بها بتكوين أواصر تساهمية، فتكون حالة التأكسد الرباعية (+4).
• مركبات الكاربون والسليكون: تساهمية ذات حالة تأكسد رباعية.
• الجرمانيوم والقصدير والرصاص: مركبات تساهمية وأيونية (أيونات Ge²⁺، Sn²⁺، Pb²⁺).
• فعاليتها ضعيفة، وتتفاعل مع اللافلزات كالأوكسجين لكن بالتسخين.
• يُستعمل القصدير في طلاء الحديد (علب حفظ الأغذية)، وسبيكة الرصاص والقصدير في لحيم التوصيلات الكهربائية.

السليكون Si (العدد الذري 14، العدد الكتلي 28، الترتيب 2, 8, 4):
• له أربعة إلكترونات في الغلاف الخارجي فيشارك بها، لذلك أغلب مركباته تساهمية وتكافؤه رباعي.

وجوده:
• العنصر الأكثر انتشاراً في القشرة الأرضية بعد الأوكسجين (نحو 28%).
• لا يوجد حراً بل متحداً: SiO₂ (الكوارتز، الرمل) وسليكات متنوعة.
• له صورتان: متبلورة (مسحوقها بني غامق، أقل فعالية) وغير متبلورة (مسحوقها رصاصي غامق).

تحضيره:
• مختبرياً: السليكون غير المتبلور بتسخين البوتاسيوم في جو من SiF₄. والمتبلور بإذابته في منصهر الألمنيوم ثم تبريد المحلول فتنفصل البلورات.
• صناعياً: باختزال السليكا SiO₂ بدرجات حرارة عالية بالكاربون أو المغنيسيوم، والناتج سليكون صناعي نقاوته 90–95% يُستعمل في سبائك البرونز والحديد (وخاصة المطاوع) وتحضير السليكونات.
• التنقية: يُحوَّل إلى SiCl₄ ثم يُختزل بالمغنيسيوم، ويُغسل الناتج بالماء الحار فيذوب MgCl₂ ولا يذوب السليكون. وللحصول على نقاوة أعلى تُستعمل طريقة منطقة التكرير.
• السليكون عالي النقاوة يُستعمل في أشباه الموصلات والرقائق الدقيقة والخلايا الشمسية.

الخواص الفيزيائية:
• شبه فلز، صلب جداً، درجة انصهاره عالية (1410 °م)، له بريق معدني، وهو شبه موصل للتيار الكهربائي.

الخواص الكيميائية:
• خامل تجاه معظم الحوامض، ويذوب في المحاليل المائية للقواعد.
• فعال جداً تجاه الكلور.
• لا يتأثر بالهواء عند الدرجات الاعتيادية ويتفاعل عند 950 °م.
• السليكون ومركباته الطبيعية (السليكا والسليكات) غير سامة.

استعمالاته:
• الصناعة الإلكترونية: الدوائر المتكاملة والخلايا الشمسية.
• السبائك.
• صناعة الزجاج والسمنت والسيراميك.
• المواد السليكونية العضوية: الزيوت والبلاستيكات.

مركبات السليكون:
1) هيدريدات السليكون: مثل SiH₄ (مركب فعال جداً، يشتعل تلقائياً في الهواء).
2) ثنائي أوكسيد السليكون (السليكا) SiO₂:
• نقية: حجر الصوان والكوارتز (شديدة الصلادة، تقطع الزجاج وتخدش الحديد الصلب).
• غير نقية: الرمل.
• غير فعالة، لا تتفاعل مع الكلور أو البروم أو الهيدروجين ومعظم الحوامض، لكنها تتفاعل مع HF والقواعد.
• تتفاعل مع الأكاسيد أو الكاربونات الفلزية بالتسخين الشديد فتتكون السليكات.
• جل السليكا: مسحوق غير بلوري ناتج عن إضافة حامض لمحلول سليكات، يُستعمل عاملاً مجففاً.
3) السليكات: مع الأوكسجين نحو 74% من القشرة الأرضية، مثل CaSiO₃ وNa₂SiO₃. أكثرها استعمالاً سليكات الصوديوم القابلة للذوبان، ومحلولها المركز يسمى ماء الزجاج (حماية الأقمشة والورق من الحرائق، مادة لاصقة رخيصة، تقوية السمنت).
4) كاربيد السليكون SiC: بنية شبكية مثل الماس، صلد للغاية، مادة جلاية (ورق الجام وحجر الكوسرة).
5) السليكونات: مركبات عضوية غير سامة ومستقرة: زيوت السليكون (مانعة للالتصاق ومضادة للرطوبة)، مطاط السليكون (يبقى مرناً بمدى حراري واسع، يُستعمل مادة إحكام)، الراتنجات السليكونية (عازلة كهربائياً ومضادة للماء).'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• السليكا: ثنائي أوكسيد السليكون SiO₂.
• السليكات: مركبات السليكون والأوكسجين مع الفلزات (CaSiO₃, Na₂SiO₃).
• ماء الزجاج: المحلول المائي المركز لسليكات الصوديوم.
• جل السليكا: مسحوق غير بلوري يُستعمل عاملاً مجففاً.
• السليكون الصناعي: سليكون نقاوته 90–95% ناتج عن اختزال السليكا بالكاربون.
• السليكونات: مركبات عضوية غير سامة ومستقرة في مدى واسع من درجات الحرارة.
• طريقة منطقة التكرير: تسخين قالب السليكون من طرفه بمصدر حراري حلقي متحرك فتتركز الشوائب في الطرف الآخر ويُقطع ويُتخلص منها.

التعاليل:
• أغلب مركبات السليكون تساهمية: لأنه يحتاج إلى فقد أو اكتساب أربعة إلكترونات وهذا صعب، فيشارك بها.
• لا يوجد السليكون حراً في الطبيعة: لأنه يتحد بسهولة مع الأوكسجين.
• يُستعمل السليكون في الصناعات الإلكترونية: لأنه شبه موصل للتيار الكهربائي.
• السليكون المتبلور أقل فعالية من غير المتبلور.
• لا يصلح السليكون الصناعي لصناعة الرقائق الدقيقة والخلايا الشمسية: لأن نقاوته غير كافية، فيُنقى أولاً.
• يُغسل السليكون بالماء الحار بعد التنقية: لأن MgCl₂ يذوب فيه ولا يذوب السليكون.
• يُستعمل جل السليكا مجففاً: لمساحته السطحية الكبيرة وقابليته العالية لامتصاص الماء.
• كاربيد السليكون صلد جداً: لبنيته الشبكية ذات الأواصر التساهمية (تشبه الماس).
• يُستعمل القصدير في طلاء علب حفظ الأغذية: لحمايتها من التآكل.
• تتدرج عناصر الزمرة الرابعة من اللافلزية إلى الفلزية: بزيادة العدد الذري.'''),
    Section('المسائل والمعادلات', Icons.calculate, '''الترتيب الإلكتروني:
• Si: 1s² 2s² 2p⁶ 3s² 3p²
• Si⁴⁺: 1s² 2s² 2p⁶

تحضير السليكون:
• مختبرياً: SiF₄ + 4K → Si + 4KF (تسخين)
• صناعياً: SiO₂ + 2C → Si + 2CO↑ (تسخين شديد)
• بالمغنيسيوم: SiO₂ + 2Mg → Si + 2MgO
• التنقية: Si + 2Cl₂ → SiCl₄ ثم SiCl₄ + 2Mg → Si + 2MgCl₂

خواص السليكون:
• مع القواعد: Si + 2NaOH + H₂O → Na₂SiO₃ + 2H₂
• مع الكلور: Si + 2Cl₂ → SiCl₄
• مع الأوكسجين (عند 950 °م): Si + O₂ → SiO₂
• مع الكاربون: Si + C → SiC

مركبات السليكون:
• تحضير SiH₄: Mg₂Si + 4HCl → SiH₄ + 2MgCl₂
• اشتعال SiH₄: SiH₄ + 2O₂ → SiO₂ + 2H₂O
• السليكا مع HF: SiO₂ + 6HF → H₂SiF₆ + 2H₂O
• السليكا مع القواعد: SiO₂ + 2NaOH → Na₂SiO₃ + H₂O
• السليكا مع كاربونات فلزية: SiO₂ + Na₂CO₃ → Na₂SiO₃ + CO₂ (تسخين شديد)
• السليكا مع أكاسيد فلزية: SiO₂ + CaO → CaSiO₃ (تسخين شديد)
• السليكا مع كاربونات الكالسيوم: SiO₂ + CaCO₃ → CaSiO₃ + CO₂
• كاربيد السليكون: SiO₂ + 3C → SiC + 2CO'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها (إكمال الفراغات):
• يوجد SiO₂ في الطبيعة نوعين: نقي مثل الكوارتز والصوان، وغير نقي مثل الرمل.
• يمكن تحضير السليكات من التسخين الشديد للسليكا مع كاربونات فلزية أو أكسيد فلزي.
• حالتا التأكسد الشائعتان لعناصر الزمرة الرابعة: (+4) و(+2).
• الحالة (+4) تكون مستقرة في الكاربون والسليكون.
• يتفاعل السليكون عند 950 °م مع الأوكسجين فيعطي ثنائي أوكسيد السليكون SiO₂.
• تزداد الصفات الفلزية كلما انتقلنا من أعلى الزمرة إلى أسفلها وتقل الصفات اللافلزية.
• للسليكون صورتان: متبلورة (مسحوقها بني غامق) وغير متبلورة (مسحوقها رصاصي غامق).

أسئلة للمراجعة:
1) اكتب معادلات موزونة لكل مما يأتي:
• تفاعل المغنيسيوم مع ثنائي أوكسيد السليكون.
• اختزال ثنائي أوكسيد السليكون بالكاربون.
• تفاعل سليسيد المغنيسيوم مع HCl.
• تفاعل SiO₂ مع كاربونات الكالسيوم.
• تفاعل SiO₂ مع حامض الهيدروفلوريك.
• تفاعل SiO₂ مع كاربونات الصوديوم.
• تفاعل السليكون مع الكاربون.
2) اكتب الترتيب الإلكتروني لـ Si وSi⁴⁺.
3) ما هو السليكون عالي النقاوة وكيف يحضّر؟
4) اشرح مع كتابة المعادلات طرائق تحضير السليكون.
5) عدّد ستة استعمالات متنوعة للسليكون ومركباته.'''),
  ]),
  Chapter('الفصل السادس: مدخل في الكيمياء العضوية', [
    Section('الملخص', Icons.notes, '''أهمية المركبات العضوية:
• المواد الغذائية: البروتينات والكاربوهيدرات والزيوت والشحوم.
• المنتجات الطبيعية والصناعية: القطن والصوف والحرير والورق والبلاستيك.
• أصناف الوقود: النفط والغاز الطبيعي والخشب.
• العقاقير الطبية والفيتامينات والهرمونات والإنزيمات.

إثبات وجود الكاربون في المركبات العضوية:
• عند حرق شمعة أو ورق يتحرر CO₂ ويُكشف عنه بإمراره على ماء الجير Ca(OH)₂ فيعكره لتكوّن CaCO₃.
• عند حرق السكر في أنبوبة اختبار تتخلف مادة سوداء هي الكاربون.

صفات المركبات العضوية:
1) تحتوي على الكاربون وتقبل الاحتراق أو التحلل بالتسخين.
2) ترتبط ذراتها غالباً بأواصر تساهمية فتتفاعل ببطء.
3) كثير منها لا يذوب في الماء ويذوب في مذيبات عضوية (الكحول، الإيثر، الأسيتون، رباعي كلوريد الكاربون).

الأواصر التساهمية للكاربون:
• العدد الذري 6، وفي غلافه الخارجي 4 إلكترونات، فيشارك بها ليصبح حوله ثمانية إلكترونات.
• ميثان CH₄: أربع أواصر مفردة.
• إيثيلين C₂H₄: أصرة مزدوجة بين ذرتي كاربون.
• أستيلين C₂H₂: أصرة ثلاثية بين ذرتي كاربون.
• ترتبط ذرات الكاربون ببعضها بسلاسل مفتوحة (مستمرة أو متفرعة) أو مغلقة (حلقات)، لذلك توجد مئات الآلاف من المركبات العضوية.

التصنيف:
• الهيدروكاربونات: مركبات من الكاربون والهيدروجين فقط.
• المشبعة (ألكانات): أواصر مفردة (الميثان).
• غير المشبعة: ألكينات (أصرة مزدوجة، الإيثيلين) وألكاينات (أصرة ثلاثية، الأستيلين).
• مركبات فيها أوكسجين: كحول الإيثيل، حامض الخليك.
• مركبات حلقية: البنزين والفينول.

الميثان CH₄:
• أبسط هيدروكاربون، يوجد في الغاز الطبيعي المصاحب لاستخراج النفط وفي مناجم الفحم (غاز المناجم) وينتج من تحلل المواد العضوية في المستنقعات (غاز المستنقعات).
• تحضيره: تسخين خلات الصوديوم مع هيدروكسيد الصوديوم وأوكسيد الكالسيوم، ويُجمع الغاز بإزاحة الماء إلى الأسفل.
• خواصه: عديم اللون والرائحة، قليل الذوبان في الماء، يشتعل بلهب أزرق فاتح غير داخن.

الإيثيلين C₂H₄:
• ألكين (غير مشبع، أصرة مزدوجة).
• تحضيره: تسخين كحول الإيثيل مع H₂SO₄ المركز إلى نحو 170 °م (ينتزع الحامض جزيء الماء من الكحول).
• خواصه: غاز عديم اللون لا يذوب في الماء، يشتعل بلهب داخن، يتفاعل مع ماء البروم الأحمر فيزيل لونه.
• استعمالاته: مادة أولية لتحضير اللدائن (البلاستيك)، إنضاج الخضروات والفواكه (كالطماطم)، صناعة كحول الإيثيل.

الأستيلين C₂H₂:
• ألكاين (غير مشبع، أصرة ثلاثية).
• تحضيره: تفاعل كاربيد الكالسيوم مع الماء (يُضاف الماء ببطء ويُجمع الغاز بإزاحة الماء).
• خواصه: غاز عديم اللون ذو رائحة كريهة تشبه رائحة الثوم، لا يذوب في الماء، يشتعل في الهواء بلهب داخن، ويشتعل في الأوكسجين بلهب أزرق باهت وحرارة عالية، ويزيل لون ماء البروم الأحمر.
• استعمالاته: مزيج الأستيلين والأوكسجين يعطي الشعلة الأوكسي أستيلينية لقطع المعادن ولحمها، ومادة أولية لصناعة المطاط والبلاستيك وحامض الخليك.

كحول الإيثيل (الإيثانول) C₂H₅OH:
• يحضَّر تقليدياً بتخمير الدبس أو التمر أو عصير العنب (بإنزيم الزايميز)، ثم يُفصل بالتقطير.
• صناعياً: من تفاعل الإيثيلين مع الماء بوجود H₂SO₄ المركز.
• خواصه: سائل أقل غلياناً من الماء، له رائحة مميزة، مذيب جيد للمواد العضوية، يشتعل بلهب أزرق باهت.
• استعمالاته: مادة أولية في الصناعات (مواد التجميل والعطور والورنيش والحبر والمطاط الصناعي)، مركبات دوائية ومشروبات روحية، وقود (مخلوطاً بمشتقات نفطية)، محلول مع اليود لتعقيم الجروح (سام).
• الكحول المعطَّل (السبيرتو): كحول إيثيل رخيص للأغراض الصناعية تضاف إليه مواد سامة مثل كحول المثيل وأصباغ لتمييزه.
• تأثيره في الإنسان: يعطل ترابط الجهاز العضلي مع العصبي ويبطئ عمل الجهاز العصبي، والإدمان عليه ضار جداً بالصحة.

حامض الخليك CH₃COOH:
• يُحضَّر صناعياً من تفاعل الأستيلين مع الماء بوجود H₂SO₄ وعوامل مساعدة.
• سائل بدرجات الحرارة الاعتيادية، يتجمد عند 18 °م، رائحته نفاذة، يمتزج بالماء بأية نسبة، يتفاعل مع NaOH ليكوّن خلات الصوديوم.

البنزين (البنزول) C₆H₆:
• يُستخرج من قطران الفحم، سائل سريع التبخر، يغلي عند 80 °م، لا يذوب في الماء، بخاره سام.
• هيدروكاربون عطري (أروماتي)، يشتعل بلهب داخن جداً لارتفاع نسبة الكاربون.
• استعمالاته: مذيب للأصباغ والورنيش، مبيدات حشرية، صناعة النايلون ومساحيق التنظيف.

الفينول C₆H₅OH:
• مادة صلبة عديمة اللون ذات رائحة خاصة، تتلف الجلد وتسبب حروقاً تُعالج بغسلها بمحلول مخفف من كاربونات الصوديوم.
• يذوب في الماء، ومحلوله (9%) يسمى حامض الكاربوليك ويُستعمل لتعقيم المرافق الصحية.
• يُشتق منه المعقمات والمطهرات ومساحيق التنظيف ومبيدات الحشرات والبلاستيك.
• حامض السلسليك أحد الفينولات ويُحضَّر منه الأسبرين.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• الكيمياء العضوية: دراسة مركبات الكاربون.
• الهيدروكاربون: مركب يتكون من الكاربون والهيدروجين فقط.
• الهيدروكاربونات المشبعة (الألكانات): مركبات فيها أواصر تساهمية مفردة فقط، مثل الميثان.
• الألكينات: هيدروكاربونات غير مشبعة فيها أصرة مزدوجة، مثل الإيثيلين.
• الألكاينات: هيدروكاربونات غير مشبعة فيها أصرة ثلاثية، مثل الأستيلين.
• الهيدروكاربونات العطرية (الأروماتية): مركبات ذات روائح خاصة، أبسطها البنزين.
• الكحول المعطَّل (السبيرتو): كحول إيثيل صناعي رخيص أضيفت إليه مواد سامة لمنع شربه.

التعاليل:
• كثرة المركبات العضوية: لقدرة الكاربون على تكوين أواصر مفردة ومزدوجة وثلاثية، ولارتباط ذراته ببعضها بسلاسل مفتوحة أو مغلقة.
• تتفاعل المركبات العضوية ببطء: لأن ذراتها مرتبطة بأواصر تساهمية.
• يُجمع غاز الميثان بإزاحة الماء إلى الأسفل: لأنه قليل الذوبان في الماء.
• يُستعمل خليط NaOH مع CaO في تحضير الميثان: لأن الخليط أقل تأثيراً في الزجاج وأعلى في درجة الانصهار من NaOH وحده.
• يُستعمل H₂SO₄ المركز في تحضير الإيثيلين: لينتزع جزيء الماء من الكحول.
• الميثان يشتعل بلهب غير داخن: لانخفاض نسبة الكاربون فيه.
• الأستيلين والبنزين يشتعلان بلهب داخن: لارتفاع نسبة الكاربون فيهما.
• يُستعمل الأستيلين مع الأوكسجين لقطع المعادن ولحمها: لأن الشعلة ناتجة ذات حرارة عالية.
• يُعالج حرق الفينول بمحلول كاربونات الصوديوم المخفف: لمعادلة تأثير الفينول.
• يُعطَّل كحول الإيثيل الصناعي بإضافة مواد سامة وأصباغ: لتمييزه ومنع شربه.

التمييز بين الميثان والإيثيلين والأستيلين:
• الإيثيلين والأستيلين يزيلان لون ماء البروم الأحمر.
• الميثان لا يتفاعل معه ولا يزول اللون.'''),
    Section('المسائل والمعادلات', Icons.calculate, '''إثبات وجود الكاربون:
• CO₂ + Ca(OH)₂ → CaCO₃↓ + H₂O (تعكر ماء الجير)

الميثان:
• التحضير: CH₃COONa + NaOH → CH₄↑ + Na₂CO₃ (تسخين، بوجود CaO)
• الاحتراق: CH₄ + 2O₂ → CO₂ + 2H₂O + طاقة

الإيثيلين:
• التحضير: C₂H₅OH → C₂H₄↑ + H₂O (H₂SO₄ مركز، 170 °م)
• الاحتراق: C₂H₄ + 3O₂ → 2CO₂ + 2H₂O

الأستيلين:
• التحضير: CaC₂ + 2H₂O → C₂H₂↑ + Ca(OH)₂
• الاحتراق: 2C₂H₂ + 5O₂ → 4CO₂ + 2H₂O + طاقة

الكحول:
• التخمر: سكر بسيط ← (إنزيم الزايميز) ← كحول الإيثيل + CO₂
• صناعياً: C₂H₄ + H₂O → C₂H₅OH (H₂SO₄ مركز)

التمييز بماء البروم الأحمر:
• إيثيلين أو أستيلين + ماء البروم الأحمر ← يختفي اللون الأحمر.
• ميثان + ماء البروم الأحمر ← لا يختفي اللون.

صيغ مهمة:
• ميثان CH₄، إيثيلين C₂H₄، أستيلين C₂H₂، كحول الإيثيل C₂H₅OH، حامض الخليك CH₃COOH، بنزين C₆H₆، فينول C₆H₅OH.

أمثلة على المركبات (أشكال السلاسل):
• سلسلة مستمرة: بيوتان. متفرعة: أيزوبيوتان.
• حلقية: بروبان حلقي (ثلاثي)، بنتان حلقي (خماسي)، هكسان حلقي (سداسي).'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• كل المركبات العضوية تحتوي على الكاربون.
• الارتباط بين ذرتي كاربون في المركب المشبع يكون بأواصر تساهمية مفردة.
• الغاز الذي نسبته الحجمية أكبر في الغاز الطبيعي هو الميثان.
• في الأستيلين ترتبط ذرتا الكاربون بأصرة ثلاثية.
• الغاز المتجمع بإزاحة الماء إلى الأسفل: دليل على قلة ذوبانه في الماء.
• الغاز الذي لا يتفاعل مع البروم ويشتعل بلهب أزرق فاتح غير داخن هو الميثان.
• اشتعال الأستيلين والبنزين بلهب داخن يدل على ارتفاع نسبة الكاربون فيهما.

أسئلة للمراجعة:
1) وضح مع الرسم جهاز تحضير الميثان في المختبر مع المعادلة.
2) أعطِ مثالاً لكل مما يأتي: سلسلة كاربونية مستمرة، سلسلة كاربونية حلقية، سلسلة كاربونية متفرعة.
3) وضح مع الرسم جهاز تحضير الأستيلين في المختبر مع المعادلة.
4) ما أهم مميزات المركبات العضوية؟
5) عبّر بمعادلات موزونة عن: تسخين خلات الصوديوم وهيدروكسيد الصوديوم، حرق الميثان والإيثيلين والأستيلين، تسخين كحول الإيثيل وحامض الكبريتيك المركز إلى 170 °م، تفاعل الماء مع كاربيد الكالسيوم.
6) اشرح تأثير الكحول الاعتيادي على جسم الإنسان.
7) ما المقصود بالكحول المعطل (السبيرتو)؟
8) قارن بين الميثان والإيثيلين والأستيلين من حيث: اللون والرائحة، قابلية الذوبان في الماء، الاشتعال بالهواء، التفاعل مع ماء البروم الأحمر.
9) ماذا يُستخدم لإنتاج الشعلة القوية؟ (الأستيلين مع الأوكسجين)
10) ما أهمية البنزين والفينول؟'''),
  ]),
  Chapter('الفصل السابع: الزمرة الخامسة (النتروجين والفسفور)', [
    Section('الملخص', Icons.notes, '''عناصر الزمرة VA:
• النتروجين N، الفسفور P، الزرنيخ As، الأنتيمون Sb، البزموث Bi.
• تشترك بخمسة إلكترونات في غلاف الطاقة الخارجي.
• العناصر الخمسة تشكل أقل من 0.2% من وزن القشرة الأرضية لكنها مهمة جداً.

الصفات العامة:
• تتدرج من اللافلزية (النتروجين والفسفور) إلى أشباه الفلزات (الزرنيخ والأنتيمون) إلى الفلزية (البزموث).
• النتروجين غاز، وباقي العناصر صلبة في الظروف الاعتيادية.
• الفسفور يميل مثل النتروجين إلى تكوين مركبات تساهمية، ويزداد ميل باقي العناصر إلى تكوين مركبات أيونية (الزرنيخ والبزموث).
• أكاسيدها تتدرج من حامضية (الفسفور) إلى قاعدية (البزموث).

النتروجين N (العدد الذري 7، العدد الكتلي 14، الترتيب 2, 5):
• يشكل نحو 78% من حجم الغلاف الجوي.
• غير فعال تقريباً في الظروف الاعتيادية، لذلك سُمّي قديماً الأزوت (عديم الحياة).
• مركباته مهمة في الأغذية والأسمدة والمفرقعات.

تحضيره:
• مختبرياً: تسخين مزيج من كلوريد الأمونيوم ونتريت الصوديوم بوجود قليل من الماء (لمنع الانفجار).
• صناعياً: التقطير التجزيئي للهواء المسال الخالي من CO₂، فيتقطر النتروجين أولاً (درجة غليانه −198 °م أوطأ من الأوكسجين −183 °م). وتُزال آثار الأوكسجين بإمرار الغاز على برادة النحاس الساخنة فتكوّن CuO.

خواصه:
• فيزيائياً: غاز عديم اللون والرائحة، جزيء ثنائي الذرة N₂، قليل الذوبان في الماء، غير فعال تقريباً.
• كيميائياً: يتحد بالتسخين مع المغنيسيوم والليثيوم والكالسيوم، ويكوّن مع الأوكسجين بالشرارة الكهربائية أكاسيد (NO وNO₂)، ومع الهيدروجين بضغط عالٍ وعامل مساعد يعطي الأمونيا (طريقة هابر).

استعمالاته:
• إنتاج الأمونيا صناعياً (هابر) وحامض النتريك (أوستولد) والأسمدة.
• تبريد الأغذية بالتجميد بالغمر في الغاز المسال.
• الصناعات النفطية: زيادة ضغط آبار النفط ليتدفق النفط.
• جو خامل في خزانات المواد القابلة للانفجار.

الأمونيا NH₃:
• تنتج في الطبيعة من تحلل أجسام الحيوانات والنباتات بعد موتها، وتوجد في التربة على هيئة أملاح الأمونيوم.
• تحضيرها مختبرياً: تسخين كلوريد الأمونيوم بلطف مع هيدروكسيد الكالسيوم، وتُجمع بالإزاحة السفلية للهواء (لأنها أخف منه) بعد إمرارها على عمود CaO لإزالة الرطوبة.
• صناعياً (طريقة هابر): اتحاد النتروجين والهيدروجين بضغط عالٍ وعامل مساعد ودرجة حرارة (460–550 °م)، وتُسال الأمونيا الناتجة وتُعاد الغازات غير المتفاعلة.

الخواص الفيزيائية للأمونيا:
• غاز عديم اللون، رائحته نفاذة لاذعة تسبب دمع العين، أخف من الهواء.
• كثير الذوبان في الماء، ومحلوله يسمى ماء الأمونيا (NH₄OH). تُثبت ذلك تجربة النافورة بدليل الفينولفثالين (يتلون المحلول بأحمر وردي).
• يسهل إسالتها بضغط 8–10 جو، ودرجة غليان الأمونيا السائلة −33.5 °م، ولها حرارة تبخر كامنة عالية فتُستعمل في مصانع الثلج والتبريد.

الخواص الكيميائية للأمونيا:
• ثابتة كيميائياً لكنها تتفكك عند إمرارها على سطح فلزي ساخن أو بإمرار شرارة كهربائية.
• قابلة للاشتعال في جو الأوكسجين.
• محلولها قاعدي: يحول لون ورقة زهرة الشمس الحمراء إلى الأزرق.
• الكشف عنها: عند اتحادها مع غاز كلوريد الهيدروجين تنتج أبخرة بيضاء كثيفة من كلوريد الأمونيوم.

حامض النتريك HNO₃:
• من أهم الحوامض الأوكسجينية للنتروجين.
• مختبرياً: تسخين نترات البوتاسيوم مع H₂SO₄ المركز في معوجة زجاجية ويُكثَّف البخار في وعاء مبرد بالماء.
• صناعياً (طريقة أوستولد): أكسدة الأمونيا بالهواء بوجود البلاتين عاملاً مساعداً، ثم يُمتص الناتج في الماء.
• خواصه: الحامض النقي عديم اللون وتنبعث منه أبخرة نفاذة، وغير النقي (أو النقي بعد مدة) يكون أصفر لاحتوائه على أكاسيد النتروجين الذائبة (NO₂). يمتزج بالماء ويغلي مزيجه (68%) عند 120.5 °م.

الفسفور P (العدد الذري 15، العدد الكتلي 31، الترتيب 2, 8, 5):
• من المكونات الأساسية للكائنات الحية (الخلايا العصبية والعظام وسيتوبلازم الخلايا).
• لا يوجد حراً في الطبيعة، وخامه المهم الأباتايت (شكل غير نقي لفوسفات الكالسيوم)، وتوجد ترسبات كبيرة منه في العراق.

إنتاجه صناعياً:
• تسخين فوسفات الكالسيوم مع الرمل والكاربون في فرن كهربائي عند 1500 °م بمعزل عن الهواء.
• الناتج الفسفور الأبيض، ويُصب ويُحفظ تحت الماء لانخفاض درجة اتقاده وسرعة اتحاده مع الأوكسجين.

صورتا الفسفور (الأبيض والأحمر):
• الأبيض: شبه شفاف أبيض مائل للصفرة، قضبان، يُحفظ تحت الماء، أقل كثافة، يذوب في ثنائي كبريتيد الكاربون ولا يذوب في الماء، درجة انصهاره وأتقاده واطئة فيشتعل بسهولة، سام.
• الأحمر: أحمر مائل للبنفسجي، مسحوق لا يتأثر بالهواء، أعلى كثافة، لا يذوب في المذيبات العضوية ولا في الماء، يتسامى بالتسخين، درجة اتقاده عالية، غير سام.
• الفسفور الأبيض أكثر فعالية: لاختلاف طريقة ترابط ذراته.
• خصائص الأبيض: يتوهج في الظلام بلون أخضر باهت في الهواء الرطب (التألق الكيميائي) مع رائحة تشبه الثوم، ويشتعل تلقائياً في الهواء مكوناً P₂O₅.

مركبات الفسفور:
• حامض الفسفوريك H₃PO₄: سائل كثيف عديم اللون، حامض ضعيف غير مؤكسد، يكوّن الفوسفات ذات الأهمية في الأسمدة.
• فوسفات الصوديوم Na₃PO₄: من مساحيق التنظيف (تتحلل مائياً فتكوّن NaOH يزيل الدهون)، وتحلية الماء العسر، وحفظ بعض الأغذية.

الاستعمالات الصناعية:
• صناعة الثقاب: يُعامَل العود بمحلول فوسفات الأمونيوم (يحترق بلهب بلا دخان ولا يتقد بعد الانطفاء)، ورأس العود عجينة من: مادة قابلة للاشتعال (Sb₂S₃)، ومادة مؤكسدة (KClO₃)، ومادة تزيد الاحتكاك (مسحوق الزجاج)، ومادة صمغية. ويُحك بجانب العلبة الذي فيه الفسفور الأحمر.
• الأسمدة الفوسفاتية: الفسفور أساسي لنمو النباتات (يقوي السيقان ويعجل نمو البذور ويزيد مقاومة الأمراض، وخاصة السنبليات كالحنطة والشعير والذرة).
• فوسفات الكالسيوم قليل الذوبان، فيُحوَّل بمعاملته بالحامض إلى سماد سوبر فوسفات (اعتيادي بحامض الكبريتيك، وثلاثي بحامض الفسفوريك وهو أجود لأنه لا يحتوي كبريتات الكالسيوم).
• العراق مصدر مهم لفوسفات الكالسيوم (الرطبة، حقول عكاشات في الأنبار).'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• الأزوت: الاسم القديم للنتروجين ومعناه (عديم الحياة).
• طريقة هابر: تحضير الأمونيا صناعياً من اتحاد النتروجين والهيدروجين.
• طريقة أوستولد: تحضير حامض النتريك صناعياً بأكسدة الأمونيا بالهواء بوجود البلاتين.
• التألق الكيميائي: توهج الفسفور الأبيض في الظلام بلون أخضر باهت عند تعرضه لهواء رطب.
• السوبر فوسفات: سماد فوسفاتي قابل للذوبان يُحضَّر من فوسفات الكالسيوم.
• الأباتايت: شكل غير نقي لفوسفات الكالسيوم، خام الفسفور المهم.

التعاليل:
• النتروجين قليل النشاط في الظروف الاعتيادية: لقوة الرابطة الثلاثية بين ذرتيه في جزيء N₂.
• يُحضَّر النتروجين مختبرياً بوجود قليل من الماء: لمنع حدوث انفجار.
• يتقطر النتروجين أولاً عند تقطير الهواء المسال: لأن درجة غليانه أوطأ من الأوكسجين.
• تُمرَّر الأمونيا على عمود CaO: للتخلص من الرطوبة المصاحبة للغاز.
• تُجمع الأمونيا بالإزاحة السفلية للهواء: لأنها أخف من الهواء.
• تتلون الأمونيا بعد دخولها الفينولفثالين باللون الأحمر الوردي: بسبب قاعدية محلولها.
• تُستعمل الأمونيا في مصانع الثلج: لأن لها حرارة تبخر كامنة عالية.
• يكون حامض النتريك غير النقي أصفر: لاحتوائه على أكاسيد النتروجين الذائبة (NO₂).
• يُحفظ الفسفور الأبيض تحت الماء: لدرجة اتقاده الواطئة وسرعة اتحاده مع الأوكسجين واشتعاله في الهواء.
• الفسفور الأبيض أكثر فعالية من الأحمر: لاختلاف كيفية ترابط الذرات في كل صورة.
• الفسفور الأبيض سام بينما الأحمر غير سام: لأن الأبيض يذوب في العصارات الهضمية بخلاف الأحمر.
• يُعامل عود الثقاب بفوسفات الأمونيوم: ليحترق بلهب بدون دخان ويمنع اتقاده بعد انطفاء الشعلة.
• يُحوَّل فوسفات الكالسيوم إلى سوبر فوسفات: لأن فوسفات الكالسيوم قليل الذوبان جداً في الماء ولا يستفيد منه النبات.
• السوبر فوسفات الثلاثي أجود من الاعتيادي: لأنه لا يحتوي على كبريتات الكالسيوم.
• تُستعمل فوسفات الصوديوم في مساحيق التنظيف: لأنها تتحلل مائياً فتكوّن هيدروكسيد الصوديوم الذي يزيل الدهون.'''),
    Section('المسائل والمعادلات', Icons.calculate, '''النتروجين:
• تحضيره مختبرياً:
NH₄Cl + NaNO₂ → NaCl + NH₄NO₂
NH₄NO₂ → N₂ + 2H₂O
• مع الأوكسجين بالشرارة: N₂ + O₂ → 2NO
• طريقة هابر: N₂ + 3H₂ ⇌ 2NH₃ (ضغط عالٍ + عامل مساعد + تسخين)

الأمونيا:
• تحضيرها مختبرياً: 2NH₄Cl + Ca(OH)₂ → CaCl₂ + 2H₂O + 2NH₃↑
• تفككها: 2NH₃ → N₂ + 3H₂
• احتراقها: 4NH₃ + 3O₂ → 2N₂ + 6H₂O
• الكشف عنها: NH₃ + HCl → NH₄Cl (أبخرة بيضاء)

حامض النتريك:
• مختبرياً: KNO₃ + H₂SO₄ → KHSO₄ + HNO₃ (تسخين)
• صناعياً (أوستولد): تُؤكسد الأمونيا بالهواء بوجود البلاتين: 4NH₃ + 5O₂ → 4NO + 6H₂O
ثم 2NO + O₂ → 2NO₂
ثم يُمتص NO₂ في الماء فينتج HNO₃

الفسفور:
• إنتاجه: 2Ca₃(PO₄)₂ + 6SiO₂ + 10C → 6CaSiO₃ + 10CO + P₄ (1500 °م)
• احتراقه بوفرة الأوكسجين: P₄ + 5O₂ → 2P₂O₅
• بكمية محدودة من الأوكسجين: P₄ + 3O₂ → 2P₂O₃

الأسمدة:
• السوبر فوسفات الاعتيادي:
Ca₃(PO₄)₂ + 2H₂SO₄ → Ca(H₂PO₄)₂ + 2CaSO₄
• السوبر فوسفات الثلاثي:
Ca₃(PO₄)₂ + 4H₃PO₄ → 3Ca(H₂PO₄)₂

الترتيب الإلكتروني:
• N: 2, 5 — تحتوي ذرته 7 بروتونات و7 إلكترونات.
• P: 2, 8, 5 — تحتوي ذرته 15 بروتوناً و15 إلكتروناً.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• العدد الذري للنتروجين 7: تحتوي ذرته 7 بروتونات يدور حولها 7 إلكترونات.
• العدد الذري للفسفور 15: تحتوي نواته 15 بروتوناً يدور حولها 15 إلكتروناً.
• يشكل النتروجين نحو 78% من حجم الغلاف الجوي.
• يُحضَّر النتروجين مختبرياً بتسخين مزيج كلوريد الأمونيوم مع نتريت الصوديوم بوجود قليل من الماء.
• يغطى رأس عود الثقاب بعجينة من: مادة قابلة للاشتعال (كبريتيد الأنتيمون)، مادة مؤكسدة (كلورات البوتاسيوم)، مادة تزيد الاحتكاك (مسحوق الزجاج).
• يتواجد النتروجين في الطبيعة على هيئة جزيء ثنائي الذرة صيغته N₂.
• NH₃ هي الصيغة الكيميائية للأمونيا، جزيء مكون من اتحاد ذرة من عنصر النتروجين وثلاث ذرات من عنصر الهيدروجين.
• محلول الأمونيا يحول ورقة زهرة الشمس الحمراء إلى الزرقاء.
• الصورة التي تكفي حرارة اليد لاتقادها: الفسفور الأبيض.
• المادة التي تُستعمل مباشرة كسماد فوسفاتي: السوبر فوسفات.
• يحضَّر حامض النتريك بكميات تجارية بأكسدة الأمونيا بالهواء بوجود البلاتين عاملاً محفزاً.

أسئلة للمراجعة:
1) من فوائد السماد الفوسفاتي للسنبليات (اذكر ثلاثاً): يقوي سيقانها، يعجل نمو بذورها، يزيد مقاومتها للأمراض.
2) قارن بين الفسفور الأبيض والفسفور الأحمر (الشكل، الكثافة، الذوبان، الاتقاد، السمية).
3) كيف تحضّر الأمونيا مختبرياً وصناعياً؟
4) كيف تكشف عن الأمونيا؟
5) ما استعمالات غاز النتروجين؟
6) كيف يُحضَّر حامض النتريك مختبرياً وصناعياً؟
7) كيف تتحول فوسفات الكالسيوم إلى سماد؟
8) علل: يُحفظ الفسفور الأبيض تحت الماء.'''),
  ]),
  Chapter('الفصل الثامن: الزمرة السادسة (الكبريت ومركباته وحامض الكبريتيك)', [
    Section('الملخص', Icons.notes, '''عناصر الزمرة VIA:
• الأوكسجين O، الكبريت S، السلينيوم Se، التيلوريوم Te، البولونيوم Po.
• تقع على يمين الجدول الدوري.

الصفات العامة:
• تتدرج خواصها بازدياد العدد الذري: الأوكسجين والكبريت والسلينيوم لافلزات، والتيلوريوم أشبه بالفلزات، والبولونيوم له صفات فلزية.
• جميعها تمتلك ست إلكترونات في الغلاف الخارجي، فتميل إلى اكتساب إلكترونين لتصل إلى ترتيب إلكتروني مستقر مشابه للغازات النبيلة.

الكبريت S (العدد الذري 16، العدد الكتلي 32، الترتيب 2, 8, 6):

وجوده:
• حراً في مناجم خاصة (مناجم المشراق في الموصل شمال العراق).
• مركبات في المناطق البركانية: H₂S وSO₂.
• كبريتيدات فلزية مثل الجالكوبايريت CuFeS₂.
• كبريتات: Na₂SO₄·10H₂O وCaSO₄·2H₂O.

تحضيره:
• مختبرياً: إضافة HCl المركز إلى محلول ثايوكبريتات الصوديوم Na₂S₂O₃ عند −10 °م فيترسب الكبريت ويُجمع بالترشيح.
• استخراجه (طريقة فراش): لاستخراج الكبريت الحر المترسب تحت الأرض بصهره في باطن الأرض بثلاثة أنابيب متحدة المركز: يُضخ بخار الماء المضغوط (170 °م) في الأنبوبة الخارجية فينصهر الكبريت، ويُضخ الهواء المضغوط في الأنبوبة الداخلية فيرفع الكبريت المنصهر مخلوطاً بفقاعات الهواء عبر الأنبوبة الوسطى إلى السطح فيُصب في أحواض ويتصلب. نقاوة الناتج 99.5–99.9% فلا يحتاج إعادة تنقية.

الخواص الفيزيائية:
• صلب أصفر، عديم الطعم برائحة مميزة، لا يذوب في الماء ويذوب في ثنائي كبريتيد الكاربون CS₂ (بتبخره يترسب الكبريت بلورات S₈ ثمانية الشكل)، غير موصل للكهرباء.
• له صور متعددة (أشكال مختلفة الخواص الفيزيائية للعنصر نفسه):
- بلورية: المعيني (أكثرها استقراراً، أصفر ليموني، يوجد في المناطق البركانية) والموشوري.
- غير بلورية: الكبريت المطاطي (اللدن): يتكون بتسخين الكبريت ثم صبّ سائله في ماء بارد، فيه سلاسل حلزونية وهو أقل استقراراً ويتحول ببطء إلى البلوري.
• صيغته S₈، وهي من أنشط صوره بسبب التوتر الشديد على الحلقة الثمانية.

الخواص الكيميائية:
• غير فعال في الدرجات الاعتيادية، وبالتسخين يتحد مع كل العناصر تقريباً مباشرة.
• مع اللافلزات: يحترق في الهواء بلهب أزرق مكوناً SO₂، ومع الكاربون يعطي CS₂.
• مع الفلزات: يكوّن كبريتيداتها (Fe, Cu, Zn).
• لا يتأثر بالحوامض المخففة ويتأكسد بالحوامض المركزة القوية (H₂SO₄ الساخن، HNO₃ المركز الساخن).

استعمالاته:
• صناعة الثقاب والبارود الأسود والألعاب النارية.
• الزراعة: معادلة قلوية التربة، بعض الأسمدة، مبيدات الفطريات والحشرات.
• أهم استعماله: تحضير حامض الكبريتيك (أهم مادة كيميائية تجارية في العالم).
• الأصباغ والدهانات والورق والمنسوجات، تعدين الفلزات، تصفية النفط، المطاط، الشامبو، بطاريات السيارات، أفلام التصوير.
• علاج بعض الأمراض الجلدية، وزهر الكبريت لعلاج اضطرابات الهضم.

غاز ثنائي أوكسيد الكبريت SO₂:
• يتولد من احتراق الكبريت بوجود الأوكسجين، ومن النشاط البركاني، وتعدين الفلزات، وحرق النفط والفحم الحجري.
• مختبرياً: إضافة H₂SO₄ المخفف إلى كبريتيت الصوديوم Na₂SO₃، ويُجمع بإزاحة الهواء إلى الأعلى (لأنه أثقل من الهواء).
• خواصه: عديم اللون، رائحة نفاذة قوية، أثقل من الهواء، يذوب قليلاً في الماء مكوناً حامض الكبريتوز الضعيف (يحمّر ورقة زهرة الشمس الزرقاء المبللة).
• صناعياً: بحرق الكبريت المصهور في الهواء في أبراج حرق خاصة.
• استعمالاته: قصر ألوان المواد العضوية كالورق والقش والحرير الصناعي والأصواف (التي تتأثر بالكلور)، التعقيم بحرق الكبريت، حفظ الأغذية. تعود أغلب المواد المقصورة إلى ألوانها بتعرضها للهواء.
• يشتعل الكبريت تلقائياً عند 400 °م بوجود الأوكسجين.
• غاز ضار جداً بالإنسان والحيوان والنبات ومن أهم مسببات الأمطار الحامضية.

غاز كبريتيد الهيدروجين H₂S:
• غاز عديم اللون ذو رائحة كريهة نفاذة كرائحة البيض الفاسد.
• يتكون في الطبيعة من تحلل المواد العضوية، أو من المياه الجوفية الكبريتية (العيون الكبريتية في حمام العليل بنينوى)، أو من نشاط بكتريا تستخدم الحديد والمنغنيز.
• يوجد في الغازات النفطية والطبيعية.
• سام جداً، وأخطر من غاز أحادي أوكسيد الكاربون.
• مختبرياً: تفاعل حامض مخفف مع كبريتيد فلز (مثل FeS).
• عند إمراره في محاليل أيونات الفلزات يتكون راسب كبريتيد الفلز (كبريتيد النحاس راسب أسود).

حامض الكبريتيك H₂SO₄:
• من أوائل الحوامض المعروفة، عرفه العرب منذ القرن الثامن الميلادي، وأطلق عليه جابر بن حيان اسم زيت الزاج.
• سائل عديم اللون زيتي القوام عديم الرائحة، كثافته 1.84 غ/سم³.
• حامض معدني قوي يذوب في الماء بجميع التراكيز مولداً حرارة عالية (يستوجب الحذر عند تخفيفه).
• يعمل عاملاً مجففاً (ينتزع الماء من المركبات العضوية)، فعند إضافته إلى السكر يتفحم السكر (يتكون الكاربون الأسود).

تحضيره صناعياً (طريقة التلامس):
1) حرق الكبريت: S + O₂ → SO₂
2) أكسدة SO₂ في برج التلامس بوجود عامل مساعد خامس أوكسيد الفاناديوم V₂O₅: 2SO₂ + O₂ → 2SO₃
3) امتصاص SO₃ في H₂SO₄ المركز فيتكون حامض الكبريتيك الداخن H₂S₂O₇: SO₃ + H₂SO₄ → H₂S₂O₇
4) إضافة الماء: H₂S₂O₇ + H₂O → 2H₂SO₄ (تركيز 93–100%)

استعمالاته:
• تحضير حوامض أخرى (النتريك والهيدروكلوريك) بسبب درجة غليانه العالية.
• تجفيف المواد (وخاصة الغازات التي لا تتفاعل معه) لميله الشديد للاتحاد بالماء.
• تنقية البترول.
• صناعة المتفجرات (نترات الكليسرين ونترات السليلوز).
• إذابة الصدأ عن الأدوات الحديدية قبل طلائها بالخارصين.
• صناعة البطاريات (الرصاصية) والطلاء الكهربائي لنقل محاليله التيار الكهربائي.
• الأسمدة (كبريتات الأمونيوم والأسمدة الفوسفاتية).

الكبريتات:
• أملاح حامض الكبريتيك الناتجة من تفاعله مع الفلزات أو أكاسيدها أو هيدروكسيداتها أو كاربوناتها.
• كبريتات الكالسيوم المائية (الجبس) CaSO₄·2H₂O، وتُسمى محلياً (بورك) وتُستعمل في البناء والنقوش المعمارية والتماثيل وتجبير العظام.
• كبريتات المغنيسيوم المائية MgSO₄·7H₂O: في صناعة الأنسجة القطنية.
• كبريتات الأمونيوم (NH₄)₂SO₄: سماد نتروجيني.
• كبريتات الصوديوم المائية Na₂SO₄·10H₂O.

الكشف عن أيون الكبريتات:
• بإضافة محلول يحتوي على أيونات الباريوم (مثل كلوريد الباريوم) فيتكون راسب أبيض من كبريتات الباريوم.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• صور العنصر (التآصل): أشكال مختلفة الخواص الفيزيائية كالشكل واللون تعود للعنصر نفسه.
• الكبريت المعيني: أكثر صور الكبريت البلورية استقراراً.
• الكبريت المطاطي (اللدن): كبريت غير بلوري يتكون بصب الكبريت المنصهر في ماء بارد.
• طريقة فراش: استخراج الكبريت الحر من باطن الأرض بصهره بالماء الساخن المضغوط.
• طريقة التلامس: الطريقة الصناعية لتحضير حامض الكبريتيك.
• حامض الكبريتيك الداخن: H₂S₂O₇.
• زيت الزاج: الاسم القديم لحامض الكبريتيك.
• الكبريتات: أملاح حامض الكبريتيك.

التعاليل:
• تميل عناصر الزمرة السادسة إلى اكتساب إلكترونين: لتصل إلى ترتيب إلكتروني مستقر مشابه للغازات النبيلة.
• الكبريت S₈ من أنشط صوره: بسبب التوتر الشديد في حلقته الثمانية.
• الكبريت المطاطي أقل استقراراً من البلوري: لأن فيه سلاسل حلزونية يتحول بها ببطء إلى البلوري.
• لا يحتاج الكبريت المستخرج بطريقة فراش إلى إعادة تنقية: لارتفاع نقاوته (99.5–99.9%).
• يُجمع SO₂ بإزاحة الهواء إلى الأعلى: لأنه أثقل من الهواء.
• تحمر ورقة زهرة الشمس الزرقاء المبللة بالماء في SO₂: لتكوّن حامض الكبريتوز.
• يُستعمل SO₂ في قصر ألوان القش والحرير والصوف: لأنها تتأثر بغاز الكلور فلا يصلح لها.
• SO₂ من مسببات الأمطار الحامضية.
• يتفحم السكر عند إضافة H₂SO₄ المركز إليه: لأن الحامض يمتلك ميلاً شديداً لانتزاع الماء من المركبات العضوية.
• يُستعمل H₂SO₄ في تحضير الحوامض الأخرى (النتريك والهيدروكلوريك): بسبب درجة غليانه العالية.
• يُستعمل H₂SO₄ في تجفيف الغازات: لميله الشديد للاتحاد بالماء.
• يُستعمل H₂SO₄ في البطاريات والطلاء الكهربائي: لأن محاليله توصل التيار الكهربائي.
• يُستعمل V₂O₅ في برج التلامس: عامل مساعد لتسريع أكسدة SO₂ إلى SO₃.
• يُضاف الحامض إلى الماء عند التخفيف بحذر: لأن ذوبانه يولد حرارة عالية.
• H₂S أخطر من أحادي أوكسيد الكاربون: لأنه سام جداً.'''),
    Section('المسائل والمعادلات', Icons.calculate, '''تحضير الكبريت مختبرياً:
2HCl + Na₂S₂O₃ → S↓ + SO₂↑ + 2NaCl + H₂O (عند −10 °م)

تفاعلات الكبريت:
• مع الأوكسجين: S + O₂ → SO₂ (لهب أزرق)
• مع الكاربون: 2S + C → CS₂
• مع الحديد: S + Fe → FeS
• مع الحوامض المركزة:
S + 2H₂SO₄ (مركز ساخن) → 3SO₂ + 2H₂O
S + 6HNO₃ (مركز ساخن) → H₂SO₄ + 6NO₂ + 2H₂O

ثنائي أوكسيد الكبريت:
• تحضيره: H₂SO₄ + Na₂SO₃ → SO₂↑ + Na₂SO₄ + H₂O
• مع الماء: SO₂ + H₂O ⇌ H₂SO₃ (حامض الكبريتوز)
• صناعياً: S + O₂ → SO₂

كبريتيد الهيدروجين:
• تحضيره: FeS + H₂SO₄ → H₂S↑ + FeSO₄
• مع كبريتات النحاس: H₂S + CuSO₄ → H₂SO₄ + CuS↓ (راسب أسود)

حامض الكبريتيك بطريقة التلامس:
• S + O₂ → SO₂
• 2SO₂ + O₂ → 2SO₃ (V₂O₅)
• SO₃ + H₂SO₄ → H₂S₂O₇
• H₂S₂O₇ + H₂O → 2H₂SO₄

تفحم السكر:
C₁₂H₂₂O₁₁ → 12C + 11H₂O (H₂SO₄ مركز)

تكوين الكبريتات (مع الخارصين Zn):
• Zn + H₂SO₄ → ZnSO₄ + H₂
• ZnO + H₂SO₄ → ZnSO₄ + H₂O
• Zn(OH)₂ + H₂SO₄ → ZnSO₄ + 2H₂O
• ZnCO₃ + H₂SO₄ → ZnSO₄ + CO₂↑ + H₂O

الكشف عن أيون الكبريتات:
BaCl₂ + SO₄²⁻ → BaSO₄↓ + 2Cl⁻ (راسب أبيض)'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• يوجد الكبريت في الطبيعة حراً ومركبات (الخيار الثالث).
• عناصر مثل الكبريت والفسفور والكاربون تظهر بأشكال مختلفة تدعى صور العنصر.
• الجزيء الذي يحتوي ثماني ذرات: الكبريت (S₈).
• الصفة الإلكترونية المشتركة: امتلاك ست إلكترونات في الغلاف الخارجي.
• عند تمرير H₂S في كبريتات النحاس يتكوّن راسب أسود من كبريتيد النحاس CuS؛ وفي كبريتات الخارصين راسب أبيض من كبريتيد الخارصين ZnS.
• تفاعل H₂S مع كبريتات الخارصين: H₂S + ZnSO₄ → ZnS↓ + H₂SO₄.

أسئلة للمراجعة:
1) تتدرج الخواص الفيزيائية لعناصر الزمرة VIA من الأوكسجين إلى البولونيوم، اذكر هذه الصفات.
2) كيف يُستخرج الكبريت بطريقة فراش؟ ما الذي يُمرَّر في الأنبوبة الخارجية؟ وما دور الأنبوبة الداخلية؟
3) كيف تفصل خليطاً ناعماً من ملح الطعام والطباشير والكبريت؟
4) اكتب معادلات موزونة لتفاعل الكبريت المباشر مع الفلزات واللافلزات.
5) اشرح باختصار طريقة التلامس لتصنيع حامض الكبريتيك مع المعادلات.
6) أكمل ووازن: FeS + H₂SO₄ → ؟ ، SO₃ + H₂O → ؟ ، BaCl₂ + SO₄²⁻ → ؟
7) ما استعمالات ثنائي أوكسيد الكبريت وما أضراره؟
8) اذكر ثلاثة استعمالات لحامض الكبريتيك.'''),
  ]),
  Chapter('الفصل التاسع: الزمرة السابعة (الكلور وكلوريد الهيدروجين)', [
    Section('الملخص', Icons.notes, '''عناصر الزمرة VIIA (الهالوجينات):
• الفلور F، الكلور Cl، البروم Br، اليود I، الأستاتين At.
• تتميز بصفات لافلزية عالية وهي شديدة الفعالية، لذا لا توجد حرة في الطبيعة بل متحدة مع غيرها.

الصفات العامة:
• جميعها تحتوي على سبعة إلكترونات في الغلاف الخارجي وتميل إلى اكتساب إلكترون واحد لإشباعه، وتتدرج قابليتها على اكتساب الإلكترون من الفلور إلى اليود.
• في درجة الحرارة الاعتيادية: الفلور (F₂) والكلور (Cl₂) غازان، والبروم (Br₂) سائل، واليود (I₂) صلب.
• مواد ملونة لأنها تمتص جزءاً من الأشعة المرئية الساقطة عليها.
• تزداد درجتا انصهار وغليان الهالوجينات مع ازدياد العدد الذري.

الكلور Cl (العدد الذري 17، العدد الكتلي 35، الترتيب 2, 8, 7):
• تعرّف عليه العالم شل (Scheele) لأول مرة عام 1774 من تفاعل MnO₂ مع حامض HCl المركز.
• يميل إلى اكتساب إلكترون واحد، لذلك يكون في معظم مركباته أحادي التكافؤ وعدده التأكسدي (−1)، ويكوّن أيون الكلوريد Cl⁻.

وجوده:
• لا يوجد حراً لفعاليته العالية، وأهم مركباته انتشاراً كلوريد الصوديوم NaCl (ملح الطعام) في ماء البحر والترسبات الملحية.

تحضيره:
• مختبرياً: أكسدة حامض الهيدروكلوريك المركز بثنائي أوكسيد المنغنيز بالتسخين. يُخلَّص الغاز من HCl بإمراره على الماء ثم من الرطوبة بإمراره على H₂SO₄ المركز، ويُجمع بإزاحة الهواء إلى الأعلى.
• MnO₂ في هذا التفاعل ليس عاملاً مساعداً بل عامل مؤكسد (يُستهلك).
• صناعياً: التحليل الكهربائي لمحلول NaCl في الماء أو لمنصهر NaCl (يتصاعد Cl₂ عند القطب الموجب ويتكون الصوديوم عند القطب السالب).

خواصه:
1) لونه أخضر مصفر.
2) أثقل من الهواء (يُجمع بإزاحة الهواء إلى الأعلى).
3) قليل الذوبان في الماء.
4) رائحته خانقة، يهاجم الأنسجة المخاطية للأنف والبلعوم، واستنشاقه بكمية كبيرة يتلف الرئتين ويسبب الموت.
5) يتفاعل بشدة مع الفلزات الفعالة (الصوديوم المسخن يكوّن NaCl وهو مركب أيوني).
6) يتفاعل مع اللافلزات كالفسفور مكوناً كلوريدات الفسفور (مركبات تساهمية).
7) يتحد مع الهيدروجين مكوناً غاز كلوريد الهيدروجين.

استعمالاته:
1) تعقيم مياه الشرب وأحواض السباحة.
2) تحضير بعض العقاقير الطبية.
3) تركيب كثير من المذيبات العضوية الصناعية (الكلوروفورم CHCl₃، ثنائي كلوريد المثيل CH₂Cl₂، رباعي كلوريد الكاربون CCl₄).
4) قصر الألوان النباتية: يتفاعل مع الماء فيحرر الأوكسجين الذري (الفعال) الذي يزيل الألوان ويقتل الجراثيم.
5) قصر ألوان الملابس القطنية بخاصة ولا يُستعمل مع الصوف والحرير الطبيعي لأنه يتلفهما.
6) إمرار الكلور في هيدروكسيد الكالسيوم الجاف يكوّن مسحوقاً أبيض (هايبوكلوريت الكالسيوم Ca(OCl)₂) وهو المادة الفعالة في مسحوق القصر والتعقيم.
• ملاحظة: جفاف الكلور لا يقصر الألوان، فللماء أهمية كبيرة في عملية القصر.

غاز كلوريد الهيدروجين HCl:
• لا يوجد حراً في الطبيعة، لكنه يوجد في العصارات المعدية بشكل محلول حامض الهيدروكلوريك الذي يساعد على هضم البروتينات.
• تحضيره مختبرياً: تفاعل حامض الكبريتيك المركز مع كلوريد الصوديوم بالتسخين، ويُجمع الغاز الجاف.

خواصه:
1) غاز عديم اللون، رائحته خانقة نفاذة.
2) أثقل من الهواء، يُجمع بإزاحة الهواء إلى الأعلى.
3) محلوله المائي (حامض الهيدروكلوريك) حامضي التأثير، يحول ورقة زهرة الشمس الزرقاء إلى الأحمر.
4) كثير الذوبان في الماء (تجربة نافورة كلوريد الهيدروجين بدليل المثيل البرتقالي، ولا تتم في الجو الرطب).
5) يتفاعل مع برادة الحديد مكوناً كلوريد الحديد (II) ومحرراً الهيدروجين.
6) غاز لا يشتعل ولا يساعد على الاشتعال.

الكشف عن غاز HCl:
• يُغمر ساق زجاجي في محلول الأمونيا ثم يُقرَّب من فوهة قنينة الغاز، فتتكون مادة ضبابية بيضاء من كلوريد الأمونيوم.
• محلوله (حامض الهيدروكلوريك) يُكشف عنه بنترات الفضة فيتكون راسب أبيض من AgCl.

الكلوريدات:
• أملاح حامض الهيدروكلوريك، وتنشأ من إحلال فلز أو جذر كالأمونيوم محل هيدروجين الحامض.
• تُحضَّر أيضاً بالاتحاد المباشر بين الكلور والفلزات (NaCl وKCl).
• جميع الكلوريدات تذوب في الماء عدا كلوريد الفضة AgCl وكلوريد الزئبق (II) HgCl₂. أما كلوريد الرصاص PbCl₂ فيذوب في الماء الحار ولا يذوب في البارد.

الكشف عن الكلوريدات:
• بإضافة محلول نترات الفضة إلى محلول الكلوريد (أو إلى حامض الهيدروكلوريك) فيتكون راسب أبيض من كلوريد الفضة، وهو يذوب بسهولة في محلول الأمونيا.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• الهالوجينات: عناصر الزمرة السابعة VIIA (F, Cl, Br, I, At).
• الكلوريدات: أملاح حامض الهيدروكلوريك.
• حامض الهيدروكلوريك: المحلول المائي لغاز كلوريد الهيدروجين.
• هايبوكلوريت الكالسيوم Ca(OCl)₂: المادة الفعالة في مسحوق القصر والتعقيم.
• الأوكسجين الذري (الفعال): الأوكسجين الناتج من تفاعل الكلور مع الماء، وهو يزيل الألوان النباتية ويقتل الجراثيم.

التعاليل:
• لا توجد الهالوجينات حرة في الطبيعة: لشدة فعاليتها وسهولة اتحادها مع غيرها من العناصر.
• تميل ذرة الكلور إلى اكتساب إلكترون واحد: لملء غلافها الخارجي الذي فيه 7 إلكترونات.
• يكون الكلور في مركباته أحادي التكافؤ وعدده التأكسدي (−1): لأنه يميل إلى اكتساب إلكترون واحد لتكوين أيون Cl⁻.
• تُجمع غاز الكلور بإزاحة الهواء إلى الأعلى: لأنه أثقل من الهواء.
• يمر غاز الكلور على الماء ثم على H₂SO₄ المركز: للتخلص من HCl ثم من الرطوبة.
• لا يقصر غاز الكلور الجاف الألوان النباتية إلا بوجود الماء: لأن الماء يتفاعل مع الكلور فيتكون الأوكسجين الذري الذي يقوم بعملية القصر.
• لا يُستعمل الكلور في قصر الصوف والحرير الطبيعي: لأنه يتلفهما.
• ثنائي أوكسيد المنغنيز في تحضير الكلور ليس عاملاً مساعداً: لأنه يُستهلك بعد انتهاء التفاعل، فهو عامل مؤكسد.
• تتكون مادة ضبابية بيضاء عند تقريب محلول الأمونيا من قنينة HCl المركز: لاتحاد غاز HCl مع غاز الأمونيا المنبعث وتكوّن كلوريد الأمونيوم.
• تنافورة HCl تدل على أنه كثير الذوبان في الماء: لتخلخل الضغط في القنينة عند ذوبانه.
• لا تتم تجربة نافورة HCl في الجو الرطب: لأن الغاز يجب أن يكون جافاً.
• يتميز كلوريد الفضة عن غيره: لأنه لا يذوب في الماء (راسب أبيض) ويذوب في محلول الأمونيا.'''),
    Section('المسائل والمعادلات', Icons.calculate, '''الكلور:
• تحضيره مختبرياً: 4HCl + MnO₂ → MnCl₂ + 2H₂O + Cl₂↑ (تسخين)
• صناعياً (تحليل كهربائي لمنصهر NaCl): 2NaCl → 2Na + Cl₂↑
• مع الصوديوم: 2Na + Cl₂ → 2NaCl (تسخين)
• مع الفسفور: 2P + 3Cl₂ → 2PCl₃ (ثلاثي كلوريد الفسفور)
2P + 5Cl₂ → 2PCl₅ (خماسي كلوريد الفسفور)
• مع الهيدروجين: H₂ + Cl₂ → 2HCl
• مع الماء: H₂O + Cl₂ → 2HCl + [O] (أوكسجين ذري)

مسحوق القصر:
• Ca(OH)₂ + Cl₂ → Ca(OCl)₂ + (مسحوق أبيض)
• Ca(OCl)₂ + CO₂ + H₂O → CaCO₃ + 2HClO
• HClO → HCl + [O]

كلوريد الهيدروجين:
• تحضيره: NaCl + H₂SO₄ (مركز) → NaHSO₄ + HCl↑ (تسخين)
• مع الحديد: Fe + 2HCl → FeCl₂ + H₂↑ (تسخين)
• الكشف: NH₃ + HCl → NH₄Cl (مادة ضبابية بيضاء)

الكلوريدات:
• Mg + 2HCl → MgCl₂ + H₂
• NH₄OH + HCl → NH₄Cl + H₂O
• الكشف عن الكلوريد: AgNO₃ + NaCl → AgCl↓ + NaNO₃
• AgNO₃ + HCl → AgCl↓ + HNO₃

حساب مكونات ذرة الكلور:
• العدد الذري 17، العدد الكتلي 35.
• عدد البروتونات = 17، عدد الإلكترونات = 17، عدد النيوترونات = 35 − 17 = 18.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• عدد إلكترونات الغلاف الخارجي لعناصر الزمرة السابعة: 7.
• تميل عناصر الزمرة السابعة إلى اكتساب إلكترون واحد لإشباع غلافها الخارجي.
• أهم مركب للكلور في الطبيعة ومرتبط بحياة الإنسان: كلوريد الصوديوم.
• لون غاز الكلور: الأخضر المصفر.
• تميل ذرة الكلور عند اتحادها مع الصوديوم إلى اكتساب إلكترون واحد.
• الغاز القادر على قصر الألوان النباتية: الكلور.
• ذرة كلور عددها الكتلي 35 وعددها الذري 17: إلكتروناتها 17، بروتوناتها 17، نيوتروناتها 18.
• أملاح حامض الهيدروكلوريك تسمى الكلوريدات.
• يتفاعل HCl مع كاربونات الكالسيوم فينتج: كلوريد الكالسيوم وثنائي أوكسيد الكاربون وماء.

أسئلة للمراجعة:
1) ما أهم تفاعلات غاز الكلور؟
2) وضح أهم استعمالات غاز الكلور.
3) بيّن مع الرسم جهاز تحضير غاز الكلور مختبرياً مع ذكر أهم خواص هذا الغاز.
4) أكمل ووازن: MnO₂ + HCl → ؟ ، NaCl (منصهر) → ؟ ، Fe + HCl → ؟ ، Mg + HCl → ؟ ، H₂ + Cl₂ → ؟ ، NH₄OH + HCl → ؟
5) علل: يكون الكلور في مركباته على العموم أحادي التكافؤ كما في NaCl.
6) علل: غاز الكلور لا يقصر الألوان النباتية إلا بوجود الماء.
7) علل: تتكون مادة ضبابية عند تقريب محلول الأمونيا من قنينة حامض الهيدروكلوريك المركز.
8) كيف تستدل أو تكشف عن وجود: حامض الهيدروكلوريك، غاز كلوريد الهيدروجين؟
9) ماذا نقصد بالكلوريدات؟ بيّن بمعادلات كيفية الحصول على كلوريد المغنيسيوم وكلوريد الأمونيوم.
10) يحضَّر غاز كلوريد الهيدروجين مختبرياً من تفاعل كلوريد الصوديوم مع حامض الكبريتيك المركز، اكتب المعادلة.'''),
  ]),
];

const List<Chapter> physics = [
  Chapter('الفصل الأول: الكهربائية الساكنة', [
    Section('الملخص', Icons.notes, '''مقدمة:
• اكتشف الإغريقي طاليس (600 ق.م) أن الكهرمان (Amber) عند دلكه بالصوف يجذب الأجسام الخفيفة، ومنه اشتُقت كلمة الكهربائية (Electron).
• أطلق العالم وليم كلبرت (1600م) اسم الكهربائية على هذه الظاهرة.
• أمثلة: انجذاب قصاصات الورق إلى مشط مدلوك، التصاق البالون المدلوك بالجدار، الصعقة الخفيفة عند لمس مقبض معدني بعد المشي على سجادة صوف، انجذاب ماء الحنفية نحو مشط مشحون.
• الهواء الرطب يساعد على تفريغ الشحنات بسرعة.

الشحنة الكهربائية:
• الذرة: إلكترونات سالبة (e⁻) تدور حول النواة، ونواة فيها بروتونات موجبة (p⁺) ونيوترونات متعادلة (n).
• معظم الذرات متعادلة (عدد الإلكترونات = عدد البروتونات).
• الجسم الذي فقد إلكترونات يصبح موجب الشحنة (+q)، والذي اكتسبها يصبح سالب الشحنة (−q).
• شحنة البروتون تساوي مقدار شحنة الإلكترون، وهي أصغر وحدة شحنة.
• شحنة أي جسم = مضاعفات صحيحة لشحنة الإلكترون.
• شحنة الإلكترون = 1.6 × 10⁻¹⁹ كولوم.
• الكولوم (C) وحدة قياس الشحنة، ويعادل شحنة 6.25 × 10¹⁸ إلكتروناً.
• 1 μC = 10⁻⁶ C ، 1 nC = 10⁻⁹ C.

التجاذب والتنافر:
• الشحنات المتشابهة تتنافر، والمختلفة تتجاذب.
• ساقا المطاط المدلوكتان بالصوف (سالبتان) تتنافران، وساقا الزجاج المدلوكتان بالحرير (موجبتان) تتنافران، وساق زجاج مع ساق مطاط تتجاذبان.

طرائق الشحن:
1) الدلك: عند دلك بالون بقطعة صوف تظهر شحنة موجبة على الصوف (فقدت إلكترونات) وسالبة على البالون (اكتسبها).
2) التماس: يلامس جسم مشحون جسماً متعادلاً فينتقل إليه جزء من الشحنة فيصبح مشحوناً بالشحنة نفسها (تنافر الكرتين).
3) الحث: تقريب ساق مشحونة (سالبة مثلاً) من كرة معدنية معزولة متعادلة؛ تتنافر الإلكترونات إلى الجهة البعيدة (شحنات طليقة) وتظهر شحنة موجبة في الجهة القريبة (شحنات مقيدة). عند التأريض تتسرب الطليقة إلى الأرض، ثم يُقطع التأريض ثم تُبعد الساق فتتوزع الشحنة المقيدة (المخالفة لشحنة الساق) بانتظام على سطح الكرة.
• الجسم المؤرض: موصل مشحون موصول بالأرض فتتعادل شحنته.

الكشاف الكهربائي:
• جهاز يكشف وجود الشحنة على جسم ويعرف نوعها.
• أجزاؤه: ساق معدنية، قرص (أو كرة) معدني في الطرف العلوي، ورقتان رقيقتان من الذهب أو الألمنيوم في الطرف السفلي، صندوق بنافذة زجاجية، سداد من الفلين أو المطاط لعزل الساق عن الصندوق.

شحن الكشاف:
• بالتماس (التوصيل): تنفرج ورقتاه لاكتسابهما شحنة مماثلة لشحنة الجسم الملامس.
• بالحث: يُقرَّب ساق مشحونة من القرص فيشحن القرص بشحنة مخالفة والورقتان بشحنة مشابهة (تنفرجان). عند وصل القرص بالأرض (بالإصبع) تنطبق الورقتان، ثم يُرفع الإصبع ثم تُبعد الساق فتنفرج الورقتان بشحنة مخالفة لشحنة الساق.

تطبيقات الكهربائية الساكنة:
• المرذاذ (صبغ السيارات): فوهة المرذاذ بالقطب الموجب فتتشحن قطيرات الصبغة بشحنة موجبة فتتنافر وتتباعد، والجسم المطلوب صبغه يوصل بالقطب السالب أو بالأرض فتنجذب القطيرات إليه فيتجانس الصبغ.
• أجهزة الاستنساخ، وأجهزة الترسيب في معامل الأسمنت لتقليل التلوث، وتثبيت مواد التجميل والعدسات اللاصقة.

الموصلات والعوازل:
• الموصلات: مواد فيها وفرة من الإلكترونات ضعيفة الارتباط بالنواة تتحرك بسهولة (النحاس والفضة والألمنيوم).
• العوازل: مواد لا تتحرك فيها الشحنات بحرية (الزجاج والصوف والمطاط).
• أشباه الموصلات (السيليكون والجرمانيوم) توصل في ظروف معينة وتعزل في أخرى.
• ساق النحاس الممسوكة باليد لا تنشحن بالدلك لأن الشحنات تتسرب عبر الجسم إلى الأرض، لكنها تنشحن إذا أُمسكت بمقبض عازل.

قانون كولوم:
• القوة الكهربائية المتبادلة بين شحنتين نقطيتين ساكنتين تتناسب طردياً مع حاصل ضرب مقداريهما وعكسياً مع مربع البعد بينهما.
• F = k · q₁ · q₂ / r²
• k = 9 × 10⁹ N·m²/C² في الفراغ.
• القوى المتبادلة تخضع للقانون الثالث لنيوتن: F₂₁ = −F₁₂.

المجال الكهربائي:
• الحيز المحيط بشحنة والذي تظهر فيه تأثيرات قوة كهربائية.
• يُختبر بشحنة اختبار صغيرة موجبة (q′).
• E = F / q′ ووحدته N/C.
• خطوط المجال غير مرئية، تبدأ من الشحنة الموجبة وتنتهي بالسالبة.
• المجال المنتظم: يتولد بين لوحين معدنيين متوازيين مشحونين بشحنتين متساويتين مقداراً ومختلفتين نوعاً، خطوطه متوازية متساوية الأبعاد وعمودية على اللوحين (ثابت المقدار والاتجاه).'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• الكهربائية الساكنة: الشحنات الكهربائية المتولدة على الأجسام والتي لا تتحرك (ساكنة).
• الكولوم: وحدة قياس الشحنة، يعادل شحنة 6.25×10¹⁸ إلكتروناً.
• الشحنات الطليقة: الإلكترونات التي تنتقل إلى الجهة البعيدة عن الجسم المشحون في الحث.
• الشحنات المقيدة: الشحنات المخالفة في الجهة القريبة من الجسم المؤثر.
• الكشاف الكهربائي: جهاز للكشف عن وجود الشحنة ونوعها.
• الموصل: مادة تتحرك فيها الإلكترونات بسهولة.
• العازل: مادة لا تتحرك فيها الشحنات بحرية.
• الجسم المؤرض: جسم موصول بالأرض فتتعادل شحنته.
• المجال الكهربائي: الحيز المحيط بالشحنة وتظهر فيه تأثيراتها.
• شدة المجال الكهربائي: القوة الكهربائية المؤثرة في وحدة الشحنة الموجبة (شحنة الاختبار).
• المجال المنتظم: المجال الثابت المقدار والاتجاه في جميع نقاطه.

التعاليل:
• ينجذب الورق إلى المشط المدلوك: لأن المشط صار مشحوناً بشحنات كهربائية ساكنة.
• يلتصق البالون بالجدار ساعات في الجو الجاف: لأن الهواء الرطب يساعد على تفريغ الشحنات بسرعة.
• تتعادل شحنة الجسم المشحون عند إيصاله بالأرض: لأن الأرض مستودع كبير لتصريف الشحنات.
• تُجهَّز سيارات نقل الوقود بسلاسل معدنية تلامس الأرض: لتفريغ الشحنات المتولدة بالاحتكاك ومنع حدوث الشرارة.
• تشعر بصعقة عند لمس مقبض الباب بعد المشي على سجادة: لتفرّغ الشحنات التي اكتسبها جسمك بالاحتكاك.
• تنفرج ورقتا الكشاف المشحون بالتماس: لاكتسابهما شحنة مماثلة فتتنافران.
• يزداد انفراج ورقتي الكشاف المشحون سالباً عند تقريب جسم سالب من قرصه: لأن إلكترونات إضافية تُدفع إلى الورقتين فتزداد شحنتهما.
• لا تنجذب القصاصات إلى ساق النحاس الممسوكة باليد بعد دلكها: لأن الشحنات تسربت إلى الأرض عبر الجسم.
• تتوزع الشحنات على سطح الكرة المعدنية بانتظام بعد الحث: لأنها موصلة تتنافر شحناتها فتتوزع على سطحها الخارجي.'''),
    Section('القوانين والمسائل', Icons.calculate, '''القوانين:
• شحنة جسم: q = n × e (e = 1.6 × 10⁻¹⁹ C)
• قانون كولوم: F = k q₁ q₂ / r² ، k = 9 × 10⁹ N·m²/C²
• المجال الكهربائي: E = F / q′ ، ومنه F = q′ E
• وحدة F: نيوتن (N)، وq: كولوم (C)، وr: متر (m)، وE: N/C.
• عند مضاعفة البعد إلى مثليه تقل القوة إلى ربع قيمتها (علاقة عكسية مع r²).

مثال 1 (قانون كولوم):
شحنتان موجبتان: q₁ = +4×10⁻⁶ C وq₂ = +9×10⁻⁶ C، البعد 0.06 m.
F = 9×10⁹ × (4×10⁻⁶ × 9×10⁻⁶) ÷ (0.06)²
F = 9×10⁹ × 36×10⁻¹² ÷ 36×10⁻⁴ = 90 N
القوة موجبة، فهي قوة تنافر. وقوة الشحنة الثانية على الأولى مساوية لها بالمقدار ومعاكسة لها بالاتجاه.

مثال 2 (المجال الكهربائي):
شحنة +2×10⁻⁹ C تأثرت بقوة 4×10⁻⁶ N.
E = F ÷ q′ = 4×10⁻⁶ ÷ 2×10⁻⁹ = 2×10³ N/C

مسائل الفصل مع الجواب:
1) شحنتان متماثلتان قوة التنافر بينهما 9×10⁻⁷ N والبعد 10 cm: q² = F r² ÷ k ← q = 1×10⁻⁹ C لكل منهما.
2) شحنتان موجبتان 3×10⁻⁹ C لكل منهما والبعد 5 cm: F = 9×10⁹ × 9×10⁻¹⁸ ÷ (0.05)² = 3.24×10⁻⁵ N.
3) شحنة +3 μC في مجال 4×10⁶ N/C: F = qE = 3×10⁻⁶ × 4×10⁶ = 12 N.
4) عدد الإلكترونات المفقودة لشحنة 1.6×10⁻⁹ C: n = 1.6×10⁻⁹ ÷ 1.6×10⁻¹⁹ = 10¹⁰ إلكترون.

مراجعة الأسس (من الكتاب):
• 10ᵃ × 10ᵇ = 10ᵃ⁺ᵇ ، 10ᵃ ÷ 10ᵇ = 10ᵃ⁻ᵇ
• الجذر التربيعي: √(4×10⁶) = 2×10³'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة اختيار مع أجوبتها:
• الذرة المتعادلة: عدد إلكتروناتها يساوي عدد بروتوناتها.
• يصير الجسم موجب الشحنة إذا كان عدد الإلكترونات أقل من عدد البروتونات.
• فقدان شحنة 1.6×10⁻⁹ C يعني فقدان 10¹⁰ إلكترون.
• استبدال إحدى شحنتين موجبتين بسالبة بالمقدار نفسه: لا يتغير مقدار القوة (يتغير نوعها فقط).
• عند مضاعفة البعد من 3 cm إلى 6 cm: F₂ = ¼ F₁.
• الصعقة بعد السير على السجادة سببها الشحنات المتولدة بالاحتكاك بين جسمك والسجادة.
• القوتان المتبادلتان بين جسمين مشحونين: F_AB = −F_BA.
• تقريب جسم موجب من قرص كشاف مشحون موجب: يزداد انفراج الورقتين.
• تقريب جسم سالب من قرص كشاف متصل بالأرض: تبقى الورقتان منطبقتين رغم ظهور شحنة موجبة على القرص.

أسئلة للمراجعة:
1) علل: تجهز سيارات نقل الوقود بسلاسل معدنية تلامس الأرض.
2) علل: تتعادل شحنة الجسم المشحون عند إيصاله بالأرض.
3) علل: يزداد انفراج ورقتي الكشاف المشحون بسالبة عند تقريب جسم سالب من قرصه.
4) وضح كيفية شحن كشاف بشحنة موجبة بساق زجاج موجبة، ثم بساق مطاط سالبة.
5) عدد طرائق شحن الأجسام بالكهربائية الساكنة.
6) طالب قرّب ساقاً موجبة من قرص كشاف ولمسه بإصبعه ثم أبعد الساق ثم رفع إصبعه فانطبقت الورقتان. فسّر ذلك. (لأنه أبعد الساق قبل رفع الإصبع، فتسربت الشحنة المقيدة إلى الأرض.)
7) اذكر نص قانون كولوم مع صيغته.
8) عرّف المجال الكهربائي وما وحدته؟'''),
  ]),
  Chapter('الفصل الثاني: المغناطيسية', [
    Section('الملخص', Icons.notes, '''مفهوم المغناطيسية:
• اكتشف اليونانيون منذ 25 قرناً معدناً يجذب قطع الحديد سمّوه المغنيت، وهو أوكسيد الحديد الأسود Fe₃O₄، ويُعرف بالحجر المغناطيسي.
• المغانط الصناعية: ساق مغناطيسية، ومغناطيس بشكل حرف U.
• استعمالاتها: المغانط الكهربائية الضخمة لرفع الفولاذ وحديد الخردة، السماعات، المولدات والمحركات الكهربائية، التلفاز وأجهزة التسجيل، الحروف المطبعية للآلة الكاتبة، بوصلات الملاحة.
• إبرة البوصلة: مغناطيس دائمي صغير يدور بحرية في مستوى أفقي حول محور شاقولي مدبب.

المواد المغناطيسية (ثلاثة أنواع):
1) الدايامغناطيسية: تتنافر مع المغناطيس القوي تنافراً ضعيفاً (البزموث، الأنتيمون، النحاس، السيليكون، الفضة).
2) البارامغناطيسية: تنجذب بالمغناطيس القوي انجذاباً ضعيفاً (الألمنيوم، الكالسيوم، الصوديوم، التيتانيوم).
3) الفيرومغناطيسية: تنجذب بالمغناطيس الاعتيادي ولها قابلية تمغنط عالية (الحديد، الفولاذ، النيكل، الكوبلت).
• ماسكات الأوراق والدبابيس والإبر (فيرومغناطيسية) تنجذب، أما قلم الرصاص والطباشير والممحاة فلا تتأثر.

الأقطاب المغناطيسية:
• لكل مغناطيس قطبان: شمالي (الباحث عن الشمال) وجنوبي (الباحث عن الجنوب).
• الأقطاب: مناطق في المغناطيس تكون عندها القوة المغناطيسية أعظم ما يمكن (تتجمع عندها برادة الحديد بتركيز عالٍ).
• الأقطاب لا توجد منفردة، بل أزواجاً متساوية بالمقدار ومختلفة بالنوع.
• عند تقطيع المغناطيس إلى قطع كبيرة أو صغيرة، تمتلك كل قطعة قطبين (شمالي وجنوبي).
• الساق المغناطيسية المعلقة من منتصفها تتخذ وضعاً أفقياً بموازاة خط الشمال–الجنوب الجغرافي تقريباً.

القوى بين الأقطاب:
• الأقطاب المتشابهة تتنافر، والمختلفة تتجاذب (كما في الشحنات الكهربائية).

المجال المغناطيسي:
• الحيز الذي يحيط بالمغناطيس ويظهر فيه تأثير القوى المغناطيسية.
• يُمثَّل بخطوط مقفلة غير مرئية تتجه من القطب الشمالي نحو الجنوبي خارج المغناطيس، وتكمل دورتها داخله.
• خطوط المجال لا تتقاطع.
• تُرسم الخطوط باستعمال البوصلة المغناطيسية أو مجموعة بوصلات صغيرة، ويُكشف عنها ببرادة الحديد.
• المجال المغناطيسي ينفذ خلال جسم الإنسان ومواد مختلفة (ورق مقوى سميك، زجاج، ماء).

تمغنط المواد:
1) التمغنط بالدلك: تُدلك إبرة فولاذ بأحد قطبي مغناطيس بحركة بطيئة باتجاه واحد فقط وتُكرر عدة مرات. القطب المتولد في نهاية جهة الدلك يكون مخالفاً لقطب المغناطيس الدالك.
2) التمغنط بالحث (التأثير):
• بالتقريب: يُقرَّب مسمار حديد غير ممغنط من مغناطيس قوي دون تماس فيكتسب المغناطيسية. الطرف القريب من المغناطيس يكون قطباً مخالفاً له، والبعيد قطباً مشابهاً له.
• بالتيار الكهربائي المستمر: وضع الفولاذ داخل ملف مجوف أو لف سلك معزول حوله ووصل طرفي السلك ببطارية، فنحصل على مغناطيس كهربائي (الطريقة المفضلة).

قوة المغناطيس الكهربائي تعتمد على:
• مقدار التيار المستمر في الدائرة.
• عدد لفات السلك.
• نوع المادة المراد مغنطتها.

فقدان المغناطيسية: بالطرق القوي، وبالتسخين الشديد.
• الحافظة المغناطيسية: مادة فيرومغناطيسية تحمي الأجهزة (كالساعات) من التأثيرات المغناطيسية الخارجية وتحفظ المغانط الدائمة من زوال مغناطيسيتها.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• المغناطيس: مادة تجذب إليها قطع الحديد، وله قطبان.
• الحجر المغناطيسي (المغنيت): معدن طبيعي أوكسيد الحديد الأسود Fe₃O₄.
• المواد الدايامغناطيسية: تتنافر مع المغناطيس القوي تنافراً ضعيفاً.
• المواد البارامغناطيسية: تنجذب بالمغناطيس القوي انجذاباً ضعيفاً.
• المواد الفيرومغناطيسية: تنجذب بالمغناطيس الاعتيادي ولها قابلية تمغنط عالية.
• الأقطاب المغناطيسية: مناطق في المغناطيس تكون عندها القوة المغناطيسية أعظم ما يمكن.
• المجال المغناطيسي: الحيز المحيط بالمغناطيس والذي يظهر فيه تأثير القوى المغناطيسية.
• إبرة البوصلة: مغناطيس دائمي صغير يدور بحرية في مستوى أفقي حول محور شاقولي مدبب.
• المغناطيس الكهربائي: مغناطيس ينتج من لف سلك معزول حول قطعة فولاذ ووصله ببطارية.

التعاليل:
• تُستعمل البوصلة لرسم خطوط المجال: لأن إبرتها مغناطيس دائمي صغير يدور بحرية في مستوى أفقي.
• تصنع المغانط الدائمة من الفولاذ: لأنه يحتفظ بمغناطيسيته مدة طويلة.
• تكون المغانط ملائمة لأبواب خزانات الملابس والثلاجة: لأنها تجذب الباب الفيرومغناطيسي فتبقيه مغلقاً بإحكام.
• لا يمكن الحصول على قطب مغناطيسي منفرد: لأن الأقطاب توجد أزواجاً، وعند تقطيع المغناطيس تصبح كل قطعة مغناطيساً ذا قطبين.
• يكتسب مسمار الحديد المغناطيسية عند تقريبه من مغناطيس دون تماس: بالحث (التأثير).
• تتجمع برادة الحديد بتركيز عالٍ عند الأقطاب: لأن القوة المغناطيسية أعظم ما يمكن عندها.
• تنجذب المسامير داخل الأسطوانة الزجاجية المملوءة بالماء نحو المغناطيس: لأن المجال المغناطيسي ينفذ خلال الزجاج والماء.
• يفقد المغناطيس مغناطيسيته بالطرق القوي أو التسخين الشديد: لاضطراب ترتيب الأقطاب المغناطيسية الصغيرة فيه.'''),
    Section('القوانين والمسائل', Icons.calculate, '''قواعد أساسية (الفصل نظري ولا فيه قوانين رياضية):

الأقطاب:
• القطب الشمالي مع الشمالي ← تنافر.
• القطب الجنوبي مع الجنوبي ← تنافر.
• القطب الشمالي مع الجنوبي ← تجاذب.

خطوط المجال المغناطيسي:
• تتجه من الشمالي إلى الجنوبي خارج المغناطيس.
• داخل المغناطيس تتجه من الجنوبي إلى الشمالي (مقفلة).

التمغنط:
• بالدلك: القطب المتولد في طرف إبرة الفولاذ جهة نهاية الدلك = مخالف لقطب المغناطيس الدالك.
• بالحث: الطرف القريب من المغناطيس المؤثر = قطب مخالف له، والطرف البعيد = قطب مشابه له.

العوامل المؤثرة في قوة المغناطيس الكهربائي (تزداد بـ):
• زيادة التيار المستمر.
• زيادة عدد لفات الملف.
• اختيار مادة مناسبة (فيرومغناطيسية).

تصنيف المواد (للحفظ):
• دايا: بزموث، أنتيمون، نحاس، سيليكون، فضة.
• بارا: ألمنيوم، كالسيوم، صوديوم، تيتانيوم.
• فيرو: حديد، فولاذ، نيكل، كوبلت.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة اختيار مع أجوبتها:
• تُستعمل البوصلة لرسم خطوط المجال لأن إبرتها مغناطيس دائمي صغير يدور بحرية في مستوى أفقي حول محور شاقولي مدبب.
• المغانط الدائمية تُصنع من الفولاذ.
• تُصنف المواد حسب خواصها المغناطيسية إلى: دايامغناطيسية وبارامغناطيسية وفيرومغناطيسية.
• خطوط المجال المغناطيسي تتجه من القطب الشمالي نحو الجنوبي خارج المغناطيس.
• عند تقطيع ساق مغناطيسية: تمتلك كل قطعة قطبين، أحدهما شمالي والآخر جنوبي.

أسئلة للمراجعة:
1) علل: في كثير من الأحيان تكون المغانط ملائمة للاستعمال في أبواب خزانات الملابس والثلاجة الكهربائية.
2) لديك ثلاث سيقان متشابهة (ألمنيوم، حديد، مغناطيس دائمي). كيف تميز كلاً منها؟ (قرّب كل ساق من مسامير أو برادة الحديد: المغناطيس هو الذي يجذبها بقوة، ثم قرّب المغناطيس من الساقين الباقيتين: تنجذب الحديد ولا تنجذب الألمنيوم.)
3) ارسم شكل خطوط المجال المغناطيسي في حالات (ساق مستقيمة، مغناطيس U، قطبين متشابهين، قطبين مختلفين).
4) اشرح نشاطاً لمشاهدة خطوط المجال المغناطيسي ببرادة الحديد لساق مغناطيسية مستقيمة (ضع لوح زجاج فوق الساق، انثر برادة الحديد، انقر اللوح بلطف فتترتب البرادة بشكل خطوط المجال).
5) قارن بين التمغنط بالدلك والتمغنط بالحث.
6) ما العوامل التي تعتمد عليها قوة المغناطيس الكهربائي؟
7) كيف يفقد المغناطيس مغناطيسيته؟
8) ما الفرق بين المواد الدايا والبارا والفيرومغناطيسية؟'''),
  ]),
  Chapter('الفصل الثالث: التيار الكهربائي', [
    Section('الملخص', Icons.notes, '''حركة الشحنات:
• الشحنات الساكنة لا تنجز شغلاً، لكنها تنجز شغلاً إذا تحركت خلال أسلاك التوصيل فتشغّل الأجهزة الكهربائية.
• التيار الكهربائي وسيلة لنقل الطاقة الكهربائية من مصادر توليدها (المولدات، البطاريات، الخلايا الشمسية) إلى الأجهزة.

التيار الكهربائي:
• في الموصلات: إلكترونات التكافؤ ضعيفة الارتباط بالنواة، وعند تعرضها لمجال كهربائي خارجي تتحرك بعكس اتجاه المجال لأنها سالبة.
• في العوازل: قوى ارتباط الإلكترونات بالنواة كبيرة جداً فلا تتحرك (الخشب الجاف، البلاستيك، الزجاج، المطاط).
• التيار الإلكتروني: حركة الإلكترونات من القطب السالب للبطارية إلى الموجب خلال أسلاك التوصيل (عكس اتجاه المجال).
• التيار الاصطلاحي: اتجاهه مع اتجاه المجال الكهربائي، من القطب الموجب إلى السالب، وهو المعتمد في دراستنا لتحديد اتجاه التيار.
• في المحاليل الإلكتروليتية: التيار ناتج عن حركة الأيونات الموجبة والسالبة. في أسلاك التوصيل: عن حركة الإلكترونات فقط. وفي الغازات المتأينة (مصباح الفلورسنت): بحركة الأيونات الموجبة والإلكترونات.

مقدار التيار:
• مقدار الشحنة الكلية التي تعبر مقطع موصل في وحدة الزمن: I = q / t
• وحدته الأمبير (A) = كولوم/ثانية.
• 1 mA = 10⁻³ A ، 1 μA = 10⁻⁶ A.
• الأمبير الواحد: تدفق كولوم واحد من الشحنات خلال مقطع موصل في ثانية واحدة.

أنواع التيار:
• المستمر (DC): ثابت الاتجاه (مصادره: مولدات التيار المستمر والبطاريات). تيار البطارية ثابت المقدار والاتجاه (مثالي)، وتيار المولد البسيط ثابت الاتجاه متغير المقدار (غير مثالي).
• المتناوب (AC): متغير المقدار والاتجاه مع الزمن.

الدائرة الكهربائية:
• المسار المغلق الذي تتحرك خلاله الإلكترونات. تتألف من: مصباح (الحمل)، أسلاك توصيل، مفتاح، بطارية.
• المفتوحة: المفتاح مفتوح، لا يتوهج المصباح (فيها قطع).
• المغلقة: المفتاح مغلق، تنساب الإلكترونات ويتوهج المصباح.

الأميتر (قياس التيار):
• يُربط على التوالي مع الحمل (لتنساب خلاله جميع الشحنات).
• مقاومته صغيرة جداً.
• طرفه الموجب (أحمر) يُربط مع القطب الموجب للبطارية (النقطة الأعلى جهداً)، والسالب (أسود) من جهة القطب السالب.
• للتيارات الصغيرة: الملي أميتر.
• قبل القياس يُفتح المفتاح ثم يُغلق بعد التأكد من صحة الربط.

فرق الجهد الكهربائي:
• يحدد مقدار التيار المنساب بين نقطتين. يسري التيار من النقطة الأعلى جهداً إلى الأوطأ، وإذا تساوى الجهدان توقف التيار.
• وحدته الفولط (V) ويُقاس بالفولطميتر.

الفولطميتر:
• يُربط على التوازي بين طرفي الحمل المراد قياس فرق الجهد بين طرفيه.
• مقاومته كبيرة جداً.
• طرفه الموجب مع القطب الموجب، والسالب مع القطب السالب.
• للفولطيات الصغيرة: الملي فولطميتر (mV).
• فرق الجهد بين قطبي العمود والدائرة مفتوحة (التيار = صفر) يسمى القوة الدافعة الكهربائية (emf).

المقاومة الكهربائية:
• الإعاقة التي يبديها المقاوم للتيار المار فيه (بسبب تصادم الإلكترونات بعضها مع بعض ومع ذرات الموصل، فترتفع حرارته).
• وحدتها الأوم (Ω).
• أنواعها: ثابتة المقدار (تُعرف قيمتها من ألوان الحلقات على سطحها)، ومتغيرة المقدار (الريوستات).
• تُقاس مباشرة بالأوميتر (بشرط أن لا تكون موصولة بدائرة).

قانون أوم:
• نسبة فرق الجهد بين طرفي مقاوم إلى التيار فيه مقدار ثابت (ضمن حدود معينة) هو المقاومة: R = V / I
• الأوم: مقاومة موصل فرق الجهد بين طرفيه فولط واحد والتيار المار فيه أمبير واحد.

العوامل المؤثرة في مقاومة الموصل:
1) درجة الحرارة: الموصلات النقية (النحاس) تزداد مقاومتها بارتفاع الحرارة. الكاربون تقل مقاومته بارتفاعها. المنكانين والكونستنتان مقاومتهما ثابتة تقريباً. وعند خفض الحرارة كثيراً تصبح بعض المواد فائقة التوصيل.
2) الطول: مقاومة الموصل تتناسب طردياً مع طوله.
3) مساحة المقطع العرضي: تتناسب عكسياً مع المساحة.
4) نوع المادة: مقاومة سلك الفضة أصغر من مقاومة سلك حديد مساوٍ له بالطول والمقطع والحرارة.
• R ∝ L / A

ربط المقاومات على التوالي:
• مسرب واحد للتيار. التيار متساوٍ في جميع الأجزاء: I = I₁ = I₂
• فرق الجهد الكلي: V = V₁ + V₂
• المقاومة المكافئة: R_eq = R₁ + R₂
• يقل التيار بزيادة عدد المصابيح لازدياد المقاومة المكافئة، ويقل توهجها.
• إذا تلف مصباح أو رُفع انطفأت جميع المصابيح.

ربط المقاومات على التوازي:
• عدة مسارب للتيار. فرق الجهد متساوٍ: V = V₁ = V₂
• التيار الكلي: I = I₁ + I₂
• المقاومة المكافئة: 1/R_eq = 1/R₁ + 1/R₂
• تقل المقاومة المكافئة بزيادة عدد المقاومات.
• إذا تلف مصباح بقيت المصابيح الأخرى متوهجة (لأنها موصولة مباشرة بالمصدر).
• لذلك تُربط جميع الأجهزة المنزلية على التوازي.

الدائرة القصيرة:
• ربط سلك موصل غليظ بين طرفي مصباح يجعل معظم التيار ينساب في السلك (مقاومته صغيرة جداً) فينطفئ المصباح، ويزداد توهج المصباح الآخر لنقصان المقاومة المكافئة.
• تجنب ربط الأميتر مباشرة مع المصدر دون حمل: يسبب دائرة قصيرة وتيار عالٍ فيتلف الأميتر والبطارية.

ربط الخلايا (الأعمدة):
• على التوالي: الموجب للأولى مع السالب للثانية وهكذا. تُجهَّز فولطية أكبر: emf_total = مجموع emf الخلايا (خليتان 1.5V ← 3V).
• على التوازي: توصل جميع الأقطاب الموجبة معاً والسالبة معاً. تُجهَّز تياراً أكبر، وemf_total = emf الخلية الواحدة (1.5V).'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• التيار الكهربائي: مقدار الشحنة الكهربائية التي تعبر مقطع موصل في وحدة الزمن.
• الأمبير: تدفق كولوم واحد من الشحنات في مقطع موصل خلال ثانية واحدة.
• التيار الاصطلاحي: التيار الذي اتجاهه من القطب الموجب إلى السالب (مع اتجاه المجال).
• التيار الإلكتروني: حركة الإلكترونات من القطب السالب إلى الموجب.
• التيار المستمر DC: تيار ثابت الاتجاه. المتناوب AC: متغير المقدار والاتجاه.
• الدائرة الكهربائية: المسار المغلق الذي تتحرك خلاله الإلكترونات.
• فرق الجهد الكهربائي: ما يحدد مقدار التيار بين نقطتين، ويُقاس بالفولط.
• القوة الدافعة الكهربائية (emf): فرق الجهد بين قطبي العمود عندما تكون الدائرة مفتوحة (التيار = صفر).
• المقاومة الكهربائية: الإعاقة التي يبديها المقاوم للتيار المار فيه.
• الأوم: مقاومة موصل فرق الجهد بين طرفيه 1 فولط والتيار فيه 1 أمبير.
• قانون أوم: R = V / I (نسبة فرق الجهد إلى التيار ثابتة ضمن حدود معينة).
• الدائرة القصيرة: ربط موصل صغير المقاومة بين طرفي جزء من الدائرة فينساب فيه معظم التيار.
• المواد فائقة التوصيل: مواد تصير مثالية في نقل الطاقة عند خفض حرارتها كثيراً.

التعاليل:
• يُربط الأميتر على التوالي: لتنساب خلاله جميع الشحنات المارة في الجزء المراد قياس تياره، ولأن مقاومته صغيرة جداً.
• يُربط الفولطميتر على التوازي: لقياس فرق الجهد بين طرفي الحمل، ومقاومته كبيرة جداً حتى لا يغير التيار.
• يقل توهج المصباح عند تسخين سلك النحاس المربوط معه على التوالي: لازدياد مقاومة النحاس بارتفاع الحرارة فيقل التيار.
• ترتفع حرارة الموصل عند مرور التيار: بسبب تصادم الإلكترونات مع ذرات الموصل.
• تزداد مقاومة الموصل بزيادة طوله: لأن الإلكترونات تواجه تصادمات أكثر.
• تقل مقاومة الموصل بزيادة مساحة مقطعه: لتوفر مسارات أكثر للإلكترونات فيزداد التيار.
• عند ربط مصابيح على التوالي يقل توهجها: لزيادة المقاومة المكافئة ونقصان التيار.
• عند تلف مصباح في دائرة التوالي تنطفئ جميع المصابيح: لوجود مسرب واحد للتيار.
• عند تلف مصباح في دائرة التوازي تبقى الأخرى متوهجة: لأن التيار يتوقف في فرعه فقط وكل مصباح موصول مباشرة بالمصدر.
• تُربط الأجهزة المنزلية على التوازي: لتعمل بالفولطية نفسها وإذا تلف جهاز عملت الأخرى.
• ينطفئ المصباح عند ربط سلك غليظ بين طرفيه ويزداد توهج الآخر: لأن السلك يولّد دائرة قصيرة (معظم التيار فيه) وتقل المقاومة المكافئة فيزداد تيار الدائرة.
• يُمنع ربط الأميتر مباشرة بالمصدر: لأنه يولّد دائرة قصيرة فيمر تيار عالٍ يتلف الجهاز والبطارية.
• تُربط الخلايا على التوالي: للحصول على فولطية أكبر. وعلى التوازي: للحصول على تيار أكبر.'''),
    Section('القوانين والمسائل', Icons.calculate, '''القوانين:
• التيار: I = q / t ← q = I × t
• قانون أوم: R = V / I ← V = I R ← I = V / R
• توالي: R_eq = R₁ + R₂ + … ، I ثابت، V = V₁ + V₂
• توازٍ: 1/R_eq = 1/R₁ + 1/R₂ + … ، V ثابت، I = I₁ + I₂
• R ∝ L / A

أمثلة محلولة:
1) شحنة 1.2 C تعبر مقطع موصل كل دقيقة: I = 1.2 ÷ 60 = 0.02 A
2) تيار 0.4 A: الشحنة خلال 2 s: q = 0.4 × 2 = 0.8 C. خلال 4 دقائق: q = 0.4 × (4×60) = 96 C.
3) ثلاث مقاومات R₁ = 6 Ω ، R₂ = 9 Ω ، R₃ = 18 Ω على التوازي عبر 18 V:
1/R_eq = 1/6 + 1/9 + 1/18 = (3+2+1)/18 = 6/18 ← R_eq = 3 Ω
I₁ = 18÷6 = 3 A ، I₂ = 18÷9 = 2 A ، I₃ = 18÷18 = 1 A
التيار الكلي = 3 + 2 + 1 = 6 A (ويساوي 18 ÷ 3 = 6 A).

مسائل الفصل مع الجواب:
1) شحنة 9 μC في 3 μs: I = 9×10⁻⁶ ÷ 3×10⁻⁶ = 3 A.
2) ثلاث مقاومات 3 Ω و6 Ω و9 Ω على التوازي عبر 18 V:
R_eq = 1.6 Ω تقريباً (1/3 + 1/6 + 1/9 = 11/18)
V₁ = V₂ = V₃ = 18 V
I₁ = 6 A ، I₂ = 3 A ، I₃ = 2 A
3) مقاومتان 2 Ω وR على التوالي عبر 12 V والتيار 2 A:
R_eq = 12 ÷ 2 = 6 Ω ← R = 6 − 2 = 4 Ω
V على 2 Ω = 2×2 = 4 V ، V على R = 2×4 = 8 V (المجموع 12 V).

قياس مقاومة عملياً:
• يُربط الأميتر على التوالي مع المقاومة والفولطميتر على التوازي بين طرفيها، ثم R = قراءة الفولطميتر ÷ قراءة الأميتر.

ربط الخلايا:
• خليتان 1.5 V على التوالي: 3 V. وعلى التوازي: 1.5 V.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة اختيار مع أجوبتها:
• مزايا ربط المصابيح على التوازي: جميع ما ذُكر (تبقى الباقية متوهجة عند تلف أحدها، وكلها متصلة مباشرة بالمصدر، وتوجد عدة مسارب للتيار).
• عند زيادة عدد المقاومات على التوازي: يتساوى فرق الجهد بين طرفي كل مقاومة.
• وحدة المقاومة الكهربائية: الأوم = فولط ÷ أمبير.
• لا يعتمد مقدار مقاومة السلك على: التيار المنساب فيه (يعتمد على الطول والقطر ونوع المادة).
• عند ربط سلك غليظ بين طرفي المصباح الثاني: ينطفئ الثاني مع زيادة توهج الأول.

أسئلة للمراجعة:
1) قياس التيار في حمل: هل يُربط الأميتر على التوالي أم على التوازي؟ وضح. (على التوالي، لتمر فيه جميع الشحنات.)
2) لماذا يُفضَّل ربط المصابيح والأجهزة في المنازل على التوازي؟
3) ما الفرق بين التيار الاصطلاحي والتيار الإلكتروني؟
4) ما الفرق بين الأميتر والفولطميتر في طريقة الربط والمقاومة؟
5) اذكر العوامل التي تتوقف عليها مقاومة موصل.
6) اكتب قانون أوم وعرّف الأوم.
7) قارن بين ربط المقاومات على التوالي وعلى التوازي (التيار، الجهد، المقاومة المكافئة).
8) ما الدائرة القصيرة؟ ولماذا تُجنَّب مع الأميتر؟
9) ما الفرق بين ربط الخلايا على التوالي وعلى التوازي؟
10) ما الفرق بين التيار المستمر والمتناوب؟'''),
  ]),
  Chapter('الفصل الرابع: البطارية والقوة الدافعة الكهربائية', [
    Section('الملخص', Icons.notes, '''مقدمة:
• البطارية: مصدر لإنتاج الطاقة الكهربائية عن طريق التفاعل الكيميائي. تتكون من خلية كهربائية واحدة أو أكثر. اخترعها العالم الإيطالي أليساندو فولطا.
• تُصنع بأحجام مختلفة: صغيرة في الساعات اليدوية، وضخمة تغذي الغواصات (كتلتها نحو 910 kg).
• بطارية الليمون: مسمار مغلون (سالب) وقطعة نحاس (موجب) في ليمونة، فيتولد فرق جهد وينحرف مؤشر الملي أميتر. تنطلق الإلكترونات من المسمار بتأثير المحلول الحامضي نحو النحاس.

الخلية الكهربائية البسيطة:
• صفيحتان من معدنين مختلفين (نحاس وخارصين) في حامض الكبريتيك المخفف. يتولد بينهما فرق جهد نحو فولط واحد (جهد النحاس أكبر من جهد الخارصين) فينساب تيار عند ربطها بدائرة خارجية.
• الكلفانوميتر (G): يتحسس بالتيارات الصغيرة جداً (μA) وينعكس اتجاه انحرافه بانعكاس اتجاه التيار. الملي أميتر (mA) لقياس أجزاء الأمبير.

تصنيف البطاريات:
• حسب الوسط: سائل (بطارية السيارة)، صلب (الخلايا الجافة)، غازي (بطارية الوقود).
• أو حسب إمكانية الشحن: أولية، ثانوية، بطارية وقود.

1) البطارية الأولية: ينتهي مفعولها بعد استهلاك أحد موادها الكيميائية ولا يمكن إعادة شحنها (الخلية الكلفانية البسيطة، الخلية الجافة).
• الخلية الكلفانية (خلية دانيال): نصفا خليتين، لوح خارصين Zn في محلول كبريتات الخارصين ZnSO₄، ولوح نحاس Cu في محلول CuSO₄. ذرات المعدن تترك الإلكترونات على اللوح وتدخل المحلول أيونات موجبة، وتراكم الإلكترونات على لوح الخارصين (القطب السالب) أكبر منه على النحاس (القطب الموجب). الجسر الملحي يربط المحلولين ويساعد على هجرة الأيونات.
• الخلية الجافة (كاربون–خارصين): وعاء خارصين (القطب السالب) في وسطه عمود كاربون (القطب الموجب) محاط بعجينة إلكتروليتية (كلوريد الأمونيوم وكلوريد الخارصين وماء وثنائي أوكسيد المنغنيز ومسحوق الكاربون)، وفتحتها العليا مغلقة بمادة عازلة. فرق جهدها 1.5 V. تُستعمل في كشافات الضوء اليدوية، وأجهزة التحكم عن بعد، وآلات التصوير، ولعب الأطفال.

2) البطارية الثانوية: يمكن إعادة شحنها بإمرار تيار في الاتجاه المعاكس لتيار التفريغ (تحويل طاقة كهربائية إلى كيميائية تُخزن). أمثلتها: بطارية السيارة وبطارية أيون–الليثيوم.
• سحب تيار عالٍ في فترة قصيرة يقصّر عمر الخلية، وخزنها طويلاً يقلل كفاءتها.

بطارية السيارة (رصاص–حامض):
• وعاء بلاستيك أو مطاط صلب فيه 6 خلايا، كل خلية صفائح يحيط بها محلول إلكتروليتي (حامض الكبريتيك وماء مقطر) كثافته النسبية 1.3 عند تمام الشحن.
• كل خلية تولد 2 V، فالست خلايا على التوالي تعطي 12 V.
• ألواح الرصاص Pb (القطب السالب) وألواح أوكسيد الرصاص PbO₂ (القطب الموجب) في حامض الكبريتيك.
• تعطي تياراً عالياً فتُربط بأسلاك توصيل غليظة.

شحن البطارية:
• تُربط بمصدر تيار مستمر (شاحنة): الموجب مع الموجب والسالب مع السالب.
• emf البطارية 12 V، ويجب أن تكون فولطية المصدر الشاحن أكبر قليلاً (نحو 14 V) لتعويض الجهد الضائع في المقاومة الداخلية وأسلاك التوصيل.
• تُرفع الأغطية البلاستيكية أثناء الشحن للتخلص من الغازات المتولدة.

العناية بالبطارية:
1) تجنب سحب تيار عالٍ لفترة طويلة (حرارة تتلف البطارية).
2) إبقاء مستوى الإلكتروليت أعلى من الصفائح بقليل، وعند النقصان يُضاف ماء مقطر مع ثبوت الكثافة 1.3 تقريباً.
3) عدم ترك البطارية مدة طويلة دون استعمال (تتكون طبقة كبريتات عازلة على الألواح).

بطارية أيون–الليثيوم:
• تُستعمل في الحاسوب النقال والموبايل وأجهزة MP3 والكاميرات، وتُشحن مرات عديدة دون أن تضعف.
• غلاف متين يتحمل الضغط والحرارة وفيه صمام أمان.
• ثلاث شرائح رقيقة ملفوفة لولبياً: القطب الموجب (أوكسيد كوبلت الليثيوم)، العازل، القطب السالب (الكاربون)، مغمورة في محلول إلكتروليتي (غالباً الأيثر).
• شريحة العازل (بلاستيك) تعزل القطبين وتسمح للأيونات بالمرور.
• تفقد 5% من شحنتها شهرياً عند عدم الاستعمال، مقابل 20% للبطاريات الجافة.

3) بطارية الوقود (خلية وقود الهيدروجين):
• تولد تياراً بالاعتماد على وقود (مواد كيميائية) يُجهَّز من مصدر خارجي، ولا ينتهي مفعولها ما دامت مجهزة بالوقود.
• تحول الطاقة الكيميائية إلى كهربائية: غاز الهيدروجين وأوكسجين الجو يتحولان إلى ماء وطاقة كهربائية.
• شرائح رقيقة تولد كل منها 1 V، ويزداد فرق الجهد بزيادة عدد الشرائح الموصولة على التوالي.
• تُستعمل في الحاسوب وتسيير المركبات الحديثة.
• مزاياها: لا تلوث البيئة ولا تستهلك الوقود التقليدي (الهيدروجين ينتج من الماء ويعود ماءً)، آمنة، كفاءتها عالية جداً (تحويل مباشر دون فقدان)، عمرها طويل.

القوة الدافعة الكهربائية (emf):
• فرق الجهد بين القطبين الموجب والسالب لأي بطارية عندما تكون الدائرة مفتوحة.
• هي مقدار الطاقة التي تزودها البطارية لوحدة الشحنة: emf = W / q
• وحدتها: الجول/كولوم = فولط. وتُقاس بالفولطميتر.
• معنى emf = 1.5 V: أن البطارية تعطي 1.5 جول من الطاقة لكل كولوم يمر خلالها.

المقاومة الداخلية (r):
• الإعاقة التي تبديها مادة الوسط (المركبات الكيميائية) داخل البطارية لحركة الشحنات خلالها.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• البطارية: مصدر لإنتاج الطاقة الكهربائية بالتفاعل الكيميائي.
• الخلية الكهربائية البسيطة: صفيحتان من معدنين مختلفين في محلول حامضي يتولد بينهما فرق جهد.
• البطارية الأولية: لا يمكن إعادة شحنها.
• البطارية الثانوية: يمكن إعادة شحنها بإمرار تيار معاكس لتيار التفريغ.
• بطارية الوقود: خلية تولد التيار بوقود يُجهز من مصدر خارجي ولا ينتهي مفعولها.
• القوة الدافعة الكهربائية (emf): الطاقة التي تزودها البطارية لوحدة الشحنة، أو فرق الجهد بين قطبيها والدائرة مفتوحة.
• المقاومة الداخلية: إعاقة مادة الوسط داخل البطارية لحركة الشحنات.
• الجسر الملحي: يربط محلولي الإنائين ويساعد على هجرة الأيونات.

التعاليل:
• تتحول الطاقة الكيميائية إلى كهربائية في الخلية: بسبب التفاعل الكيميائي بين الصفيحتين والمحلول.
• يتولد فرق جهد بين نحاس وخارصين: لأن جهد النحاس أكبر من جهد الخارصين.
• الخلية الكلفانية بطارية أولية: لأنها لا يمكن إعادة شحنها.
• تُربط بطارية السيارة بأسلاك غليظة: لأنها تعطي تياراً عالياً.
• بطارية السيارة 12 V: لأنها 6 خلايا على التوالي كل منها 2 V.
• يجب أن تكون فولطية المصدر الشاحن أكبر قليلاً من emf البطارية: لتعويض الجهد الضائع في المقاومة الداخلية وأسلاك التوصيل.
• تُرفع الأغطية البلاستيكية عند شحن بطارية السيارة: للتخلص من الغازات المتولدة.
• يُضاف الماء المقطر لبطارية السيارة: لتعويض نقصان المحلول بالتبخر مع ثبوت كثافته 1.3.
• لا تُترك البطارية الحامضية مدة طويلة دون استعمال: لتكوّن طبقة كبريتات عازلة على ألواحها.
• لا يُسحب تيار عالٍ من بطارية السيارة مدة طويلة: لتوليد كمية كبيرة من الحرارة تتلفها.
• تتميز بطارية أيون–الليثيوم باحتفاظها بالشحنة: فتفقد 5% شهرياً فقط.
• لخلية الوقود كفاءة عالية: لأنها تحول الطاقة الكيميائية إلى كهربائية مباشرة دون فقدان.
• خلية وقود الهيدروجين لا تلوث البيئة: لأن الهيدروجين ينتج من الماء ويعود إلى ماء.'''),
    Section('القوانين والمسائل', Icons.calculate, '''القوانين:
• القوة الدافعة الكهربائية: emf = W / q (جول/كولوم = فولط)
• الشغل (الطاقة): W = emf × q
• الشحنة: q = W / emf
• الخلايا على التوالي: emf_total = مجموع الـ emf.
• الخلايا على التوازي: emf_total = emf الخلية الواحدة.
• بطارية السيارة: 6 × 2 V = 12 V.

مثال محلول:
انسابت شحنة 10 C خلال بطارية فاكتسبت طاقة 20 J. احسب emf:
emf = W ÷ q = 20 ÷ 10 = 2 V

مسائل الفصل مع الجواب:
1) الشغل على شحنة 2 C في دائرة بطارية emf = 1.5 V:
W = emf × q = 1.5 × 2 = 3 J
2) بطارية emf = 12 V والشغل الذي تزوده لتحريك الشحنة 120 J. احسب الشحنة:
q = W ÷ emf = 120 ÷ 12 = 10 C'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة اختيار مع أجوبتها:
• وحدة emf هي الفولط، وتساوي جول/كولوم (J/C).
• الخلية الكلفانية البسيطة: بطارية أولية.
• بطارية السيارة 12 V: ست خلايا جميعها على التوالي.
• شريحة العازل في بطارية أيون–الليثيوم: تسمح للأيونات بالمرور خلالها.
• عند شحن بطارية السيارة: فولطية المصدر أكبر قليلاً من emf البطارية.
• خلية وقود الهيدروجين: تحول الطاقة الكيميائية إلى طاقة كهربائية.

أسئلة للمراجعة:
1) ما البطارية الثانوية؟ اذكر مثالاً لها. (بطارية يمكن إعادة شحنها، كبطارية السيارة.)
2) ما نوع الطاقة المخزونة في البطارية الثانوية؟ (طاقة كيميائية.)
3) وضّح بالرسم عملية شحن بطارية السيارة.
4) ما الإجراءات اللازمة للعناية ببطارية السيارة وإدامتها؟
5) اذكر أربعة أجهزة تستعمل فيها البطارية الجافة.
6) ما مزايا خلية وقود الهيدروجين؟
7) ما مكونات كل من الخلية الجافة وبطارية أيون–الليثيوم؟
8) ما الفرق بين البطارية الأولية والثانوية؟
9) ماذا نعني بأن emf لبطارية = 1.5 فولط؟
10) ما المقاومة الداخلية للبطارية؟'''),
  ]),
  Chapter('الفصل الخامس: الطاقة والقدرة الكهربائية', [
    Section('الملخص', Icons.notes, '''القدرة الكهربائية:
• عند تشغيل أي جهاز كهربائي يستهلك مقداراً من الطاقة الكهربائية ويحولها إلى طاقة أخرى: حركية (المحركات)، حرارية (المدافئ)، ضوئية (المصابيح).
• القدرة الكهربائية المستهلكة في الجهاز: مقدار الطاقة التي يستهلكها (أو يستثمرها) الجهاز في وحدة الزمن.
• P = E / t ، وحدتها الواط (W) = جول/ثانية.
• المصباح 20 W يستهلك 20 J في كل ثانية، والمصباح 100 W يستهلك 100 J في كل ثانية، لذا إضاءته أكبر.
• القدرة تعتمد على التيار وفرق الجهد: P = I × V (1 واط = 1 أمبير × 1 فولط).
• وبتطبيق قانون أوم: P = I² R ، و P = V² / R
• الطاقة الكهربائية = القدرة × الزمن.
• الأجهزة الكهربائية في المنازل توصل على التوازي.

سطوع المصابيح المتماثلة:
• التيار المنساب في خويط المصباح هو الذي يؤثر في مقدار توهجه.
• تيار الدائرة يتأثر بـ: فرق الجهد بين طرفي الدائرة، وعدد المصابيح (مقاومة الدائرة) وطريقة ربطها.
• زيادة عدد الأعمدة تزيد فرق الجهد على المصباح فيزداد التيار والتوهج والقدرة (P = V²/R).
• زيادة عدد المصابيح على التوالي تزيد المقاومة المكافئة فيقل التيار ويقل التوهج.
• مصباحان 60 W و30 W على التوازي: مقاومة الأول أقل من الثاني (R = V²/P)، والتيار في الأول أكبر، وإضاءته أكبر، وفرق الجهد بينهما متساوٍ.

الطاقة الكهربائية وحسابها:
• E = P × t (جول = واط × ثانية).
• الوحدة التجارية: الكيلو واط–ساعة (kW-h).
• كلفة الطاقة = القدرة (kW) × الزمن (h) × ثمن الوحدة (دينار لكل kW-h).
• تركّب وزارة الكهرباء في كل منزل مقياساً لتسجيل الطاقة المستهلكة.

الكهرباء في بيوتنا:
• تجهزنا محطات التوليد بسلكين يمر فيهما تيار متناوب فرق الجهد بينهما 220 V.
• السلك الحي (الحار) L: جهده 220 V.
• السلك المتعادل (البارد) N: يحمل التيار أيضاً لكنه مؤرض عند محطة القدرة فجهده ليس عالياً.

الدوائر المؤرضة:
• السلك المؤرض E: متصل بالأرض وهو سلك الأمان. عند حدوث خلل أو تماس بين السلك الحي والغلاف المعدني للجهاز ينساب معظم التيار من السلك الحي إلى الأرض عبر سلك التأريض، فيقل خطر الصعقة.
• القابس ذو الفاصم: يتركب من السلك الحي L والمتعادل N والمؤرض E والفاصم، وهي جميعاً وسائل الأمان.
• الفاصم (Fuse): سلك فلزي لا يتحمل تياراً أكبر من حد معين، فإذا تجاوزه سخن وانصهر وانقطع التيار عن الجهاز.
• يُوضع الفاصم على التوالي مع السلك الحي قبل دخول التيار إلى الجهاز.
• القاطع الكهربائي (قاطع الدورة): يقطع التيار تلقائياً عند انسياب تيار أكبر من التيار المصمم له.

تجنب الصعقة الكهربائية:
• التأريض: الاتصال بالأرض، ويُرمز له بالرمز ⏚.
• تُؤرض الأجهزة ذات الغلاف المعدني لأن سلك التأريض غليظ ومقاومته صغيرة جداً (أقل من مقاومة جسم الإنسان)، فينساب التيار فيه لا في جسم الشخص.
• الغسالة بقابس ثنائي: إن لامس السلك الحار غلافها المعدني ولمسها شخص مر التيار عبر جسمه إلى الأرض فيُصعق. وبقابس ثلاثي (فيه سلك التأريض) لا تحدث الصعقة.
• تأثير التيار في الجسم: 0.005 A ألم بسيط، 0.01 A تنقبض العضلات، 0.1 A لثوانٍ قليلة قد يؤدي إلى الموت.

إجراءات السلامة:
1) لا تلمس شخصاً تعرض لصعقة إلا بعد فصله عن مصدر الكهرباء.
2) تجنب وضع جسم معدني ممسوك باليد (مسمار حديد أو سلك غير معزول) في نقطة الكهرباء.
3) لا تترك الأسلاك متهرئة (مكشوفة بدون عازل).
4) تجنب أن يتصل جسمك بين السلك الحي والمتعادل، أو بين الحي والأرض.

ترشيد الاستهلاك:
• الاستخدام الأمثل للطاقة: استغلال الإضاءة الطبيعية نهاراً، وإطفاء الإنارة وأجهزة التبريد والتدفئة في الغرف غير المستعملة، واستعمال المصابيح الاقتصادية (الفلورسنت).'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• القدرة الكهربائية: مقدار الطاقة التي يستهلكها الجهاز في وحدة الزمن.
• الواط: قدرة جهاز يستهلك جولاً واحداً من الطاقة في ثانية واحدة.
• الكيلو واط–ساعة: وحدة قياس الطاقة الكهربائية المستهلكة تجارياً.
• السلك الحي (الحار): سلك جهده 220 V.
• السلك المتعادل (البارد): سلك مؤرض عند محطة القدرة.
• سلك التأريض (سلك الأمان): سلك يصل الغلاف المعدني للجهاز بالأرض.
• الفاصم: سلك فلزي ينصهر إذا تجاوز التيار حداً معيناً فيقطع الدائرة.
• القاطع الكهربائي: جهاز يقطع التيار تلقائياً عند تجاوز التيار المصمم له.
• التأريض: الاتصال بالأرض.
• الترشيد: الاستخدام الأمثل لموارد الطاقة الكهربائية.

التعاليل:
• المصباح 100 W إضاءته أكبر من 20 W: لأنه يستهلك طاقة أكبر في الثانية (100 J مقابل 20 J).
• يُربط الفاصم (والقاطع) على التوالي مع السلك الحي قبل دخول التيار إلى الجهاز: ليقطع الدائرة عند انسياب تيار أكبر من المناسب فيحمي الجهاز.
• تُؤرض الأجهزة ذات الغلاف المعدني: لأن سلك التأريض غليظ مقاومته أقل من مقاومة الجسم فيمر معظم التيار فيه ولا يمر في جسم من يلمس الجهاز.
• يمكن لطائر أن يقف على سلك جهد عالٍ دون أن يُصعق: لأن قدميه على نقطتين متساويتي الجهد تقريباً فلا يوجد فرق جهد بينهما فلا يمر تيار في جسمه (ولا يتصل بالأرض).
• يُربط القاطع على التوالي (لا على التوازي) مع الجهاز: ليمر فيه كل تيار الجهاز فيقطعه عند زيادته.
• تُربط الأجهزة المنزلية على التوازي: لتعمل كلها بفولطية 220 V ولا تتوقف بعطب أحدها.
• يزداد توهج المصباح بزيادة عدد الأعمدة: لزيادة فرق الجهد فيزداد التيار والقدرة.
• يقل توهج المصباح بزيادة عدد المصابيح على التوالي: لزيادة المقاومة المكافئة ونقصان التيار.'''),
    Section('القوانين والمسائل', Icons.calculate, '''القوانين:
• P = E / t ← E = P × t
• P = I × V
• P = I² × R
• P = V² / R
• E (جول) = P (واط) × t (ثانية)
• الكلفة = P (kW) × t (h) × ثمن الوحدة (دينار/kW-h)
• 1 kW = 1000 W ، 1 h = 3600 s ، 1 min = 60 s

أمثلة محلولة:
1) مدفأة عليها 220 V ومقاومة أحد أسلاك التسخين 88 Ω:
القدرة: P = V² ÷ R = (220)² ÷ 88 = 550 W
التيار: I = V ÷ R = 220 ÷ 88 = 2.5 A
2) مجفف شعر 1500 W لمدة 20 دقيقة:
t = 20 × 60 = 1200 s ← E = 1500 × 1200 = 1 800 000 J = 1800 kJ
3) إبريق شاي 220 V وتياره 10 A:
P = I × V = 10 × 220 = 2200 W
E خلال 20 s = 2200 × 20 = 44 000 J = 44 kJ
4) مكنسة كهربائية 1000 W لمدة 30 دقيقة وثمن الوحدة 100 دينار:
P = 1 kW ، t = 0.5 h
الكلفة = 1 × 0.5 × 100 = 50 دينار

مسائل الفصل مع الجواب:
1) فولطميتر 3 V وأميتر 0.5 A:
R = V ÷ I = 3 ÷ 0.5 = 6 Ω
P = I × V = 0.5 × 3 = 1.5 W
2) مقاومتان 90 Ω و180 Ω على التوازي عبر 36 V:
I₁ = 36 ÷ 90 = 0.4 A ، I₂ = 36 ÷ 180 = 0.2 A
P₁ = V²/R = 1296 ÷ 90 = 14.4 W ، P₂ = 1296 ÷ 180 = 7.2 W
(أو P = I²R: 0.16 × 90 = 14.4 W ، 0.04 × 180 = 7.2 W)
الاستنتاج: في التوازي تستهلك المقاومة الأصغر قدرة أكبر.
3) مصباح (21 V، 24 W) لمدة 10 ساعات:
E = 0.024 kW × 10 h = 0.24 kW-h
4) سخان 2 kW لمدة 6 ساعات وثمن الوحدة 100 دينار:
الكلفة = 2 × 6 × 100 = 1200 دينار'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة اختيار مع أجوبتها:
• الفاصم يجب أن يُربط على التوالي مع السلك الحي.
• الكيلو واط–ساعة (kW-h) وحدة قياس الطاقة الكهربائية.
• ليست وحدة للقدرة: جول × ثانية (J × s).
• إبريق 1200 W وتياره 5 A: V = P ÷ I = 1200 ÷ 5 = 240 V.
• جهاز يستثمر 18000 J في 5 دقائق: P = 18000 ÷ 300 = 60 W.

أسئلة للمراجعة:
1) علل: يُربط قاطع الدورة على التوالي مع السلك الحار قبل تجهيز الأجهزة بالطاقة.
2) علل: تُؤرض الأجهزة الكهربائية وبخاصة ذات الغلاف المعدني.
3) علل: يمكن لطائر أن يقف على سلك مكشوف من أسلاك الجهد العالي دون أن يُصاب بصعقة.
4) هل يُربط قاطع الدورة على التوالي أم على التوازي مع الجهاز المراد حمايته؟ ولماذا؟
5) عرّف القدرة الكهربائية وما وحدتها؟
6) اكتب قوانين القدرة الثلاثة (P = IV و P = I²R و P = V²/R).
7) كيف تحسب كلفة الطاقة الكهربائية المستهلكة؟
8) عدد أجزاء القابس ذي الفاصم.
9) اذكر إجراءات السلامة من مخاطر الكهرباء.
10) ما أهمية الترشيد في استعمال الطاقة الكهربائية؟'''),
  ]),
  Chapter('الفصل السادس: الكهربائية والمغناطيسية', [
    Section('الملخص', Icons.notes, '''تجربة أورستد (1820م):
• لاحظ انحراف إبرة مغناطيسية موضوعة بجوار سلك عند انسياب تيار مستمر فيه.
• الإبرة تنحرف ثم تستقر بوضع عمودي على طول السلك، وتعود إلى وضعها السابق عند انقطاع التيار، وينعكس اتجاه انحرافها بعكس اتجاه التيار.
• الاستنتاج: انسياب تيار كهربائي في سلك موصل يولد حوله مجالاً مغناطيسياً.
• يُغلق المفتاح لبرهة فقط لأن التيار العالي في السلك الغليظ يسبب حرارة ويُنهك البطارية.

المجال حول سلك مستقيم:
• تترتب برادة الحديد بشكل دوائر متحدة المركز مركزها السلك في مستوى عمودي عليه، وهي خطوط المجال.
• اتجاه الأقطاب الشمالية لأبر البوصلات يمثل اتجاه المجال في تلك النقطة.
• قاعدة الكف اليمنى (للسلك المستقيم): أمسك السلك بالكف اليمنى بحيث يشير الإبهام إلى اتجاه التيار، فيكون اتجاه لف الأصابع هو اتجاه المجال المغناطيسي.
• العوامل: يزداد المجال بزيادة التيار، ويزداد بالاقتراب من السلك ويقل بالابتعاد عنه، واتجاهه يعتمد على اتجاه التيار.

المجال لحلقة دائرية وملف حلزوني:
• حلقة دائرية: خطوط بيضوية الشكل تقريباً، تزدحم داخل الحلقة وتكون عمودية على مستوى الحلقة.
• الملف الحلزوني: داخله خطوط مستقيمة متوازية، وخارجه خطوط مقفلة (يشبه مجال ساق ممغنطة).
• يتناسب مقدار المجال طردياً مع التيار وعدد اللفات في وحدة الطول.
• قاعدة الكف اليمنى للملف: أمسك الملف بالكف اليمنى بحيث تمثل الأصابع اتجاه التيار، فيشير الإبهام إلى اتجاه المجال داخل الملف (القطب الشمالي).
• الشحنة المتحركة (كالإلكترون حول النواة) تولد مجالاً مغناطيسياً.

المغناطيس الكهربائي:
• مغناطيس مؤقت يزول بزوال التيار. يتركب من قلب من الحديد المطاوع ملفوف حوله سلك موصل معزول (ساق مستقيمة أو بشكل U).
• في شكل U يُلف السلك باتجاهين متعاكسين فيتولد قطبان.
• للاحتفاظ بالمغناطيسية مدة أطول بعد انقطاع التيار يُستعمل الفولاذ بدلاً من الحديد المطاوع.
• يعتمد مجاله على: عدد لفات الملف لوحدة الطول، ونوع مادة القلب، ومقدار التيار.
• يزداد المجال بين قطبي المغناطيس إذا كان بشكل U.

استعمالات المغانط الكهربائية:
• رفع الأثقال الكبيرة.
• الجرس الكهربائي: مغناطيس كهربائي U، وحافظة من الحديد المطاوع، ومسمار محوري، ومطرقة، وناقوس معدني. عند إغلاق المفتاح يجذب المغناطيس قطعة الحديد فتضرب المطرقة الناقوس وتنفتح الدائرة فيفقد مغناطيسيته وتبتعد المطرقة، وتتكرر العملية.
• الهاتف: التكلم أمام اللاقطة يغير التيار بتردد موجات الصوت، وينتقل التغير إلى السماعة الأخرى فيمر عبر مغناطيس كهربائي يجذب قرصاً رقيقاً من الحديد المطاوع فيتذبذب مولداً موجات صوتية مشابهة.
• المرحل الكهربائي: مفتاح مغناطيسي للتحكم في فتح وإغلاق دائرة؛ ففي السيارة يتحكم بدائرة التيار الكبير (المحرك) بتيار صغير عند إدارة مفتاح التشغيل.

الحث الكهرومغناطيسي:
• تحريك سلك (موصول بكلفانوميتر) موازياً لخطوط المجال لا يولد تياراً، وتحريكه عمودياً عليها يولد تياراً (ينحرف المؤشر باتجاهين متعاكسين)، وعند توقفه لا ينحرف المؤشر.
• التيار المحتث: تيار لحظي يتولد في دائرة مقفلة عندما يقطع السلك خطوط المجال المغناطيسي (عند تغير عدد خطوط القوة في وحدة الزمن) دون بطارية.
• تحريك مغناطيس نحو ملف أو سحبه منه يولد تياراً باتجاهين متعاكسين، وعند ثباته لا يتولد تيار.
• القوة الدافعة الكهربائية المحتثة: فرق جهد يتولد على طرفي الموصل ويُقاس بالفولط، اكتشفها فراداي عام 1831م.
• الحث الكهرومغناطيسي: ظاهرة توليد فولطية محتثة عبر موصل في مجال مغناطيسي متغير، أو بحركة نسبية بين الموصل والمجال.
• هو أساس عمل المولد الكهربائي.

المولد الكهربائي للتيار المتناوب:
• يحول الطاقة الميكانيكية (الحركية) إلى طاقة كهربائية بوجود مجال مغناطيسي، ويعمل بمبدأ الحث الكهرومغناطيسي.
• أجزاؤه: ملف من سلك معزول حول قلب حديد مطاوع، حلقتان معدنيتان معزولتان، فرشاتان كاربون، مغناطيس دائمي أو كهربائي بشكل U.
• عند دوران الملف يقطع خطوط المجال فتتولد emf محتثة وتيار متناوب ينتقل عبر الحلقتين والفرشاتين إلى الدائرة الخارجية.

مولد التيار المستمر (الدينامو):
• الأجزاء نفسها، لكنه يستعمل نصفي حلقة معدنية معزولين (المبادل) متصلين بطرفي الملف، فيكون التيار باتجاه واحد (DC).
• في المولدات العملية تُستعمل عدة ملفات وليس ملفاً واحداً، وقد تدور المغانط ويبقى الملف ثابتاً.

المحرك الكهربائي:
• يحول الطاقة الكهربائية إلى ميكانيكية بوجود مجال مغناطيسي (عكس عمل المولد).
• مبدأ عمله: القوة المغناطيسية المؤثرة في سلك ينساب فيه تيار مستمر موضوع في مجال مغناطيسي.
• أجزاء محرك التيار المستمر: نواة (ملف نحاس معزول حول حديد مطاوع)، مغناطيس دائمي قوي، المبادل (نصفا حلقة)، فرشاتان كاربون متصلتان بقطبي مصدر مستمر.
• عند إغلاق الدائرة يمر التيار في طرفي الملف باتجاهين متعاكسين فتتولد قوتان متساويتان ومتعاكستان على جانبيه تديرانه، ويستمر الدوران باتجاه واحد بسبب المبادل.
• استعمالاته: المكنسة الكهربائية، المثقاب، الخلاط، المروحة، والقطارات (محركات أضخم).
• من التطبيقات الحديثة: التصوير الطبي بالرنين المغناطيسي MRI.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• استنتاج أورستد: انسياب تيار كهربائي في سلك موصل يولد حوله مجالاً مغناطيسياً.
• المغناطيس الكهربائي: مغناطيس مؤقت يتكون من قلب حديد مطاوع ملفوف حوله سلك معزول ينساب فيه تيار، ويزول بزوال التيار.
• الجرس الكهربائي: جهاز تنبيه يعمل بالمغناطيس الكهربائي.
• المرحل الكهربائي: مفتاح مغناطيسي يتحكم بفتح وإغلاق دائرة.
• الحث الكهرومغناطيسي: توليد فولطية محتثة عبر موصل في مجال مغناطيسي متغير أو بحركة نسبية بينهما.
• التيار المحتث: تيار لحظي ينشأ من تغير المجال المغناطيسي دون بطارية.
• emf المحتثة: فرق جهد يتولد على طرفي الموصل بسبب الحث، وتُقاس بالفولط.
• المولد الكهربائي: جهاز يحول الطاقة الميكانيكية إلى كهربائية.
• المحرك الكهربائي: جهاز يحول الطاقة الكهربائية إلى ميكانيكية.
• المبادل: نصفا حلقة معدنية معزولان يجعلان التيار الخارج من المولد مستمراً (باتجاه واحد).

التعاليل:
• يُستعمل سلك غليظ في تجربة أورستد: ليمر تيار كبير فيتولد مجال مغناطيسي واضح التأثير.
• تُغلق الدائرة لبرهة فقط: لتجنب ارتفاع حرارة السلك واستنزاف البطارية.
• عودة الإبرة إلى وضعها السابق عند قطع التيار: لأن التيار هو الذي ولّد المجال.
• يزداد المجال المغناطيسي للملف عند وضع قطعة حديد في جوفه: لأن الحديد يتمغنط بالحث فيضيف مجاله إلى مجال الملف.
• يُستعمل الحديد المطاوع قلباً للمغناطيس الكهربائي: ليفقد مغناطيسيته بسرعة بانقطاع التيار (ولو احتاج الاحتفاظ بها استُعمل الفولاذ).
• يُلف السلك باتجاهين متعاكسين في المغناطيس الكهربائي بشكل U: للحصول على قطبين أحدهما شمالي والآخر جنوبي.
• لا يتولد تيار محتث عند تحريك السلك موازياً لخطوط المجال: لأنه لا يقطعها ولا يحدث تغير في عدد خطوط المجال.
• لا يتولد تيار عندما يكون المغناطيس ساكناً بالنسبة للملف: لعدم حدوث تغير في خطوط المجال.
• ينحرف مؤشر الكلفانوميتر باتجاهين متعاكسين عند إدخال المغناطيس وسحبه: لأن اتجاه التغير في المجال ينعكس.
• يستمر ملف المحرك بالدوران باتجاه واحد: بسبب وجود المبادل.
• يتميز المغناطيس الكهربائي عن الدائمي: بإمكانية التحكم بقوته (بالتيار وعدد اللفات) وإزالة مغناطيسيته بقطع التيار.
• لا يتأثر السلك الموازي لخطوط المجال بقوة مغناطيسية: لأن القوة المغناطيسية تتولد عندما يكون السلك عمودياً على المجال.
• في سؤال المغناطيس المتحرك داخل الملف: مصدر الطاقة الكهربائية المتولدة هو الطاقة الحركية (الميكانيكية) المبذولة في تحريك المغناطيس.'''),
    Section('القوانين والمسائل', Icons.calculate, '''قواعد أساسية (الفصل نظري ولا فيه قوانين رياضية):

قاعدة الكف اليمنى:
• لسلك مستقيم: الإبهام = اتجاه التيار، الأصابع = اتجاه المجال.
• لملف حلزوني: الأصابع = اتجاه التيار، الإبهام = اتجاه المجال (القطب الشمالي).

العوامل المؤثرة:
• مجال سلك مستقيم: يزداد بزيادة التيار وبالاقتراب من السلك.
• مجال ملف حلزوني: يتناسب طردياً مع التيار وعدد اللفات في وحدة الطول.
• المغناطيس الكهربائي: عدد اللفات لوحدة الطول، نوع مادة القلب، التيار.
• التيار المحتث يزداد بزيادة سرعة حركة المغناطيس داخل الملف (تغير أسرع في المجال).

مقارنة المولدات:
• مولد متناوب: حلقتان معدنيتان + فرشاتان ← تيار متناوب.
• مولد مستمر: نصفا حلقة (مبادل) + فرشاتان ← تيار مستمر باتجاه واحد.

تحويل الطاقة:
• المولد: ميكانيكية ← كهربائية.
• المحرك: كهربائية ← ميكانيكية.
• الجرس والهاتف: كهربائية ← حركية وصوتية.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة اختيار مع أجوبتها:
• emf المحتثة تتولد من تغير المجال المغناطيسي.
• يزداد التيار المحتث إذا تحرك المغناطيس بسرعة داخل الملف.
• يُحوَّل مولد التيار المتناوب إلى مستمر برفع حلقتي الزلق وربط طرفي الملف بمبادل.
• المولد الكهربائي يحول الطاقة الميكانيكية إلى كهربائية.
• المحرك الكهربائي يحول الطاقة الكهربائية إلى ميكانيكية.
• لا يزيد قوة المغناطيس الكهربائي: إدخال ساق نحاس في جوف الملف.
• العبارة غير الصحيحة: يزول المجال المغناطيسي للمسمار بعد فترة زمنية من انقطاع التيار (يزول بسرعة بانقطاعه).
• الشحنات الكهربائية المتحركة تولد مجالاً كهربائياً ومجالاً مغناطيسياً.

أسئلة للمراجعة:
1) بما يتميز المغناطيس الكهربائي عن المغناطيس الدائمي؟
2) ساق مغناطيسية تتحرك داخل ملف موصول بملي أميتر: ما سبب انسياب التيار؟ وما مصدر الطاقة الكهربائية؟
3) ارسم خطوط المجال لتيار في: سلك مستقيم، حلقة، ملف محلزن.
4) في أي الحالتين يتأثر سلك ينساب فيه تيار بقوة مغناطيسية: (أ) طوله عمودي على خطوط المجال، (ب) طوله موازٍ لها؟ (في الأولى فقط).
5) علل: يزداد المجال المغناطيسي لملف عند وضع قطعة حديد في جوفه.
6) ما المكونات الأساسية للمولد الكهربائي وللمحرك الكهربائي؟
7) ما مبدأ عمل المولد؟ وما مبدأ عمل المحرك؟
8) ما الفرق بين مولد التيار المتناوب ومولد التيار المستمر في الأجزاء والتيار الخارج؟
9) اذكر استنتاج أورستد وصف تجربته.
10) اذكر قاعدة الكف اليمنى لسلك ولملف.'''),
  ]),
  Chapter('الفصل السابع: المحولة الكهربائية', [
    Section('الملخص', Icons.notes, '''مقدمة:
• التيار المحتث يتولد من تغير خطوط المجال المغناطيسي خلال الموصل في وحدة الزمن، أو بحركة نسبية بين الموصل والمجال مقترنة بتغير الفيض المغناطيسي.
• يتطلب أحياناً رفع الفولطية المتناوبة (كجهاز التلفاز) أو خفضها (كالمذياع والمسجل)، وتُستعمل لذلك المحولات الكهربائية.

نشاط التيار المحتث:
• ملف أسطواني (الابتدائي) فيه ساق حديد مطاوع، موصول بمصدر فولطية متناوبة ومفتاح. وملف حلقي (الثانوي) موصول بمصباح.
• عند إغلاق دائرة الابتدائي يتوهج المصباح.
• الاستنتاج: تولد تيار محتث في الثانوي نتيجة تغير خطوط المجال المغناطيسي في وحدة الزمن المتولد في الابتدائي بسبب التيار المتناوب فيه.

المحولة الكهربائية:
• جهاز يرفع الفولطية المتناوبة أو يخفضها، فيقل التيار أو يزداد.
• تتألف من ملفين من أسلاك نحاسية معزولة ملفوفة حول قلب مغلق من الحديد المطاوع.
• عند انسياب تيار متناوب في الملف الابتدائي يتولد مجال مغناطيسي متغير داخل القلب الحديدي يشج الملف الثانوي كما يشج الابتدائي.
• هي جهاز من أجهزة التيار المتناوب ولا تعمل بالتيار المستمر (لعدم تغير المجال داخل القلب فلا يتولد تيار محتث في الثانوي).
• الملف الابتدائي (N₁): موصول بمصدر الفولطية المتناوبة. الملف الثانوي (N₂): موصول بالحمل.

المحولة المثالية:
• تهمل فيها خسائر الطاقة في أسلاك الملفين والقلب.
• القدرة الداخلة = القدرة الخارجة: P₁ = P₂ ← I₁V₁ = I₂V₂
• V₂ / V₁ = N₂ / N₁ = I₁ / I₂
• تُسمى N₂/N₁ نسبة التحويل (نسبة عدد اللفات).

المحولة العملية:
• يحصل فيها ضياع قدرة أثناء عملها، فتكون القدرة الخارجة أقل من الداخلة.
• كفاءة المحولة: η = (P₂ / P₁) × 100%

نقل الطاقة:
• عند نقل الطاقة الكهربائية لمسافات بعيدة تُنقل بفولطية عالية وتيار واطئ لتقليل الخسارة الناتجة عن مقاومة الأسلاك الطويلة.

نوعا المحولة:
1) المحولة الخافضة: N₂ < N₁ ← V₂ < V₁ (وهي رافعة للتيار I₂ > I₁، ونسبة التحويل أقل من 1).
• استعمالاتها: الفولطية الداخلة إلى المنازل، مناطق استلام القدرة في المدن، جهاز اللحام الكهربائي، شاحنة الموبايل.
2) المحولة الرافعة: N₂ > N₁ ← V₂ > V₁ (وهي خافضة للتيار I₂ < I₁، ونسبة التحويل أكبر من 1).
• استعمالاتها: جهاز التلفاز (فولطية عالية للقاذف الإلكتروني)، محطات توليد الطاقة عند إرسالها إلى المدن.
• المحولة الرافعة للفولطية خافضة للتيار والعكس صحيح.

خسائر القدرة في المحولة:
1) خسارة مقاومة أسلاك الملفين: تظهر طاقة حرارية في الملفين بسبب مقاومتهما الأومية. تُقلل بصنع الأسلاك من مادة مقاومتها صغيرة (النحاس).
2) خسارة التيارات الدوامة: تظهر طاقة حرارية في القلب الحديدي بسبب تغير المجال المغناطيسي الذي يولد تيارات محتثة داخل القلب. تُقلل بصنع القلب من صفائح رقيقة من الحديد المطاوع معزولة بعضها عن بعض، مكبوسة، ومستواها موازٍ للمجال.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• المحولة الكهربائية: جهاز يرفع الفولطية المتناوبة أو يخفضها (يغير مقدارها).
• الملف الابتدائي: الملف المربوط بمصدر الفولطية المتناوبة (عدد لفاته N₁).
• الملف الثانوي: الملف المربوط بالحمل (عدد لفاته N₂).
• المحولة المثالية: محولة تُهمل فيها خسائر القدرة فتكون القدرة الخارجة = الداخلة.
• نسبة التحويل: N₂ / N₁ = V₂ / V₁.
• كفاءة المحولة: النسبة المئوية بين القدرة الخارجة من الثانوي والقدرة الداخلة في الابتدائي.
• المحولة الرافعة: عدد لفات ثانويها أكبر من ابتدائيها (ترفع الفولطية).
• المحولة الخافضة: عدد لفات ثانويها أقل من ابتدائيها (تخفض الفولطية).
• التيارات الدوامة: تيارات محتثة تتولد في القلب الحديدي بسبب تغير المجال المغناطيسي.

التعاليل:
• تحتاج المحولة إلى تيار متناوب: لأن تغير المجال المغناطيسي داخل القلب هو الذي يولد التيار المحتث في الثانوي.
• لا تعمل المحولة بتيار مستمر (بطارية على الابتدائي): لعدم حدوث تغير في المجال المغناطيسي داخل القلب فلا يتولد تيار محتث في الثانوي.
• يُصنع قلب المحولة من الحديد المطاوع: ليتمغنط ويفقد مغناطيسيته بسهولة مع تغير التيار.
• تُصنع أسلاك الملفين من النحاس: لأن مقاومته صغيرة فتقل الخسارة الحرارية.
• يُصنع القلب من صفائح رقيقة معزولة: لتقليل خسارة التيارات الدوامة.
• تُنقل الطاقة بفولطية عالية وتيار واطئ: لتقليل الضياع الحراري في أسلاك النقل الطويلة (P = I²R).
• المحولة الرافعة للفولطية خافضة للتيار: لأن P₁ = P₂ فالفولطية والتيار يتناسبان عكسياً.
• الفائدة الاقتصادية لنقل القدرة بفولطية عالية وتيار واطئ: تقليل الفقد في الأسلاك وبالتالي تقليل الكلفة.
• تُستعمل محولة رافعة عند محطة الإرسال (بداية خطوط النقل): لرفع الفولطية وخفض التيار فتقل خسائر النقل.
• تُستعمل محولة خافضة في نهاية الخطوط قبل دخول المصنع: لخفض الفولطية إلى القيمة المناسبة لتشغيل الأجهزة.'''),
    Section('القوانين والمسائل', Icons.calculate, '''القوانين:
• P₁ = I₁ × V₁ ، P₂ = I₂ × V₂
• محولة مثالية: P₁ = P₂ ← I₁ V₁ = I₂ V₂
• V₂ / V₁ = N₂ / N₁
• I₁ / I₂ = N₂ / N₁ = V₂ / V₁
• الكفاءة: η = (P₂ / P₁) × 100%
• القدرة المفقودة: P_lost = P₁ − P₂
• محولة رافعة: N₂/N₁ > 1 ، خافضة: N₂/N₁ < 1.

أمثلة محلولة:
1) ملف ابتدائي 240 V و500 لفة، والحمل على ثانوي 12 V:
النوع: خافضة لأن 12 V أصغر من 240 V.
12 ÷ 240 = N₂ ÷ 500 ← N₂ = 25 لفة.
2) قدرة داخلة 220 W وخسائر 11 W:
P₂ = 220 − 11 = 209 W
η = (209 ÷ 220) × 100% = 95%

مسائل الفصل مع الجواب:
1) محولة كفاءتها 100% ونسبة التحويل 1/2 على 220 V والتيار في الثانوي 1.1 A:
V₂ = 220 × ½ = 110 V
I₁ = I₂ × (N₂/N₁) = 1.1 × ½ = 0.55 A
2) كفاءة 80% والقدرة الخارجة 4.8 kW:
P₁ = 4.8 ÷ 0.8 = 6 kW
3) كفاءة 95% والقدرة الداخلة 9.5 kW:
P₂ = 9.5 × 0.95 = 9.025 kW
4) مصباح (6 V، 12 W) على ثانوي محولة مثالية، الابتدائي 240 V و8000 لفة:
N₂ = 8000 × 6 ÷ 240 = 200 لفة
تيار المصباح: I₂ = P ÷ V = 12 ÷ 6 = 2 A
تيار الابتدائي: I₁ = P ÷ V₁ = 12 ÷ 240 = 0.05 A'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة اختيار مع أجوبتها:
• التيار في الثانوي تيار محتث يتولد بوساطة مجال مغناطيسي متغير خلال قلب الحديد.
• النسبة V₂/V₁ لا تعتمد على مقاومة أسلاك الملفين.
• محولة مثالية N₁ = 800 و N₂ = 200 و I₂ = 40 A: I₁ = 40 × 200 ÷ 800 = 10 A.
• N₂ = 300 و N₁ = 6000 و V₁ = 240 V: V₂ = 240 × 300 ÷ 6000 = 12 V.
• N₁ = 600 و N₂ = 1800 والقدرة 720 W بـ 240 V: V₂ = 720 V ← I₂ = 720 ÷ 720 = 1 A.

أسئلة للمراجعة:
1) بماذا تختلف المحولة الرافعة عن الخافضة؟
2) ما أساس عمل المحولة الكهربائية؟ (الحث الكهرومغناطيسي.)
3) وضح كيف تعمل المحولة على تغيير مقدار الفولطية.
4) في أي المجالات تُستعمل المحولة الرافعة والخافضة؟
5) وضح الفائدة الاقتصادية من نقل القدرة لمسافات بعيدة بفولطية عالية وتيار واطئ.
6) لماذا تحتاج المحولة إلى تيار متناوب؟
7) هل تعمل المحولة إذا وُضعت بطارية بين طرفي ابتدائيها؟ وضح.
8) ما نوع المحولة المستعملة عند محطة الإرسال وعند المصنع؟ (رافعة ثم خافضة.)
9) عدد خسائر القدرة في المحولة وطرق تقليلها.
10) اكتب قانون كفاءة المحولة وقانون نسبة التحويل.'''),
  ]),
  Chapter('الفصل الثامن: تكنولوجيا مصادر الطاقة', [
    Section('الملخص', Icons.notes, '''الطاقة في حياتنا:
• الطاقة من المقومات الرئيسة للمجتمعات المتحضرة، تُستعمل في تشغيل المصانع وتحريك وسائط النقل وتشغيل الأدوات المنزلية.
• صور الطاقة: الضوء، الحرارة، الصوت، الميكانيكية، الكيميائية (المخزونة في أواصر الذرات والجزيئات)، النووية، والكهربائية.
• الطاقة: المقدرة على إنجاز شغل. وحدتها الجول (Joule).
• يمكن تحويل الطاقة من صورة إلى أخرى.

مصادر الطاقة الحالية (ثلاثة أقسام):
1) المصادر الأحفورية: النفط، الفحم، الغاز الطبيعي.
2) مصادر الطاقة المائية.
3) مصادر الطاقة النووية.

1) مصادر الطاقة الأحفورية:
• تتكون من الكاربون والهيدروجين (مواد هيدروكاربونية) إضافة إلى نسب من الماء والكبريت والأوكسجين والنتروجين وأكاسيد الكاربون.
• من مصادر الطاقة غير المتجددة: احتياطي العالم منها يتناقص باستمرار لأن معدل تكونها أقل بكثير من معدل استهلاكها.
• استعمالاتها: توليد الكهرباء (حرق الوقود يسخن الماء فينتج بخاراً يدير توربينات موصلة بمولدات)، تشغيل وسائل النقل، وقود مباشر للطهي والتسخين.

2) مصادر الطاقة المائية:
• تعتمد على تحويل طاقة الوضع (الكامنة) في المياه المحفوظة خلف السدود أو في أماكن مرتفعة إلى طاقة ميكانيكية (حركية) أثناء سقوط الماء.
• يتدفق الماء خلال مجرى أو أنبوب إلى توربينات فيدور محورها ويدير المولدات الكهربائية الكبيرة فتنتج الطاقة الكهربائية.

3) مصادر الطاقة النووية:
• تنتج محطات الطاقة النووية الكهرباء بمنظومة تسمى المفاعل النووي.
• ينتج المفاعل طاقة حرارية هائلة بانشطار (Fission) نوى ذرات عنصر ثقيل مثل اليورانيوم (235) وهو الوقود النووي.
• تُستعمل الحرارة لتحويل الماء إلى بخار يدير التوربين البخاري الذي يدير المولد الكهربائي.

المصادر البديلة (المتجددة):
• مصادر الأحفورية في تناقص ومشكلات التلوث الناتجة عنها تتزايد، فبُحث عن مصادر أكثر ديمومة.
• أسباب تفضيل الطاقة المتجددة:
1) لا تُستنفذ.
2) نظيفة (غير ملوثة) بعكس الوقود الأحفوري الذي تنبعث منه مواد هيدروكاربونية عند احتراقه.
3) يمكن أن تكون متاحة محلياً خلافاً للوقود الأحفوري.
4) قلة تكاليف إنتاج الطاقة منها.
• أهم أنواعها: الطاقة الشمسية، طاقة الرياح، طاقة الوقود الحيوي، طاقة المد والجزر.

1) تكنولوجيا الطاقة الشمسية:
• الطاقة الشمسية التي تستقبلها الأرض هي مصدر الحياة والمصدر المباشر وغير المباشر لمختلف أنواع الطاقة عليها.
• تتميز بسهولة توفرها في كثير من بقاع العالم وخلوها من التأثيرات السلبية على البيئة (لا تنطلق منها غازات أو مواد كيميائية ضارة).
• مجالات استثمارها: توليد الكهرباء، التطبيقات الحرارية (تسخين المياه والتدفئة)، تحلية المياه المالحة.

الخلية الشمسية:
• مبدأ عملها: تحويل طاقة ضوء الشمس (الطاقة الضوئية) إلى طاقة كهربائية.
• تُغطى بلوح زجاجي لحمايتها من التأثيرات الجوية.
• تُستعمل الطاقة المتولدة منها مثلاً لرفع مياه الآبار.

السخان الشمسي:
• منظومة متكاملة تجمع الأشعة الشمسية الساقطة وتستثمر طاقتها الحرارية في تسخين المياه خلال فترة سطوع الشمس، وكذلك في تدفئة المنازل.
• تُستعمل فيها معادن غير قابلة للصدأ مطلية باللون الأسود لامتصاص أكبر كمية من الأشعة (مثل أكاسيد الكروم والكوبلت).
• وأنواع أخرى تستعمل مرايا بشكل قطع مكافئ للحصول على حرارة التسخين.

تحلية المياه المالحة (المقطر الشمسي):
• تُستعمل أشعة الشمس مصدراً حرارياً لرفع حرارة الماء غير النقي ثم تبخيره وتحويله إلى ماء نقي.

2) تكنولوجيا طاقة الرياح:
• مبدأها: استثمار قوة الرياح في تدوير المروحة الهوائية، فتتحرك ريشها وتدور، وتتصل بمولد كهربائي فتدور نواته وتتولد الطاقة الكهربائية.
• حركة الهواء متغيرة حسب المواقع، وتكون سريعة في المناطق الساحلية والصحراوية.
• تعتمد على سرعة الرياح التي يجب ألا تقل عن 5.4 m/s وأن تهب لساعات طويلة في اليوم.

3) تكنولوجيا طاقة الوقود الحيوي:
• الطاقة المستثمرة من الكائنات الحية نباتية أو حيوانية، وهو أهم مصادر الطاقة المتجددة، ويتصدره الوقود الحيوي السائل بنوعين:
• وقود الإيثانول: يُستخرج من قصب السكر والبطاطا الحلوة والذرة والتمر، ويُستعمل في تشغيل بعض السيارات.
• الديزل الحيوي: يُستخرج من النباتات الحاوية على الزيوت (فول الصويا، زيت النخيل، عباد الشمس) بعد معالجتها كيميائياً.
• الوقود الحيوي الغازي (غاز الميثان): ينتج من التحلل الكيميائي للمزروعات والفضلات ومخلفات الحيوانات والنفايات والمجاري ومخلفات الأغذية بالهضم اللاهوائي.

4) تكنولوجيا طاقة المد والجزر:
• استثمار حركة المد والجزر في توليد الكهرباء: يرتفع منسوب الماء وقت المد وينخفض وقت الجزر في البحار والمحيطات، ويشكل فارق الارتفاع وحركة المياه مصدراً كبيراً للطاقة يُستعمل في تشغيل التوربينات.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• الطاقة: المقدرة على إنجاز شغل (وحدتها الجول).
• مصادر الطاقة غير المتجددة: مصادر يتناقص احتياطيها لأن معدل استهلاكها أكبر بكثير من معدل تكونها (الأحفورية).
• مصادر الطاقة المتجددة (البديلة): مصادر لا تُستنفذ (الشمس، الرياح، الوقود الحيوي، المد والجزر).
• الوقود الأحفوري: النفط والفحم والغاز الطبيعي (مواد هيدروكاربونية).
• طاقة الوضع: الطاقة الكامنة في المياه المحفوظة خلف السدود أو في أماكن مرتفعة.
• المفاعل النووي: منظومة تنتج طاقة حرارية هائلة بانشطار نوى عنصر ثقيل كاليورانيوم.
• الانشطار النووي: انقسام نواة ذرة عنصر ثقيل (اليورانيوم 235).
• الخلية الشمسية: جهاز يحول ضوء الشمس إلى طاقة كهربائية.
• الوقود الحيوي: الطاقة المستثمرة من الكائنات الحية النباتية أو الحيوانية.
• طاقة المد والجزر: توليد الكهرباء من ارتفاع منسوب الماء وانخفاضه في البحار والمحيطات.

التعاليل:
• تُعد مصادر الطاقة الأحفورية غير متجددة: لأن معدل استهلاكها أكبر بكثير من معدل تكونها فيتناقص احتياطيها.
• تُفضَّل الطاقة المتجددة على غير المتجددة: لأنها لا تُستنفذ، ونظيفة غير ملوثة، ومتاحة محلياً، وقليلة التكاليف.
• توضع طبقة من الزجاج على لوح الخلية الشمسية: لحمايتها من التأثيرات الجوية.
• تُطلى معادن السخان الشمسي باللون الأسود: لامتصاص أكبر كمية ممكنة من الأشعة الشمسية.
• تُستعمل معادن غير قابلة للصدأ في السخان الشمسي: لحمايتها من التآكل بالماء والجو.
• تُستعمل مرايا بشكل قطع مكافئ في بعض أنواع السخانات: لتركيز الأشعة والحصول على حرارة عالية.
• لا تُنصب طواحين الرياح إلا في مواقع هبوب سرعة الرياح فيها كافية: لأن سرعة الرياح يجب ألا تقل عن 5.4 m/s.
• الطاقة الشمسية صديقة للبيئة: لأنها لا تنتج غازات أو مواد كيميائية ضارة.
• يُدار البخار التوربين في محطات الوقود الأحفوري والنووي: ليدور المولد الكهربائي فتتولد الكهرباء.'''),
    Section('القوانين والمسائل', Icons.calculate, '''الفصل نظري ولا فيه قوانين رياضية، وهذه جداول للحفظ:

أنواع مصادر الطاقة:
• غير متجددة: النفط، الفحم الحجري، الغاز الطبيعي، (والوقود النووي يُصنف مصدراً حالياً).
• متجددة: الشمسية، الرياح، الوقود الحيوي، المد والجزر.
• الطاقة المائية (السدود): تُعد من المصادر الحالية.

تحولات الطاقة:
• خلية شمسية: ضوئية ← كهربائية.
• سخان شمسي: ضوئية ← حرارية.
• محطة مائية: طاقة وضع ← حركية ← كهربائية.
• محطة نووية: نووية ← حرارية ← حركية ← كهربائية.
• محطة وقود أحفوري: كيميائية ← حرارية ← حركية ← كهربائية.
• مروحة الرياح: حركية ← كهربائية.
• المد والجزر: طاقة حركة المياه ← كهربائية.

أنواع الوقود الحيوي السائل:
• الإيثانول: من قصب السكر والبطاطا الحلوة والذرة والتمر.
• الديزل الحيوي: من فول الصويا وزيت النخيل وعباد الشمس.
• الغازي: الميثان من الهضم اللاهوائي للفضلات.

أرقام مهمة:
• أقل سرعة رياح لتشغيل التوربين: 5.4 m/s.
• وقود المفاعل النووي: اليورانيوم 235.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة اختيار مع أجوبتها:
• من مصادر الطاقة غير المتجددة: طاقة الفحم الحجري.
• من مصادر الطاقة المتجددة: طاقة الخلايا الشمسية.
• الخلية الشمسية تحول الطاقة الضوئية إلى طاقة كهربائية.
• المولدات الطافية في البحر تُستعمل لتوليد طاقة المد والجزر.
• الوقود المستعمل في المفاعلات النووية: اليورانيوم.
• الطاقة المتولدة من حركة أو سقوط المياه تدعى الطاقة المائية.

أسئلة للمراجعة:
1) توضع طبقة من الزجاج على لوح الخلية الشمسية. ما الفائدة؟ (حمايتها من التأثيرات الجوية.)
2) لماذا تُفضَّل الطاقة المتجددة على غير المتجددة؟ وضح.
3) اذكر مبدأ عمل: تكنولوجيا الخلايا الشمسية، وتكنولوجيا طاقة الرياح.
4) عدد مصادر الطاقة الأحفورية واستعمالاتها.
5) كيف تُنتج الكهرباء في المحطات المائية؟ وفي المحطات النووية؟
6) ما الفرق بين مصادر الطاقة المتجددة وغير المتجددة؟
7) اذكر أنواع الوقود الحيوي ومصادر كل نوع.
8) كيف يعمل السخان الشمسي؟ ولماذا يُطلى باللون الأسود؟
9) كيف تُحلى المياه المالحة بالطاقة الشمسية؟
10) كيف تُستثمر حركة المد والجزر في توليد الكهرباء؟'''),
  ]),
  Chapter('الفصل التاسع: فيزياء الجو وتقنية الاتصالات الحديثة', [
    Section('الملخص', Icons.notes, '''جو الأرض ومكوناته:
• جو الأرض: غلاف الهواء المحيط بالكرة الأرضية إحاطة تامة، وسمكه صغير جداً مقارنة بقطر الأرض (يُرى من الفضاء طبقة رقيقة من الضوء الأزرق الغامق).
• خليط من الغازات مرتبط بالأرض بفعل الجاذبية، وبعضها بنسب ثابتة (كالهواء الجاف).
• نسب الغازات: النتروجين N₂ (78.08%)، الأوكسجين O₂ (20.94%)، الأرغون Ar (0.9325%)، ثنائي أوكسيد الكاربون CO₂ (0.036%)، ثم النيون والهيليوم والكريبتون والميثان والهيدروجين وأكسيد النتروجين والأوزون والزينون بنسب ضئيلة.
• النشاط البشري غير المتوازن يغير هذه النسب فيزداد الاحتباس الحراري، فتحدث تغيرات مناخية وفيضانات وانصهار جليد القطبين وأعاصير غير مألوفة.
• الاحترار العالمي: ازدياد معدل الحرارة في جو الأرض عن المعدل الطبيعي وعدم تسربها إلى خارج الغلاف نتيجة امتصاص غاز CO₂ المنبعث من المصانع والأنشطة البشرية.

طبقات الغلاف الجوي:
• الغلاف كتلة غير متجانسة، تتكون من طبقات بعضها فوق بعض تتحدد بما تحويه من غازات وبضغطها ودرجة حرارتها التي تتغير مع الارتفاع. الطبقات خمس رئيسة:

1) التروبوسفير: الأولى القريبة من سطح الأرض، تمتد إلى 14 km تقريباً وتشكل 80% من الغلاف.
• أكثر الطبقات اضطراباً، تحدث فيها جميع الظواهر المناخية والتغيرات الجوية.
• يتناقص فيها الضغط والكثافة بسرعة مع الارتفاع، وتتناقص الحرارة بمعدل ثابت نحو 6.5 °C لكل 1 km.

2) الستراتوسفير: فوق التروبوسفير، من 14 km حتى 50 km.
• تحتوي طبقة الأوزون وأكبر تركيز للأوزون عند ارتفاع 25 km (تقريباً منتصف الطبقة).
• ترتفع فيها الحرارة نسبياً مع الارتفاع: من −60 °C عند الحافة السفلى إلى −15 °C عند العليا.

3) الميزوسفير: في منتصف الغلاف، من 50 km حتى 90 km.
• مكوناتها الغازية الهيليوم والهيدروجين، ضغطها منخفض وكثافتها قليلة.
• تقل فيها الحرارة مع الارتفاع إلى أقصى ما يمكن (نحو −120 °C) في منطقتها العليا.

4) الثرموسفير (الطبقة الحرارية): فوق الميزوسفير من 90 km حتى 500 km.
• تحتوي إلكترونات حرة وأيونات، فتُعرف بالطبقة المتأينة (الأيونوسفير).
• ترتفع الحرارة مع الارتفاع حتى نحو 1000 °C عند حافتها العليا.
• تمتاز بعكس الموجات الراديوية ذات الترددات الأقل من 300 kHz، فتسمح بوصول البث لمسافات بعيدة.

5) الإكسوسفير: أعلى طبقة، ارتفاعها أكثر من 500 km، وهي الغلاف الغازي الخارجي.
• جزيئات الغاز فيها سريعة جداً ولها طاقة حركية كافية للإفلات من جاذبية الأرض والهروب إلى الفضاء الخارجي.

طبقة الأوزون:
• يتولد الأوزون في الستراتوسفير بالأشعة فوق البنفسجية من الشمس. الأشعة فوق البنفسجية ثلاثة أنواع A وB وC.
• النوع C هو الضار بالأحياء على سطح الأرض، وطبقة الأوزون مظلة واقية تحجب هذا الإشعاع.
• النوعان A وB لهما دور في توليد الأوزون: يمتصهما جزيء الأوكسجين O₂ فيتفكك إلى ذرتي أوكسجين، ثم تندمج كل ذرة مع جزيء أوكسجين مولدة جزيء الأوزون O₃.
• ثقب الأوزون: انخفاض تركيز الأوزون ويتضح قرب القطبين الجنوبي والشمالي بمساحات كبيرة.
• التعرض الطويل للأشعة فوق البنفسجية B يسبب حروق الجلد وقد يسبب سرطان الجلد.

انتشار الموجات اللاسلكية:
1) الموجات الأرضية (السطحية): موجات راديوية تنتقل قريبة من سطح الأرض بخطوط مستقيمة، قصيرة المدى، لا تؤمن اتصالاً إلا لمسافات قصيرة نسبياً بسبب تحدب سطح الأرض. تعتمد على طبيعة الهوائي وتردد الموجات وقدرة جهاز الإرسال، وترددها أقل من 200 MHz.
2) الموجات السماوية: تُستعمل في الاتصالات بعيدة المدى وتسلك أنماطاً حسب ترددها.
• الموجات عالية التردد (HF) تنعكس عن طبقة الأيونوسفير فتنتقل لآلاف الكيلومترات.
• الموجات الأعلى من HF هي الموجات المايكروية (Microwaves): تخترق الأيونوسفير وتنفذ إلى الفضاء، فتُستعمل في اتصالات الأقمار الصناعية (يستلمها القمر ويقويها ويعيد بثها إلى الأرض)، وفي الهواتف النقالة.

الهاتف النقال:
• جهاز تقني معقد لتكدس الدوائر الإلكترونية على مساحة صغيرة، وهو وسيلة اتصال لاسلكية.
• مكوناته الأساسية: دائرة إلكترونية تحتوي رقائق المعالج والذاكرة، هوائي، شاشة عرض، لوحة مفاتيح، لاقطة الصوت، سماعة، بطارية.

الأقمار الصناعية:
• القمر الصناعي: تابع يدور حول الأرض يحمل أجهزة ومعدات إلكترونية تُستعمل في الاتصالات والأغراض العلمية.
1) أقمار اتصالات: للاتصالات الهاتفية والقنوات التلفازية ونقل المعلومات، على ارتفاع عالٍ جداً نحو 36000 km (أعلى من بقية الأقمار).
2) أقمار علمية: لمراقبة الطقس والأنواء الجوية والنشاط الشمسي وأقمار تحديد المواقع (GPS)، على ارتفاعات متوسطة.
3) أقمار عسكرية: في مدارات خاصة وارتفاعات واطئة نسبياً لمسح وتصوير المواقع العسكرية (التجسس).'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• جو الأرض (الغلاف الجوي): غلاف الهواء المحيط بالكرة الأرضية، خليط من الغازات مرتبط بها بالجاذبية.
• الاحترار العالمي: ازدياد معدل الحرارة في جو الأرض عن المعدل الطبيعي وعدم تسربها إلى الخارج.
• التروبوسفير: الطبقة الأولى القريبة من سطح الأرض (حتى 14 km).
• الستراتوسفير: الطبقة التي تحتوي طبقة الأوزون (14–50 km).
• الميزوسفير: الطبقة الوسطى (50–90 km).
• الثرموسفير (الأيونوسفير): الطبقة الحرارية المتأينة (90–500 km) التي تعكس الموجات الراديوية.
• الإكسوسفير: أعلى طبقة (فوق 500 km).
• طبقة الأوزون: مظلة واقية في الستراتوسفير تحجب الأشعة فوق البنفسجية الضارة نوع C.
• ثقب الأوزون: انخفاض تركيز الأوزون قرب القطبين.
• الموجات الأرضية (السطحية): موجات راديوية تنتقل قريبة من سطح الأرض لمسافات قصيرة.
• الموجات السماوية: موجات بعيدة المدى تنعكس عن الأيونوسفير أو تخترقه.
• الموجات المايكروية: موجات ترددها أعلى من HF تخترق الأيونوسفير.
• القمر الصناعي: تابع يدور حول الأرض ويحمل معدات إلكترونية.

تصحيح عبارات (من أسئلة الفصل):
• يتألف الغلاف الجوي من خليط من الغازات بعضها ثابت النسب (ليست جميعها متغيرة).
• الغلاف الجوي كتلة غير متجانسة ومن طبقات بعضها فوق بعض.
• في التروبوسفير يتناقص الضغط والكثافة ودرجة الحرارة مع زيادة الارتفاع.
• الثرموسفير هي التي تحتوي إلكترونات حرة وأيونات (لا الستراتوسفير).
• الميزوسفير توجد في منتصف الغلاف الجوي (لا الستراتوسفير).
• الموجات الراديوية السطحية تسمى الموجات الأرضية (لا السماوية).
• العبارات الصحيحة: بتأثير الأشعة فوق البنفسجية A وB في الأوكسجين يتولد الأوزون. تمتاز الثرموسفير بعكس الموجات الراديوية. ارتفاعات أقمار الاتصالات عالية جداً.

التعاليل:
• الغلاف الجوي مرتبط بالأرض: بفعل الجاذبية الأرضية.
• تحدث الظواهر المناخية في التروبوسفير: لأنها أكثر الطبقات اضطراباً وتحتوي معظم الغلاف (80%).
• تُعد طبقة الأوزون مظلة واقية: لأنها تحجب الأشعة فوق البنفسجية الضارة نوع C عن الوصول إلى سطح الأرض.
• ترتفع الحرارة في الستراتوسفير مع الارتفاع: بسبب امتصاص طبقة الأوزون للأشعة فوق البنفسجية.
• تنخفض الحرارة في الميزوسفير: لقلة الكثافة وبعدها عن سطح الأرض.
• تسمى الثرموسفير الأيونوسفير: لاحتوائها على إلكترونات حرة وأيونات (طبقة متأينة).
• تُعكس موجات الراديو التي ترددها أقل من 300 kHz في الثرموسفير: لتصل إلى مسافات بعيدة.
• الموجات الأرضية قصيرة المدى: لأنها تنتشر بخطوط مستقيمة وسطح الأرض متحدب.
• تُستعمل الموجات المايكروية في اتصالات الأقمار الصناعية: لأنها تخترق الأيونوسفير وتنفذ إلى الفضاء.
• جزيئات الإكسوسفير تهرب إلى الفضاء: لأن طاقتها الحركية كافية للإفلات من جاذبية الأرض.
• أقمار الاتصالات على ارتفاع 36000 km: لتغطي مساحات واسعة من سطح الأرض.'''),
    Section('القوانين والمسائل', Icons.calculate, '''الفصل نظري ولا فيه قوانين رياضية، وهذه جداول للحفظ:

طبقات الغلاف الجوي (من الأسفل إلى الأعلى):
• التروبوسفير: 0 – 14 km (80% من الغلاف) — الحرارة تقل (6.5 °C/km).
• الستراتوسفير: 14 – 50 km — فيها الأوزون، الحرارة ترتفع (−60 إلى −15 °C).
• الميزوسفير: 50 – 90 km — الحرارة تقل حتى نحو −120 °C.
• الثرموسفير: 90 – 500 km — الحرارة ترتفع حتى نحو 1000 °C، أيونوسفير.
• الإكسوسفير: أكثر من 500 km — الغلاف الخارجي.

تفاعل تكوين الأوزون:
• O₂ + أشعة فوق بنفسجية (A وB) → O + O
• O + O₂ → O₃ (الأوزون)

النسب المهمة للغازات:
• N₂ ≈ 78% ، O₂ ≈ 21% ، Ar ≈ 0.93% ، CO₂ ≈ 0.036%.

ارتفاعات الأقمار:
• اتصالات: نحو 36000 km (عالية جداً).
• علمية وGPS: متوسطة.
• عسكرية: واطئة نسبياً.

الموجات:
• أرضية: ترددها أقل من 200 MHz، قصيرة المدى.
• سماوية HF: تنعكس عن الأيونوسفير.
• مايكروية: تخترق الأيونوسفير (أقمار صناعية وهواتف نقالة).'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة اختيار مع أجوبتها:
• يتألف الغلاف الجوي من خليط غازات بنسب ثابتة (بعضها).
• الطبقة التي تحتوي طبقة الأوزون: الستراتوسفير.
• أعلى طبقة من طبقات الغلاف الجوي: الإكسوسفير.
• تُستعمل الموجات السماوية للاتصالات بعيدة المدى.
• الغاية من الأقمار الصناعية العلمية: مراقبة الطقس والأنواء الجوية.

أسئلة للمراجعة:
1) اذكر أربعة غازات من مكونات الغلاف الجوي.
2) اذكر طبقات الغلاف الجوي الرئيسة.
3) اذكر ميزات: التروبوسفير، الستراتوسفير، الميزوسفير.
4) ما الأوزون؟ وأين يوجد؟ وكيف يتكون؟
5) ما المكونات الرئيسة للهاتف النقال؟
6) اذكر ثلاثة استعمالات للأقمار الصناعية.
7) ما الفرق بين الموجات الأرضية والسماوية؟
8) ما الاحترار العالمي وما أسبابه؟
9) لماذا تُستعمل الموجات المايكروية في الاتصالات عبر الأقمار الصناعية؟
10) صحح العبارات الخاطئة الواردة في أسئلة الفصل.'''),
  ]),
];

const List<Chapter> biology = [
  Chapter('الفصل الأول: الجهاز العصبي', [
    Section('الملخص', Icons.notes, '''مقدمة:
• مجموع الخلايا ذات المنشأ نفسه = نسيج. مجموع الأنسجة المتماثلة = عضو (يتخصص بوظيفة محددة). مجموعة الأعضاء المتكاملة الوظائف = جهاز.

مكونات الجهاز العصبي:
1) الخلية العصبية: وحدة البناء والوظيفة في الجهاز العصبي. تتكون من جسم الخلية (فيه النواة) والمحور وتنتهي بالتفرعات. التشجرات (dendrites) مناطق اتصال الخلية العصبية بالخلايا الأخرى، وتكون أحادية القطب أو ثنائية القطب أو متعددة الأقطاب. الخلايا العصبية لا يمكن تعويضها بخلايا أخرى إذا ماتت أو تضررت.
2) النسيج العصبي: تجمع أعداد كبيرة من الخلايا العصبية، يقوم بنقل الإيعاز العصبي. لونه سنجابي في قشرة الدماغ وأبيض في الذي يغطي الحبل الشوكي.
3) الأعصاب: حزمة من المحاور العصبية مرتبطة بنسيج ليفي رابط، حسية أو حركية.
• العصب الحسي: ينقل الحافز من أنحاء الجسم إلى الجهاز العصبي المركزي.
• العصب الحركي: ينقل الإيعاز بالرد من الجهاز العصبي المركزي إلى أنحاء الجسم.

أقسام الجهاز العصبي:

أولاً: الجهاز العصبي المركزي (CNS): الدماغ والحبل الشوكي.
أ) الدماغ ويتألف من:
1) المخ: أكبر أجزاء الدماغ، من نصفين يفصلهما شق عميق، سطحه متعرج. يسيطر على مراكز الحواس والحركات الإرادية ومختلف الفعاليات العضلية والانفعالات النفسية.
2) المخيخ: أسفل القسم الخلفي للمخ، من قسمين. وظيفته تنظيم حركة العضلات الإرادية.
3) النخاع المستطيل: في القسم الخلفي من قاعدة تجويف الجمجمة، يصل الدماغ بالحبل الشوكي، وفيه مراكز حيوية تسيطر على التنفس والدوران (القلب) وبعض الحركات اللاإرادية.
ب) الحبل الشوكي: تركيب أسطواني طوله نحو 45 سم، من نهاية النخاع المستطيل إلى الفقرة القطنية الأخيرة، داخل قناة عظمية تكونها الفقرات.

ثانياً: الجهاز العصبي المحيطي (PNS):
• أعصاب منتشرة في الجسم تتسلم الحوافز من أعضاء الحس وتوصلها للجهاز المركزي ثم تتسلم الإيعاز. مثال: رؤية النار ← العين ترسل الصورة للدماغ ← الدماغ يرسل إيعازاً لعضلات الأرجل للابتعاد.
• مكوناته: الأعصاب الشوكية (31 زوجاً، حسية وحركية، تتفرع من الحبل الشوكي)، والأعصاب القحفية (12 زوجاً، حسية وحركية ومختلطة).

ثالثاً: الجهاز العصبي الذاتي:
• ينظم وظائف الجسم اللاإرادية تلقائياً كضربات القلب والتنفس والتعرق، ويمتد جنباً إلى جنب مع المحيطي ويتصل بالمركزي. ويشمل:
• الودي (العطوف أو السمبثاوي): أعصاب دقيقة تتفرع من جانبي القسم الوسطي من الحبل الشوكي، ينظم عمل الجسم في حالات الخطر والخوف: زيادة ضربات القلب وتوسع بؤبؤ العين.
• جار الودي (الباراسمبثاوي): أعصاب تتفرع من بعض مناطق الدماغ والجزء السفلي من الحبل الشوكي، وظيفته عكس الودي: تقليل معدل ضربات القلب.

فسلجة الجهاز العصبي:
• الإيعاز العصبي: انتقال الحوافز ورد الفعل عليها من الخلايا العصبية إلى أجزاء الجسم الأخرى، يشبه انتقال التيار الكهربائي. سرعته في الجسم 90 متراً/ثانية.
• قد يكون صادراً من المركزي إلى أعضاء الجسم، أو واردا ينقل الحوافز إلى المركزي.
• الوصلة العصبية: منطقة التقاء التفرعات الشجيرية لخلية عصبية مع الفروع الدقيقة لجسم خلية أخرى، وهي نقطة انتقال الإيعاز بين خليتين. وبين الخلية والعضلات تسمى الوصلة العضلية–العصبية.

أنواع الأفعال العصبية:
• الإرادية: مركزها المخ (المشي والكلام والكتابة).
• اللاإرادية: مركزها النخاع المستطيل (نبضات القلب والتنفس وعمل المعدة والأمعاء).
• الانعكاسية: مركزها الحبل الشوكي (سحب اليد أو القدم عند وخزها بإبرة).'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• النسيج: مجموع الخلايا ذات المنشأ نفسه.
• العضو: مجموع الأنسجة المتماثلة التي تقوم بوظيفة محددة.
• الجهاز: مجموعة أعضاء تتكامل وظائفها.
• الخلية العصبية: وحدة البناء والوظيفة في الجهاز العصبي.
• التشجرات: مناطق اتصال الخلية العصبية بالخلايا الأخرى.
• الأعصاب: تجمع حزمة من المحاور العصبية مرتبطة بنسيج ليفي رابط.
• العصب الحسي: ينقل الحافز من الجسم إلى الجهاز العصبي المركزي.
• العصب الحركي: ينقل الإيعاز من المركزي إلى أنحاء الجسم.
• الأعصاب الشوكية: ألياف عصبية حسية وحركية، 31 زوجاً، تتفرع من الحبل الشوكي.
• الأعصاب القحفية: 12 زوجاً حسية وحركية ومختلطة.
• الإيعاز العصبي: انتقال الحوافز ورد الفعل عليها بين الخلايا العصبية وأجزاء الجسم.
• الوصلة العصبية: نقطة التقاء خليتين عصبيتين وانتقال الإيعاز بينهما.
• القوس الانعكاسي: الأعصاب التي تنقل الإيعاز والتي ترد عليه في الفعل الانعكاسي.

التعاليل:
• يُعد الجهاز العصبي الودي معاكساً لجار الودي: لأن الودي ينظم الجسم في الخطر (يزيد ضربات القلب)، وجار الودي يقلل ضربات القلب.
• يصاحب شلل الأطفال صعوبة في التنفس: لأن عضلات الصدر قد تصاب بالشلل.
• تزداد ضربات القلب عند الركض: بسبب الجهاز العصبي الودي.
• لا يمكن تعويض الخلايا العصبية عند موتها: لأنها من الخلايا التي لا تتجدد.

مقارنة: الأفعال الإرادية واللاإرادية:
• الإرادية: مركزها المخ، يتحكم بها الإنسان (المشي والكلام والكتابة).
• اللاإرادية: مركزها النخاع المستطيل، لا يتحكم بها (نبضات القلب والتنفس وعمل المعدة).'''),
    Section('الأمراض والمقارنات', Icons.healing, '''1) ذات السحايا (Meningitis):
• السبب: البكتريا غالباً، وقد يسببه نوع من الفيروسات. ينتقل بالرذاذ المتطاير من فم المريض عن طريق الأنف ثم الدورة الدموية ثم الخلايا السحائية المحيطة بالدماغ.
• الأعراض: ارتفاع الحرارة وصداع، تصلب الرقبة والانزعاج من الضوء والشعور بالنعاس.
• العلاج: مضادات حيوية يصفها الطبيب (إذا كان السبب بكتريا)، شرب كميات كبيرة من الماء والسوائل، الراحة التامة.
• الوقاية: تجنب العطاس بدون مناديل ورقية، عدم مصافحة أو تقبيل المصابين، التعقيم المستمر لأدوات ومكان المريض، التطعيم بلقاح السحايا للفئات المعرضة.

2) شلل الأطفال (Polio):
• السبب: فيروس يصيب الأطفال في مراحل أعمارهم المبكرة، ينتقل عن طريق الجهاز الهضمي ثم يصل إلى الجهاز العصبي (الحبل الشوكي والنخاع المستطيل). حضانة المرض عشرة أيام.
• الأعراض: ارتفاع الحرارة وتشنج عضلات الرقبة والظهر، اضطرابات عصبية وهذيان، فقدان الشهية وتقيؤ، شلل الأطراف العلوية والسفلية مع ألم في العضلات، وصعوبة التنفس والاختناق إذا أصيبت عضلات الصدر.
• العلاج: نقل الطفل إلى المستشفى، علاج طبيعي منتظم لمعالجة ضمور العضلات.
• الوقاية: اللقاح بشكل قطرات عن طريق الفم بثلاث جرعات أولية (بين كل جرعة وأخرى شهر)، ثم جرعتان منشطتان، أو حقنة في عضلة الفخذ الأيمن في الشهرين الرابع والسادس. وعزل الطفل المصاب وعدم استعمال أدواته.

3) الكزاز (Tetanus):
• السبب: بكتريا عصوية ذات مقاومة عالية للحرارة وغير متأثرة بالمطهرات، تصيب الجهاز العصبي المركزي وقد تؤدي إلى الشلل والوفاة.
• الأعراض: ارتفاع شديد في الحرارة وتشوش الرؤية وصداع، تشنجات عضلية في الرقبة وتصلب البلعوم وفقدان القدرة على بلع الطعام، تصلب عضلات البطن والظهر مع ألم شديد، تسارع النبض، تعابير تشبه التكشير على الوجه.
• العلاج: نقل المريض فوراً إلى المستشفى ووضعه تحت المراقبة.
• الوقاية: تفادي تلوث اليدين عند العمل بالتربة الرطبة واستعمال الأدوات الصدئة، استعمال الكفوف المطاطية، تعقيم الجروح فوراً، إكمال جرعات اللقاح الثلاثي (الكزاز والخناق والسعال الديكي)، وأخذ مصل ضد الكزاز فور التعرض للجروح.

الأمراض النفسية:
• تُدرج ضمن الجهاز العصبي لأن منشأها خلل في عمل الدماغ والأعصاب. التدخين والكحول والمخدرات والكسل ونمط الحياة غير الصحي والعوامل الوراثية تلعب دوراً في الإصابة.
1) الكآبة: حالة من الكسل الجسدي الشديد بسبب ظروف حياتية معينة أو الإدمان على المخدرات والكحول وبعض الأدوية غير الموصوفة. قد تكون مؤقتة أو دائمية.
• الأعراض: إرهاق وحزن وانعزال، صداع أو دوار مستمر، عدم السيطرة على الانفعالات.
• العلاج والوقاية: مراجعة الطبيب النفسي، الالتزام بالعلاج الموصوف، الامتناع عن الكحول والتدخين والمخدرات، نظام حياة صحي وتجنب السهر، شغل الفراغ بهوايات مفيدة.
2) انفصام الشخصية: مرض نفسي وراثي غالباً سببه خلل في عمل الجهاز العصبي المركزي (تغيرات في الإنزيمات والناقلات العصبية).
• الأعراض: هلوسة وتناقض الأفكار وتغير المزاج المفاجئ، اضطراب الذاكرة وعدم التعامل مع الآخرين، أرق وانعدام التركيز.
• العلاج والوقاية: عرض المريض على الأطباء فوراً، قد يحتاج مستشفى نفسي، تجنب الزواج بين العوائل التي تحمل تاريخاً مرضياً متكرراً، الابتعاد عن المخدرات والكحول والضوضاء، تجنب الإجهاد الطويل.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• عند الركض تزداد ضربات القلب بسبب الجهاز العصبي الودي.
• يمتد الحبل الشوكي بين نهاية النخاع المستطيل والفقرة القطنية الأخيرة.
• وظيفة المخيخ: تنظيم حركة العضلات الإرادية في الجسم.
• تصحيح: القوس الانعكاسي هو الأعصاب الناقلة للإيعاز والراد عليه في الفعل الانعكاسي، ومثاله سحب اليد عند وخزها بدبوس (وليس عمل المعدة).

أسئلة للمراجعة:
1) ما المقصود بكل مما يأتي: الأعصاب الشوكية، الأعصاب القحفية، الإيعاز العصبي؟
2) قارن بين الأفعال الإرادية والأفعال اللاإرادية.
3) ما أقسام الدماغ ووظيفة كل قسم؟
4) فسّر: وظيفة الجهاز العصبي الودي تعاكس وظيفة جار الودي.
5) فسّر: يصاحب مرض شلل الأطفال صعوبة في التنفس.
6) اذكر أعراض مرض ذات السحايا وطرق الوقاية منه.
7) اذكر طرق الوقاية من الكزاز وشلل الأطفال.
8) ما أنواع الأفعال العصبية ومركز كل منها؟
9) ارسم خلية عصبية نموذجية.'''),
  ]),
  Chapter('الفصل الثاني: الجهاز الهيكلي (العظمي)', [
    Section('الملخص', Icons.notes, '''مقدمة:
• الجهاز الهيكلي دعامة قوية صلبة تعطي الجسم شكله. العضلات والعظام معاً تسمى الجهاز الحركي: العضلات تولد القوة، والعظام هي المرتكز الذي تستند عليه العضلات.
• يحمي أعضاء الجسم: الجمجمة تحمي الدماغ، والقفص الصدري يحمي القلب والرئتين.

تركيب العظم:
• يتكون من نسيج مؤلف من خلايا عظمية نجمية الشكل مرتبة على هيئة حلقات أو دوائر في وسطها قناة مركزية تسمى قناة هافرس (نسبة إلى العالم كليبتون هافرس) تمر منها الأوعية الدموية المغذية لنسيج العظم.
• تقوم الخلايا العظمية بإفراز صفائح عظمية رقيقة تشكل المادة الصلبة في العظام.

التركيب الكيميائي للعظم:
1) مواد عضوية (35% تقريباً): غروية تسمى الكولاجين، ومادة شبه مخاطية تشبه الزلال لها أهمية في مرونة العظم تسمى ميوكول (Mucol).
2) مواد غير عضوية (65%): أملاح الكالسيوم (فلوريد وكلوريد وفوسفات الكالسيوم) وفوسفات المغنيسيوم وكلوريد الصوديوم.

أجزاء العظم (مثل عظم الفخذ):
• نهايتان إسفنجيتان منتفختان محاطتان بالغضروف (طبقة ملساء).
• بينهما جسم العظم المغطى بطبقة رقيقة تسمى القشرة أو السمحاق.
• يليها جزء صلب في داخله نقي العظم (نخاع العظم).

أقسام الجهاز الهيكلي:
• عدد عظام جسم الإنسان 206 عظام، موزعة على الهيكل المحوري والهيكل الطرفي.
• أنواعها: طويلة (الذراع)، قصيرة (المشط والسلاميات)، مسطحة (لوح الكتف)، غير منتظمة (الفقرات).

أولاً: الهيكل المحوري ويتكون من:
1) الجمجمة (29 عظماً): تحافظ على الدماغ.
• عظام القحف: 8 عظام حافاتها مسننة متداخلة تكوّن مفاصل ثابتة، وفي أسفلها فتحة لمرور الحبل الشوكي تسمى الثقب الأعظم. جمجمة الطفل فيها فراغات غضروفية–ليفية بين العظام تسمى اليافوخات.
• عظام الوجه: 14 عظماً (المحجران، الأنف، الفك العلوي غير المتحرك، الفك السفلي المتحرك).
• عظيمات الأذن الوسطى: المطرقة والسندان والركاب.
• الأسنان: تراكيب عظمية مخروطية لتقطيع ومضغ الطعام، عددها 32 سناً في البالغ (موزعة بالتساوي على الفكين). مؤقتة في الأطفال حتى السادسة (20 سناً لبنياً) ثم تصبح دائمة. يقسم السن إلى: التاج (الظاهر أعلى اللثة)، العنق (المينا ثم العاج ثم السمنت)، والجذر (مغروس في اللثة تمر منه الأعصاب والأوعية).
2) العمود الفقري: دعامة الجسم، طوله نحو 75 سم، يتكون من 33 فقرة تفصل بينها وسائد أو أقراص غضروفية تسهل انحناءه.
• أجزاء الفقرة: جسم الفقرة (الجزء القرصي المسطح)، القوس الشوكي (فيه الفراغ الشوكي، وفراغات جميع الفقرات تكوّن القناة الشوكية التي يمر فيها الحبل الشوكي)، النتوءات (النتوء الشوكي والنتوءان المستعرضان للأربطة والعضلات، وزوجان من النتوءات المفصلية يربطان الفقرات).
• أقسام العمود الفقري: العنقية (7 فقرات، أولها الأطلس ثم المحور)، الصدرية (12 فقرة تتصل بها الأضلاع)، القطنية (5 فقرات عريضة)، العجزية (5 فقرات مندمجة تكوّن عظم العجز)، العصعصية (4 فقرات ملتحمة تكوّن عظم العصعص).
3) القفص الصدري: الأضلاع وعظم القص.
• الأضلاع 12 زوجاً ترتبط من الخلف بنتوءات الفقرات الصدرية، ومن الأمام بعظم القص بقطع غضروفية (مهمة للتنفس: تسهل تمدد الحجاب الحاجز وحركة الرئتين).
• سبعة أزواج حقيقية (تتصل بعظم القص مباشرة)، ثلاثة أزواج كاذبة (ترتبط بغضروف الضلع السابع)، وزوجان سائبان لا يتصلان بشيء من الأمام.
• عظم القص: تركيب عظمي طويل مسطح من ثلاث قطع مندمجة.

ثانياً: الهيكل الطرفي (حزام الكتف مع الأطراف العليا، وحزام الحوض مع الأطراف السفلى):
• حزام الكتف: عظمان في كل جانب: لوح الكتف (مثلث الشكل خلف القفص الصدري) والترقوة (عظم رفيع مقوس يربط أعلى لوح الكتف بأعلى القص). التجويف الأروح ينشأ من التقاء الترقوة والكتف ويستقر فيه رأس العضد.
• الأطراف العليا: العضد (طويل قوي يتمفصل بالساعد بمفصل المرفق)، الساعد (الزند: الأطول ويقع للخارج جهة الخنصر، والكعبرة: الأقصر وتقع للداخل جهة الإبهام)، الكف (27 عظماً: الرسغ 8 عظام في صفين، المشط 5 عظام، السلاميات 14 عظماً: ثلاث في كل إصبع عدا الإبهام سلاميتان).
• حزام الحوض: نصفان متماثلان متصلان بالعمود الفقري وبعظم الفخذ، من الحرقفة والورك والعانة. حوض الإناث أخف نسبياً وأعرض وأقل عمقاً لتسهيل الحمل.
• الأطراف السفلى: عظم الفخذ (أطول وأقوى عظام الجسم)، مفصل الركبة تحميه الرضفة (الصابونة)، الساق (القصبة: ثاني أكبر عظام الساق، والشظية: نحيفة خلفية)، القدم (26 عظماً: الكاحل 7، المشط 5، الأصابع 14 سلامية).

الأجزاء الساندة:
1) الأربطة: أشرطة مرنة ليفية تربط العظام وتحمي المفاصل.
2) الأوتار: حبال ليفية تربط العضلات بالعظام.
3) الغضاريف: أجزاء مرنة بيضاء شبه شفافة تغلف نهايات العظام لحمايتها.
4) المفاصل: مناطق ارتباط عظمين، ثابتة (قحف الجمجمة) أو متحركة (المرفق). في المتحرك نهاية إحدى العظمتين محدبة والأخرى مقعرة بينهما كيس بروتيني يقلل الاحتكاك يسمى كيس المفصل. تعرض المفصل لقوة خارجية يسبب خلع العظام.
• أشكال المفاصل: كرة وتجويف (الكتف والحوض)، قفل ومفتاح (الركبة والمرفق)، محورية (فقرة الأطلس)، متزحلقة (رسغ اليد وكاحل القدم).

مزايا الجهاز الهيكلي للإنسان:
1) موازنة الجمجمة على العمود الفقري فصار الرأس مرفوعاً وبصر الإنسان بعيد المدى.
2) العمود الفقري رفيع من الأعلى ومتوسع من الأسفل فاكتسب الجسم المرونة والانتصاب.
3) سعة الحوض ساعدت على اتزانه على الأطراف السفلى.
4) الأطراف السفلى أطول من العليا فسهلت السير بخطوات متباعدة وطويلة.
5) تقوس أخمص القدم سهل المشي بصورة مريحة.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• الجهاز الحركي: العضلات والعظام معاً.
• قناة هافرس: قناة مركزية في نسيج العظم تمر منها الأوعية الدموية المغذية.
• السمحاق (القشرة): طبقة رقيقة تغطي جسم العظم.
• نقي العظم (نخاع العظم): جزء داخل العظم الصلب.
• الثقب الأعظم: فتحة أسفل القحف لمرور الحبل الشوكي.
• اليافوخات: فراغات غضروفية–ليفية بين عظام جمجمة الطفل.
• الأسنان اللبنية: 20 سناً مؤقتة في الأطفال حتى السادسة.
• الأربطة: أشرطة ليفية مرنة تربط العظام وتحمي المفاصل.
• الأوتار: حبال ليفية تربط العضلات بالعظام.
• الغضاريف: أجزاء مرنة تغلف نهايات العظام.
• المفصل: منطقة ارتباط عظمين، ثابت أو متحرك.
• كيس المفصل: كيس بروتيني يقلل الاحتكاك بين العظمين.
• خلع العظام: انفصال العظمين عند تعرض المفصل لقوة خارجية.
• عظم القص: تركيب عظمي طويل مسطح تتصل به الأضلاع الحقيقية.

التعاليل:
• وجود الوسائد (الأقراص) الغضروفية بين الفقرات: لتسهل انحناء العمود الفقري إلى الجهات كافة وعدم انفصال الفقرات عند حمل الأثقال.
• وجود القطع الغضروفية في الجهة الأمامية للأضلاع: لتسهل تمدد الحجاب الحاجز وحركة الرئتين أثناء التنفس.
• تقوس أخمص القدم في الإنسان: ليسهل المشي بصورة مريحة.
• حافات عظام القحف مسننة متداخلة: لتكوّن مفاصل ثابتة.
• حوض الإناث أعرض وأخف: لتسهيل عملية الحمل.
• لا تتسوس عظام الجسم كالأسنان: لأنها لا تتعرض للطعام والجراثيم كالفم (لا تحاط بالمينا والعاج).
• أصابع القدم مقتصرة على المشي: لأنها لا تتحرك بسهولة مثل أصابع اليد.

تصحيح عبارة:
• ترتيب طبقات السن من الداخل إلى الخارج: السمنت ثم العاج ثم المينا (وليس السمنت–الميناء–العاج).'''),
    Section('الأمراض والمقارنات', Icons.healing, '''1) الكساح (Rickets):
• يصيب الأطفال الصغار بين 1–2 سنة.
• السبب: نقص فيتامين D في الجسم وعدم التعرض الكافي لأشعة الشمس.
• الأعراض: تأخر المشي وتقوس الساقين وبطء تعظم الجمجمة (اليافوخ)، والطفل يصبح عصبياً ويبكي باستمرار.
• العلاج: مراجعة الطبيب، نظام غذائي غني بالعناصر المساعدة على بناء العظام، جرعات منتظمة من فيتامين D والكالسيوم.
• الوقاية: الرضاعة الطبيعية، وجود الأطفال في أماكن مشمسة شتاءً مع عدم تعريضهم لفترة طويلة صيفاً.

2) هشاشة العظام (Osteoporosis):
• ضعف النسيج العظمي وبنية العظم فتصاب العظام بإصابات خطيرة عند بذل أدنى جهد وقد تتطور إلى كسور مضاعفة. يصيب النساء أكثر من الرجال وخصوصاً بعد سن الخمسين.
• الأعراض: ألم حاد في العظام والأنسجة المحيطة بسبب التآكل، حدوث الكسور بسهولة، انحناء وتقوس العظام والفقرات مع التقدم بالعمر.
• العلاج: مراجعة الطبيب المختص، تحاليل دورية لنسبة الكالسيوم وفيتامين D (خصوصاً للنساء اللواتي تضم عوائلهن إصابات وراثية).
• الوقاية: غذاء صحي متوازن، عدم زيادة الوزن (السمنة)، عدم تناول المشروبات الغازية لأنها تسبب تآكل العظام ونخرها، عدم التدخين وتناول الكحول والعقاقير غير المسموحة.

3) التهاب المفاصل (Arthritis):
• تورم يصيب مفصلاً أو أكثر ويظهر أكثر مع التقدم في السن.
• أنواعه: عظمي (بسبب تكسر واضمحلال الغضاريف التي تغطي نهايات العظام)، وروماتيزمي (تتآكل بطانة المفصل من الداخل بسبب خلل في الجهاز المناعي).
• أسبابه: العوامل الوراثية أساساً، وارتفاع حامض اليوريك في الدم فيتراكم في المفاصل ويسبب تصلبها وصعوبة حركتها.
• الأعراض: تيبس المفاصل، ألم حاد عند الحركة، تورم المنطقة واحمرار الجلد المحيط.
• العلاج: الالتزام بعلاج الطبيب، علاج طبيعي ورياضة المشي البطيء في الحالات الطفيفة، وفي المتفاقمة جراحة لإصلاح المفصل أو استبداله.
• الوقاية: الحذر من السمنة، غذاء متوازن وعدم الإكثار من اللحوم الحمراء (مصدر حامض اليوريك)، رياضة منتظمة، تدفئة الجسم شتاءً وتجنب تيارات الهواء البارد.

مقارنة: حزام الكتف وحزام الحوض:
• حزام الكتف: عظمان في كل جانب (لوح الكتف والترقوة) يتصل بالأطراف العليا.
• حزام الحوض: نصفان متماثلان من الحرقفة والورك والعانة، يتصل من الأعلى بالعمود الفقري ومن الأسفل بعظم الفخذ (الأطراف السفلى). وهو أعرض وأخف في الإناث.

مقارنة: الأضلاع:
• 7 أزواج حقيقية (مباشرة بالقص)، 3 أزواج كاذبة (بغضروف الضلع السابع)، زوجان سائبان.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• الفراغات الغضروفية–الليفية في جمجمة الطفل تسمى اليافوخات.
• المنطقة التي تسبق الفقرات القطنية في العمود الفقري: الصدرية.
• العظم الذي لا ينتمي للأطراف العليا: القصبة (من عظام الساق).
• عدد عظام الجسم 206، الجمجمة 29، الأسنان 32، فقرات العمود 33.

أسئلة للمراجعة:
1) ما المقصود بكل من: قناة هافرس، السمحاق، الثقب الأعظم، الأوتار، عظم القص؟
2) وضح التركيب الكيميائي للعظم.
3) صف أجزاء الفقرة.
4) قارن بين حزام الكتف وحزام الحوض في الإنسان.
5) عدد مزايا الجهاز الهيكلي في الإنسان.
6) فسّر: وجود الوسائد الغضروفية بين الفقرات، وجود القطع الغضروفية أمامية للأضلاع، تقوس أخمص القدم.
7) صحح: تركيب السن من الداخل إلى الخارج.
8) عدد أقسام العمود الفقري وعدد فقرات كل قسم.
9) ما أعراض الكساح وهشاشة العظام وكيف تقي منهما؟
10) ارسم مع التأشير: مقطع عرضي لنسيج العظم، تركيب السن، تركيب الفقرة.'''),
  ]),
  Chapter('الفصل الثالث: الجهاز العضلي', [
    Section('الملخص', Icons.notes, '''مقدمة:
• العضلات تستند إلى الجهاز العظمي، وهي بمثابة العجلات التي تنقل جسم السيارة. تنجز وظيفة الحركة في الجسم سواء الخارجية (الركض) أو الداخلية (تقلص الأمعاء).

أنواع العضلات في جسم الإنسان:

1) العضلات الهيكلية (إرادية):
• مجموع العضلات الجسمية المرتبطة بالهيكل العظمي، تحرك الجسم أو جزءاً منه، وتشكل أغلب عضلات الجسم. تقلصها وانبساطها تحت سيطرة الإنسان.
• تتألف من خلايا وألياف عضلية أسطوانية عديدة النوى طويلة جداً (قد يصل طولها 130 ملم)، تتجمع في مجاميع تسمى الحزيمات، وبتجمعها تكون العضلة الهيكلية.
• مميزاتها: حمراء اللون مخططة، إرادية، كبيرة غالباً (عضلات الساق والذراع)، ترتبط بالعظام عن طريق الأوتار (وبعضها يتصل مباشرة كعضلة العين)، شكلها أسطواني مخطط عديدة النوى جانبية الموقع.

2) العضلات الملساء (لاإرادية):
• توجد في جدار القناة الهضمية والأجزاء الداخلية للجسم (الأوعية الدموية والمعدة والأمعاء). تقلصها وانبساطها لا يخضع لإرادة الفرد.
• تتألف من خلايا طويلة مغزلية الشكل لكل منها نواة واحدة بيضوية في المركز، وغير مخططة (ولذلك سميت ملساء)، لا ترتبط بالجهاز الهيكلي.

3) العضلات القلبية (لاإرادية):
• توجد في جدار القلب فقط. كل ليف عضلي قلبي يتألف من لييفات مرتبة طولياً ومخططة عرضياً.
• مميزاتها: مخططة حمراء متفرعة أحادية أو متعددة النوى، لها أقراص بينية (بمثابة الغشاء الخلوي الفاصل بين كل خليتين من خلايا عضلة القلب)، لاإرادية، توجد في عضلة القلب فقط.

كيف تعمل العضلات؟
• تعمل العضلات الجسمية بانسجام مع الهيكل العظمي وفق مبدأ العتلات. عند رفع ثقل يجب تحريك أجزاء أخرى من الجسم لتوزيع القوى (انفراج القدمين).
• موقع الجمجمة على فقرة الأطلس يتيح تحريكها للجهات المختلفة أثناء رفع الثقل دون فقدان التوازن. وعند الركض تمتد القدم اليمنى واليد اليسرى للأمام بينما اليسرى واليمنى للخلف لتوزيع القوة.
• التنسيق في عمل العضلات: في عضد اليد تتقلص العضلة الثنائية فيتقرب الساعد من العضد، وبتقلص الثلاثية يبتعد الساعد عنه. وفي الفخذ إذا انقبضت العضلة الرباعية صار الفخذ بامتداد الساق.
• تصنف حسب آلية العمل إلى: قابضة وباسطة، ومقربة (الصدرية الكبيرة تقرب الذراع نحو منتصف الصدر)، ومبعدة (الدالية تبعد الذراع عن الصدر وترفعها).

آلية عمل العضلة:
1) يصدر الدماغ إيعازاً للعضلة عبر التفرعات العصبية من النخاع الشوكي ثم الأعصاب المحيطية، وتتصل بالعضلة بوساطة الوصلة العصبية–العضلية.
2) عند تسلم العضلة الإيعاز تتقلص أو تنبسط حسب الإيعاز الوارد من الجهاز العصبي المركزي.
3) التقلص والانبساط يتم بصورة تشبه انتقال التيار الكهربائي.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• العضلات الهيكلية: العضلات المرتبطة بالهيكل العظمي المسؤولة عن حركة الجسم، وهي إرادية.
• العضلات الملساء: عضلات لاإرادية غير مخططة في جدار القناة الهضمية والأعضاء الداخلية.
• العضلات القلبية: عضلات لاإرادية مخططة متفرعة توجد في جدار القلب فقط.
• الحزيمات: مجاميع من الألياف العضلية تشكل بتجمعها العضلة الهيكلية.
• الأقراص البينية: تراكيب في العضلة القلبية بمثابة الغشاء الخلوي الفاصل بين كل خليتين.
• الإعياء العضلي: أقصى درجات التعب، تفقد فيه العضلة استجابتها بسبب تراكم حامض اللبنيك.
• الوصلة العصبية–العضلية: ارتباط خاص يربط الأعصاب المحيطية بالعضلة.
• ضمور العضلات: ضعف وانحلال الأنسجة العضلية تدريجياً بسبب قلة أو انعدام الحركة.

التعاليل:
• تنصح الأمهات حديثات الولادة بالرضاعة الطبيعية: لأنها تحمي أنسجة الثدي من التصلب وتسمح للدم بالسريان فيها بشكل طبيعي (وتقي من سرطان الثدي).
• يفرج الإنسان قدميه عند رفع جسم ثقيل: ليوزع القوى ويحافظ على توازن الجسم.
• تسمى العضلات الملساء بهذا الاسم: لأنها غير مخططة.
• تسمى الهيكلية إرادية: لأن الإنسان يتحكم بتقلصها وانبساطها.
• تتعب العضلة عند العمل المستمر: لتراكم حامض اللبنيك الناتج عن حرق الكلوكوز.
• تسارع ضربات القلب وارتفاع الحرارة والتعرق في الإعياء: نتيجة التعب الشديد للعضلات.
• يحدث الخدر في الساقين عند الجلوس طويلاً: بسبب ضغط الجلوس وقلة وصول الدم والأوكسجين إلى العضلات والأعصاب.

مقارنة بين أنواع العضلات:
• الهيكلية: إرادية، مخططة، حمراء، عديدة النوى، أسطوانية، ترتبط بالعظام بالأوتار.
• الملساء: لاإرادية، غير مخططة، خلاياها مغزلية أحادية النواة مركزية، في القناة الهضمية والأوعية والأعضاء الداخلية، لا ترتبط بالهيكل.
• القلبية: لاإرادية، مخططة، متفرعة، أحادية أو متعددة النوى، فيها أقراص بينية، في القلب فقط.
• الصفة المشتركة بين الملساء والقلبية: الحركة اللاإرادية.'''),
    Section('الأمراض والمقارنات', Icons.healing, '''1) الإعياء العضلي (Muscle fatigue):
• تحتاج العضلة للأوكسجين وسكر الكلوكوز، والأوكسجين يحرق السكر لتحرير الطاقة:
كلوكوز + أوكسجين ← ثنائي أوكسيد الكاربون + ماء + طاقة + حامض اللبنيك (اللاكتيك).
• لا بد من توفر الطاقة والأوكسجين والراحة لتعمل العضلات بشكل طبيعي، وإلا أصيبت بالتعب. والاستمرار بالعمل والعضلات متعبة يسبب الإعياء.
• الآثار: عدم استجابة العضلة للعمل بسبب تراكم حامض اللبنيك رغم الأوامر العصبية، تسارع ضربات القلب وارتفاع حرارة الجسم، تعب شديد وتعرق وعدم القدرة على التركيز.

2) سرطان الثدي (Breast cancer):
• من أخطر الأمراض وقد يسبب الموت إن لم يُشخص ويُعالج مبكراً. ينشأ من انقسام الخلايا في الغدد اللبنية انقساماً سريعاً غير منظم فيتضخم النسيج ويتصلب ويمنع وصول الدم للخلايا، ثم ينتشر الورم إلى الأنسجة والعقد اللمفاوية والأعضاء القريبة.
• المسببات: العامل الوراثي أبرزها، ثم التعرض لمواد مشعة وكيميائية خطيرة، أو انتقال الورم عبر اللمف من أعضاء أخرى.
• الأعراض: ظهور عقد صغيرة في الثدي، تورم العقد اللمفاوية تحت الإبط، إفرازات من الحلمة، تغير شكل الحلمة ولونها في الحالات المتقدمة.
• العلاج: مراجعة الطبيب فوراً، الجراحة لاستئصال الورم أو الثدي كاملاً، العلاج الكيميائي بعد الجراحة (مواد كيميائية ذات آثار جانبية قوية تمنع انتشار الورم وتقتل الخلايا السرطانية).
• الوقاية: فحص دوري للثدي مرة شهرياً، الرضاعة الطبيعية، عدم تعريض مناطق الثدي للمواد المشعة (الليزر خصوصاً)، تجنب التدخين والكحول.

3) ضمور العضلات (Muscles Atrophy):
• ضعف وانحلال الأنسجة العضلية تدريجياً بسبب قلة أو انعدام الحركة لوقت طويل، يظهر أحياناً في الطفولة المبكرة ويتفاقم مع السن، ويصيب غالباً المصابين بعوق دائمي وقليلي الحركة. له أنواع حسب مكان الإصابة.
• الأعراض: صعوبة بالغة عند الوقوف، عدم القدرة على المشي، ألم قوي وتيبس في العضلات، تهدل الجلد المحيط بالعضلات.
• العلاج: مراجعة الطبيب، علاج بدني وفيزيائي، الالتزام بالعلاج الموصوف، نظام غذائي موصوف لإعادة بناء الأنسجة.
• الوقاية: ممارسة الرياضة وتجنب الجلوس الطويل بدون حركة، تغيير وضعية نوم المرضى الراقدين باستمرار، الغذاء الصحي الحاوي على البروتينات (أهم عنصر لبناء العضلات)، الابتعاد عن التدخين والكحول والهواء الملوث.

الصداع (معلومة إضافية): ألم في عضلات الرأس بسبب خلل في الدورة الدموية أو الجيوب الأنفية أو الإجهاد أو الحمى أو أمراض العين أو ارتفاع الضغط أو إصابة في الرأس.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• من الأعضاء التي تحتوي عضلات ملساء: الأمعاء.
• الصفة التي تجمع العضلات الملساء والقلبية: الحركة اللاإرادية.
• تصحيح: تتصل الأعصاب المحيطية بالعضلات بوساطة ارتباط خاص يسمى الوصلة العصبية–العضلية (وليس الأوتار).
• تصحيح معادلة الإعياء العضلي: كلوكوز (وليس الفركتوز) + أوكسجين ← ثنائي أوكسيد الكاربون + طاقة + ماء + حامض اللبنيك (وليس الكبريتيك).

أسئلة للمراجعة:
1) ما المقصود بـ: العضلات الهيكلية، العضلات الملساء، العضلات القلبية، الإعياء؟
2) وضح تركيب العضلة.
3) اذكر جوانب الاختلاف بين العضلات الهيكلية والملساء والقلبية.
4) اشرح وظيفة كل نوع من أنواع العضلات.
5) فسّر: قيام الإنسان بإفراج قدميه عند رفع جسم ثقيل.
6) فسّر: تنصح الأمهات حديثات الولادة بالرضاعة الطبيعية.
7) لخص آلية عمل العضلة.
8) ما أعراض الإعياء العضلي وضمور العضلات وسرطان الثدي؟
9) ارسم مع التأشير: عضلة هيكلية، عضلة ملساء، عضلة قلبية.
10) أي الرياضيين يصاب بالإعياء العضلي أسرع: العداء أم لاعب الكرة الطائرة؟ ولماذا؟'''),
  ]),
  Chapter('الفصل الرابع: الجهاز الهضمي', [
    Section('الملخص', Icons.notes, '''مقدمة:
• يحتاج الجسم للطاقة لإنجاز فعالياته والنمو وتعويض الخلايا التالفة، فيحتاج للغذاء باستمرار. يحول الجهاز الهضمي المواد الغذائية إلى مواد أبسط تركيباً يمكن امتصاصها، ويطرح غير المفيد منها، وتعينه غدد ملحقة.

أجزاء الجهاز الهضمي:
1) الفم: بداية الجهاز الهضمي، سقفه عظمي مبطن بغشاء مخاطي. فيه اللسان (عضو عضلي يدور اللقمة عند المضغ ويدفعها للبلعوم ويقوم بالتذوق والنطق) والأسنان، وتفتح فيه الغدد اللعابية.
• وظيفة الأسنان: القواطع (4 في كل فك) تقطع الطعام، الأنياب (2 في كل فك) تمزق الأجزاء القوية كاللحوم، الأضراس (10 في كل فك) تطحن الطعام.
2) البلعوم: جزء عضلي مخاطي يتصل بالفم أمامياً وبالمريء والحنجرة خلفياً، ويفصله عن الحنجرة قطعة غضروفية مرنة تسمى لسان المزمار. على جانبيه اللوزتان (غدتان لمفاويتان)، وتفتح فيه قناتا أوستاكي المتصلتان بالأذن الوسطى.
3) المريء: أنبوب عضلي طوله نحو 25 سم، يصل البلعوم بالمعدة (الفتحة الفؤادية)، يمر من الحجاب الحاجز، جداره يتقلص دافعاً الغذاء نحو المعدة.
4) المعدة: كيس عضلي تحت الحجاب الحاجز في الجهة العلوية اليسرى من البطن، جدرانها عضلية متعرجة فيها العصارات الهاضمة، يغلفها البريتون. الفتحة الفؤادية (مع المريء) فيها عضلة عاصرة تمنع رجوع الغذاء للمريء، والفتحة البوابية (السفلى) فيها عضلة عاصرة بوابية تمنع رجوع الغذاء من الإثنى عشري.
• وظائف المعدة: خلط الطعام بحركتها التموجية، إفراز إنزيم الببسين الذي يجزئ البروتينات إلى أحماض أمينية، إفراز حامض الهيدروكلوريك HCl المخفف (تركيز 0.2%) لجعل الوسط حامضياً مناسباً لعمل الإنزيمات، وامتصاص بعض العناصر الغذائية.
5) الأمعاء الدقيقة: أنبوب عضلي طوله 6–7 م، جدرانه الداخلية فيها أعداد هائلة من البروزات تسمى الزغابات (تكمل الهضم وتمتص المواد المهضومة وتدفع الفضلات نحو الغليظة). وتقسم إلى:
• الإثنا عشري: على شكل حرف U، فيه غدة البنكرياس، تفتح فيه القناة الصفراوية مشتركة مع البنكرياس، طوله نحو 30 سم.
• الصائم: يلي الإثنا عشري، لا يثبت فيه الطعام ويكون خالياً من الطعام عند وفاة الإنسان (لذا سمي بالصائم).
• اللفائفي: القسم الأخير والأكبر، يتصل بالأمعاء الغليظة عن طريق الأعور.
6) الأمعاء الغليظة: آخر القناة الهضمية، طولها نحو 1.5 م، جدرانها عضلية متعددة الطبقات خالية من الزغابات، وظيفتها إكمال امتصاص الماء ودفع الفضلات نحو المخرج. تقسم إلى:
• الأعور: في بداية الأمعاء الغليظة (السفلى اليمنى)، كيسي الشكل، يتصل بأنبوب صغير مغلق يسمى الزائدة الدودية.
• القولون: صاعد (يمين الجوف البطني)، مستعرض (أعلى البطن من اليمين إلى اليسار)، نازل (يسار البطن وينتهي بالمستقيم).
7) المستقيم: أنبوب عضلي يربط القولون بالشرج.
8) المخرج (الشرج): الفتحة الخارجية للجهاز الهضمي.

الغدد الملحقة:
1) الغدد اللعابية (3 أزواج): النكفية (على جانبي الوجه)، تحت الفكية، تحت اللسانية. تفرز اللعاب الذي يرطب الفم ويحتوي إنزيم التايلين الذي يحول المواد النشوية إلى سكريات بسيطة حلوة.
2) البنكرياس: غدة مستطيلة بين المعدة والإثنى عشري. فيه جزر لانكرهانز تفرز هرمون الأنسولين للدم، وخلايا إفرازية تفرز إنزيمات هاضمة للبروتينات والدهنيات والكاربوهيدرات تصب في قناة رئيسية إلى الإثنى عشري.
3) الكبد: في الجهة البطنية اليمنى العليا تحت الأضلاع، بني اللون إسفنجي القوام، من فصين (أيسر صغير وأيمن كبير). على السطح السفلي للفص الأيمن كيس الصفراء (المرارة) الذي يفرز ويخزن المادة الصفراء لهضم الدهون وتنتقل إلى الأمعاء عن طريق القناة الصفراوية.
• وظائف الكبد: إفراز الصفراء لهضم الدهون، خزن الكاربوهيدرات الزائدة على هيئة نشا حيواني (كلايكوجين)، تحويل البروتينات الزائدة إلى يوريا تطرح عن طريق الكليتين، تصنيع إنزيم الهيبارين الذي يمنع تخثر الدم داخل الجسم، تصنيع مواد تخثر الدم عند الجروح (البروثرومبين والفايبرينوجين).

كيف يحدث الهضم؟
• الهضم: تحويل المواد الغذائية معقدة التركيب إلى مواد بسيطة يسهل امتصاصها.
أولاً: في الفم (هضم ميكانيكي): تذوق وتدوير الطعام باللسان، تقطيعه ومضغه بالأسنان، إفراز اللعاب بإنزيم التايلين الذي يهضم النشويات إلى سكريات بسيطة، ودفع الطعام نحو البلعوم.
ثانياً: في المعدة: يمتزج الغذاء بالإنزيمات (ومنها الببسين) بحركات المعدة التموجية، يعمل HCl المخفف مع الببسين على تجزئة البروتينات، يتحول الغذاء إلى كتلة تسمى الكيموس، ويُدفع الكيموس من الفتحة البوابية إلى الإثنى عشري.
ثالثاً: في الأمعاء الدقيقة: يمتزج الغذاء بالصفراء (من الكبد عن طريق القناة الصفراوية) وبإنزيمات البنكرياس وإنزيمات الغدد الهاضمة المعوية لتهضم الدهنيات والبروتينات والكاربوهيدرات، ويتحول إلى سائل أبيض كثيف القوام يسمى الكيلوس (مواد بسيطة التركيب) ثم يُمتص عبر جدران الأمعاء.

الامتصاص والتمثيل الغذائي:
• الزغابات تمتص المواد الغذائية بتوسيع السطح الداخلي للأمعاء. الدم ينقل الأحماض الأمينية (البروتينات البسيطة) والسكريات إلى خلايا الجسم، واللمف ينقل الأحماض الدهنية والكليسرين.
• التمثيل الغذائي (الأيض): تحويل المواد الغذائية الأولية الممتصة من الأمعاء الدقيقة إلى مواد حية تضاف إلى الجسم لبناء أو تعويض الخلايا التالفة.

مكونات الغذاء:
1) الكاربوهيدرات (CxHxOx: كاربون وهيدروجين وأوكسجين بنسب محددة):
• السكريات: بسيطة حلوة تذوب بسهولة، أحادية (الكلوكوز C₆H₁₂O₆ وهو سكر العنب، والفركتوز سكر الفواكه) وثنائية من جزيئتين أحاديتين (السكروز سكر القصب، واللاكتوز سكر الحليب). سريعة الامتصاص، والكلوكوز ينتشر للخلايا دون هضم.
• النشويات: جزيئات كبيرة من اتحاد السكريات، لا تذوب بسهولة (النشا في الحنطة والشعير والرز والبطاطا)، تهضمها العصارات اللعابية والمعوية بإنزيمي الأميليز واللايبيز.
• السيليلوز: كاربوهيدرات معقدة غير قابلة للهضم تخرج مع الغائط.
2) الدهنيات (C، H، O بنسب تختلف عن الكاربوهيدرات): مصدر أساسي للطاقة (سعراتها أعلى كثيراً من الكاربوهيدرات)، تُخزن تحت الجلد أو داخل الجسم. نباتية (زيت السمسم والزيتون وزهرة الشمس والفول السوداني) أو حيوانية (الزبد والحليب والشحوم).
3) البروتينات: كاربون وهيدروجين وأوكسجين ونتروجين وقليل من الكبريت والفسفور. مصدرها حيواني (لحوم، بيض، حليب ومشتقاته) أو نباتي (الباقلاء والفاصوليا والحمص والعدس). يحتاجها الجسم نحو 100 غم يومياً، وأكثر بعد الإصابة بالأمراض لتعويض الخلايا الميتة.
4) الفيتامينات: ضرورية بكميات قليلة وبصورة مستمرة. تتميز بأن: بعضها يذوب في الماء وبعضها في الدهون (التي تذوب في الدهون لا تذوب في الماء)، وتتلف بالحرارة، وزيادتها عن حاجة الجسم تسبب آثاراً سلبية.
5) الأملاح والمعادن: مكملة لعمل الجسم (الحديد، الصوديوم، البوتاسيوم، الكالسيوم، الفسفور، اليود) في ملح الطعام والفواكه والخضر واللحوم والحليب. نقصها يسبب فقر الدم واضطراب الغدة الدرقية.
6) الماء: يشكل 60% من وزن الجسم، وسط تذوب فيه المواد وتنتقل. نقصه يسبب الجفاف وخللاً في عمل الكلية. تزداد الحاجة له في الأيام الحارة وعند المجهود الشاق.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• الهضم: تحويل المواد الغذائية معقدة التركيب إلى مواد بسيطة يسهل امتصاصها.
• التمثيل الغذائي (الأيض): تحويل المواد الغذائية الأولية الممتصة إلى مواد حية تضاف للجسم لبناء أو تعويض الخلايا.
• البلعوم: جزء عضلي مخاطي بين الفم والمريء والحنجرة.
• المريء: أنبوب عضلي طوله 25 سم يصل البلعوم بالمعدة.
• الكيموس: كتلة غذائية تتكون في المعدة.
• الكيلوس: سائل أبيض كثيف القوام في الأمعاء الدقيقة من مواد غذائية بسيطة.
• الزغابات: بروزات دقيقة في جدار الأمعاء الدقيقة توسع سطح الامتصاص.
• الكاربوهيدرات: مواد من الكاربون والهيدروجين والأوكسجين بنسب محددة.
• السيليلوز: كاربوهيدرات معقدة لا تهضم.
• الكلايكوجين: النشا الحيواني، شكل خزن الكاربوهيدرات في الكبد.
• الفتحة الفؤادية: فتحة المعدة المتصلة بالمريء، فيها عضلة عاصرة تمنع رجوع الغذاء.
• الفتحة البوابية: الفتحة السفلى للمعدة نحو الإثنى عشري.
• لسان المزمار: قطعة غضروفية تفصل البلعوم عن الحنجرة.

وظائف مهمة:
• الفتحة الفؤادية: عضلة عاصرة تمنع رجوع الغذاء للمريء.
• كيس الصفراء: يخزن ويفرز المادة الصفراء لهضم الدهون.
• إنزيم التايلين: يحول النشويات إلى سكريات بسيطة (في الفم).

التعاليل:
• احتواء الأمعاء الدقيقة على أعداد هائلة من الزغابات: لتوسيع السطح الداخلي وزيادة امتصاص المواد الغذائية.
• سمي الصائم بهذا الاسم: لأنه يكون خالياً من الطعام عند وفاة الإنسان.
• نقص فيتامين K يؤدي إلى بطء تخثر الدم عند الجروح: لأنه يساعد على تكوين الخثرة الدموية.
• يفرز المعدة HCl: لجعل الوسط حامضياً مناسباً لعمل الإنزيمات الهاضمة.
• تسبب السكائر تلف المعدة والأسنان وفقدان الشهية: بسبب مواد ضارة تؤثر في الأنسجة والعصارات.
• عدم قابلية السيليلوز للهضم: لأنه معقد التركيب فيخرج مع الغائط.

مقارنة بين الأمعاء الدقيقة والغليظة:
• الدقيقة: طولها 6–7 م، فيها زغابات، وظيفتها إكمال الهضم وامتصاص المواد المهضومة.
• الغليظة: طولها 1.5 م، خالية من الزغابات، وظيفتها إكمال امتصاص الماء ودفع الفضلات للمخرج.

تصحيح عبارات:
• الهضم: تحويل المواد المعقدة إلى بسيطة. التمثيل الغذائي: تحويل المواد الممتصة إلى مواد حية (الجملة في السؤال معكوسة).
• يبدأ هضم المواد النشوية في الفم (وليس الأمعاء الدقيقة) بإنزيم التايلين.
• الناقل الرئيس لمرض التيفوئيد هو الذباب (وليس الجرذان).'''),
    Section('الفيتامينات والأمراض', Icons.healing, '''الفيتامينات التي تذوب في الماء:
• فيتامين B (B1، B2، B3، B5، B6، B12): مصادره الحليب والبيض والبقوليات والأسماك والكبد. يؤثر في سلامة الجهاز العصبي والبصر والفعاليات الحيوية وبناء كريات الدم الحمر. نقصه: اضطراب عمل الجسم والأعصاب وفقر الدم.
• فيتامين C: الحمضيات وبعض الخضراوات. يقاوم الأمراض ويعزز المناعة. نقصه: تسوس الأسنان ونزف اللثة وتشقق الشفة (داء الإسقربوط) واضطراب عمل الكبد.

الفيتامينات التي تذوب في الدهون:
• فيتامين D: الكبد والبيض والحليب والزبد وأشعة الشمس. ينمي العظام والأسنان ويؤثر على امتصاص الكالسيوم والفسفور. نقصه: هشاشة العظام والمفاصل (الكساح).
• فيتامين A: الحليب والزبد والبيض والسمك والجزر والطماطم والفواكه. سلامة البصر ومقاومة الأمراض. نقصه: العشو الليلي وجفاف الجلد وضعف مقاومة الأغشية المخاطية.
• فيتامين E: الحليب والبيض والبقوليات والخضراوات والمكسرات. ينشط المناعة ويقلل تصلب الشرايين وخطر السرطان. نقصه: ضعف الأعصاب والعضلات.
• فيتامين K (K1، K2، K3): الخضراوات كالسبانغ ومنتجات الألبان واللحوم والأسماك. يساعد على تكوين الخثرة الدموية. نقصه: بطء تخثر الدم.

1) الكوليرا (Cholera):
• مرض وبائي معدي ينتشر بسرعة في الصيف، تسببه بكتريا ضمات الكوليرا (Vibrio cholera) اكتشفها روبرت كوخ عام 1885. ينتقل بالغذاء والماء الملوثين. تظهر أعراضه بعد يومين من الإصابة.
• الأعراض: تقيؤ وإسهال شديد بدون ألم، قوام الغائط سائل يشبه ماء الرز، جفاف شديد وفقدان وزن وتجعد الجلد، عجز عن الحركة وانخفاض حرارة الجسم مع تقدم المرض.
• العلاج: مراجعة الطبيب وإدخال المستشفى وإعطاء المضادات الحيوية، سائل مغذٍّ بالوريد وشرب السوائل، عزل المريض.
• الوقاية: عدم الاختلاط بالمصابين واستعمال أدواتهم، غسل الفواكه والخضر، عدم تناول أي طعام أو ماء من الباعة المتجولين، زيادة نسبة الكلور في الماء ضمن النسب المسموحة.

2) التيفوئيد (Typhoid):
• ينتقل بالطعام والشراب الملوثين ببكتريا Salmonella typhi.
• الأعراض: ارتفاع الحرارة مع صداع شديد، فقدان الشهية وضعف عام.
• العلاج: مراجعة الطبيب، عدم الإجهاد، شرب كميات كافية من الماء والسوائل، كمادات عند ارتفاع الحرارة.
• الوقاية: الامتناع عن الأطعمة من الباعة المتجولين وعدم الشرب من نفس القدح، القضاء على الذباب (أهم واسطة نقل)، عدم استعمال أدوات المريض، غسل اليدين بالماء والصابون بعد دورة المياه، نظافة المنزل.

3) قرحة المعدة والإثنى عشري:
• تسببها أنواع من البكتريا، والتدخين وتناول الكحول والمخللات بكثرة، والشد النفسي والعصبي، والعوامل الوراثية.
• الأعراض: حرقة شديدة وألم في المعدة، انتفاخ وعدم هضم الطعام وغازات ورغبة بالتقيؤ، فقدان الوزن.
• العلاج: مراجعة الطبيب والفحص بالناظور، الالتزام بالحمية وانتظام العلاج.
• الوقاية: الابتعاد عن التدخين والكحول والأغذية الغنية بالتوابل والمواد الحامضية والدهون، الامتناع عن المشروبات الغازية، عدم البقاء مدة طويلة بدون طعام أو شراب.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• من إنزيمات المعدة: الببسين.
• حامض الهيدروكلوريك في المعدة له دور في تجزئة البروتينات.
• نقص فيتامين A يؤدي إلى العشو الليلي.
• الفيتامين الذي يذوب في الماء: فيتامين C.

أسئلة للمراجعة:
1) ما المقصود بكل من: البلعوم، المريء، الكيموس، الكاربوهيدرات؟
2) بيّن أنواع الأسنان ووظائفها.
3) تتبع بالأسهم مسار الغذاء في الجهاز الهضمي.
4) وضح وظيفة كل من: الفتحة الفؤادية، كيس الصفراء، إنزيم التايلين.
5) اذكر جوانب الاختلاف بين الأمعاء الدقيقة والغليظة.
6) قارن بين فيتامين C وفيتامين A.
7) ما أبرز أعراض الكوليرا؟
8) فسّر: نقص فيتامين K يؤدي إلى بطء تخثر الدم، واحتواء الأمعاء الدقيقة على أعداد هائلة من الزغابات.
9) عدد وظائف الكبد والبنكرياس.
10) صحح: تعريف الهضم والتمثيل الغذائي، بدء هضم النشويات، ناقل التيفوئيد.
11) ارسم مع التأشير: تركيب الجهاز الهضمي وتركيب الزغابة.'''),
  ]),
  Chapter('الفصل الخامس: جهاز الدوران', [
    Section('الملخص', Icons.notes, '''مقدمة:
• جهاز الدوران مسؤول عن نقل الأوكسجين والمواد الغذائية الممتصة والهرمونات إلى أنسجة الجسم، ونقل ثنائي أوكسيد الكاربون إلى الرئتين واليوريا والماء والأملاح الزائدة إلى الجلد والكليتين.
• مزاياه في الإنسان: جهاز مغلق (الدم يدور في أوعية دموية متصلة)، القلب من أربع ردهات لا يختلط فيها الدم، والدم من خلايا متخصصة بالتنفس والدفاع والبلازما هي السائل الناقل.

مكونات جهاز الدوران:

1) الدم: سائل أحمر يشكل نحو 7% من وزن الجسم (4–6 لترات)، ويتكون من:
أ) البلازما: سائل مائل للاصفرار يشكل نحو 55% من الدم، والماء أهم مكوناتها (90%). وسط ينقل الغذاء الممتص والماء والأملاح والهرمونات واليوريا.
ب) خلايا الدم:
• خلايا الدم الحمر (RBC): قرصية الشكل، لها أنوية في بداية تكوينها ثم تفقدها، تعيش نحو أربعة أشهر، قطرها 8 مايكرون. وظيفتها تنفسية لاحتوائها على صبغة الهيموغلوبين (من بروتين Globin وحديد Haemo): تنقل الأوكسجين من الرئتين إلى الخلايا وثنائي أوكسيد الكاربون من الخلايا إلى الرئتين. عددها: نحو 5 ملايين/ملم³ في الذكور و4.5 مليون في الإناث. يكونها نخاع العظم في البالغين (وفي الأجنة الكبد والطحال). قلتها تسبب فقر الدم (Anemia).
• خلايا الدم البيض (WBC): عديمة اللون لانعدام الهيموغلوبين، لها نواة، أكبر من الحمر (قطرها 6–15 مايكرون)، عددها نحو 8000/ملم³ في الذكور و6000 في الإناث، يزداد عند الالتهابات وأمراض الدم كسرطان الدم (Leukemia). وهي مجموعتان:
- حبيبية وذات نواة مفصصة: تتكون في نخاع العظم.
- غير حبيبية وغير مفصصة النواة: تتكون في العقد اللمفاوية، لها قابلية تكوين أقدام كاذبة تخترق جدران الشعيرات وتلتهم الأجسام الغريبة وتكوّن أجساماً مضادة (المناعة).
• الصفيحات الدموية: أجسام صغيرة (2 مايكرون) بيضوية أو قرصية خالية من النواة، عددها نحو 250 ألف/ملم³، تتكون في نقي العظم وتسهم في تخثر الدم عند النزف.

2) القلب: عضو عضلي مخروطي الشكل في القفص الصدري بين الرئتين، قاعدته نحو الأعلى ورأسه مائل لأسفل اليسار، محاط بغشاء رقيق يسمى التامور. يتكون من نصفين يفصل بينهما حاجز عضلي، وكل نصف من ردهة عليا رقيقة الجدار (أذين) وردهة سفلى سميكة الجدار (بطين) يفصل بينهما صمام ينظم مرور الدم من الأذين إلى البطين. عدد ضربات القلب في الراحة نحو 70 ضربة/دقيقة (النبض)، وتزداد أو تقل مع المجهود أو الخوف أو المرض.

3) الأوعية الدموية:
أ) الشرايين: تنقل الدم من القلب إلى أنحاء الجسم، عميقة الموقع، دمها أحمر قانٍ (عدا الشريان الرئوي) لكثرة الأوكسجين، جدارها أسمك من الوريد. المتصل بالقلب منها:
• الشريان الرئوي: يتفرع من البطين الأيمن إلى فرعين لكل رئة.
• الشريان الأبهر: يتفرع من البطين الأيسر إلى جميع أنحاء الجسم عدا الرئتين، وهو أكبر الشرايين.
• الشرايين التاجية: زوج ينقل الدم من الأبهر لتغذية عضلة القلب.
ب) الأوردة: تنقل الدم من أنحاء الجسم إلى القلب، جدرانها أرق، أقرب لسطح الجسم، دمها أحمر قاتم (عدا الأوردة الرئوية). المتصلة بالقلب:
• الوريد الأجوف الأعلى: يجمع الدم من فوق الحجاب الحاجز ويصب في الأذين الأيمن.
• الوريد الأجوف الأسفل: يجمع الدم من تحت الحجاب الحاجز ويصب في الأذين الأيمن.
• الأوردة الرئوية: أربعة أوردة تنقل الدم المؤكسج من الرئتين إلى الأذين الأيسر.
• الأوردة التاجية: صغيرة تجمع الدم من عضلة القلب لتصب في الأذين الأيمن.
ج) الأوعية الدموية الشعرية: أوعية مجهرية كثيرة التشعب تصل نهايات الشرايين ببدايات الأوردة، جدرانها رقيقة من طبقة واحدة من خلايا طلائية لتسهيل التبادل بين الدم والخلايا. الدم لا يترك الأوعية إلا عند النزف.

فصائل الدم:
• أربع فصائل: A وB وAB وO، ولكل إنسان فصيلة واحدة. نقل الدم بين فصائل متضادة يسبب تحلل الخلايا وترسبها في الكليتين والرئتين والدماغ وقد يؤدي للوفاة.
• جدول المنح والتلقي (المتلقي ← يتلقى من):
- A: يتلقى من A وO.
- B: يتلقى من B وO.
- AB: يتلقى من جميع الفصائل (المستلم العام).
- O: يتلقى من O فقط، ويمنح جميع الفصائل (المانح العام).
• العامل الريسي (Rh): أجسام خاصة على سطح خلايا الدم الحمر. 85% من البشر يحتوون عليه (Rh+) و15% لا يحتوون (Rh−). زواج امرأة Rh− من رجل Rh+ يهدد حياة الجنين، ولذلك يجب فحص مجاميع الدم قبل الزواج.

تخثر الدم:
• عملية إصلاحية عند الجروح لتفادي استمرار النزف، تعتمد على سلسلة تفاعلات بوجود الكالسيوم وفيتامين K:
1) تتكسر الصفائح الدموية ويفرز منها بروتين الثرمبوبلاستين.
2) بوجود الكالسيوم يحول الثرمبوبلاستين البروثرومبين (غير فعال) إلى الثرومبين (فعال).
3) يحول الثرومبين الفايبرينوجين (ذائب) إلى الفايبرين (غير ذائب صلب).
4) يترسب الفايبرين شبكة من الألياف تحجز كريات الدم الحمر فتكوّن خثرة تمنع النزف.

الجهاز اللمفاوي:
• أوعية شعرية صغيرة تتصل بعقد لمفاوية تنقل اللمف: بلازما مترشحة من الأوعية الدموية الشعرية مع بعض خلايا الدم البيض، يحيط بالخلايا ويسهل التبادل. يجري في أقنية موازية لجهاز الدوران باتجاه القلب، وتساعد على حركته تقلصات عضلات الجسم (بخلاف الدوران الذي يخضع للقلب).
• العقد اللمفاوية: مجاميع على طول الأقنية فيها عدد كبير من الخلايا البيض، تنقي اللمف من البكتريا. تكثر تحت الإبط وتحت الفك السفلي وأسفل البطن. واللوزتان عقدتان لمفاويتان كبيرتان تتضخمان عند الالتهابات.
• الأقنية اللمفاوية: القناة اليمنى (تجمع اللمف من الجانب الأيمن للرأس والعنق والقصبة وأجزاء من الكبد وتصب في الوريد الأجوف الأعلى)، والقناة اليسرى (أكبر قناة، تجمع من باقي الجسم وتصب في الوريد الأجوف الأعلى عند قاعدة العنق).
• الطحال: عضو أحمر غامق فوق المعدة في الجانب العلوي الأيسر من البطن، يشبه العقد اللمفاوية، ويتصف بأنه: يخزن كمية كبيرة من الدم، يكوّن خلايا الدم الحمر عند عجز نخاع العظم، يحلل الحمر الميتة ويعيد مكوناتها، يتضخم في بعض الأمراض كالملاريا واللشمانيا الأحشائية، واستئصاله عند الضرورة لا يؤثر في حياة الإنسان.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• البلازما: سائل مائل للاصفرار يشكل نحو 55% من الدم.
• الهيموغلوبين: صبغة في خلايا الدم الحمر من بروتين (Globin) وحديد (Haemo)، تنقل الأوكسجين.
• الصفيحات الدموية: أجسام صغيرة خالية من النواة تسهم في تخثر الدم.
• العامل الريسي: أجسام خاصة على سطح خلايا الدم الحمر.
• التامور: غشاء رقيق يحيط بالقلب.
• الأذين: ردهة عليا رقيقة الجدار. البطين: ردهة سفلى سميكة الجدار.
• النبض: عدد ضربات القلب في الدقيقة (نحو 70 في الراحة).
• الشرايين: أوعية تنقل الدم من القلب إلى الجسم. الأوردة: تنقله من الجسم إلى القلب.
• الأوعية الشعرية: أوعية مجهرية تصل نهايات الشرايين ببدايات الأوردة.
• تخثر الدم: عملية إصلاحية تمنع استمرار النزف عند الجروح.
• اللمف: بلازما مترشحة من الأوعية الشعرية مع بعض خلايا الدم البيض.
• العقد اللمفاوية: مجاميع على الأقنية اللمفاوية تنقي اللمف من البكتريا.
• ضغط الدم: القوة التي تنشأ على جدران الأوعية الدموية بسبب سريان الدم وضخ القلب.

التعاليل:
• تسمية خلايا الدم البيض بهذا الاسم: لعدم احتوائها على صبغة الهيموغلوبين (عديمة اللون).
• الدم في الشرايين أحمر قانٍ: لاحتوائه على كمية عالية من الأوكسجين (عدا الشريان الرئوي).
• الدم في الأوردة أحمر قاتم: لقلة الأوكسجين فيه (عدا الأوردة الرئوية).
• جدار الشريان أسمك من جدار الوريد: لتحمل ضغط الدم المندفع من القلب.
• نشعر بالنبض عند الضغط على الشرايين لا الأوردة: لأن الشرايين يندفع فيها الدم بضغط من انقباض القلب.
• رقة جدران الأوعية الشعرية (طبقة واحدة): لتسهيل التبادل بين الدم وخلايا الجسم.
• النوبة القلبية: تنتج عن انخفاض تدفق الدم لعضلة القلب بسبب تراكم الدهون في شرايين القلب فتغلقها جزئياً أو كلياً.
• يجب فحص مجاميع الدم قبل الزواج: لأن زواج امرأة Rh− من رجل Rh+ يهدد حياة الجنين.
• يسمى فصيلة O المانح العام: لأنه يمنح جميع الفصائل. وAB المستلم العام: لأنه يتلقى من جميع الفصائل.
• يُضاف الهيبارين لدم المصارف: لمنع تخثره.
• لا يتخثر الدم داخل الأوعية الدموية: لعدم تكسر الصفائح وسلامة جدران الأوعية، وللهيبارين الذي يصنعه الكبد.

مقارنة بين خلايا الدم الحمر والبيض:
• الحمر: قرصية، بلا نواة في البالغة، فيها هيموغلوبين، قطر 8 مايكرون، عددها 5 ملايين/ملم³، تنقل الغازات، تعيش 4 أشهر، تكونها نخاع العظم.
• البيض: عديمة اللون، لها نواة، أكبر (6–15 مايكرون)، عددها نحو 6000–8000/ملم³، وظيفتها الدفاع والمناعة، تتكون في نخاع العظم والعقد اللمفاوية.

مقارنة بين الدم واللمف:
• الدم: يحتوي الحمر والبيض والصفيحات والبلازما، يجري باتجاه القلب وبعيداً عنه ويضخه القلب.
• اللمف: بلازما مع بعض خلايا الدم البيض، يجري باتجاه القلب فقط، وتحركه تقلصات عضلات الجسم.

تصحيح عبارات:
• تنقي العقد اللمفاوية اللمف من البكتريا (وليس الدم من ثنائي أوكسيد الكاربون).
• يكوّن الطحال خلايا الدم الحمر (وليس البيض) عند عجز نخاع العظم.'''),
    Section('الأمراض والتبرع', Icons.healing, '''1) ضغط الدم:
• الضغط العالي يحدث عند تقلص البطينين، والواطئ عند استراحة عضلة القلب بين تقلصين (يتقلص الأذينان والبطينان مستريحان). يُقاس بجهاز خاص على الشريان العضدي (فوق العضد الأيسر) ويجب أن تكون القراءة من طبيب أو ممرض أو شخص مدرب.
• العوامل المؤثرة: العمر (أقل في الأطفال)، الجنس (النساء أقل قليلاً)، وقت الراحة (أقل في الراحة والنوم)، نوع العمل (المجهود البدني والذهني المفرط يرفعه)، طبيعة الغذاء (الدهون وزيادة الملح ترفعه)، عدم انتظام العلاج (يتلف الشرايين الدقيقة المغذية للقلب فتحدث النوبات القلبية والسكتة الدماغية).
• أعراض ارتفاعه: صداع حاد على جانبي الرأس، ضيق تنفس وألم في الصدر، طنين في الأذن، نزيف الأنف.
• أعراض انخفاضه: دوار، برودة ملحوظة في الجسم والأطراف، غثيان، تشوش الرؤية وإغماء.
• العلاج: قياس الضغط دورياً (خصوصاً كبار السن)، مراجعة الطبيب والالتزام بالعلاج، رياضة المشي، الحمية الغذائية، تجنب التدخين والكحول والمنبهات (الشاي والقهوة).
• الوقاية: رياضة منتظمة، غذاء صحي متوازن وعدم الإكثار من الدهنيات والمالح، عدم التدخين والكحول والمخدرات، تنظيم أوقات العمل وتجنب الإجهاد والأماكن المزدحمة والملوثة.

2) النوبة القلبية:
• الأعراض: ألم في الصدر يمتد حتى الذراع الأيسر، تعرق مفرط، إرهاق شديد ومفاجئ، دوار مع ضيق تنفس.
• العلاج: نقل المريض فوراً إلى المستشفى، وفي أثناء ذلك لا يتجمهر أفراد العائلة حوله، وتُفتح الشبابيك للهواء النقي، وتُفتح الأربطة حول العنق، ويستلقي المريض بهدوء. والالتزام بالعلاج الموصوف.
• الوقاية: الابتعاد عن الدهنيات والسكريات بكثرة والإكثار من الخضراوات والفواكه، عدم التدخين والكحول والمخدرات، الرياضة والمشي، تجنب الإجهاد والنوم الكافي.

3) الثلاسيميا (Thalassemia):
• مرض وراثي غير معدٍ بسبب جينات حاملة للمرض، يصيب خلايا الدم الحمر ويخفض إنتاج الهيموغلوبين فينخفض الأوكسجين في الدم. يسمى فقر دم البحر الأبيض المتوسط لأن منشأه في دول حوض المتوسط.
• أنواعه: الكبرى (عند الأطفال في السنتين الأولى والثانية من العمر)، والصغرى (عند البالغين الحاملين للجين، ينقلونه لأبنائهم ولا تظهر عليهم الأعراض).
• الأعراض: تعب وضعف عام، شحوب البشرة واصفرارها، تغير لون البول إلى الداكن، ضيق تنفس وزيادة سرعة النبض، انتفاخ البطن بسبب تضخم الكبد والطحال، تشوهات في عظام الوجه وتأخر النمو.
• العلاج: نقل الدم المتكرر بجدول (الأساس)، العلاج المناسب (حامض الفوليك لبناء الحمر)، زرع الخلايا الجذعية (نخاع العظم).
• الوقاية: الفحص الطبي الشامل قبل الزواج، والابتعاد عن زواج الأقارب الحاملين للمرض.

التبرع بالدم:
• الدم لا يمكن صنعه مختبرياً لأنه من خلايا حية. يُحفظ في مصارف الدم داخل قناني زجاجية أو أوعية بلاستيكية بعد إضافة الهيبارين لمنع تخثره، وفي ثلاجات بدرجة حرارة واطئة. التبرع عمل إنساني وأخلاقي ووطني.
• شروط المتبرع: عمره بين 17 و55 سنة، لا تتبرع الحامل والمرضعة، لا يتبرع من يعاني فقر الدم، ولا المصابون بأي مرض (خاصة الإيدز)، وتُجرى فحوص للمتبرع، ويمكن للسليم التبرع دورياً دون تأثير على صحته.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• الوريد الذي لا يصب في الأذين الأيمن: الأوردة الرئوية (تصب في الأيسر).
• في تخثر الدم تتكسر الصفائح الدموية ويتكون بروتين الثرمبوبلاستين.
• اللمف: بلازما مع بعض خلايا الدم البيض.
• أحمد (A+) إن احتاج دماً: يتبرع له محمود (A+) ومحمد (O)، ولا يتبرع له حسن (AB−) لأن AB لا يمنح إلا لفصيلتين.

أسئلة للمراجعة:
1) ما المقصود بـ: البلازما، الهيموغلوبين، الصفيحات الدموية، العامل الريسي؟
2) صف: خلايا الدم الحمر، خلايا الدم البيض، القلب.
3) بين الجزء الذي يكوّن خلايا الدم الحمر في الإنسان.
4) قارن بين الدم واللمف.
5) فسّر: تسمية خلايا الدم البيض، سبب النوبة القلبية، كون الدم في الشرايين أحمر قانياً.
6) عدد الأوعية الدموية المتصلة مباشرة بالقلب.
7) بين خطوات تخثر الدم.
8) عدد فصائل الدم وقابلية المنح والتلقي لكل منها.
9) ما أعراض ارتفاع وانخفاض ضغط الدم؟
10) ما شروط التبرع بالدم؟
11) ارسم مع التأشير: مكونات الدم.'''),
  ]),
  Chapter('الفصل السادس: جهاز التنفس', [
    Section('الملخص', Icons.notes, '''مقدمة:
• الجسم يحتاج الغذاء للبناء والطاقة، لكن الخلايا (بيوت الطاقة) لا تستفيد منه إلا بوجود الأوكسجين الذي يصل إلى الخلايا بوساطة خلايا الدم الحمر (تشبه ساعي البريد) وجهاز التنفس هو المسؤول.
• المعادلة: سكر الكلوكوز + أوكسجين ← ثنائي أوكسيد الكاربون + ماء + طاقة. غاز ثنائي أوكسيد الكاربون سام للجسم ويجب طرحه.

تركيب الجهاز التنفسي:
1) تجويف الأنف: قناتان تخترقان الجمجمة، تتصلان من الأعلى بالمنخرين ومن الأسفل بفتحتي المنخرين الخارجيتين. في مقدمته شعيرات مع المواد المخاطية تمنع دخول الأتربة، وفي جداره خلايا حسية شمية، وفي الغشاء المخاطي شبكة شعيرات دموية تدفئ الهواء المار إلى الرئتين.
2) البلعوم: أنبوب عضلي مشترك بين الجهازين الهضمي والتنفسي، تفتح فيه الفتحتان المنخريتان الداخليتان وقناة أوستاكي، يتصل بالمريء من الأسفل وبالحنجرة من الأعلى، وعلى جانبيه اللوزتان. يمر الهواء عبره إلى الحنجرة من فتحة المزمار.
3) الحنجرة: تركيب مخروطي في أعلى القصبة الهوائية من تسع قطع غضروفية (ثلاث مفردة وثلاث مزدوجة). من المفردة قطعة هلالية تكوّن تفاحة آدم، وقطعة ورقية الشكل هي لسان المزمار وتشكل غطاء للقصبة لمنع دخول دقائق الغذاء. في فراغ الحنجرة أربع طيات غشائية: اثنتان تسميان الحبال الصوتية واثنتان الحبال اللاصوتية. يخرج الصوت بهواء الزفير مع التحكم بالحبال الصوتية وحركة الفم واللسان والشفاه فيحدث النطق.
4) القصبة الهوائية: طولها 12 سم وقطرها 2.5 سم، تصل الحنجرة بالرئتين، جدارها غضروفي حلقي غير مكتمل من الخلف، مبطنة بغشاء مخاطي مهدب يرطب الهواء ويطرد المواد الغريبة. تتفرع عند قاعدتها إلى فرعين لكل رئة، ثم إلى القصيبات الرئوية التي تنتهي بأكياس هي الحويصلات الهوائية المحاطة بأوعية دموية شعرية تسمح بالتبادل الغازي.
5) الرئتان: عضوان إسفنجيان يحتلان معظم التجويف الصدري الذي يفصله عن البطني الحجاب الحاجز (حاجز عضلي محدب للأعلى). وظيفتهما التبادل الغازي. الرئة اليمنى من ثلاثة فصوص واليسرى من فصين (يستقر بينهما القلب). يغطيهما غشاء الجنب الحشوي (الداخلي) ويبطن القفص الصدري الجنب الجداري، والفراغ بينهما فراغ الجنب فيه سائل يسهل حركة الرئتين.

آلية التنفس:
الشهيق (بالتتابع):
1) ينخفض الحجاب الحاجز للأسفل ويصبح مسطحاً.
2) يتحرك عظم القص والأضلاع للأعلى بتقلص العضلات بينها.
3) يقل ضغط الهواء داخل الرئتين لاتساع حجميهما.
4) يدخل الهواء الجوي إلى الرئتين عن طريق الأنف.
الزفير (بالتتابع):
1) يعود الحجاب الحاجز إلى وضعه المحدب.
2) تتحرك الأضلاع وعظم القص للداخل قليلاً (وضعهما الطبيعي).
3) يزداد ضغط الهواء داخل الرئتين.
4) يخرج الهواء من الرئتين إلى خارج الجسم.

التنفس الخارجي والداخلي:
• التنفس عملية معقدة كيميائياً تتكون فيها مركبات قلقة داخل الحمر: أوكسي هيموغلوبين (ينقل الأوكسجين للخلايا) وكاربوكسي هيموغلوبين (يعيد ثنائي أوكسيد الكاربون منها).
• التنفس الخارجي: انتشار الأوكسجين من داخل الحويصلات الرئوية إلى خلايا الدم الحمر عبر غشائها الرقيق، وانتقال ثنائي أوكسيد الكاربون وبخار الماء من الحمر إلى الحويصلات.
• التنفس الداخلي: انتشار الأوكسجين من خلايا الدم الحمر إلى خلايا الجسم، وقيام بيوت الطاقة (المايتوكوندريا) بأكسدة الغذاء (سكر العنب) لتحرير الطاقة وطرح ثنائي أوكسيد الكاربون والماء.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• الحويصلات الهوائية (الرئوية): أكياس تنتهي بها القصيبات الرئوية، محاطة بشعيرات دموية للتبادل الغازي.
• الحجاب الحاجز: حاجز عضلي محدب للأعلى يفصل التجويف الصدري عن البطني.
• لسان المزمار: قطعة غضروفية ورقية تغطي القصبة الهوائية لمنع دخول الغذاء.
• تفاحة آدم: قطعة هلالية من غضاريف الحنجرة.
• الحبال الصوتية: طيتان غشائيتان في الحنجرة تسهمان في إنتاج الصوت.
• غشاء الجنب: غشاء مزدوج رقيق يغطي الرئتين (حشوي) ويبطن القفص الصدري (جداري).
• التنفس الخارجي: انتشار الأوكسجين من الحويصلات إلى الحمر وانتقال CO₂ وبخار الماء بالعكس.
• التنفس الداخلي: انتشار الأوكسجين من الحمر إلى الخلايا وأكسدة الغذاء لتحرير الطاقة.
• الأوكسي هيموغلوبين: مركب ينقل الأوكسجين. الكاربوكسي هيموغلوبين: مركب يعيد CO₂.

التعاليل:
• وجود شعيرات في مدخل الأنف: مع المواد المخاطية تمنع دخول الأتربة المصاحبة للهواء.
• تدفئة الهواء في الأنف: بسبب شبكة الشعيرات الدموية في الغشاء المخاطي.
• عدم اكتمال الجدار الغضروفي للقصبة الهوائية من الخلف: لتسمح بمرور الغذاء في المريء الملاصق لها خلفها (وتمنع انغلاقها).
• القصبة الهوائية مبطنة بغشاء مخاطي مهدب: لترطيب الهواء وطرد المواد الغريبة.
• جدار الحويصلات رقيق وفيه شعيرات دموية: لتسهيل التبادل الغازي.
• ينخفض الحجاب الحاجز في الشهيق: لتتسع الرئتان فيقل الضغط ويدخل الهواء.
• تنتشر أمراض الجهاز التنفسي شتاءً أكثر: بسبب البرد وتيارات الهواء وازدحام الأماكن المغلقة وانتقال العدوى.
• يجب عدم التدخين: لأنه أبرز أسباب أمراض الجهاز التنفسي وتحطيم الرئتين والقلب.

تصحيح عبارات:
• التنفس الداخلي: انتشار الأوكسجين من خلايا الدم الحمر إلى خلايا الجسم (وليس من الخلايا إلى الدم).

مقارنة بين الشهيق والزفير:
• الشهيق: الحجاب الحاجز ينخفض، الأضلاع والقص تتحرك للأعلى، ضغط الرئتين يقل، يدخل الهواء.
• الزفير: الحجاب يعود محدباً، الأضلاع والقص تعود للداخل، ضغط الرئتين يزداد، يخرج الهواء.'''),
    Section('الأمراض والمقارنات', Icons.healing, '''1) السل الرئوي (TB):
• السبب: بكتيريا عصوية الشكل اكتشفها روبرت كوخ عام 1882. مرض معدٍ خطير ينتقل بالتقبيل أو الرذاذ أو استعمال حاجيات المريض أو تناول حليب الأبقار المصابة. انحسر كثيراً بعد اكتشاف المضادات الحيوية وتحسن الظروف.
• الأعراض: تعب وإجهاد شديد، ضعف الشهية وفقدان كبير للوزن وشحوب الوجه، ارتفاع الحرارة ليلاً وتعرق وسعال خفيف، وفي المراحل المتقدمة سعال شديد مع قشع مصحوب بالدم.
• العلاج: عزل المريض وإدخاله المستشفى، المضادات الحيوية، غذاء غني بالفيتامينات والسعرات.
• الوقاية: تلقيح الأطفال بلقاح BCG، الابتعاد عن المصاب وعدم استعمال أدواته، تجنب الأماكن الملوثة والمكتظة، رياضة وغذاء متوازن، غلي الحليب جيداً وعدم شراء اللحوم من خارج المجازر الصحية، فحوصات دورية.

2) ذات الرئة (Pneumonia):
• مرض معدٍ تسببه جراثيم منها بكتريا Pneumoia sp. يؤدي إلى التهاب الحويصلات الهوائية وتكوّن القيح فيها فلا تقوم بوظيفتها.
• الأعراض: ضيق وألم في الصدر عند التنفس والسعال، حمى وقشعريرة، إعياء وغثيان أحياناً، سعال مع قشع كثيف مائل للاخضرار.
• العلاج: مراجعة الطبيب فوراً والمضادات الحيوية تحت إشرافه حصراً، إدخال المستشفى عند الحاجة، أدوية مقشعة وسوائل واستعمال المناديل عند السعال، غذاء غني، غرفة دافئة جيدة التهوية وعدم التعرض لتيار هواء بارد.
• الوقاية: الابتعاد عن المصابين، مراجعة الطبيب عند ظهور أعراض، الرياضة وتجنب التلوث والأماكن المغلقة، عدم التدخين، النظافة الشخصية والعامة وعدم البصق على الأرض.

3) الربو (Asthma):
• مرض مزمن غالباً يصيب الجهاز التنفسي بسبب تضيق ممرات الهواء فيصبح التنفس شاقاً. يصيب جميع الأعمار وتختلف شدة أعراضه.
• الأعراض: صعوبة شديدة وضيق في التنفس، نوبات سعال جاف متكرر مع غثيان، ألم في الصدر، وفي الحالات المتقدمة عدم القدرة على النوم والحركة بشكل طبيعي.
• العلاج: مراجعة الطبيب، البخاخ الموسع للقصبات الهوائية، الابتعاد عن الأماكن المزدحمة والمغبرة وتهوية الأماكن المغلقة.
• الوقاية: عدم التدخين، الكمامات الواقية في معامل الأسمنت والجص وصبغ السيارات والنجارة ولعمال النظافة، كمامات أو شاش مبلل في الأيام المغبرة خصوصاً لمن يعاني حساسية تنفسية، رياضة منتظمة كالمشي في مناطق مفتوحة.

التمييز بين الربو والسل الرئوي:
• السل: مرض معدٍ بكتيري، تعب وفقدان وزن وارتفاع حرارة ليلية وتعرق وقشع مصحوب بالدم.
• الربو: مرض مزمن غير معدٍ بسبب تضيق الممرات الهوائية، سعال جاف متكرر وضيق تنفس وألم صدر، ويعالج بالبخاخ.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• للوقاية من السل الرئوي يُلقَّح الأطفال بلقاح BCG.
• يقع على جانبي البلعوم: اللوزتان.
• تتكون الحبال الصوتية والحبال اللاصوتية من أربع طيات غشائية (اثنتان للصوتية).
• بكتيريا السل الرئوي من النوع العصوي.
• الرئة اليمنى 3 فصوص والرئة اليسرى فصان.
• القصبة الهوائية طولها 12 سم وقطرها 2.5 سم.

أسئلة للمراجعة:
1) ما المقصود بـ: الحويصلات الرئوية، الحجاب الحاجز، لسان المزمار؟
2) صف: البلعوم، الحنجرة، الرئتين.
3) قارن بين الشهيق والزفير.
4) شخصان أحدهما مصاب بالربو والآخر بالسل، كيف تميز بينهما؟
5) فسّر: وجود شعيرات في مدخل الأنف، عدم اكتمال الجدار الغضروفي للقصبة الهوائية من الخلف.
6) صحح: التنفس الداخلي هو انتشار الأوكسجين من خلايا الجسم إلى خلايا الدم الحمر.
7) ما الفرق بين التنفس الخارجي والداخلي؟
8) ما أعراض السل الرئوي وذات الرئة؟
9) ما طرق الوقاية من الربو؟
10) ارسم القصبة الهوائية والحويصلات الرئوية.'''),
  ]),
  Chapter('الفصل السابع: الجهاز البولي والإخراج', [
    Section('الملخص', Icons.notes, '''مقدمة:
• تنتج الفضلات السائلة من الفعاليات الحيوية ولا بد من التخلص منها لأن بقاءها يسمم الجسم، ومن أهمها اليوريا. الجهاز المختص بالتخلص من الفضلات السائلة هو الجهاز البولي.

تركيب الجهاز البولي:
1) الكليتان: عضوان في التجويف البطني ملاصقان للظهر، تشبه الكلية بذرة الفاصوليا وتحتوي عدداً كبيراً من النبيبات البولية. يدخلها شريان كلوي ويخرج منها وريد كلوي. في وسطها الحوض: تجويف صغير يمثل بداية الحالب المتسعة داخل الكلية.
2) الحالبان: أنبوب عضلي دقيق طوله نحو 22 سم يصل كل كلية بالمثانة، وينزل منه البول إلى المثانة.
3) المثانة: كيس من أنسجة عضلية ملساء (غير إرادية). توجد ألياف عضلية دائرية مخططة (إرادية) تتحكم بفتح وغلق الإحليل الذي يقع أسفل المثانة. الإحليل: أنبوب يصرف البول من المثانة إلى خارج الجسم.

أنواع الإخراج:
1) الإخراج الكلوي: التخلص من الفضلات السائلة كاليوريا والماء الزائد عن طريق الكليتين.
2) الإخراج الجلدي: التخلص من الماء الزائد والأملاح وقليل من ثنائي أوكسيد الكاربون عن طريق التعرق وإفراز الدهون.
3) الإخراج الرئوي: التخلص من CO₂ وبخار الماء عن طريق التنفس.
4) الإخراج الهضمي: التخلص من الفضلات الصلبة والخلايا الميتة من بطانة القناة الهضمية.

الجلد وملحقاته (طبقات الجلد من الخارج للداخل):
1) البشرة وتتألف من طبقتين:
أ) الطبقة المتقرنة: الخارجية الظاهرة للعين، من خلايا طلائية جافة ميتة ملتصقة، تندثر بالاحتكاك ويتم تعويضها باستمرار من الطبقة تحتها.
ب) الطبقة المولدة (المالبيجية): خلايا حية قابلة للانقسام المستمر، لخلاياها حبيبات صبغية تسمى الميلانين تعطي لون البشرة حسب تركيزها. مسؤولة عن تكوين الشعر والأظافر، وفيها الغدد العرقية والنهايات الطرفية للأعصاب. عديمة الأوعية الشعرية وتتغذى بترشيح البلازما من أوعية الأدمة.
2) الأدمة: طبقة متعرجة السطح تكوّن الحليمات التي عليها نهايات الأعصاب الحسية للمس. تتكون من أنسجة رابطة ونسيج دهني وأوعية دموية وأعصاب.

ملحقات الجلد:
1) الشعر: متقرن، له جزء متصلب رفيع يسمى القصبة، وجزء قاعدي منغرس في الأدمة هو بصيلة الشعرة ضمن انبعاج يسمى حويصلة الشعرة. تتصل بها غدة دهنية تفرز مادة تمنع تكسر الشعرة (يجف السائل مكوّناً القشرة)، وألياف عضلية ملساء لاإرادية لها علاقة بانتصاب الشعرة.
2) الأظافر: أجزاء صلبة متقرنة تفرزها خلايا الطبقة المولدة، تحافظ على نهايات الأصابع من التشقق وتسهل التقاط الأجسام ومسكها.
3) الغدد الجلدية:
أ) الغدد العرقية: قناة غدية ملتفة القاعدة تحيط بها شعيرات دموية، قاعدتها في الأدمة ولها فتحة خارجية تسمى المسامة الجلدية. تفرز العرق (99% ماء، والباقي أملاح ويوريا). مهمة للإخراج وخفض حرارة الجسم: كل غرام ماء يحتاج 540 سعرة ليتبخر. تزداد في الحمى (ارتفاع الحرارة فوق 37.5 °م) وهي وسيلة دفاعية لخفض الحرارة، وقد تتعرق أيضاً عند الارتباك والقلق والخوف.
ب) الغدد الدهنية: ذات إفراز خارجي منتشرة في الأدمة، من خلايا دهنية، تحفظ رطوبة الجلد وتحمي الشعر وترطبه، وتنعدم في باطن اليد.

صحة الجلد:
1) الاستحمام المنتظم. 2) الوقاية من الخدوش والجروح. 3) عدم التعرض لأشعة الشمس الحارقة. 4) مراجعة الطبيب عند ظهور البثور أو أي مرض جلدي. 5) عدم العبث بالبثور (ظاهرة طبيعية في المراهقة). 6) غسل الوجه بالماء والصابون مرتين يومياً على الأقل. 7) عدم عمل وشم (مواد غير صحية وتنقل أمراضاً خطيرة). 8) عدم لبس الملابس الضيقة التي تمنع التعرق الطبيعي.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• الكليتان: عضوان يصفيان الدم ويطرحان الفضلات السائلة.
• النبيبات البولية: تراكيب دقيقة كثيرة في الكلية.
• الحالب: أنبوب عضلي يصل الكلية بالمثانة (22 سم).
• المثانة: كيس من أنسجة عضلية ملساء يخزن البول.
• الإحليل: أنبوب يصرف البول من المثانة إلى الخارج.
• الطبقة المتقرنة: الطبقة الخارجية للبشرة من خلايا ميتة جافة.
• الميلانين: حبيبات صبغية تعطي لون البشرة.
• الأدمة: طبقة تحت البشرة فيها نهايات الأعصاب الحسية والأوعية الدموية.
• بصيلة الشعرة: الجزء القاعدي المنغرس في الأدمة.
• المسامة الجلدية: الفتحة الخارجية للغدة العرقية.
• الإخراج: التخلص من الفضلات الناتجة عن الفعاليات الحيوية.

التعاليل:
• يجب التخلص من الفضلات السائلة: لأن بقاءها في الجسم يؤدي إلى تسممه.
• تتغذى الطبقة المولدة بالترشيح: لأنها عديمة الأوعية الشعرية فتأخذ البلازما من أوعية الأدمة.
• يزداد التعرق في الحمى: وسيلة دفاعية لخفض درجة حرارة الجسم إلى المعدل الطبيعي (وليس للتخلص من الماء الزائد).
• أهمية العرق في الصيف: لأن تبخر العرق يمتص حرارة كبيرة (540 سعرة لكل غرام) فتنخفض حرارة الجسم.
• وجود الأظافر: لحماية أطراف الأصابع من التشقق والجروح ولتسهيل مسك الأجسام.
• تفرز الغدة الدهنية مادة دهنية: لتمنع تكسر الشعرة وترطب الجلد والشعر.
• يفضل امتناع المصاب بالبول الزلالي عن تناول اللحوم: لأنها غنية بالبروتين والبروتين يخرج في الإدرار.
• لا يعمل الإنسان وشماً: لأن مواده غير صحية وتنقل أمراضاً خطيرة.

تصحيح عبارات:
• الغدد الدهنية وظيفتها ترطيب الجلد وحماية الشعر (وليست المساعدة على انتصاب الشعر؛ فذلك من عمل الألياف العضلية الملساء).
• يزداد تعرق المصاب بالحمى لخفض حرارة الجسم (وليس لتخليص الجسم من الماء الزائد).
• العبارة الصحيحة: لولا الأظافر لتعرضت الأصابع للتشقق والجروح.

مقارنة: السكري والبول الزلالي:
• السكري: مرتبط بخلل عمل البنكرياس (الأنسولين)، مزمن، السكر في الدم والإدرار، عطش وكثرة إدرار ونحول وبطء التئام الجروح.
• البول الزلالي: خلل في وظيفة الكلية، غير مزمن ويمكن علاجه، خروج البروتين مع البول، رغوة في الإدرار وتورم القدمين.'''),
    Section('الأمراض والمقارنات', Icons.healing, '''1) داء البول السكري (Diabetes):
• مرض مزمن غالباً مرتبط باختلال عمل البنكرياس الذي يفرز هرمون الأنسولين، وظيفته المحافظة على مستوى السكر في الدم بين 80 و120 ملغم/ديسلتر (يلاحظ عند الجوع أو الاستيقاظ صباحاً)، ويرتفع بعد الطعام.
• زيادة السكر عن الطبيعي تسبب اضطراباً مثل الجلطات القلبية، وانخفاضه دون 80 ملغم/ديسلتر يسبب الإغماء.
• للكليتين دور: السكر غير المحروق تطرحه الكليتان مع البول، وهذا يفسر كثرة الإدرار عند المصابين وزيادة نسبة السكر في الإدرار، لأن كمية الأنسولين المفرزة غير كافية.
• الأعراض (قد لا تظهر كلها): تعب وإجهاد مستمران ونحول وتناقص الوزن بسرعة، كثرة الإدرار والعطش وجفاف الفم، حبوب حمراء في أماكن من الجسم، بطء التئام الجروح وصعوبة توقف النزف، تشويش الرؤية. وتتفاقم مع نوع المرض والأمراض الأخرى (تآكل القدم من الأعراض المتقدمة).
• العلاج: مراجعة الطبيب، حقن الأنسولين لضبط السكر، الحمية والامتناع عن السكريات قطعياً، الرياضة وتجنب التدخين والكحول والسهر والقلق.
• الوقاية: فحوصات دورية للسكر (خصوصاً لمن لديهم استعداد وراثي)، غذاء صحي وسكريات معتدلة ومعالجة السمنة، رياضة منتظمة، الامتناع عن التدخين، الحفاظ على الصحة النفسية وتجنب القلق والاكتئاب.

2) البول الزلالي (Albuminuria):
• خلل في وظيفة الكلية يسبب ترشح جزيئات البروتين من الدم إلى خارج الجسم مع البول، لأن النبيبات البولية لا تعمل بصورة طبيعية بسبب التهابات. مرض غير مزمن ويمكن علاجه (عكس السكري).
• الأعراض: تعب شديد وفقر دم وشحوب، كثرة التبول وميلان الإدرار للاصفرار الشديد ووجود رغوة بسبب تركيز البروتين، حرقة بعد التبول (التهاب الكليتين والمجاري البولية)، تورم القدمين وبثور حمراء على الأرجل.
• العلاج: مراجعة الطبيب، الامتناع عن تناول البروتينات بكافة أنواعها، شرب كميات كافية من الماء، تقليل ملح الطعام (لأنه يزيد نفاذية النبيبات البولية).
• الوقاية: تناول البروتينات بكميات معقولة (لا تُخزن مثل الدهون بل يطرح الزائد على هيئة يوريا)، مراجعة الطبيب عند أي اضطراب أو حرقة في المجاري البولية، عدم التدخين والكحول والأدوية العشوائية.

3) حصى الكلية:
• تتكون لأسباب كنمط التغذية غير الصحي من ترسبات الأملاح كفوسفات الكالسيوم وأوكزالات الكالسيوم في حوض الكلية والحالبين والمثانة.
• الأعراض: رغبة مستمرة بالتبول مع ألم شديد أسفل الظهر، تبول دموي لخدش الحصى جدران المجاري، المغص الكلوي (ألم شديد في الكلية عند نزول الحصى من الحوض إلى الحالب قد يمنع الحركة).
• العلاج: مراجعة الطبيب والتحاليل، الإكثار من شرب الماء والسوائل، عدم تناول بعض الخضراوات كالطماطم والسبانغ لاحتوائها أملاح كلسية عالية.
• الوقاية: الإكثار من الماء صيفاً لتعويض ما فُقد بالتعرق، غذاء متوازن وعدم الإكثار من المالح، النشاط البدني.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• نسبة السكر الطبيعية في الدم: 80–120 ملغم/ديسلتر.
• ارتفاع السكر في الدم قد يسبب كثرة الإدرار (وانخفاضه دون 80 يسبب الإغماء).
• تتكون الحصى في الكلية نتيجة ترسب فوسفات الكالسيوم.
• نسبة الماء في العرق نحو 99%.
• طول الحالب نحو 22 سم.

أسئلة للمراجعة:
1) ما المقصود بـ: الطبقة المتقرنة، الميلانين، الأدمة؟
2) صف مكونات الجهاز البولي في الإنسان.
3) ما أنواع الإخراج في جسم الإنسان؟
4) شخصان أحدهما مصاب بالسكري والآخر بالبول الزلالي، كيف تميز بينهما؟
5) فسّر: إصابة بعض الأشخاص بداء البول السكري، وامتناع المصاب بالبول الزلالي عن تناول اللحوم.
6) صحح: وظيفة الغدد الدهنية هي المساعدة على انتصاب الشعر، ويزداد تعرق المصاب بالحمى لتخليص الجسم من الماء الزائد.
7) اذكر طبقات الجلد من الخارج للداخل ووظيفة كل طبقة.
8) ما وظيفة الغدد العرقية والغدد الدهنية والأظافر؟
9) اذكر الأعراض والوقاية لكل من السكري والبول الزلالي وحصى الكلية.
10) ارسم مع التأشير: مقطع طولي في الكلية، تركيب الجهاز البولي.'''),
  ]),
  Chapter('الفصل الثامن: الجهاز التناسلي', [
    Section('الملخص', Icons.notes, '''مقدمة:
• التكاثر هو الوسيلة الوحيدة التي تضمن استمرار الحياة على الأرض وحماية النوع من الانقراض. والجهاز المسؤول عن التكاثر في الإنسان هو الجهاز التناسلي.

أولاً: الجهاز التناسلي الذكري:
وظيفته تكوين الخلايا التناسلية الذكرية (النطف) وأجزاء مساعدة تنقلها إلى جسم الأنثى لإتمام إخصاب البيضة.
1) الخصيتان: زوج من الغدد البيضوية منفصلتان في كيس جلدي رقيق خارج الجسم يسمى كيس الصفن. تنتجان النطف أو الحيامن (Sperms) وهي خلايا فيها نصف العدد الأصلي من الكروموسومات، وتفرزان هرمونات ذكرية تتحكم بالصفات الجنسية الثانوية (كثافة الشعر وخشونة الصوت). تمر النطف إلى أقنية رفيعة هي النبيبات المنوية ثم إلى الوعاء الناقل.
2) الوعاءان الناقلان: ينقلان النطف من كل خصية إلى الإحليل، وفيهما مناطق كثيرة الالتواء تسمى البربخ. يفتحان على جانبي الإحليل الذي له فتحة للخارج ضمن العضو التناسلي.
3) الحويصلتان المنويتان: مستودعان صغيران في نهاية كل وعاء ناقل قرب قاعدة المثانة، وظيفتهما حفظ الخلايا التناسلية الذكرية بعد اكتمال نضجها.
4) الغدد الملحقة (تفرز سوائل تحافظ على حيوية النطف):
• غدة البروستات: عند قاعدة المثانة من الأسفل وتحيط بها، تفرز سوائل تغذي النطف وتحافظ على حيويتها.
• غدتا كوبر: زوج صغير تحت البروستات، وظيفتهما حماية النطف أثناء مرورها في الإحليل.

ثانياً: الجهاز التناسلي الأنثوي:
وظيفته تكوين البيوض وتوفير المكان المناسب للإخصاب والنمو وإتمام الحمل والولادة.
1) المبيضان: غدتان بيضويتا الشكل في الجزء الأسفل من الجوف الجسمي على جانبي الرحم، تنتجان البيوض والهرمونات الخاصة بالصفات الجنسية الثانوية للمرأة.
2) قناتا البيض (قناتا فالوب): فوق كل مبيض فتحتان قمعيتا الشكل، تفتحان على جانبي الرحم من الناحيتين العليا اليمنى واليسرى، ووظيفتهما نقل البويضات من المبيض إلى الرحم.
3) الرحم: عضو عضلي كمثري الشكل، قاعدته مغلقة من الأعلى ونهايته مفتوحة للأسفل متصلة بقناة المهبل. تنغرس فيه البويضة المخصبة وتتم فيه عملية الحمل واكتمال نمو الجنين.

البلوغ:
• الذكر يبلغ في عمر يقرب من 15 سنة: قدرة جسمه على تكوين النطف مع ظهور الشعر في الوجه وخشونة الصوت.
• الأنثى تبلغ بين 14–16 سنة غالباً: تكوّن المبايض البيوض مع تغيرات جسمية أبرزها الدورة الشهرية (الطمث): اضمحلال البيوض غير المخصبة بعد نحو أربعة أسابيع من تكوينها ويرافقها نزف دموي يستمر 3–7 أيام. تنقطع الدورة بعد سن الخمسين عادةً (عدم قدرة المبايض على تكوين البيوض). تنتج المرأة في حياتها نحو 400 بيضة.

الصفات الجنسية الثانوية:
1) الصوت: خشن في الذكر وناعم في الأنثى.
2) كثافة الشعر: أكثر على جسم الذكر.
3) الغدد اللبنية (الأثداء): تنمو بوضوح في الأنثى وتكون فعالة بعد الولادة، وضامرة غير فعالة عند الذكر.

الإخصاب والحمل والعقم:
أ) الإخصاب: اندماج الخليتين الذكرية والأنثوية (النطفة مع البيضة) لتكوين البيضة المخصبة التي تحتوي العدد الكامل من الكروموسومات (نصفها من الذكر ونصفها من الأنثى).
ب) الحمل: تمر البيضة المخصبة بانقسامات في قناة فالوب مكونة كتلة من الخلايا تستقر في الرحم وتحدث فيها عمليات تمايز تكوّن الجنين (Embryo)، الذي يرتبط بجدار الرحم بوساطة الحبل السري الذي يوفر له الغذاء والأوكسجين ويربطه بدورة الأم الدموية من خلال شبكة واسعة من الأوعية الشعرية على جدار الرحم تسمى المشيمة (Placenta). مدة الحمل الطبيعية تسعة أشهر وقد تكون سبعة أشهر أحياناً، ويسمى الأطفال المولودون حينها الأطفال الخدج.
جـ) الولادة: بعد 9 أشهر يكون الجنين قد اكتمل نموه وصار قادراً على التنفس والرضاعة والسمع والرؤية والحس. تحس الأم بتقلصات بطنية ونزول سوائل إشارة لاقتراب الولادة، ثم يُقطع الحبل السري وتنزل المشيمة. وقد يُلجأ للولادة القيصرية (فتح جزء من البطن وإخراج الطفل) عند عدم القدرة على الولادة الطبيعية.
• الرضاعة الطبيعية: غذاء معقم دافئ مكتمل المواد الغذائية للرضيع، تقي من الأمراض وتقلل الإصابة بسرطان الثدي لدى الأم، وتعزز مناعة الرضيع، والأطفال المرضعون من أمهاتهم أقل عرضة للاضطرابات النفسية.
د) العقم: عدم مقدرة الذكر أو الأنثى على الإنجاب بسبب قلة أو عدم تكوين النطف أو البيوض (الوراثة واضطراب الهرمونات وغيرها). وقد يُلجأ إلى إخصاب البيضة بنطف الأب خارج جسم الأم ثم إعادتها إلى الرحم مع أدوية وراحة تامة، وهي تقنية أطفال الأنابيب.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• كيس الصفن: كيس جلدي رقيق خارج الجسم يحوي الخصيتين.
• النطف (الحيامن): الخلايا التناسلية الذكرية، فيها نصف عدد الكروموسومات.
• النبيبات المنوية: أقنية رفيعة تمر فيها النطف بعد تكوينها.
• الوعاء الناقل: ينقل النطف من الخصية إلى الإحليل.
• البربخ: مناطق كثيرة الالتواء في الوعاء الناقل.
• البروستات: غدة عند قاعدة المثانة تفرز سوائل تغذي النطف.
• غدتا كوبر: تحميان النطف أثناء مرورها في الإحليل.
• قناة فالوب: تنقل البويضات من المبيض إلى الرحم.
• الرحم: عضو عضلي كمثري تنغرس فيه البويضة المخصبة ويكتمل فيه نمو الجنين.
• البلوغ: قدرة الجسم على تكوين الخلايا التناسلية (15 سنة للذكر، 14–16 للأنثى).
• الدورة الشهرية (الطمث): اضمحلال البيوض غير المخصبة بعد نحو أربعة أسابيع مع نزف دموي 3–7 أيام.
• الإخصاب: اندماج الخلية الذكرية والأنثوية لتكوين البيضة المخصبة.
• التلقيح: انتقال النطف إلى جسم الأنثى (وهو مرحلة تسبق الإخصاب).
• الحبل السري: يربط الجنين بجدار الرحم ويوفر له الغذاء والأوكسجين.
• المشيمة: شبكة واسعة من الأوعية الدموية الشعرية على جدار الرحم تربط الجنين بدورة الأم.
• الأطفال الخدج: المولودون بعد سبعة أشهر من الحمل.
• العقم: عدم القدرة على الإنجاب.
• أطفال الأنابيب: إخصاب البيضة خارج جسم الأم ثم إعادتها إلى الرحم.

التعاليل:
• النزف الدموي يرافق الدورة الشهرية: لأن البيوض غير المخصبة تضمحل بعد نحو أربعة أسابيع مع تساقط بطانة الرحم.
• خطورة مرض نقص المناعة المكتسبة (الإيدز): لعدم وجود علاج له لحد الآن، ولا تظهر أعراضه إلا بعد سنوات فينتشر بسهولة بين الناس.
• الخصيتان خارج الجسم: داخل كيس الصفن (حسب نص الكتاب).
• أهمية الرضاعة الطبيعية: غذاء معقم دافئ مكتمل، تقي الطفل من الأمراض وتعزز مناعته، وتقلل من خطر سرطان الثدي لدى الأم.

مقارنة بين الإخصاب والتلقيح:
• الإخصاب: اندماج الخليتين الذكرية والأنثوية لتكوين البيضة المخصبة.
• التلقيح: انتقال النطف إلى جسم الأنثى.

تصحيح عبارات:
• تظهر الصفات الجنسية الثانوية عند البلوغ (نحو 15 سنة للذكر و14–16 للأنثى) وليس بعد سن 21 عاماً.
• يرتبط الجنين بجدار الرحم بوساطة الحبل السري (والمشيمة هي الأوعية الشعرية التي تربطه بدورة الأم).'''),
    Section('الأمراض والمقارنات', Icons.healing, '''الإيدز: متلازمة العوز المناعي المكتسب (AIDS):
• نبذة: مرض يسببه فيروس HIV، لا تظهر أعراضه مباشرة بل بعد سنوات من الإصابة (ما لم يكتشفه المصاب بالتحاليل) فينتشر بسهولة. اكتشف أول مرة عام 1981م في بضع دول وانتشر في أغلب دول العالم. لا يوجد علاج له لحد الآن وإنما لقاحات يُعتمد عليها في التقليل من انتشاره.
• الأعراض: ارتفاع الحرارة والتعرق الشديد لعدة أسابيع، سعال جاف وضيق تنفس، إسهال مستمر لمدة طويلة، تعب وإنهاك شديد وفقدان النشاط، تضخم العقد اللمفاوية بشكل ملحوظ في العنق وتحت الإبط.
• العلاج: لا يوجد علاج، وإنما وسائل تعتمد على تقوية مناعة الجسم ضد الفيروس: غذاء خاص، منع اختلاط المريض بالأصحاء، عدم استعمال أدواته وحاجياته (خصوصاً أدوات الحلاقة) أو الاتصال المباشر معه، وعزل الأم عن الأب عند إصابته ومنع إنجاب أي طفل.
• الوقاية: تجنب الممارسات الجنسية غير المشروعة (أهم سبب لانتقال المرض فهو مرض جنسي فتاك)، التأكد من صحة الزوج أو الزوجة قبل الزواج بالفحوصات والتحاليل، التأكد من سلامة الدم قبل نقله للمريض في العمليات الجراحية، جمع معلومات دقيقة عن المصابين للتأكد من عدم انتشار المرض.

مقارنة بين الجهازين:
• الذكري: خصيتان (النطف)، وعاءان ناقلان، حويصلتان منويتان، غدة البروستات وغدتا كوبر، إحليل.
• الأنثوي: مبيضان (البيوض)، قناتا فالوب، رحم، مهبل.

معلومات رقمية للحفظ:
• بلوغ الذكر: نحو 15 سنة. بلوغ الأنثى: 14–16 سنة.
• الدورة الشهرية: نزف 3–7 أيام، وتنقطع بعد سن الخمسين.
• عدد البيوض في حياة المرأة: نحو 400 بيضة.
• مدة الحمل: 9 أشهر (أو 7 أشهر للخدج).'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• يبدأ البلوغ عند ذكر الإنسان ويصبح قادراً على تكوين النطف بعمر 15 سنة.
• الرضاعة الطبيعية تجنب المرأة مرض سرطان الثدي.
• يولد الأطفال الخدج بعد الشهر السابع من الحمل.
• تنقطع الدورة الشهرية عادةً بعد سن الخمسين (عدم القدرة على تكوين البيوض).

أسئلة للمراجعة:
1) ما المقصود بـ: كيس الصفن، البروستات، قناة فالوب؟
2) اشرح وظيفة كل من: غدتي كوبر، المشيمة، الحبل السري.
3) وضح جوانب الاختلاف بين الإخصاب والتلقيح.
4) وضح تأثير الرضاعة الطبيعية على الأم والطفل.
5) فسّر: النزف الدموي المرافق للدورة الشهرية، وخطورة مرض نقص المناعة المكتسبة.
6) صحح: تظهر الصفات الجنسية الثانوية بعد سن 21 عاماً، ويرتبط الجنين بجدار الرحم بوساطة المشيمة.
7) عدد أجزاء الجهاز التناسلي الذكري والأنثوي ووظيفة كل منها.
8) ما الصفات الجنسية الثانوية؟
9) اذكر أعراض الإيدز وطرق الوقاية منه.
10) ارسم مع التأشير بيضة ونطفة الإنسان، واكتب تقريراً عن تقنية أطفال الأنابيب.'''),
  ]),
  Chapter('الفصل التاسع: أعضاء الحس', [
    Section('الملخص', Icons.notes, '''مقدمة:
• الحواس الخمس: اللمس والتذوق والبصر والشم والسمع. مجسات تنبه الإنسان للمؤثرات (المناسب والمفيد والمؤذي) وتعمل جميعاً لحماية الجسم واستمرار عمله. ترتبط بالدماغ بالأعصاب وتنقل له المنبهات ليتخذ الإيعاز المناسب.
• أعضاء الحس تتكون من:
أ) أجزاء أساسية: الخلايا العصبية التي تتسلم المنبهات.
ب) أجزاء مساعدة: تراكيب توصل المنبهات إلى نهايات الأعصاب (عدسة العين، قناة السمع، عظام المطرقة والسندان).

1) حاسة اللمس:
• في أدمة الجلد أعداد هائلة من الخلايا الحسية تتحسس الحرارة والبرودة والألم. تقع العقد الحسية على أعماق مختلفة داخل الأدمة، وتتركز في مناطق كالأصابع (ولذلك أهمية كبرى لتحسس ومسك الأجسام).
• الحفاظ على الجلد: النظافة الشخصية والاستحمام، تجنب أشعة الشمس لفترات طويلة صيفاً، الابتعاد عن الوشوم وكثرة مستحضرات التجميل.
• أمراض الجلد: حب الشباب (بثور مؤقتة في المراهقة بسبب التغيرات الهرمونية، ولا يُعبث بها)، البهاق (تغير لون الجلد لأفتح أو أغمق، أسبابه وراثية أو اضطراب إفراز الميلانين نتيجة خلل في وظائف الكبد)، الطفح الجلدي (احمرار حاد يصيب الأطفال خاصة نتيجة التحسس من مواد معينة، يُعالج بالمراهم بعد استشارة الطبيب).

2) حاسة التذوق:
• تتركز في اللسان بخلايا حسية تسمى براعم التذوق تتصل بألياف حسية إلى الدماغ:
- براعم الحلاوة: في مقدمة اللسان.
- براعم الملوحة: في مقدمة اللسان أيضاً.
- براعم الحموضة: على جوانب اللسان.
- براعم المرارة: في مؤخرة اللسان.
• تتأثر براعم التذوق بالأنفلونزا والتهابات الفم والأسنان والحمى القرمزية (تشقق اللسان وتغير لونه). للحفاظ عليها: عدم التدخين وتجنب المشروبات الساخنة أو الباردة جداً، عدم وضع أشياء غريبة في الفم، غسل الأسنان يومياً مرتين على الأقل.

3) حاسة الشم:
• الأنف فتحة الجهاز التنفسي الخارجية، وله أهمية أساسية في تحديد الروائح. تلتقط التفرعات الدقيقة للخلايا العصبية في الغشاء المخاطي المبطن للأنف الروائح وترسلها إلى الدماغ الذي يفسرها بناءً على ما يخزنه من معلومات ثم يصدر الإيعاز المناسب.
• الحفاظ عليها: عدم استعمال مناديل الآخرين أو اليد في مسح الأنف، استعمال مناديل نظيفة عند الأنفلونزا ووضعها على الأنف عند العطس، ارتداء أقنعة واقية لمن يتعرضون للمواد الكيميائية (سمكرة وصبغ السيارات)، الابتعاد عن التدخين (القطران ضار)، تجنب الأماكن ذات الروائح النفاذة وارتداء الكمامة.
• الجيوب الأنفية: تجاويف داخل عظام الجمجمة تكوّن مادة مخاطية تحافظ على الأنف خالياً من البكتيريا. مواقعها: الجيوب الجبهية، الفكية، وعلى جانبي الأنف (Ethmoid). تلتهب فيصاحب ذلك صداع شديد ورشح متقطع وتنزل مواد قيحية إلى البلعوم.
• أسباب التهابها: استنشاق حبوب الطلع في الربيع، تيار هواء بارد، الغبار والأتربة، رذاذ الأصباغ وأبخرة الحوامض والقواعد، التدخين، أمراض كالأنفلونزا والتهاب المجاري التنفسية وبطانة الفم.

4) حاسة البصر (العين):
أولاً: تركيب العين الخارجي:
• تركيب شبه كروي قطره نحو 3 سم، مسطح قليلاً من الأمام، في تجاويف في الجمجمة تسمى المحاجر، محاطة بمادة شحمية، تحركها ست عضلات في مختلف الاتجاهات. يحيط بها جفنان مبطنان بغشاء رقيق يسمى منضمة العين (الملتحمة)، وتتصل بالعين غدة دمعية لترطيب العين وإزالة الشوائب.
ثانياً: تركيب العين الداخلي (ثلاث طبقات):
1) الطبقة الخارجية (الصلبة): وجزؤها المحدب الأمامي القرنية، وتمثل بياض العين.
2) الطبقة الوسطى (المشيمية): فيها الأوعية الدموية الشعرية. الجزء الأوسط منها القزحية (الجزء الملون)، وفي وسطها فتحة صغيرة البؤبؤ وظيفته تنظيم الحزمة الضوئية المارة (تتحكم بقطره عضلات صغيرة جداً). خلف البؤبؤ العدسة: جزء شفاف جانبه الداخلي أكثر تحدباً من الخارجي.
3) الطبقة الداخلية (الشبكية): تبطن الجزء الداخلي وتضم تفرعات العصب البصري. في وسطها من المؤخرة الشائبة الصفراء (منطقة حساسة جداً للضوء)، وأسفلها على بعد 6 ملم المنطقة العمياء حيث يتصل العصب البصري بالعين. الأجزاء الحساسة لاستقبال الأشعة تراكيب على هيئة عصي ومخاريط.
• سوائل العين: المنطقة أمام العدسة (الردهة الأمامية) مملوءة بالسائل المائي (يشبه اللمف)، والمنطقة خلف العدسة (الردهة الخلفية) مملوءة بالسائل الزجاجي.

الإبصار (يشبه عمل الكاميرا):
1) تجميع الضوء الساقط على العين وتوجيهه إلى الشبكية.
2) ترسل التراكيب الحسية على الشبكية ما تلتقطه عبر العصب البصري إلى الدماغ (الفص البصري).
3) يجمع الفص البصري ويرتب تفاصيل الصورة فتبدو مشابهة للطبيعة.

عيوب الإبصار:
1) قصر البصر: يرى المصاب الأجسام البعيدة غير واضحة. السبب: زيادة تحدب عدسة العين وتحدب القرنية وطول كرة العين فتتكون الصورة أمام الشبكية. يُعالج بنظارات بعدسات مقعرة (مفرقة للأشعة).
2) بعد البصر: لا يرى المصاب الكتابة بوضوح. السبب: قلة تحدب العدسة والقرنية وقصر كرة العين فتقع الصورة خلف الشبكية. يُعالج بعدسات محدبة (لامّة للأشعة).
3) انحراف البصر (الاستكماتزم): اكتشفه العالم الألماني فرانسيكاس دوندرس. يحدث عندما يكون تكور العين غير منتظم فلا يميز المصاب الأشعة المتعامدة (الأفقية والعمودية) فتقع إحداهما على الشبكية والأخرى أمامها. تستعمل نظارات بعدسات خاصة.

المحافظة على العينين: عدم الجلوس طويلاً أمام الحاسبة والتلفزيون وكثرة استعمال الهاتف، عدم قضاء فترة الراحة أيام الامتحانات أمام التلفاز أو الهاتف، الوقاية من الشمس القوية وعدم النظر إليها (نظارات شمسية صيفاً)، عدم دعك العين باليد، قناع واقٍ للذين يعملون بالحديد واللحام، تجنب كثرة مواد التجميل على العين، الابتعاد عن العدسات اللاصقة غير الطبية (تسبب التهاباً حاداً للملتحمة)، الانتباه عند ممارسة الرياضة، وعدم شرب الماء دفعة واحدة بكميات كبيرة بعد جهد طويل (يسبب ارتفاعاً مفاجئاً لضغط العين).

5) حاسة السمع (الأذن):
تركيب الأذن:
1) الأذن الخارجية: الصيوان (جزء غضروفي متسع في قاعدته شعيرات) وهو بداية القناة السمعية، وفيها خلايا إفرازية تفرز مادة شمعية لوقاية الأذن من الشوائب. تنتهي القناة بغشاء الطبلة.
2) الأذن الوسطى: تجويف غير منتظم في عظم الصدغ، جانبه الخارجي مسدود بغشاء الطبلة وطرفه الداخلي متصل بالداخلية بفتحتين هما النافذة المستديرة والنافذة البيضوية مغطاتان بغشاءين رقيقين. تتصل بها قناة أوستاكي التي تربطها بأعلى البلعوم لمعادلة الضغط على غشاء الطبلة. تضم ثلاثة عظام مرتبة من جهة الطبلة: المطرقة ثم السندان ثم الركاب، ووظيفتها نقل الصوت.
3) الأذن الداخلية:
أ) القوقعة: تركيب حلزوني من التيه العظمي ثم التيه الغشائي، وبينهما سائل اللمف الخارجي الذي ينقل الصوت من النافذة البيضوية إلى اللمف الداخلي الذي ينقله إلى المستلمات الحسية العصبية فالعصب السمعي ثم الدماغ.
ب) القنوات نصف الهلالية: ثلاثة أقنية مقوسة فيها سائل لمفي وخلايا حسية مهدبة تتصل بتجاويف القوقعة، وظيفتها المحافظة على توازن الجسم.

آلية السمع:
1) يجمع صيوان الأذن الموجات الصوتية.
2) تنتقل عبر قناة السمع إلى الأذن الوسطى.
3) يهتز غشاء الطبلة ثم ينتقل الاهتزاز إلى المطرقة والسندان والركاب.
4) اهتزاز الركاب يهز اللمف الخارجي ثم الداخلي ثم الأوتار السمعية ثم أعضاء الاستقبال.
5) ينقل العصب السمعي الإيعاز إلى المراكز السمعية في المخ فيفسرها الدماغ.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• الحواس الخمس: اللمس والتذوق والبصر والشم والسمع.
• براعم التذوق: خلايا حسية في اللسان.
• الجيوب الأنفية: تجاويف في عظام الجمجمة تكوّن مادة مخاطية تحمي الأنف من البكتيريا.
• المحاجر: تجاويف في الجمجمة تحوي العين.
• الملتحمة (منضمة العين): غشاء رقيق يبطن الجفنين.
• القرنية: الجزء المحدب الأمامي للطبقة الصلبة (بياض العين).
• القزحية: الجزء الملون من العين.
• البؤبؤ: فتحة في وسط القزحية تنظم مرور الضوء.
• العدسة: جزء شفاف خلف البؤبؤ.
• الشبكية: الطبقة الداخلية فيها تفرعات العصب البصري وعصي ومخاريط.
• الشائبة الصفراء: منطقة شديدة الحساسية للضوء في الشبكية.
• المنطقة (البقعة) العمياء: موضع اتصال العصب البصري بالعين، لا تستقبل الضوء.
• السائل المائي: أمام العدسة. السائل الزجاجي: خلف العدسة.
• الصيوان: جزء غضروفي متسع من الأذن الخارجية.
• غشاء الطبلة: يغلق نهاية القناة السمعية ويهتز بالصوت.
• النافذة البيضوية: فتحة تصل الأذن الوسطى بالداخلية.
• قناة أوستاكي: تربط الأذن الوسطى بأعلى البلعوم لمعادلة الضغط.
• القوقعة: تركيب حلزوني في الأذن الداخلية.
• القنوات نصف الهلالية: تحافظ على توازن الجسم.

التعاليل:
• تتركز الخلايا الحسية في الأصابع أكثر من مناطق الجسم الأخرى: لحاجة الإنسان يومياً لتحسس ومسك الأجسام والتعرف على خواصها.
• إفراز مادة شمعية في قناة السمع: لوقاية الأذن من الشوائب الخارجية التي تعلق بها.
• يُطلب من المعرضين لأصوات عالية مفاجئة فتح أفواههم: لمعادلة الضغط على جانبي غشاء الطبلة عبر قناة أوستاكي.
• يُطلب ارتداء سدادات الأذن لمن يتعرضون لأصوات شديدة: لحماية غشاء الطبلة من التمزق.
• يحدث ضعف السمع الوقتي عند الرشح: لانسداد قناة أوستاكي وعدم توازن الضغط على جانبي الطبلة.
• يُمنع شرب الماء بكميات كبيرة دفعة واحدة بعد الجهد: لأنه يسبب ارتفاعاً مفاجئاً لضغط العين.
• تتأثر حاسة الشم لدى عمال الصبغ والسمكرة: بسبب المواد الكيميائية، فيلزم ارتداء الأقنعة.
• تشبه العين الكاميرا: لأنها تجمع الضوء وتوجهه إلى الشبكية لتكوين صورة.

تصحيح عبارات:
• يوجد السائل الزجاجي خلف العدسة (الردهة الخلفية)، أما أمام العدسة فالسائل المائي.
• ترتيب آلية السمع الصحيح: الصيوان ← قناة السمع ← غشاء الطبلة ← المطرقة ← السندان ← الركاب ← اللمف الخارجي ← اللمف الداخلي ← الأوتار السمعية ← أعضاء الاستقبال ← العصب السمعي ← المراكز السمعية في المخ (الجملة في السؤال ينقصها الركاب).

التمييز بين قصر البصر وبعد البصر:
• قصر البصر: لا يرى البعيد بوضوح، الصورة أمام الشبكية، يعالج بعدسة مقعرة.
• بعد البصر: لا يرى القريب (الكتابة) بوضوح، الصورة خلف الشبكية، يعالج بعدسة محدبة.'''),
    Section('الأمراض والمقارنات', Icons.healing, '''أمراض الأذن:
1) التهاب الأذن الوسطى:
• تدخل الجراثيم إلى الأذن عن طريق الهواء والماء أو بإدخال أجسام صلبة كالأقلام في تجويف الأذن، فيلتهب جدار قناة السمع وغشاء الطبلة، وقد تلتهب الأذن الوسطى والداخلية فيحدث فقدان السمع.
• الرشح أو التهاب الأنف والبلعوم يسبب انسداد قناة أوستاكي ويؤدي إلى عدم توازن الضغط وضعف السمع وقتياً.
2) تمزق غشاء الطبلة:
• ينتج غالباً عن الأصوات الشديدة كالانفجارات وآلات الحفر وأصوات الطائرات القريبة. يُنصح من يتعرض لها بارتداء سدادات الأذن أثناء العمل.

أمراض الجلد:
• حب الشباب: بثور مؤقتة في المراهقة (تغيرات هرمونية) — اتباع إرشادات الطبيب وعدم العبث بها والاهتمام بنظافة الوجه.
• البهاق: تغير ملحوظ في لون الجلد (وراثي أو اضطراب إفراز الميلانين نتيجة خلل في وظائف الكبد).
• الطفح الجلدي: احمرار حاد نتيجة التحسس من مواد معينة، يُعالج بالمراهم بعد استشارة الطبيب.

التهاب الجيوب الأنفية (Sinusitis):
• أعراضه صداع شديد ورشح متقطع ومواد قيحية تنزل للبلعوم.
• أسبابه: حبوب الطلع، تيار هواء بارد، الغبار والأتربة، رذاذ الأصباغ وأبخرة الحوامض والقواعد، التدخين، الأنفلونزا والتهاب المجاري التنفسية.

عيوب البصر: قصر البصر، بعد البصر، انحراف البصر (الاستكماتزم) — انظر قسم التعاريف.

مقارنة بين مواقع براعم التذوق:
• الحلاوة والملوحة: مقدمة اللسان.
• الحموضة: جوانب اللسان.
• المرارة: مؤخرة اللسان.
• عند تناول الحلوى تتأثر براعم المقدمة.

مقارنة بين أجزاء الأذن:
• الخارجية: الصيوان والقناة السمعية وغشاء الطبلة (مادة شمعية).
• الوسطى: عظام المطرقة والسندان والركاب، النافذتان، قناة أوستاكي.
• الداخلية: القوقعة (للسمع) والقنوات نصف الهلالية (للتوازن).'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• عند تناول حلوى تتأثر براعم التذوق الواقعة في المقدمة.
• من الأمراض التي تسبب انسداد قناة أوستاكي: التهاب البلعوم.
• عدد العضلات التي تتحكم بحركة العين: ست عضلات.
• الإصابة بانحراف البصر بسبب تكور العين غير المنتظم.
• قصر البصر: عدسات مقعرة. بعد البصر: عدسات محدبة.

أسئلة للمراجعة:
1) ما المقصود بـ: الجيوب الأنفية، النافذة البيضوية، القرنية، البقعة العمياء؟
2) اشرح كيف تتم عملية الشم.
3) وضح تركيب طبقات العين.
4) شخصان أحدهما مصاب بقصر البصر والآخر ببعد البصر، كيف تشخص حالتهما؟
5) فسّر: تتركز الخلايا الحسية في الأصابع، وإفراز مادة شمعية في قناة السمع.
6) صحح: السائل الزجاجي أمام العدسة، وترتيب آلية السمع.
7) عدد أجزاء الأذن ووظيفة كل منها.
8) اشرح آلية السمع خطوة بخطوة.
9) كيف تحافظ على صحة العينين والأذنين وحاسة الشم؟
10) ارسم اللسان وحدد عليه مناطق براعم التذوق.'''),
  ]),
  Chapter('الفصل العاشر: الإفراز', [
    Section('الملخص', Icons.notes, '''مقدمة:
• لتنظيم عمل الجسم المعقد لا بد من مواد مساعدة تفرزها غدد خاصة (اللعابية والدرقية والكظرية وغيرها). ومن غير المعقول أن لا توجد حدود لطول الإنسان ولا سيطرة على معدل النمو.
• الإفراز: عملية تكوين مواد معقدة التركيب مفيدة للجسم عن طريق غدد خاصة، تنظم فعاليات الجسم المختلفة.
• المواد الإفرازية مجموعتان:
1) الإنزيمات: مواد عضوية (بروتينية) معقدة التركيب يكونها الجسم في غدد خاصة وظيفتها المساعدة في إنجاز وظائف الجسم كالهضم وإفراز اللعاب.
2) الهرمونات: مواد عضوية معقدة التركيب يكونها الجسم في غدد خاصة وظيفتها تنظيم عمل الجسم، وإفرازها داخلي أي إلى الدم مباشرة: الثايروكسين (الغدة الدرقية)، الأدرينالين (الكظريتان)، الهرمونات الجنسية (المبيضان والخصيتان)، هرمونات نمو العظام (الغدة النخامية).

تصنيف الغدد (حسب طريقة الإفراز):
أولاً: غدد ذات إفراز خارجي (Exocrine): تفرز المواد خارج الدم أو اللمف، مثل الغدد اللعابية والعرقية والدهنية عند جذور الشعر والدمعية.
ثانياً: غدد ذات إفراز داخلي:
1) الغدد الصم (Endocrine): إفرازها للدم مباشرة بدون قنوات، مثل الغدة الدرقية.
2) الغدة النخامية: تقع أسفل الدماغ، قطرها لا يتجاوز 1 سم، محاطة بغشاء، مؤلفة من فص أمامي أصفر وفص خلفي أبيض. تفرز هرمونات منظمة لعمل الجسم:
• الفص الأمامي الأصفر: هرمون محفز للنمو (نقصه يسبب التقزم وزيادته تضخم الجسم بنمو غير طبيعي للعظام)، وهرمون منظم لعمل الغدة الدرقية.
• الفص الخلفي الأبيض: هرمونات معجلة لتقلص الرحم عند الولادة، هرمون منظم لضغط الدم، وهرمون منظم لإعادة امتصاص الماء من النبيبات البولية في الكلية.
3) الغدة الدرقية (الثايرويدية): أسفل الحنجرة مباشرة، من فصين (أيسر وأيمن) بينهما رابط يسمى البرزخ وفص ثالث علوي هو الفص الهرمي. وظيفتها إفراز هرمون الثايروكسين المنظم لفعاليات الجسم، وقد تعاني اضطراباً بنقصه أو زيادته.
• نقص الثايروكسين: قلة التمثيل الغذائي وزيادة الوزن، تناقص ضربات القلب وانخفاض حرارة الجسم، ضعف النمو العقلي والبدني لدى الأطفال، انتفاخ الوجه.
• زيادة الثايروكسين: زيادة معدل التمثيل الغذائي وتناقص الوزن، زيادة ضربات القلب وارتفاع ضغط الدم، تضخم الغدة الدرقية، ضعف العضلات الإرادية (الهيكلية).
4) الغدتان الكظريتان: هرميتا الشكل فوق الكلية، كل غدة من طبقتين: خارجية صفراء (القشرة) وداخلية رمادية (اللب).
• وظيفة القشرة: إفراز الهرمونات المعدنية (التوازن المائي والملحي)، والهرمونات السكرية (تمثيل الكاربوهيدرات)، والهرمونات الجنسية (ظهور الصفات الجنسية الثانوية). توقف عمل القشرة أو استئصالها يسبب انخفاض ضغط الدم والضعف العقلي وتلون الجلد باللون البرونزي (مرض أديسون).
• وظيفة اللب: إفراز هرمون يزيد فعالية القلب ونشاطه وضرباته في الحالات المفاجئة، والمحافظة على ضغط الدم الطبيعي والتمثيل الغذائي الاعتيادي.
5) الغدد اللبنية (الأثداء): تميز اللبائن ومنها الإنسان، من عدد كبير من الأقنية تفتح بفتحة صغيرة هي الحلمة، تزود بالمواد الغذائية من دورة الأم الدموية وتفرز الحليب غذاءً مثالياً للرضيع (نظيف ودرجة حرارته مناسبة). الأمهات المرضعات أقل عرضة لسرطان الثدي، والرضاعة الصناعية تضر الطفل وتقلل تعلقه بأمه.

ثالثاً: الغدد المختلطة (إفراز خارجي وداخلي):
1) المبيضان: إفراز خارجي (إنتاج البويضات) وإفراز داخلي (هرمونات الصفات الجنسية الأنثوية الثانوية: قلة الشعر ونعومة الصوت وبروز الثديين).
2) الخصيتان: إفراز خارجي (تكوين النطف) وإفراز داخلي (هرمونات الصفات الذكورية الثانوية: خشونة الصوت وكثافة الشعر، وقلتها تؤدي إلى ظهور الصفات الأنثوية).
3) البنكرياس: إفراز خارجي (الإنزيمات الهاضمة) وإفراز داخلي (الأنسولين من كتل خلوية تسمى جزر لانكرهانز اكتشفها بول لانكرهانز عام 1869م).'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• الإفراز: عملية تكوين مواد معقدة التركيب مفيدة للجسم عن طريق غدد خاصة.
• الإنزيمات: مواد عضوية بروتينية معقدة تساعد في إنجاز وظائف الجسم كالهضم.
• الهرمونات: مواد عضوية معقدة تنظم عمل الجسم وتفرز إلى الدم مباشرة.
• الغدد ذات الإفراز الخارجي: تفرز مواد خارج الدم أو اللمف (اللعابية، العرقية، الدهنية، الدمعية).
• الغدد الصم (ذات الإفراز الداخلي): تفرز إلى الدم مباشرة دون قنوات (الدرقية).
• الغدد المختلطة: غدد لها إفراز خارجي وداخلي (المبيضان، الخصيتان، البنكرياس).
• الثايروكسين: هرمون الغدة الدرقية المنظم لفعاليات الجسم.
• البرزخ: الرابط بين فصي الغدة الدرقية.
• مرض أديسون: داء بسبب خلل في وظيفة قشرة الغدة الكظرية.
• جزر لانكرهانز: كتل خلوية في البنكرياس تفرز الأنسولين.

التعاليل:
• تصنف المبايض غدداً مختلطة: لأنها تفرز البويضات (إفراز خارجي) وهرمونات الصفات الجنسية الأنثوية (إفراز داخلي).
• تصنف الغدد الدمعية غدداً ذات إفراز خارجي: لأنها تفرز الدموع خارج الدم والجسم عبر قناة.
• تسمى الغدد الصم: لأن إفرازها للدم بدون الحاجة إلى قنوات.
• يضطرب عمل الغدة الدرقية عند نقص عنصر اليود.
• يتلون الجلد باللون البرونزي في مرض أديسون: نتيجة توقف عمل قشرة الغدة الكظرية.
• الحليب غذاء مثالي للرضيع: لأنه نظيف وذو درجة حرارة مناسبة ويحتوي كل المتطلبات.
• تتعرض الأمهات غير المرضعات لسرطان الثدي أكثر: لأن الرضاعة الطبيعية تحمي الثدي.

مقارنة بين الغدد ذات الإفراز الداخلي والخارجي:
• الداخلي: يفرز إلى الدم مباشرة، بلا قنوات، هرمونات (الدرقية، النخامية، الكظريتان).
• الخارجي: يفرز خارج الدم عبر قنوات (اللعابية، العرقية، الدهنية، الدمعية).

تصحيح عبارات:
• الغدة الكظرية تقع فوق الكلية وهي هرمية الشكل من طبقتين (القشرة واللب): العبارة صحيحة.
• الغدة النخامية غدة واحدة تقع أسفل الدماغ ومؤلفة من فصين: فص أمامي وفص خلفي (وليست من فصين أماميين وفصين خلفيين).'''),
    Section('الوظائف والمقارنات', Icons.healing, '''وظائف الفص الخلفي للغدة النخامية:
• هرمونات معجلة لتقلص الرحم عند الولادة.
• هرمون منظم لضغط الدم.
• هرمون منظم لإعادة امتصاص الماء من النبيبات البولية في الكلية.

وظائف قشرة الغدة الكظرية:
• الهرمونات المعدنية: التوازن المائي والملحي.
• الهرمونات السكرية: تمثيل الكاربوهيدرات.
• الهرمونات الجنسية: الصفات الجنسية الثانوية.

وظائف لب الغدة الكظرية:
• زيادة نشاط القلب وضرباته في الحالات المفاجئة (الأدرينالين).
• المحافظة على ضغط الدم الطبيعي والتمثيل الغذائي.

أعراض اضطراب الغدة الدرقية:
• النقص: قلة التمثيل الغذائي وزيادة الوزن، بطء ضربات القلب، انخفاض الحرارة، ضعف النمو العقلي والبدني للأطفال، انتفاخ الوجه.
• الزيادة: زيادة التمثيل الغذائي ونقصان الوزن، زيادة ضربات القلب وارتفاع الضغط، تضخم الغدة، ضعف العضلات الهيكلية.

اضطرابات هرمونية مهمة:
• نقص هرمون النمو: التقزم. زيادته: تضخم الجسم ونمو غير طبيعي للعظام.
• مرض أديسون: خلل قشرة الكظرية (انخفاض ضغط الدم، ضعف عقلي، جلد برونزي).
• السكري: اضطراب إفراز الأنسولين من جزر لانكرهانز في البنكرياس (انظر الفصل السابع).

أمثلة على الغدد:
• خارجية: لعابية، عرقية، دهنية، دمعية.
• صماء: درقية، نخامية، كظريتان.
• مختلطة: مبيضان، خصيتان، بنكرياس.
• لبنية: تفرز الحليب في اللبائن.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• عند نقص هرمون الثايروكسين: تناقص ضربات القلب.
• خلل في وظيفة لب الغدة الكظرية يؤثر على نشاط القلب.
• قد يضطرب عمل الغدة الدرقية نتيجة نقص عنصر اليود.

أسئلة للمراجعة:
1) ما المقصود بـ: الإفراز، الثايروكسين، الإنزيمات؟
2) قارن بين الغدد ذات الإفراز الداخلي والغدد ذات الإفراز الخارجي.
3) عدد وظائف كل من: الفص الخلفي للغدة النخامية، قشرة الغدة الكظرية.
4) فسّر: تصنيف المبايض غدداً مختلطة، وتصنيف الغدد الدمعية غدداً ذات إفراز خارجي.
5) صحح: تقع الغدة النخامية وسط الدماغ ومؤلفة من فصين أماميين وفصين خلفيين.
6) ما أعراض نقص وزيادة هرمون الثايروكسين؟
7) ما وظائف الفص الأمامي للغدة النخامية؟
8) اذكر أمثلة على الغدد المختلطة ووظائفها.
9) ما أهمية الرضاعة الطبيعية؟
10) ما مرض أديسون وما أعراضه؟'''),
  ]),
  Chapter('الفصل الحادي عشر: المناعة والأمراض', [
    Section('الملخص', Icons.notes, '''مقدمة:
• منح الله الجسم مقاومة ذاتية للجراثيم تسمى المناعة: قدرة الجسم على مقاومة الأمراض والجراثيم. والجهاز المناعي مسؤول عنها.
• أفضل وسائل المحافظة عليه: التغذية الجيدة، الرياضة، الراحة، وعدم الاقتراب من التدخين والمواد المسكرة.

أنواع المناعة:
أولاً: المناعة الطبيعية (غير المتخصصة):
• موجودة في الجسم تلقائياً منذ الولادة، وهي خط الدفاع الأول. توصف بأنها غير متخصصة لأنها لا تستهدف جراثيم أو مواد معينة بل تحمي الجسم من دخول المواد الضارة بشكل عام: الجلد، الأغشية المخاطية، الدموع.
ثانياً: المناعة المكتسبة (المتخصصة):
• يكتسبها الفرد خلال حياته بسبب دخول مسببات الأمراض إلى جسمه فيتحفز الجهاز المناعي لتكوين الأجسام المضادة. الأجسام المضادة: تراكيب بروتينية يكونها الجسم نتيجة تحفيز الجهاز المناعي بوجود العوامل الممرضة، وتتكون إما طبيعياً بسبب الإصابة بالأمراض أو صناعياً بوساطة اللقاحات والمصول. سميت متخصصة لأن الجهاز المناعي يفرز أجساماً مضادة متخصصة بنوع معين من الجراثيم.
وتصنف المناعة المكتسبة بحسب طبيعتها إلى:
1) المناعة الفعالة: الجسم هو الذي ينتج الأجسام المضادة، في حالتين:
• طبيعية: عند التعرض للمسببات المرضية (الإصابة بالمرض).
• اصطناعية: عند حقن الجسم باللقاحات.
2) المناعة السلبية: تُنتج الأجسام المضادة خارج جسم الإنسان ثم تُنقل إليه، وهي نوعان:
• طبيعية: تتكون الأجسام المضادة في جسم الأم وتنتقل إلى الجنين عن طريق المشيمة أو إلى الرضيع بالرضاعة الطبيعية.
• اصطناعية: تُنتج الأجسام المضادة في أجسام حيوانات (كالخيول) بحقنها بالمسببات المرضية ثم تُستخلص وتُنقى وتُحقن في الإنسان.

المصول واللقاحات:
• المصول: مواد سائلة معبأة بقناني، استخلصت من دماء أشخاص أصيبوا بالمرض أو دماء حيوانات (خيول وأبقار) أُعطيت الجراثيم ثم عُزلت منها المصول الحاوية على الأجسام المضادة.
• اللقاحات: سموم جراثيم مضعفة أو ميتة (اللقاح الثلاثي، الكزاز، شلل الأطفال، الحصبة...).

نماذج من اللقاحات:
1) لقاح BCG (التدرن الرئوي): مناعة مكتسبة طوال العمر، يُعطى للطفل حديث الولادة في الأسابيع الأربعة الأولى.
2) اللقاح الثلاثي: ضد الكزاز والخناق والسعال الديكي. حقنة في عضد الطفل ثلاث مرات، بين الجرعة والأخرى شهران، تبدأ في الشهر الثاني، ثم جرعات مقوية بعد السنة الأولى ثم عند دخول المدرسة.
3) لقاح شلل الأطفال: قطرات عن طريق الفم بثلاث جرعات بالتزامن مع الثلاثي.
4) لقاح الحصبة: في السنة الأولى بحقنة في العضلة.
5) لقاح النكاف (Mumps) والحصبة الألمانية (Rubella): حقنة تحت الجلد في السنة الأولى، يقي من الأمراض الثلاثة طوال العمر.
6) لقاح الجدري: بإحداث خدوش في يد الطفل ثم قطرة لقاح، يستمر ثلاث سنوات.
7) لقاح التيفوئيد: حقنة تحت الجلد لمن قد تكون مهنتهم سبباً في إصابتهم (أثناء الحروب والفيضانات).
8) لقاح سحايا الدماغ: يُعطى عند انتشار المرض وباءً.

علم الأمراض (Pathology):
• العلم الذي يدرس الأمراض التي تصيب الإنسان من حيث الأعراض والمسبب وتشخيصها وعلاجها وانتشارها والوقاية منها.
• الصحة: خلو جسم الإنسان من أي مؤشر سلبي جسمي أو نفسي. قد تستمر الأمراض مدة قصيرة لا تتعدى ثلاثة أيام (الأنفلونزا والرشح) أو مدة طويلة (أمراض مزمنة)، وقد تكون شديدة الخطورة كالسرطان والأمراض الوبائية كالكوليرا.

تصنيف الأمراض حسب منشأها:
1) الأمراض الفيروسية: الفيروس (الراشح) يمر عبر أوراق الترشيح لصغر حجمه، حلقة وصل بين الكائنات الحية وغير الحية، يتحول إلى ما يشبه البلورات الساكنة خارج الخلية الحية فلا يصنف ضمن الكائنات الحية. اكتشفه العالم الروسي ديمتري إيفانوفسكي. يتكون من جدار وكتلة من الحمض النووي (DNA أو RNA) وزوائد تثبيته، وليس له نواة أو كروموسومات أو عضيات، يستنسخ نفسه داخل الخلية الحية فقط. أمراضه: الأنفلونزا والكورونا والتهاب الكبد الفيروسي وداء الكلب.
2) الأمراض البكتيرية: تسببها البكتريا الضارة وينشأ عنها الالتهابات، وتعالج بالمضادات الحيوية (البنسلين والتتراسايكلين). أمراضها: الكزاز وداء السحايا وذات الرئة.
3) الأمراض الطفيلية: تسببها طفيليات خارجية تدخل الجسم عبر الغذاء والماء الملوثين وعن طريق الخدوش والجروح، وتكمل دورة حياتها داخل الجسم. أمراضها: اللشمانيا والملاريا والبلهارزيا ودودة البقر الشريطية.
4) الأمراض الفطرية: فطريات تصيب الجهاز الهضمي والتناسلي والجلد (الأظافر وفروة الرأس). تكثر في الأماكن المكتظة قليلة التهوية العالية الرطوبة. الوقاية: النظافة العامة والخاصة، الابتعاد عن مصادر العدوى وعدم استعمال أدوات المرضى.
5) الأمراض الوظيفية: قصور عضو عن أداء وظيفته بشكل طبيعي (وراثي أو بسبب حوادث أو ارتفاع/انخفاض مفاجئ للسكر والضغط). تعالج بالأدوية أو الجراحة وزراعة الأعضاء. أمثلتها: العجز الكلوي وقصور عضلة القلب وتليف الكبد.
6) الأمراض السرطانية: انقسام فجائي سريع غير منظم لخلايا بعض الأنسجة (الثدي والرئة والدم)، يسمى انتشار هذه الخلايا الأرومة السرطانية وتنتشر عن طريق اللمف. من مسبباته: المواد الكيميائية المسرطنة (بعض الأصباغ ودخان السيارات)، المواد المشعة، الأشعة فوق البنفسجية الشديدة، الاستعداد الوراثي، نمط الحياة غير الصحي والكحول والتدخين والمخدرات، وأنواع من الجراثيم تسبب نحو 15% من السرطانات (سرطان عنق الرحم).

تصنيف الأمراض حسب طبيعة الانتشار:
1) المعدية: تنتقل من شخص لآخر (السل، الكوليرا، الأنفلونزا، التهاب الكبد الفيروسي، الأمراض الجلدية).
2) الوبائية: معدية تتفشى بسرعة وتصيب أعداداً كبيرة (الكوليرا والطاعون).
3) المتوطنة: توجد في منطقة جغرافية معينة بصورة دائمة (الملاريا والحمى السوداء/الكالازار والكوليرا).'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• المناعة: قدرة الجسم على مقاومة الأمراض والجراثيم.
• المناعة الطبيعية (غير المتخصصة): مناعة موجودة منذ الولادة وهي خط الدفاع الأول (الجلد والأغشية المخاطية والدموع).
• المناعة المكتسبة (المتخصصة): مناعة يكتسبها الفرد خلال حياته بتكوين أجسام مضادة.
• الأجسام المضادة: تراكيب بروتينية يكونها الجسم نتيجة تحفيز الجهاز المناعي بوجود العوامل الممرضة.
• المناعة الفعالة: الجسم نفسه ينتج الأجسام المضادة.
• المناعة السلبية: الأجسام المضادة تنتج خارج الجسم ثم تنقل إليه.
• المصول: سوائل تحوي أجساماً مضادة للمرض مستخلصة من دماء مصابين أو حيوانات.
• اللقاحات: سموم جراثيم مضعفة أو ميتة.
• علم الأمراض: العلم الذي يدرس الأمراض من حيث الأعراض والمسبب والتشخيص والعلاج والانتشار والوقاية.
• الصحة: خلو الجسم من أي مؤشر سلبي جسمي أو نفسي.
• الأمراض المزمنة: أمراض تستمر مدة طويلة أو طوال العمر.
• الراشح (الفيروس): كتلة حمض نووي بجدار تستنسخ نفسها داخل الخلية الحية فقط.
• الأمراض الوبائية: أمراض معدية تتفشى بسرعة وتصيب أعداداً كبيرة (الكوليرا والطاعون).
• الأمراض المتوطنة: توجد في منطقة معينة بصورة دائمة (الملاريا).
• التلوث: مجموع التغيرات السلبية التي تحدث في البيئة وتسبب تدهورها.
• التدخين السلبي: تعرض غير المدخنين لدخان السكائر.

التعاليل:
• سميت المناعة الطبيعية غير متخصصة: لأنها لا تستهدف جراثيم أو مواد معينة بل تحمي الجسم من المواد الضارة عموماً.
• سميت المناعة المكتسبة متخصصة: لأن الجهاز المناعي يفرز أجساماً مضادة خاصة بنوع معين من الجراثيم.
• سميت المناعة الفعالة بهذا الاسم: لأن الجسم هو الذي ينتج الأجسام المضادة.
• سميت المناعة السلبية بهذا الاسم: لأن الأجسام المضادة تنتج خارج الجسم ثم تنقل إليه.
• لا يوضع الفيروس ضمن تصنيف الكائنات الحية: لأنه يتحول إلى ما يشبه البلورات الساكنة خارج الخلية ولا يتكاثر إلا داخلها.
• يسمى الفيروس الراشح: لأنه يمر عبر أوراق الترشيح لصغر حجمه.
• تكثر الأمراض الفطرية في الأماكن المكتظة قليلة التهوية: لأنها وسط مناسب لنمو الفطريات وتكاثرها.
• أضرار التدخين السلبي على الرضع كبيرة: لأنه يسبب التهاب الرئة الحاد ومشاكل التنفس.

مقارنة بين المناعة الطبيعية والمكتسبة:
• الطبيعية: موجودة منذ الولادة، غير متخصصة، خط الدفاع الأول (جلد، أغشية مخاطية، دموع).
• المكتسبة: تُكتسب بعد الولادة، متخصصة، تعتمد على الأجسام المضادة (بالإصابة أو اللقاح أو المصل).

تصحيح عبارات:
• مرض فقر الدم ليس من الأمراض الطفيلية (اللشمانيا والملاريا والبلهارزيا طفيلية).
• من أهم الأمراض الفيروسية: الأنفلونزا (والكوليرا بكتيرية، والعجز الكلوي والسكري وظيفيان).
• أهم طريقة للوقاية من شلل الأطفال: تلقيح الأطفال في سن مبكر.'''),
    Section('التدخين والمخدرات والتلوث', Icons.healing, '''التدخين ومضاره (آفة الآفات):
1) السبب الأساس لسرطان الرئة.
2) من أهم مسببات أمراض القلب والشرايين والأوعية الدموية، ويزيد فرص الإصابة بالسكري.
3) يسبب قرحة المعدة والإثنى عشري.
4) عدم التركيز وفقدان الشهية وفقر الدم.
5) يترسب النيكوتين في نهاية أصابع القدمين فيسبب بطء أو توقف الدورة الدموية فيها.
6) يؤثر على الحبال الصوتية فيصبح صوت المدخن أجشّ مع صعوبات في التنفس.
7) رائحة كريهة وتسوس الأسنان والتهاب اللثة.
• التدخين السلبي: استنشاق غير المدخنين لدخان السكائر، ضار جداً بالأطفال الرضع (التهاب الرئة الحاد ومشاكل التنفس).

الرياضة والصحة (العقل السليم في الجسم السليم): تنشيط الدورة الدموية وطرح الفضلات، زيادة المناعة الطبيعية وتقليل الإصابة بالأمراض، المحافظة على وزن الجسم والتخلص من الشحوم الزائدة، تنمية روح العمل الجماعي والتعاون، تأثير إيجابي على الصحة النفسية.

الكحول: من أخطر الآفات الصحية والاجتماعية. مضاره: التسمم الكحولي التدريجي والإدمان، أمراض الجهاز الهضمي (قرحة المعدة والتهاب القولون المزمن)، أمراض القلب والجلطة وارتفاع الضغط وتصلب الشرايين، تضخم وتشمع الكبد وسرطانه، انخفاض الإنتاجية ومشاكل عائلية كالطلاق، ترنح المدمن وفقدانه الوعي أحياناً.

المخدرات: من أخطر مشاكل دول العالم (الحشيشة والخشخاش والمورفين والأدوية المهدئة). أضرارها: سهولة الإصابة بالإيدز والأمراض الخطرة، عدم العمل والإنتاج والكسل المستمر، فقدان الشهية والضعف العام وقلة مقاومة الأمراض، تدني الإدراك الذهني والهلوسة والأفكار السوداء التي تقود للانتحار، رفض المجتمع والعزلة، دمار الحياة العائلية وفقدان العمل والدراسة.

مصادر التلوث:
1) تلوث كيميائي: عادمات السيارات والمصانع والأسمدة المتسربة للماء والمبيدات والمولدات ومصافي النفط. يسبب السرطان والتسمم الكيميائي.
2) تلوث فيزيائي: دقائق عالقة في الهواء (الغبار)، المياه الحارة من محطات الكهرباء والنووية، الإشعاعات (اليورانيوم المنضب)، زيادة الأشعة فوق البنفسجية. يسبب السرطان وأمراض الجهاز التنفسي كالربو.
3) تلوث إحيائي: مياه فضلات المنازل ومصانع الألبان والغذاء وفضلات المستشفيات والمجازر وحقول الدواجن، تحوي جراثيم تسبب الكوليرا والتهاب الكبد الفيروسي والإسهالات المعوية.

الغبار وصحة الإنسان:
• تسبب الأتربة والعواصف الترابية أذى كبيراً للمصابين بالربو وأمراض الرئة (التدرن والحساسية) والجيوب الأنفية وأمراض القلب والمسنين والمرضى والأطفال الرضع، وتسبب حساسية للعين والأنف. والعراق يتعرض سنوياً لعواصف ترابية بسبب التصحر وقلة الأمطار والتغير المناخي.
• الوقاية: وضع كمامات على الأنف، غلق نوافذ المنزل، وقلة التنقل للمسنين.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة مع أجوبتها:
• ليس من الأمراض الطفيلية: فقر الدم.
• يستمر مفعول اللقاح ضد الجدري نحو ثلاث سنوات.
• من أهم الأمراض الفيروسية: الأنفلونزا.
• أهم طريقة للوقاية من شلل الأطفال: تلقيح الأطفال في سن مبكر.
• لقاح BCG يُعطى في الأسابيع الأربعة الأولى من الولادة.

أسئلة للمراجعة:
1) ما المقصود بـ: اللقاح، الأمراض الوبائية، الأجسام المضادة؟
2) قارن بين المناعة الطبيعية والمناعة المكتسبة.
3) اشرح تركيب الفيروس (الراشح).
4) ما أنواع المناعة المكتسبة؟ وما الفرق بين الفعالة والسلبية؟
5) صنف الأمراض حسب منشأها مع مثال لكل نوع.
6) ما الفرق بين الأمراض المعدية والوبائية والمتوطنة؟
7) اذكر أضرار التدخين، وما التدخين السلبي؟
8) اذكر فوائد الرياضة.
9) ما أضرار الكحول والمخدرات؟
10) عدد مصادر التلوث وأمراض كل منها.
11) ما أضرار الغبار والعواصف الترابية وطرق الوقاية منها؟'''),
  ]),
];

class Figure {
  final String key;
  final String caption;
  const Figure(this.key, this.caption);
}

