const List<Chapter> socialHistory = [
  Chapter('الفصل الأول: العراق في العهد العثماني الأخير', [
    Section('الملخص', Icons.notes, '''العثمانيون:
• قبائل تركية نزحت من أواسط آسيا واستوطنت شمال غرب بلاد الأناضول (تركيا الحالية)، وسُمّوا نسبة إلى جدهم مؤسس الدولة العثمانية عثمان بن أرطغرل.
• توسعوا أولاً في أوربا (استفادة من انقسام الإمبراطورية البيزنطية)، ثم اتجهوا نحو البلاد العربية في عهد السلطان سليم الأول (1512 – 1520م) بعد انتصاره على الصفويين في معركة جالديران عام 1514م واحتلال تبريز عاصمة الصفويين. فخضعت البلاد العربية للحكم العثماني نحو أربعة قرون.

الأوضاع العامة في العراق:
• سيطر عليه الصفويون مرتين: عام 1508 (إسماعيل الصفوي) وعام 1529 (طهماسب بن إسماعيل).
• الاحتلال العثماني عام 1534 في عهد السلطان سليمان القانوني (1520 – 1566) الذي احتل بغداد.
• حكم المماليك العراق (1750 – 1831م)، وبنهايتهم وعودة الحكم العثماني المباشر بدأ (العهد العثماني الأخير) الذي انتهى بخروج العثمانيين عام 1917 بعد الحرب العالمية الأولى. بدأت القوات البريطانية احتلال العراق في 6 تشرين الثاني 1914 بعد دخول الدولة العثمانية الحرب إلى جانب دول الوسط بزعامة ألمانيا.
• حكمت الدولة العثمانية العراق نحو أربعة قرون سادها الجمود والتراجع الحضاري (طبيعة الحكم، والحروب والصراعات مع الصفويين والدول الأجنبية).
• تميز العهد الأخير ببداية التطور والانفتاح واتصال العراق بالعالم، وشهد عصر التنظيمات (عصر الإصلاحات الشاملة).

ميزات العهد العثماني الأخير:
1) تأثير حركة الإصلاحات العثمانية (التنظيمات): مرسوم كلخانة 1839م وخط همايون 1856م في عهد السلطان عبد المجيد (1839 – 1861)، وهدفها إعادة بناء الدولة وفق أنظمة وقوانين حديثة، وأول دستور عثماني عام 1876م. انعكست على العراق ببطء وبحدود (إدارات حكومية جديدة، نظام المعارف، إصلاحات في الإدارة والنقل والبريد).
2) قُسِّم العراق عام 1864م إلى ثلاث ولايات: بغداد والموصل والبصرة (لكل ولاية أقضية ونواحٍ وقرى).
3) كان الولاة يُعيَّنون من إستانبول مباشرة، وعددهم خمسة وثلاثون والياً (بعضهم حكم أكثر من مرة، وبعضهم لم يكمل المدة ثلاث سنوات).
4) تعيين ولاة مصلحين، أشهرهم مدحت باشا.
5) اتصال العراق بالعالم: المدارس الأجنبية للبعثات التبشيرية (الفرنسية والبريطانية والأمريكية)، بعثات التنقيب عن الآثار، المواصلات البخارية المائية، وخطوط البرق (كسرت طوق العزلة).

أشهر الولاة المصلحين: مدحت باشا (1869 – 1872م):
• تولى ولاية بغداد عام 1869 ومنحه السلطان صلاحيات واسعة (السلطتان العسكرية والمدنية). عُدَّ أعظم الولاة العثمانيين وأكثرهم نشاطاً. استند إلى قانون الولايات العثماني، وهدفه ربط الولايات الثلاث إدارياً وسياسياً واقتصادياً وتقوية السلطة المركزية. أهم إصلاحاته:
1) نظام الطابو: تنظيم ملكية الأرض وإقرار حقوق المالك بسند رسمي. الإيجابيات: حدد عائدية الأرض (أفراد أو دولة أو أوقاف)، وقضى على نزاعات العشائر وثوراتها، وعوّدها الاستقرار وحسّن المعيشة. السلبيات: تحول كثير من رؤساء العشائر إلى ملاك كبار وأفرادها إلى فلاحين فأرسى قواعد النظام الإقطاعي.
2) إصلاح النظام العسكري: الاعتماد على العراقيين في الجيش بدل الأجنبي، وتطبيق الخدمة الإلزامية (التجنيد الإجباري) (عارضته بعض المدن وأُخمدت ثورتها)، فتضاعف عدد الجيش، وأنشأ مدرستين عسكريتين في بغداد لتدريب الضباط.
3) إنشاء المدارس الحديثة: المدرسة الرشيدية العسكرية (4 سنوات، لغات عربية وتركية وتاريخ وجغرافية وحساب وخط ودين)، المدرسة الإعدادية العسكرية (3 سنوات)، مدرسة الصناعة (4 سنوات: تجارة وخياطة وطباعة)، المدرسة الرشيدية الملكية (4 سنوات، خريجوها يوظفون في الدوائر). ووضع أسس التعليم الحديث بنظام المعارف الحكومية.
4) الصحافة: أنشأ مطبعة الولاية وصدرت منها أول جريدة رسمية في العراق (زوراء) في 15 حزيران 1869، بالعربية والتركية مرتين أسبوعياً، واستمرت حتى الاحتلال البريطاني لبغداد 1917.
5) تحديث المواصلات: أعاد تشكيل شركة الإدارة العثمانية النهرية (ثماني بواخر: أربع للنهري الداخلي وأربع للبحري)، وأسس شركة الترامواي بين بغداد والكاظمية وافتُتح عام 1871.
6) تحديث المدن: أنشأ مدينتي الناصرية والرمادي، والمجالس البلدية، والمحاكم المدنية، ومصفى للنفط في بعقوبة، ومنتزهاً عاماً في بغداد، ومعملاً لإصلاح السفن في البصرة، ومزرعة نموذجية ومستشفى.
7) إصلاحات أخرى: مصنع للملابس والبطانيات لجنود الفيلق السادس، وصندوق حكومي للقروض، ومضخة كبيرة لرفع مياه دجلة.

نتائج الحكم العثماني في العراق:
1) اهتم السلاطين بالعراق مصدراً لتمويل الخزينة دون تطوير اقتصاده.
2) تزايدت المعارضة العراقية (خاصة في القرن السادس عشر): تحالفات عشائرية، وانتفاضة كربلاء عام 1604 على الحامية العثمانية، وانتفاضة بغداد التي قادها المفتي عبد الغني آل جميل عام 1832 ضد الوالي علي رضا (ضُربت محلة المفتي قنبر علي بالمدفعية).
3) تمكنت بعض الأسر والزعامات المحلية من حكم نفسها: آل عبد الجليل والعمريون في الموصل، والسوران في راوندوز، وعشائر بني لام وآل عليان والمنتفك في الجنوب، وآل فضل وشمر في الفرات الأعلى والجزيرة.
4) تدخل القوى الأوربية (بريطانيا وفرنسا وألمانيا) لضعف الدولة، للإفادة من موقعه وثرواته وسوقاً للبضائع.
5) شعور العثمانيين بضرورة الإصلاح وإرسال ولاة أكفأ.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• العثمانيون: قبائل تركية نزحت من أواسط آسيا، سُمّوا نسبة إلى عثمان بن أرطغرل مؤسس الدولة.
• سليم الأول: سلطان عثماني (1512 – 1520) انتصر على الصفويين في جالديران 1514 وتوجه إلى البلاد العربية.
• سليمان القانوني: سلطان عثماني (1520 – 1566) احتل بغداد عام 1534.
• جالديران: معركة عام 1514 بين العثمانيين والصفويين انتصر فيها العثمانيون.
• التنظيمات: حركة الإصلاحات العثمانية الشاملة (مرسوم كلخانة 1839 وخط همايون 1856).
• مدحت باشا: أشهر الولاة العثمانيين المصلحين في العراق (1869 – 1872).
• نظام الطابو: تنظيم ملكية الأرض وإقرار حقوق مالكها بسند رسمي.
• التجنيد الإلزامي (الخدمة الإلزامية): إلزام السكان بالخدمة في الجيش.
• زوراء: أول جريدة رسمية في تاريخ العراق، صدرت عام 1869.
• الرشيدية العسكرية: أول مدرسة أسسها مدحت باشا، مدة الدراسة 4 سنوات.
• عبد الغني آل جميل: مفتي بغداد قاد انتفاضة عام 1832 ضد الوالي علي رضا.

التعاليل:
• كان لنظام الطابو دور أساسي في الحد من النزاعات العشائرية: لأنه حدد ملكية الأرض وعوّد العشائر الاستقرار وحسّن معيشتها.
• لإصلاحات مدحت باشا أهمية رغم قصر ولايته (ثلاث سنوات): لأنها شملت الإدارة والاقتصاد والجيش والتعليم والمواصلات والمدن.
• قرر مدحت باشا الاعتماد على العراقيين في الجيش بدل الأجنبي: لضمان ولاء السكان للجيش.
• تعد وسائل المواصلات الحديثة إصلاحاً مهماً: لتطور النقل النهري والبحري والبري (الترامواي) والاتصال بالعالم.
• تزايد المعارضة العراقية ضد العثمانيين: بزيادة ضعف الدولة والتدخلات الأجنبية وسوء الإدارة.
• تدخل القوى الأوربية في أوضاع العراق: لضعف الدولة العثمانية والإفادة من موقعه وثرواته وسوقاً للبضائع.
• كان لجريدة زوراء دور أساسي: في إطلاع المجتمع على أحوال العالم الخارجي ونشر الوعي الثقافي.
• ظهور حركة الإصلاح في العراق في النصف الثاني من القرن التاسع عشر: لإرسال ولاة اطلعوا على الحضارة الغربية.'''),
    Section('التواريخ والأسماء', Icons.calculate, '''تواريخ مهمة (للحفظ):
• 1508: احتلال إسماعيل الصفوي للعراق.
• 1514: معركة جالديران.
• 1529: احتلال طهماسب الصفوي للعراق.
• 1534: الاحتلال العثماني للعراق (سليمان القانوني).
• 1604: انتفاضة كربلاء على الحامية العثمانية.
• 1750 – 1831: حكم المماليك للعراق.
• 1832: انتفاضة المفتي عبد الغني آل جميل في بغداد.
• 1839: مرسوم كلخانة. 1856: خط همايون. 1876: أول دستور عثماني.
• 1864: تقسيم العراق إلى ثلاث ولايات (بغداد والموصل والبصرة).
• 1869 – 1872: ولاية مدحت باشا. 15 حزيران 1869: صدور جريدة زوراء.
• 1871: افتتاح الترامواي بين بغداد والكاظمية.
• 6 تشرين الثاني 1914: بدء الاحتلال البريطاني للعراق. 1917: خروج العثمانيين.

سلاطين: عثمان بن أرطغرل (المؤسس)، سليم الأول (1512 – 1520)، سليمان القانوني (1520 – 1566)، عبد المجيد (1839 – 1861).

مدارس مدحت باشا (مدة الدراسة): الرشيدية العسكرية 4 سنوات، الإعدادية العسكرية 3 سنوات، الصناعة 4 سنوات، الرشيدية الملكية 4 سنوات.

مقارنة العهد العثماني الأخير: انفتاح وتطور بعد قرون الجمود، وصدور التنظيمات، وولايات ثلاث، وولاة مصلحون، واتصال بالعالم (مدارس تبشيرية وبرق وبواخر).'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة للمراجعة (مع أجوبة مختصرة من الكتاب):
1) عرّف: العثمانيون، سليم الأول، سليمان القانوني، جالديران، التجنيد الإلزامي، زوراء، التنظيمات، مدحت باشا، نظام الطابو، الرشيدية العسكرية، عبد الغني آل جميل.
2) ناقش: العهد العثماني الأخير تميز ببداية التطور والانفتاح واتصال العراق بدول العالم.
3) ناقش: وضع مدحت باشا الأسس الحديثة للتعليم في العراق (بإصدار نظام المعارف الحكومية وإنشاء المدارس).
4) ناقش: كان لجريدة زوراء دور في إطلاع المجتمع على أحوال العالم الخارجي.
5) ناقش: كان لتطبيق التجنيد الإلزامي دور إيجابي في مضاعفة أعداد الجيش.
6) علل: كان لنظام الطابو دور في الحد من النزاعات العشائرية. إصلاحات مدحت باشا مهمة رغم قصر ولايته.
7) عدد: ميزات الحكم العثماني الأخير، أهم إصلاحات مدحت باشا، نتائج الحكم العثماني في العراق.
8) وضح الآثار الإيجابية والسلبية لنظام الطابو.
9) وضح أهمية إنشاء مطبعة الولاية.
10) ناقش: من نتائج الحكم العثماني تزايد المعارضة العراقية، موضحاً ذلك بأبرز الانتفاضات (انتفاضة كربلاء 1604 وانتفاضة المفتي آل جميل 1832).
11) ابحث عن الأسباب الرئيسة لمعركة جالديران وأهم نتائجها.'''),
  ]),
  Chapter('الفصل الثاني: العراق في أثناء الحرب العالمية الأولى وبعدها', [
    Section('الملخص', Icons.notes, '''أولاً: المصالح البريطانية في العراق
1) موقع العراق الاستراتيجي لطرق التجارة البريطانية مع الشرق: بدأ التوسع الأوربي نحو الشرق في القرن السادس عشر. حصلت الملكة إليزابيث الأولى عام 1580 على تعهد عثماني بحماية التجار الإنكليز. ورحلة رالف فيتش عام 1583 أكدت أن العراق حلقة المواصلات بين الدولة العثمانية وبلاد فارس، وأن البصرة مركز تجاري مهم لتجارة التوابل والأقمشة والعقاقير من الهند. فوافقت الملكة لشركة (الشرق الأدنى) الإنكليزية على التجارة مع العراق، وفي 1604 منحت الدولة العثمانية امتيازات للإنكليز: رفع أعلامهم والتجارة في الموانئ، تحديد الرسوم بـ 3% فقط، وكالة تجارية في البصرة، حق محاكمة العمال العراقيين، وممثل تجاري بريطاني بحصانة في بغداد والبصرة.
2) التنافس الألماني – البريطاني: اهتمام ألمانيا بالآثار والدراسات، ثم مشروع سكة حديد (برلين – بغداد)، وحصلوا عام 1903 على امتياز مد سكة من قونية إلى بغداد فالبصرة (واتفقوا على سكة الحجاز). كانت تجارتهم الثانية بعد البريطانية في ميناء البصرة فعدتها بريطانيا خطراً على مصالحها.
3) الظروف الدولية: الحملة الفرنسية على مصر 1798 (نابليون)، تعيين هارفورد جونز قنصلاً لبريطانيا في بغداد عام 1802 وعلاقته بالوالي المملوكي سليمان باشا الكبير، ومعاهدة الدردنيل 1809 بين بريطانيا والدولة العثمانية (حرية التجارة للبريطانيين وإلزام العثمانيين بحمايتها).
4) المصالح في نهري دجلة والفرات: الهند (درة التاج البريطاني). ثلاثة طرق تربطها بالهند: عبر رأس الرجاء الصالح (قليل الأهمية لطوله)، عبر مصر (المتوسط والأحمر)، وعبر العراق (المتوسط والخليج، وهو المفضل لأنه الأقصر). كلفت شركة الهند الشرقية الضابط فرنسيس رودن جسني بمسح الفرات (حزيران 1830 – حزيران 1831) وبينت أهميته (المواصلات بين المتوسط والخليج، صلاحيته للبواخر البخارية، التجارة والنفوذ، أهميته العسكرية). ثم بعثة 1834 بباخرتين (دجلة والفرات) وغرقت (دجلة) فغيّر جسني رأيه. وتبعتها رحلة هنري بلوس لنج (1840: شركة ملاحة في دجلة بباخرتين لندن ودجلة)، ورحلة فلكس جونز (1847 – 1853)، ورحلة القائد سلبي (1862).
5) مشاريع سكك الحديد: دعت بريطانيا عام 1857 إلى مد سكة حديد الفرات (هدفها استراتيجي أكثر منه اقتصادي).
6) الميزان التجاري لصالح بريطانيا: صدرت الأقمشة والجوت والحديد والفولاذ والتوابل والشاي والسكر، واستوردت الصوف والقمح والتمر والسمسم والجلود والخيل والصمغ. بلغت نسبة البضائع البريطانية والهندية 65.3% (1910 – 1912).
7) النزعة الاستعمارية.

ثانياً: الاحتلال البريطاني للعراق (1914)
• صرح اللورد كيرزن (نائب ملك بريطانيا في الهند) عام 1911 أن المصالح البريطانية تمتد إلى بغداد. استغلت بريطانيا نشوب الحرب العالمية الأولى: انضمت الدولة العثمانية إلى دول الوسط (ألمانيا والنمسا والمجر) ضد دول الوفاق (بريطانيا وفرنسا وروسيا). في 5 تشرين الثاني 1914 أعلنت بريطانيا وفرنسا الحرب على العثمانيين.
• تحركت القوات من البحرين (حملة ديالمين). في 6 تشرين الثاني 1914 نزلت في الفاو، واحتلت البصرة في 22 تشرين الثاني 1914 (استنجد وجهاؤها بعلماء النجف وكربلاء والكاظمية وصدرت فتاوى).
• القرنة: احتلت في 3 كانون الأول 1914 (موقعها عند ملتقى دجلة والفرات، وتوفير المؤن، وتأثيرها المعنوي) واستسلمت القوات العثمانية ليلة 8 – 9 كانون الأول.
• معركة الشعيبة (12 – 14 نيسان 1915): انسحب العثمانيون إلى الشعيبة بقيادة سليمان العسكري ومعهم آلاف المتطوعين العراقيين، عبر خطين: النجف بزعامة السيد محمد سعيد الحبوبي، والكاظمية وبغداد بزعامة السيد مهدي الحيدري والشيخ محمد الخالصي. دافعهم ديني. حُسمت المعركة لصالح بريطانيا يوم 14 نيسان بعد التعزيزات، وانتحر القائد سليمان العسكري وتوفي الحبوبي عام 1915 في الناصرية. أسباب الهزيمة: تأثير الخسائر في المعنويات، سوء التخطيط وقلة الجنود النظاميين مقابل المتطوعين، نقص السلاح والمؤن، وتأكد العراقيين من عجز العثمانيين.
• احتلال العمارة (حزيران 1915) والناصرية (تموز 1915)، وأسبابه: السيطرة على رأس الخليج وإبعاد العثمانيين عن شط العرب، منع إعادة تنظيمهم، استعادة هيبة بريطانيا، حماية مصالحها النفطية (شركة النفط الأنجلو – فارسية).
• حصار الكوت: احتلها طاوزند في أيلول 1915 وانسحب العثمانيون (نور الدين بك) إلى سلمان باك (المدائن)، ثم تراجع البريطانيون إلى الكوت فحاصرهم العثمانيون خمسة أشهر. وصل الجنرال الألماني فون دركولتز في كانون الأول 1915 وأمر بمواصلة الحصار حتى نفاد المؤن، فاستسلم طاوزند في نيسان 1916.
• احتلال بغداد: عُين الجنرال ستانلي مود قائداً للجيش البريطاني (13 كانون الأول 1916 بدأ خطته)، وصلوا مشارف بغداد في 10 آذار 1917 بعد معارك تل أسود وأم الطبول، وانسحب العثمانيون (نسفوا المخازن وأحرقوا الجسر)، ودخل مود بغداد في 11 آذار 1917 وأذاع بيانه: (لم ندخل بلادكم أعداء فاتحين إنما محررين).
• التقدم شمالاً وغرباً: بعقوبة وخانقين وسامراء والسليمانية وكركوك، والرمادي 29 أيلول 1917، والفلوجة وحديثة وعنه وتكريت، وآخر نقطة غرباً 22 تشرين الثاني 1918.
• هدنة مودروس 31 تشرين الأول 1918 (وقف العمليات) ورغم ذلك احتل البريطانيون الموصل في 10 تشرين الثاني 1918 (الجنرال مارشال وجه إنذاراً).

ثالثاً: الانتداب البريطاني
• اقترح نظام الانتداب الجنرال سمطس (جنوب أفريقيا). تعريفه: وضع الشعوب المنفصلة عن الدولة العثمانية تحت إشراف دولة كبرى تقدم الإرشاد حتى تصبح قادرة على الحكم. أدرج في المادة 22 من ميثاق عصبة الأمم (28 حزيران 1919).
• مؤتمر سان ريمو (24 – 25 نيسان 1920): فُرض الانتداب البريطاني على العراق وشرقي الأردن وفلسطين، والفرنسي على سوريا ولبنان. وعد الرئيس الأمريكي ويلسون (النقاط الأربع عشرة) بحق الشعوب في تقرير مصيرها. وقعت معاهدة سيفر (اعترفت الدولة العثمانية بانفصال العراق ووضعه تحت الانتداب).
• أهم بنود لائحة الانتداب: قانون أساسي خلال ثلاث سنوات، احتفاظ بريطانيا بقوة عسكرية وإدارة العلاقات الخارجية، المحافظة على الأراضي، إلغاء الامتيازات الأجنبية، نظام قضائي، منع التمييز بين رعايا أعضاء العصبة، وعدم منع تأسيس حكومة مستقلة إدارياً.

موقف الحركة الوطنية: اجتماعات النصف من شعبان في كربلاء (3 أيار 1920) وخطب المرجع الشيخ محمد تقي الحائري، واحتفالات المولد النبوي في بغداد 14 أيار 1920، وجمعيتا العهد العراقي وحرس الاستقلال السريتان، واجتماع 26 آذار 1920 وخطب الشيخ محمد مهدي البصير (شاعر ثورة العشرين) واختيار 15 مندوباً للقاء أرنولد ويلسون في 20 حزيران 1920، واجتماعات النجف.

رابعاً: ثورة العشرين (30 حزيران 1920)
الأسباب الداخلية: تدهور الاقتصاد والمجاعة، الضرائب الباهظة واحتكار المحاصيل، سوء الإدارة العسكرية (السخرة وتقييد التجول)، إدارة سيئة من ضباط وموظفين هنود، وضوح السياسة البريطانية (تحويل العراق إلى جزء من الإمبراطورية ثم الانتداب)، اعتقال الشخصيات الوطنية ونفيها بعد استفتاء ويلسون (1918 – 1919) الذي أكد رغبة العراقيين بحكومة دستورية ملكية مستقلة، ودور رجال الدين في النجف وكربلاء والكاظمية وسامراء والجمعيات السرية.
• جمعية العهد العراقية: سرية أسست في دمشق 1919، من رجالها ياسين الهاشمي وجميل المدفعي وجعفر العسكري ونوري السعيد ومولود مخلص والشيخ مهدي الخالصي ومحمد باقر الشبيبي ومحمد تقي الشيرازي. طالبت باستقلال العراق ضمن حدوده الطبيعية وحكم ملكي دستوري يرأسه أحد أنجال الشريف حسين.
• جمعية حرس الاستقلال: سرية أسست أواخر شباط 1919، من رجالها علي آل بزركان وناجي شوكت وعبد المهدي المنتفكي ومحيي الدين السهروردي ومحمد جعفر أبو التمن، وفروعها في بغداد والكاظمية والشامية والنجف والحلة وبعقوبة.
الأسباب الخارجية: تأثير الثورة العربية الكبرى 1916 في الحجاز (الشريف حسين)، وعود المنتصرين (إعلان مود 1917 ومبادئ ويلسون 8 كانون الثاني 1918)، الثورة المصرية 1919، وقيام دولة سوريا الملكية تموز 1920 برئاسة الأمير فيصل.

الوقائع: انطلقت الثورة في 30 حزيران 1920 بإطلاق عشيرة الظوالم سراح شيخها شعلان أبو الجون المعتقل في مخفر الرميثة، ثم عمت الفرات الأوسط وانتشرت في الأنبار وكردستان، واستمرت خمسة أشهر. أسلحة الثوار بسيطة (الفالة والمكوار والخناجر وقليل من البنادق).
• أهم المعارك: سيطر الثوار على أبي صخير والشامية والديوانية وكربلاء والنجف. معركة الرارنجية (الرستمية بين الحلة والكفل) انتصر فيها الثوار وغنموا مدفعاً حديثاً (هتفوا: الطوب أحسن لو مكواري) ودمروا به الباخرة فاير فلاي (التي جاءت لنجدة المحاصرين في الكوفة)، ثم السماوة والدغارة ومناطق المنتفك (قلعة سكر والشطرة وسوق الشيوخ).
• الثورة في ديالى: بعقوبة وديلتاوه ومندلي وشهربان؛ سيطرت عشائر العبيد على بعقوبة وشهربان وقتلوا الحاكم البريطاني، وللشيخ حبيب الخيزران دور.
• في غربي العراق: لواء الدليم (الأنبار)، الشيخ ضاري المحمود (1868 – 1928) رئيس قبيلة زوبع قاد الثائرين، رفض طلب الكولونيل لجمن (12 آب 1920 في خان النقطة)، فقتله ولداه خميس وسليمان. امتدت الثورة من الفلوجة إلى عنه.
• في كردستان: كفري (أنزلوا العلم البريطاني وأقاموا حكومة مؤقتة)، أربيل وكويسنجق وخوشناو وراوندوز، ومعركة قرب الزاب الكبير 15 أيلول.
• صحافة الثورة: جريدة الفرات (الشيخ محمد باقر الشبيبي، العدد الأول 7 آب 1920، خمسة أعداد وتوقفت 15 أيلول)، وجريدة الاستقلال (محمد عبد الحسين الكاظمي، 1 تشرين الأول 1920، ثمانية أعداد)، المجموع 13 عدداً.
مميزات الثورة: وحدت كلمة العراقيين من الجنوب إلى الشمال، نضج سياسي ووطني وإدارة المدن المحررة (مجالس شعبية)، سبقها عمل سياسي سلمي (مذكرات ووفود) فلما فشل لجأوا إلى الثورة، وانتهت عسكرياً بنصر بريطانيا لكن سياسياً لصالح الثوار فغيرت بريطانيا سياستها (مؤتمر القاهرة آذار 1921 والمناداة بفيصل ملكاً).
نتائجها: أحد أهم أسباب تأسيس الدولة العراقية الحديثة (الحكومة المؤقتة تشرين الأول 1920)، فشل الإدارة البريطانية المباشرة، أثبتت الوحدة الوطنية بين فئات الشعب، كشفت نضجاً سياسياً (الصحافة)، أضعفت مركز بريطانيا في الشرق الأدنى، نبراس للثورات العربية، واعترف المحتل بقوتها وبسالة رجالها (قال القائد هالدين في مذكراته: عقول بارعة تدير حركتهم).

خامساً: نشأة الدولة العراقية المعاصرة
1) مؤتمر القاهرة (12 آذار 1921): دعا إليه ونستون تشرشل وزير المستعمرات البريطاني، حضره برسي كوكس، وقرر ترشيح الأمير فيصل بن الحسين لعرش العراق وتشكيل قوات مسلحة وطنية. تقدم ذلك البلاغ البريطاني الفرنسي (7 تشرين الثاني 1918). أسباب ترشيح فيصل: شخصية معروفة ومقبولة، حارب مع الضباط العراقيين في الثورة العربية 1916، تحسين سمعة بريطانيا بعد سايكس – بيكو 1916 ووعد بلفور 1917، إسقاط فرنسا حكومته في سوريا 1920 (معركة ميسلون)، ومقبول أكثر من بقية المرشحين. وصل فيصل ميناء البصرة في 23 حزيران 1921.
2) الحكومة العراقية المؤقتة: وصل برسي كوكس بغداد 11 تشرين الأول 1920 حاكماً ملكياً عاماً. اختيار السيد عبد الرحمن النقيب (الكيلاني) رئيساً للحكومة المؤقتة (25 تشرين الأول 1920) مع ثمانية وزراء ومستشار بريطاني لكل وزير، وقُسم العراق إلى عشرة ألوية. في 11 تموز 1921 قرر المجلس بالإجماع مناداة فيصل ملكاً (حكومة دستورية نيابية ديمقراطية مقيدة بقانون) ونتيجة الاستفتاء 96% لصالحه. توج ملكاً في 23 آب 1921 في ساحة برج الساعة في القشلة.
• مهام فيصل: إنهاء الانتداب تدريجياً، الحفاظ على ولاية الموصل جزءاً من العراق ومواجهة الخطر التركي، حكومة وطنية دستورية وتطوير البلاد وتوطيد الوحدة الوطنية.
3) المعاهدة العراقية – البريطانية الأولى 1922: معاهدة ولاء وتحالف، أرادها العراق لتحل محل الانتداب بين دولتين متكافئتين، وأرادتها بريطانيا لتحافظ على امتيازاتها وتمرر الانتداب بأقل كلفة. وقعتها وزارة عبد الرحمن النقيب (10 تشرين الأول 1922) بعد استقالة الحكومة (19 آب 1922) تحت الضغط. تتألف من مقدمة و18 مادة، أهمها: مشورة بريطانيا للعراق مع صيانة سيادته، وضع دستور، إدخال العراق عصبة الأمم، ومدتها 20 سنة. اختصرها بروتوكول (30 نيسان 1923، وزارة عبد المحسن السعدون) إلى أربع سنوات.
4) المجلس التأسيسي: انتخابات 10 تشرين الأول 1922 (قاطعتها الحركة الوطنية)، وأجريت 12 تموز 1923، وافتتح المجلس 27 آذار 1924. مهامه: مناقشة المعاهدة وتصديقها، تشريع القانون الأساسي (الدستور)، وقانون انتخاب مجلس النواب. بعثت بريطانيا إنذاراً قبل جلسة العصبة (12 حزيران 1924)، فصدق المجلس المعاهدة في 10 حزيران 1924 (37 مؤيداً و24 معارضاً وامتناع 8، من حاضري 69 عضواً بإقناع رئيس الوزراء جعفر العسكري) بشرط بقاء ولاية الموصل جزءاً من العراق.
5) القانون الأساسي (الدستور): مقدمة و123 مادة موزعة على عشرة أبواب، صادق عليه المجلس باجماع في 20 تموز 1924 ونُشر آذار 1925 وبقي نافذاً حتى ثورة 14 تموز 1958. وصدّق قانون الانتخابات 2 آب 1924 وحُل المجلس. نصت مقدمته: العراق دولة ذات سيادة مستقلة حرة، ملكها لا يتجزأ، حكومته ملكية وراثية وشكلها نيابي، وعاصمته بغداد.
6) معاهدة 1930: وقعها نوري السعيد (30 حزيران 1930). امتيازاتها: مساعدات عسكرية لبريطانيا (مرور قواتها واستعمال السكك والأنهار والموانئ والمطارات وتأجير القواعد الجوية)، امتيازات قضائية ومالية ودبلوماسية، تنفذ عند دخول العراق عصبة الأمم، مدتها 25 سنة. صادق عليها النواب بأغلبية 69 من 88، وقوبلت بمعارضة واسعة (أبدلت الانتداب المؤقت بالاحتلال الدائم).
7) دخول عصبة الأمم: شروط إنهاء الانتداب: حكومة مستقلة وإدارة قادرة، حفظ الوحدة والاستقلال، حفظ الأمن، موارد مالية كافية، قوانين وتنظيم قضائي عادل. وسبع ضمانات: حماية الأقليات، حفظ المصالح والامتيازات الأجنبية، حفظ المصالح القضائية، حرية الفكر والعبادة وأعمال الإرساليات، الالتزامات المالية، الحقوق المكتسبة، والعهود الدولية. قُبل العراق عضواً في عصبة الأمم في 3 تشرين الأول 1932 (تسلسل 57)، أول دولة عربية عضو، وعُين نوري السعيد أول مندوب عربي. صار عيداً وطنياً (احتفال 6 تشرين الأول 1932).

سادساً: الملوك
• الملك فيصل الأول: توفي 7 أيلول 1933 في سويسرا (انسداد الشرايين).
• الملك غازي: ولد في مكة 21 آذار 1912، وصل بغداد 5 تشرين الثاني 1924، درس في مدرسة هارو والكلية العسكرية، تولى العرش 1933، وتوفي 7 نيسان 1939 بحادث سيارة قرب قصر الزهور بالحارثية (اتهمت بريطانيا بتدبيره، وقال السفير بيترس: إما أن يسيطر عليه أو يخلع). أوصى بالعرش لابن عمه الأمير عبد الإله، فأعلن فيصل الثاني ملكاً (وعمره أربع سنوات) تحت وصاية خاله الأمير عبد الإله.

سابعاً: العراق والحرب العالمية الثانية
• بعد تشكيل نوري السعيد وزارته (نيسان 1939) وإعلان بريطانيا الحرب على ألمانيا (أيلول 1939): ساءت الأوضاع التجارية والمالية، احتكار الغذاء وارتفاع الأسعار، رقابة على الصحف. قطع العراق علاقاته مع ألمانيا (أيلول 1939) والتزم بمعاهدة 1930 وسمح للقوات البريطانية بالمرور. رفض العقداء الأربعة (صلاح الدين الصباغ، ومحمود سلمان، وفهمي سعيد، وكامل شبيب) زج الجيش في الحرب إلى جانب بريطانيا. استقال نوري السعيد وشكل رشيد عالي الكيلاني وزارته (آذار 1940).
• بعد انهيار فرنسا ودخول إيطاليا الحرب، طلبت بريطانيا قطع العلاقات معها فتريث العراق. هرب الوصي إلى الديوانية فاستقال الكيلاني، وكلف طه الهاشمي (نيسان 1941)، ونُقل العقداء فاستقالت الحكومة وهرب الوصي إلى البصرة (فراغ دستوري).
• حكومة الدفاع الوطني: سيطر الجيش على بغداد (2 نيسان 1941) وشكل حكومة الدفاع الوطني برئاسة رشيد عالي الكيلاني. وفي 10 نيسان 1941 قرر مجلس الأمة عزل الوصي عبد الإله وتعيين الشريف شرف، وكلف الكيلاني بتأليف الوزارة (12 نيسان).
• العدوان البريطاني (االحتلال الثاني): عدت بريطانيا الحكومة غير شرعية، وأنزلت لواءً مدرعاً في البصرة 29 نيسان 1941. بدأت العمليات في 2 أيار 1941 بقصف الطائرات البريطانية للقوات العراقية قرب الحبانية (أربعة أيام ثم انسحاب إلى سن الذبان). عاد الوصي مع القوات البريطانية إلى بغداد في 1 حزيران 1941 وشكل وزارة موالية. أحيل العقداء الأربعة والمدنيان رشيد عالي الكيلاني ويونس السبعاوي إلى المجلس العرفي العسكري، ونُفذ الحكم عليهم عدا الكيلاني الذي كان لاجئاً.
• العراق عضو مؤسس في الأمم المتحدة عام 1945: دعت أمريكا العراق لمؤتمر سان فرانسيسكو (وفده برئاسة وزير الخارجية أرشد العمري) وافتتحه الرئيس هاري ترومان ومعه 49 دولة. ضم الميثاق 111 مادة في 19 فصلاً (حفظ السلم والأمن الدوليين، علاقات ودية، تعاون دولي، حل النزاعات سلمياً). صادق مجلس النواب العراقي على الميثاق (تشرين الأول 1945).'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• معركة الشعيبة: معركة (12 – 14 نيسان 1915) انتصرت فيها بريطانيا على العثمانيين والمتطوعين العراقيين قرب البصرة.
• محمد سعيد الحبوبي: عالم دين قاد المتطوعين من النجف في معركة الشعيبة وتوفي 1915.
• الجنرال مود: قائد الجيش البريطاني الذي احتل بغداد 11 آذار 1917.
• الجنرال دركولتز: قائد ألماني للقوات العثمانية في الكوت.
• هدنة مودروس: هدنة 31 تشرين الأول 1918 بين دول الوفاق ودول الوسط.
• الانتداب: وضع الشعوب المنفصلة عن العثمانيين تحت إشراف دولة كبرى لتقديم الإرشاد حتى تستقل بشؤونها.
• مؤتمر سان ريمو: مؤتمر الحلفاء (24 نيسان 1920) الذي وزع الانتدابات فأعطى العراق وفلسطين وشرقي الأردن لبريطانيا وسوريا ولبنان لفرنسا.
• معركة الرارنجية: معركة انتصر فيها ثوار العشرين على البريطانيين في الرستمية.
• مؤتمر القاهرة: مؤتمر آذار 1921 دعا إليه تشرشل ورشح فيصل بن الحسين لعرش العراق.
• القانون الأساسي العراقي: أول دستور عراقي (1925) فيه 123 مادة.
• معاهدة سيفر: معاهدة بين الحلفاء والدولة العثمانية اعترفت فيها بانفصال العراق ووضعه تحت الانتداب البريطاني.
• جمعية حرس الاستقلال: جمعية سرية (شباط 1919) طالبت بالاستقلال التام وحكم ملكي دستوري.
• عبد الله (عبد الإله): وصي على الملك فيصل الثاني، خاله.
• فيصل الثاني: ملك العراق بعد غازي (1939) وعمره أربع سنوات.
• 3 تشرين الأول 1932: دخول العراق عصبة الأمم دولة مستقلة.
• رشيد عالي الكيلاني: رئيس حكومة الدفاع الوطني 1941.
• حكومة الدفاع الوطني: حكومة شكلها الجيش برئاسة رشيد عالي الكيلاني بعد هروب الوصي.
• العقداء الأربعة: صلاح الدين الصباغ ومحمود سلمان وفهمي سعيد وكامل شبيب.

التعاليل:
• أهمية العراق لبريطانيا: طريق إلى الهند (درة التاج) وهو الأقصر، وموقعه على طرق التجارة، وثرواته.
• قررت بريطانيا احتلال العراق عام 1914: لحماية مصالحها في الخليج وانضمام العثمانيين إلى ألمانيا.
• كان على بريطانيا احتلال العمارة والناصرية: لتعزيز انتصاراتها والسيطرة على رأس الخليج ومنع تنظيم العثمانيين وحماية النفط.
• احتلال القرنة: لموقعها عند ملتقى النهرين وتوفير المؤن وتأثيرها المعنوي.
• معركة الشعيبة مهمة: أكدت للعراقيين عجز العثمانيين عن مواجهة بريطانيا وأثرت في معنوياتهم.
• هزيمة العثمانيين في الشعيبة: سوء التخطيط وقلة الجنود النظاميين ونقص السلاح والمؤن.
• اندلعت ثورة العشرين: لتخلي بريطانيا عن وعودها وفرض الانتداب وسوء الإدارة والضرائب.
• رفض العراقيون الانتداب: لأنه استعمار جديد، وأيقنوا أن الحرية تؤخذ ولا تعطى.
• ثورة العشرين حدث مهم: لأنها مرحلة نضال الشعب لنيل الحرية والاستقلال ومهدت لتأسيس الدولة العراقية.
• تشكيل الحكومة المؤقتة من نتائج الثورة: لأن بريطانيا غيّرت سياسة القمع بعد فشلها.
• دعمت بريطانيا ترشيح فيصل: لتحسين سمعتها وقبوله وكفاءته.
• صعوبة المفاوضات في معاهدة 1922: لاختلاف الرؤية (العراق يريد السيادة وبريطانيا الامتيازات) ورفض الشعب.
• أولوية بحث المعاهدة في المجلس التأسيسي: لأن بريطانيا أرادت أن يكون الدستور مقيداً بالمعاهدة.
• قوبلت معاهدة 1930 بمعارضة واسعة: لأنها أبدلت الانتداب بالاحتلال الدائم ومنحت بريطانيا امتيازات.
• اتهام بريطانيا بوفاة الملك غازي: لموقفه المعادي لها ومواقفه الوطنية والعربية.
• تشكيل حكومة الدفاع الوطني: لهروب الوصي وفراغ دستوري وموقف العقداء الأربعة الرافض للحرب إلى جانب بريطانيا.
• العراق عضو مؤسس في الأمم المتحدة: لأنه وقف إلى جانب الحلفاء منذ 1943 فدعته أمريكا.
• اعتبار يوم 3 تشرين الأول 1932 مهماً: لأنه دخول العراق عصبة الأمم دولة مستقلة وصار عيداً وطنياً.'''),
    Section('التواريخ والأسماء', Icons.calculate, '''تسلسل الأحداث (للحفظ):
• 1580: تعهد عثماني بحماية التجار الإنكليز. 1583: رحلة رالف فيتش. 1604: امتيازات للإنكليز.
• 1798: حملة نابليون على مصر. 1802: هارفورد جونز قنصل. 1809: معاهدة الدردنيل.
• 1830 – 1831: مسح جسني للفرات. 1834: بعثة الباخرتين. 1840: شركة بلوس لنج. 1857: سكة حديد الفرات.
• 1903: امتياز سكة حديد (قونية – بغداد – البصرة) لألمانيا.
• 1911: تصريح كيرزن. 1914 (5 تشرين الثاني): إعلان الحرب. (6 ت2): نزول الفاو. (22 ت2): احتلال البصرة. (3 ك1): القرنة.
• 1915: الشعيبة (12 – 14 نيسان)، العمارة (حزيران)، الناصرية (تموز)، الكوت (أيلول).
• 1916 (نيسان): استسلام طاوزند في الكوت.
• 1917 (11 آذار): احتلال بغداد. 1917 (29 أيلول): الرمادي.
• 1918: هدنة مودروس (31 ت1)، احتلال الموصل (10 ت2)، البلاغ البريطاني الفرنسي (7 ت2).
• 1919 (28 حزيران): ميثاق عصبة الأمم والمادة 22. تأسيس العهد وحرس الاستقلال.
• 1920: مؤتمر سان ريمو (24 – 25 نيسان)، اجتماع كربلاء (3 أيار)، ثورة العشرين (30 حزيران)، الحكومة المؤقتة (25 ت1).
• 1921: مؤتمر القاهرة (12 آذار)، وصول فيصل البصرة (23 حزيران)، قرار المجلس (11 تموز)، التتويج (23 آب).
• 1922: المعاهدة الأولى (10 ت1). 1923: بروتوكول السعدون (30 نيسان). 1924: افتتاح المجلس التأسيسي (27 آذار)، تصديق المعاهدة (10 حزيران)، الدستور (20 تموز).
• 1925: نشر القانون الأساسي. 1930: معاهدة (30 حزيران). 1932: عصبة الأمم (3 ت1).
• 1933: وفاة فيصل الأول (7 أيلول). 1939: وفاة غازي (7 نيسان).
• 1939 (أيلول): الحرب العالمية الثانية. 1940: وزارة الكيلاني. 1941: حكومة الدفاع الوطني (2 نيسان)، عزل الوصي (10 نيسان)، العدوان البريطاني (2 أيار)، عودة الوصي (1 حزيران).
• 1945: ميثاق الأمم المتحدة.

أرقام: النسب 3% (رسوم)، استفتاء فيصل 96%، التصويت على المعاهدة (37 مؤيد و24 معارض و8 ممتنع من 69)، معاهدة 1930 (69 من 88)، 123 مادة للدستور في 10 أبواب، 111 مادة للأمم المتحدة في 19 فصلاً، العراق الدولة رقم 57 في العصبة.

مدد المعاهدات: 1922 (20 سنة ثم اختصرت إلى 4)، 1930 (25 سنة).'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة للمراجعة (من الكتاب):
1) عرّف: معركة الشعيبة، محمد سعيد الحبوبي، الجنرال مود، الجنرال دركولتز، هدنة مودروس، الانتداب، مؤتمر سان ريمو، معركة الرارنجية، مؤتمر القاهرة، الملك غازي، القانون الأساسي العراقي، عبد الله، فيصل الثاني، جمعية حرس الاستقلال، 3 تشرين الأول 1932، رشيد عالي الكيلاني، حكومة الدفاع الوطني، العقداء الأربعة.
2) عدد بنقاط:
• ثورة العشرين وأسبابها الداخلية والخارجية.
• لماذا كان على بريطانيا احتلال العمارة والناصرية.
• مميزات ثورة العشرين ونتائجها.
• أسباب تشكيل حكومة الدفاع الوطني.
• مظاهر الاحتلال البريطاني الثاني عام 1941.
3) ناقش العبارات:
• كان لبريطانيا مصالح مهمة في العراق.
• تشكيل الحكومة المؤقتة من النتائج المهمة لثورة 1920.
• بعد إعلان الانتداب أيقن رجال الحركة الوطنية ضرورة مواجهته بالقوة.
• دعمت بريطانيا ترشيح الأمير فيصل بن الحسين.
• كان أمام الملك فيصل الأول مهمات عدة.
• كانت العلاقات صعبة ومعقدة عند عقد معاهدة 1922.
• كان لبريطانيا دور في تدبير حادث وفاة الملك غازي.
• العراق عضو ومؤسس في الأمم المتحدة عام 1945.
4) ما الشروط الواجب توافرها في أية دولة تريد إنهاء الانتداب؟ وما الضمانات السبع؟
5) وضح أهم بنود المعاهدة العراقية – البريطانية الأولى 1922، وامتيازات معاهدة 1930.
6) اذكر مهام المجلس التأسيسي العراقي.
7) ما الإجراءات التي اتخذتها بريطانيا لتهدئة الأوضاع بعد مقاطعة الانتخابات؟ (إعفاء كوكس وتعيين دوبس، إعادة المبعدين، تقصير مدة المعاهدة إلى أربع سنوات).
8) ما أهمية معركة الشعيبة ومعركة الرارنجية؟
9) اذكر الأحداث التي جرت في الثورة في ديالى والغرب وكردستان.
10) ارسم خريطة العراق وحدد عليها محاور تحرك قوات الاحتلال البريطاني (الفاو، البصرة، القرنة، العمارة، الناصرية، الكوت، بغداد، الموصل).'''),
  ]),
];

const List<Chapter> socialGeography = [
  Chapter('الفصل الأول: الخصائص الطبيعية لجغرافية العراق', [
    Section('الملخص', Icons.notes, '''أولاً: الموقع والحدود والمساحة
• الموقع الجغرافي: يقع العراق في النصف الشمالي من الكرة الأرضية، وفي القسم الجنوبي الغربي من قارة آسيا، وفي القسم الشمالي الشرقي من العالم العربي.
• الموقع الفلكي: بين دائرتي عرض (29° – 37°) شمالاً وخطي طول (38° – 48°) شرقاً، فامتداده من الشرق إلى الغرب يساوي تقريباً امتداده من الشمال إلى الجنوب.
• الحدود: من الشمال تركيا، ومن الشرق إيران (تفصلهما حدود طبيعية: جبال طوروس وزاكروس)، ومن الجنوب الكويت، ومن الغرب سوريا والأردن والسعودية.
• أطول حدوده البرية نحو 3462 كم، نسبها: إيران 37.5%، السعودية 23.5%، سوريا 17.4%، تركيا 11%، الكويت 5.6%، الأردن 5%.
• حدوده البحرية (الخليج العربي) نحو 60 كم.
• المساحة: نحو 435,052 كم²، وقد انعكست مساحته الواسعة على تنوع التضاريس والمناخ والنبات الطبيعي.
• الشكل: قريب من الدائري، وبغداد في وسطه، فأعطى هذا الشكل المتلاحم مزايا سياسية واقتصادية (لا يستغرق المسافر سوى ساعات بين أي مكانين بالسكك أو السيارة).
• أهمية الموقع: ثروات اقتصادية متنوعة، يشرف على القسم الشرقي من الدول العربية ضمن الهلال الخصيب، يقع ضمن الجسر الأرضي الذي يربط قارات العالم القديم (آسيا وأفريقيا وأوروبا)، وعلى أقصر الطرق البرية بين المحيط الهندي والبحر المتوسط، وتجوب سماءه خطوط ملاحة جوية كثيرة (منطقة ارتكاز في العالم).

ثانياً: أقسام سطح العراق (التضاريس)
1) المنطقة الجبلية: القسم الشمالي والشمالي الشرقي، نحو 6% من المساحة، على شكل هلال من الشمال الغربي إلى الجنوب الشرقي، من سلسلتين:
• الجبال العالية الارتفاع (2100 – 3600 م): تحاذي الحدود مع تركيا وإيران، جبال التوائية صخورها بركانية ومتحولة. فيها أعلى قمة: جبل هلكرد (أكثر من 3600 م) ضمن جبال حصاروست، وجبلا قنديل وسرميدان.
• الجبال قليلة الارتفاع (1400 – 2100 م): جنوب السلسلة الأولى، ومن جبالها بيخير وعقرة داغ وحرير وبرانان.
• المنطقة الجبلية من أهم مصادر المياه (ثلوج وأمطار تتجاوز 1000 ملم) وفيها أهم الروافد المغذية لدجلة.
• سهولها: السندي (زاخو) في دهوك، وشهرزور ورانية في السليمانية (مناطق زراعة واستيطان). هضابها: بنجوين وبشدر وجوارته (رعي وزراعة).

2) المنطقة شبه الجبلية (المتموجة): جنوب الجبلية، منطقة انتقالية، نحو 15% من المساحة، بارتفاع 200 – 1000 م، وتتألف من:
• التلال: لا يتجاوز ارتفاعها 1000 م (حمرين ومكحول ومقلوب وأوانه داغ وكيلابات ونفط داغ وكاني دومالن).
• الهضاب: هضبة كركوك (شرقاً) وهضبة الموصل (غرباً) يفصلهما سهل أربيل.
• السهول: الحويجة (كركوك) وديبكة وأربيل.

3) السهل الرسوبي: نحو 24% من المساحة (بضمنها الأهوار والبحيرات)، مستطيل طوله نحو 600 كم وعرضه 205 كم، اتجاهه شمالي غربي – جنوبي شرقي.
• حدوده: المنطقة شبه الجبلية شمالاً، الهضبة الصحراوية غرباً، جبال زاكروس شرقاً، الخليج العربي جنوباً.
• تكوّن بترسبات دجلة والفرات والأنهار المنحدرة من المرتفعات الشرقية (الكارون والكرخة).
• قليل الانحدار (يرتفع 100 م عند حدود شبه الجبلية)، فيصعب تصريف المياه عن سطحه.
• الأهوار والمستنقعات: مسطحات مائية في الأقسام الوسطى والجنوبية، مساحتها أكثر من 20000 كم²، على شكل مثلث رؤوسه العمارة والناصرية والبصرة، تزداد أواخر الشتاء والربيع وتتقلص صيفاً.
• أهمية الأهوار: خزانات طبيعية للمياه وتدرأ الفيضانات، زراعة الحبوب، ثروات نباتية (القصب والبردي) وحيوانية (أسماك وطيور وماشية)، أهمية سياحية.

4) الهضبة الصحراوية الغربية: القسم الغربي والجنوبي الغربي، نحو 270000 كم² (55% من المساحة)، وهي أكبر المناطق مساحة، امتداد لبادية الشام وهضبة جزيرة العرب.
• ارتفاعها 300 – 900 م، تتدرج بالارتفاع نحو الغرب والشمال الغربي.
• يسودها التلال والحصى والكثبان الرملية، ووديان (حوران والأبيض والخر)، ومنخفضات (الحبانية والرزازة والثرثار: طوله نحو 300 كم وعرضه 45 كم).
• فقر النبات لسيادة الجفاف، وتتعرض لتعرية شديدة (نحت وإرساب).

ثالثاً: المناخ والنبات الطبيعي
• الطقس: حالة الجو (حرارة وضغط ورياح وأمطار) لمكان محدد ولمدة قصيرة (ساعة، يوم، أسبوع).
• المناخ: وصف حالة الجو لمكان محدد ولمدة طويلة (شهر أو سنة أو عدة سنوات). مناخ العراق: حار جاف صيفاً، معتدل ممطر شتاءً.

العوامل المؤثرة في مناخ العراق:
1) الموقع الفلكي بالنسبة لدوائر العرض: الأكثر تأثيراً، يحدد زاوية سقوط الشمس وطول النهار. بين 29° – 37° شمالاً فاكتسب صفات المنطقة المدارية: نهار الصيف 14 ساعة وقصير في الشتاء (10 ساعات).
2) المسطحات المائية: (الخليج العربي والمتوسط والأحمر وقزوين والأسود) تأثيرها محدود لبعدها ولوجود السلاسل الجبلية، عدا المتوسط والأحمر والخليج في الشتاء.
3) التضاريس: ارتفاع الجبال يزيد الأمطار ويخفض الحرارة (الشمال)، والجنوب قليل الأمطار مرتفع الحرارة.

عناصر المناخ:
• الفصلان الرئيسان: الصيف والشتاء. الربيع والخريف انتقاليان لا يتجاوزان شهرين.
1) درجة الحرارة: أهم العناصر. تباين كبير بين الليل والنهار وبين الصيف والشتاء، وهذا يحدد صفة المناخ القاري. الصيف شديد الحرارة في الوسط والجنوب (مدى حراري يومي كبير)، والشمال معتدل. الشتاء بارد خاصة في الشمال (قد ينخفض دون الصفر).
2) الضغط الجوي والرياح: تهب من الضغط العالي إلى الواطئ.
• الصيف: ضغط واطئ في الهند والخليج، وضغط مرتفع فوق هضبة الأناضول، فالرياح السائدة شمالية غربية (الشمالية) تلطف الحرارة، ورياح جنوبية غربية تسبب عواصف ترابية، وجنوبية شرقية من الخليج (الشرقي) رطبة غير مريحة.
• الشتاء: ضغط منخفض فوق الخليج العربي فتهب رياح شمالية غربية، وشمالية شرقية جافة باردة، وجنوبية شرقية رطبة تسقط الأمطار في الوسط والجنوب.
3) الأمطار: المنخفضات الجوية القادمة من البحر المتوسط هي السبب الرئيس. تسقط معظمها في الشتاء (من تشرين الثاني إلى نيسان) وتنعدم صيفاً (ضغط عالٍ مداري وقلة الرطوبة). تقل في الوسط والجنوب الغربي (أقل من 250 ملم)، وتزداد نحو الشمال الشرقي (حتى 1000 ملم) بفعل الأمطار التضاريسية.

الأقاليم المناخية (3):
1) إقليم مناخ البحر المتوسط: شمال شرق العراق (المنطقة الجبلية). شتاؤه بارد تتساقط فيه الثلوج وأمطاره غزيرة (750 – 1000 ملم)، وصيفه جاف معتدل (30 – 35 °م).
2) إقليم مناخ السهوب: المنطقة شبه الجبلية، انتقالي بين المتوسط شمالاً والصحراوي جنوباً. شتاؤه أقل برودة وأمطاره أكثر من 300 ملم، وصيفه حار جاف (38 – 40 °م).
3) إقليم المناخ الصحراوي: السهل الرسوبي والهضبة الغربية، أوسع الأقاليم مساحة وأشدها حرارة وأقلها مطراً: صيفه 44 – 48 °م وأمطاره 50 – 200 ملم.

النبات الطبيعي: النبات الذي ينمو دون تدخل الإنسان. يتطابق توزيعه مع الأقاليم المناخية والتضاريس. فوائده: تلطيف الجو، ومنع انجراف التربة، ورعي الحيوانات. وهو في 5 نطاقات:
1) الغابات والأعشاب الجبلية: شمال شرق (الجبال العالية)، دائمة الخضرة، أكثرها غابات البلوط.
2) السهوب (الاستبس): نحو 15% من المساحة في المنطقة شبه الجبلية، حشائش وأعشاب وبصلية وشوكية: سهوب جافة (العاقول) ورطبة (الكعوب).
3) ضفاف الأنهار: على دجلة والفرات وروافدهما، كثيفة دائمة الخضرة: الصفصاف والحلفا وعرق السوس.
4) الأهوار والمستنقعات: جنوب السهل الرسوبي، كثيفة متعددة الأنواع: القصب والبردي (وقود، حصران، ورق، علف).
5) النباتات الصحراوية: أوسع نطاق (نحو 70% من المساحة) في السهل الرسوبي والهضبة الغربية، تكيفت مع جفاف نحو ثمانية أشهر: حولية (الخباز والحلبة والبابونك) ومعمرة (الأثل والسدر والشوك).

رابعاً: الموارد المائية
• اشتهر العراق بوفرة مياهه حتى سُمي بلاد ما بين النهرين (أرض الرافدين). وتقسم الموارد المائية إلى:
1) مياه الأمطار والثلوج: المصدر الرئيس لتغذية الأنهار. غزيرة في الجبال (أكثر من 1000 ملم) وأقل من 250 ملم في الوسط والجنوب، ويُعوَّض النقص بدجلة والفرات والجوفية.
2) المياه السطحية: دجلة والفرات وشط العرب وروافدهما، والأودية الموسمية والبحيرات. تزداد في الربيع (موسم الفيضان) وتقل في الصيف (موسم الصيهود).
3) المياه الجوفية.

نهر دجلة:
• ينبع من المرتفعات جنوب شرق تركيا، طوله الكلي نحو 1900 كم. يتكون من التقاء منبع غربي (بطمان صو) ومنبع شرقي (بوتان صو).
• يدخل العراق عند قرية فيشخابور، وأول رافد الخابور. الروافد: الزاب الكبير (جنوب الموصل، ينبع من تركيا، يسهم بنحو 33% من مياه دجلة)، الزاب الصغير (جنوب الشرقاط، ينبع من إيران، 17%)، العظيم (عند الضلوعية، ينبع من داخل العراق، وهو الرافد الوحيد الذي منبعه داخل العراق)، ديالى (جنوب بغداد، منبعاه سيروان وتانجرو).
• يدخل السهل الرسوبي عند بلد. تكثر تعرجاته بين شمال بغداد والكوت لقلة الانحدار وبطء الجريان فتزداد الترسبات والجزر.
• تفرعاته: عند سدة الكوت: الغراف والدجيلة (من اليمنى). عند العمارة: البتيرة والمجر الكبير (اليمنى)، والمشرح والكحلاء (اليسرى). ويلتقي بالفرات عند القرنة.
• بدأت تركيا بناء سدود على دجلة (مشروع الغاب) وآخرها سد إليسو (2018)، فانخفضت المناسيب.

نهر الفرات:
• ثاني أطول نهر عربي بعد النيل. ينبع من المرتفعات الشرقية في تركيا من (فرات صو) و(مراد صو) ويلتقيان عند كيبان. يدخل سوريا قرب جرابلس، ثم العراق عند حصيبة في القائم.
• يخترق الهضبة الغربية بمجرى عميق، وفيه النواعير (هيت)، ويدخل السهل الرسوبي عند الرمادي، ويقترب من دجلة عند الفلوجة (40 كم).
• عند سدة الهندية يتفرع إلى شط الحلة (ثم الدغارة والديوانية) وشط الهندية (ثم الكوفة والشامية، يلتقيان عند الشنافية، ثم العطشان والسبيل).
• قرب سوق الشيوخ يتفرع إلى ذنائب الفرات وتنتهي بهور الحمار.
• طوله من التقاء رافديه حتى مصبه في شط العرب نحو 2940 كم. ولا روافد له داخل العراق.

شط العرب: بين القرنة والخليج العربي، من التقاء دجلة والفرات، طوله 190 كم، وعرضه أكثر من 2 كم عند المصب ونحو 1 كم عند البصرة. يصب فيه الكارون (من إيران) ويرسب الطمي فيعرقل الملاحة، ويتأثر بالمد والجزر مرتين يومياً.

الأهوار والمستنقعات: أكثر من 20000 كم²، وتقسم إلى:
• الكبيرة (نحو 8750 كم²: البصرة وميسان وذي قار): الأهوار الوسطى (القرنة، 3235 كم²، تتغذى من دجلة عبر البتيرة والمجر الكبير)، هور الحويزة (2450 كم²، ميسان والبصرة)، هور الحمار (البصرة وذي قار).
• الصغيرة: الشويجة والدلمج (واسط)، ابن نجم (الديوانية)، أبو دبس (كربلاء)، والسنية والسعدية وعودة والشامية بين النهرين.
• جُففت في الثمانينات والتسعينات فاختفت تقريباً، ما سبب القضاء على الثروات ونزوح السكان والتصحر، وأُعيد إغمارها منذ 2003. وفي 17 تموز 2016 وضعتها اليونسكو في قائمة التراث العالمي.

مشاريع السيطرة والخزن: بحيرات طبيعية واصطناعية وسدود ونواظم. أهميتها: مخزون مائي في الجفاف، تنظيم الجريان وتقليل الفيضانات، توليد الكهرباء، السياحة.
• على دجلة وروافده: سد وخزان الثرثار (الأكبر، سعته 85 مليار م³، يُحوَّل إليه الماء عبر سدة سامراء، طول البحيرة 120 كم وعرضها 40 كم)، سد وبحيرة الموصل (11 مليار م³)، دوكان (على الزاب الصغير، 6.8)، دربندخان (على ديالى، 3.25)، حمرين (على ديالى، 3.95)، العظيم (1.5)، وسدات: سامراء (صلاح الدين)، الكوت (واسط)، دبس (الزاب الصغير، كركوك)، العمارة (ميسان)، ديالى (ديالى).
• على الفرات: سد وبحيرة حديثة (8 مليار م³)، الحبانية (3.3 مليار م³، تتصل بالرزازة)، وسدات: الرمادي (الأنبار)، الهندية (بابل)، الكوفة (النجف).

المياه الجوفية: المياه في باطن الأرض تظهر طبيعياً (ينابيع وعيون) أو بالآبار. تغزر في المنطقة الجبلية، وتقل ويسوء نوعها في الوسط والجنوب (الحرارة والتبخر وقلة الأمطار وزيادة الأملاح). أهميتها في المناخ الصحراوي لتعويض النقص، وتتركز السكان حولها (واحات كبيسة والرحالية وعين التمر).'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• التضاريس: الأشكال السطحية التي تتكون منها القشرة الأرضية من جبال وتلال وهضاب وسهول.
• الطقس: حالة الجو لمكان محدد لمدة قصيرة. المناخ: وصف حالة الجو لمكان محدد لمدة طويلة.
• الإقليم: منطقة محددة على سطح الأرض لها خصائص طبيعية أو بشرية تختلف عن المناطق المجاورة.
• المناخ القاري: مناخ يتباين فيه الليل والنهار والصيف والشتاء تبايناً كبيراً.
• الأمطار التضاريسية: أمطار تسقط عندما تصعد الرياح الرطبة فوق الجبال فتقل حرارتها وتتكاثف رطوبتها.
• النبات الطبيعي: النبات الذي ينمو دون تدخل الإنسان.
• النباتات الحولية: نباتات فصلية تنمو خلال الموسم الملائم لنموها (الخباز والحلبة والبابونك).
• النباتات المعمرة: نباتات دائمة كيّفت نفسها لمقاومة الجفاف والحرارة (الأثل والسدر والشوك).
• المياه السطحية: المياه الجارية على سطح الأرض.
• المياه الجوفية: المياه الموجودة في باطن الأرض.
• موسم الفيضان: الربيع. موسم الصيهود: الصيف.
• الأهوار: مسطحات مائية تغطي الأراضي المنخفضة في جنوب السهل الرسوبي.

التعاليل:
• لموقع العراق الاستراتيجي أهمية كبيرة: لثرواته المتنوعة، وإشرافه على الهلال الخصيب، ووقوعه ضمن الجسر الأرضي بين قارات العالم القديم وعلى أقصر الطرق بين المحيط الهندي والمتوسط، ومرور خطوط الملاحة الجوية.
• تعد المنطقة الجبلية أحد أهم المصادر المائية: لتراكم الثلوج على قممها ووفرة أمطارها (أكثر من 1000 ملم) وفيها روافد دجلة.
• يعاني السهل الرسوبي صعوبة في تصريف المياه: لقلة انحداره وانبساط أراضيه.
• تتعرض الهضبة الصحراوية لتعرية شديدة: لجفافها وفقر غطائها النباتي.
• اتساع المدى الحراري اليومي في العراق: لقلة الأمطار وجفاف الجو وسيادة المناخ القاري.
• ضعف تأثير المسطحات المائية (قزوين والأسود): لبعدها ولوجود السلاسل الجبلية التي تعترض طريقها.
• يعد الموقع الفلكي من أكثر العوامل تأثيراً في المناخ: لأنه يحدد زاوية سقوط الشمس وطول النهار.
• انعدام الأمطار صيفاً: بسبب سيادة الضغط العالي المداري وقلة الرطوبة النسبية.
• تتباين النباتات الطبيعية: بسبب تباين الأقاليم المناخية والتضاريس وكمية الأمطار.
• تباين الأمطار بين الشمال والوسط والجنوب: لتأثير التضاريس وامتداد السلاسل الجبلية.
• انخفاض الحرارة في الجبال: لارتفاعها عن مستوى سطح البحر.
• نباتات الأهوار دائمة الخضرة: لوفرة المياه طوال السنة.
• يتميز نهر دجلة بتعرجاته شمال بغداد إلى الكوت: لقلة انحدار الأرض وبطء الجريان.
• الزاب الكبير أهم روافد دجلة: لأنه يسهم بنحو 33% من مياهه.
• للمياه الجوفية أهمية في المناخ الصحراوي: لأنها تعوض نقص الأمطار والمياه السطحية.
• أهمية مياه البحيرات: توفير مخزون مائي، وتنظيم الجريان، وتقليل الفيضان، وتوليد الكهرباء، والسياحة.
• جميع روافد دجلة من الشرق: لأن المرتفعات الجبلية في الشرق (إيران والجبال) تغذي هذه الروافد.'''),
    Section('أرقام للحفظ', Icons.calculate, '''المساحة والحدود:
• مساحة العراق: 435,052 كم².
• الحدود البرية: 3462 كم. البحرية: 60 كم.
• نسب الحدود: إيران 37.5% ، السعودية 23.5% ، سوريا 17.4% ، تركيا 11% ، الكويت 5.6% ، الأردن 5%.
• ترتيب الحدود تصاعدياً: الأردن (5%) ← الكويت (5.6%) ← تركيا (11%) ← سوريا (17.4%) ← السعودية (23.5%) ← إيران (37.5%).
• الموقع الفلكي: عرض 29° – 37° شمالاً ، طول 38° – 48° شرقاً.

نسب التضاريس من مساحة العراق:
• الجبلية: 6%
• شبه الجبلية (المتموجة): 15%
• السهل الرسوبي: 24%
• الهضبة الصحراوية الغربية: 55% (270000 كم²)

الارتفاعات:
• الجبال العالية: 2100 – 3600 م (هلكرد أعلى قمة أكثر من 3600 م).
• الجبال قليلة الارتفاع: 1400 – 2100 م.
• المنطقة شبه الجبلية: 200 – 1000 م.
• الهضبة الصحراوية: 300 – 900 م.
• السهل الرسوبي: من 0 جنوباً إلى 100 م شمالاً.

الأقاليم المناخية:
• البحر المتوسط: أمطار 750 – 1000 ملم، صيف 30 – 35 °م.
• السهوب: أمطار أكثر من 300 ملم، صيف 38 – 40 °م.
• الصحراوي: أمطار 50 – 200 ملم، صيف 44 – 48 °م.

النبات: السهوب 15% ، الصحراوي 70% من المساحة.

الأنهار:
• دجلة: 1900 كم (كلي). الفرات: 2940 كم (من التقاء الرافدين إلى المصب). شط العرب: 190 كم.
• الزاب الكبير 33% ، الزاب الصغير 17% من مياه دجلة.
• الأهوار: أكثر من 20000 كم². الكبيرة 8750 كم². الأهوار الوسطى 3235 كم². الحويزة 2450 كم².

سعات الخزن (مليار م³): الثرثار 85 ، الموصل 11 ، حديثة 8 ، دوكان 6.8 ، حمرين 3.95 ، دربندخان 3.25 ، الحبانية 3.3 ، العظيم 1.5.

الفصول والجو: نهار الصيف 14 ساعة ، نهار الشتاء 10 ساعات. معظم الأمطار من تشرين الثاني إلى نيسان.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أجوبة أسئلة الفراغات (من الكتاب):
• مساحة العراق: 435,052 كم². يقع في الجزء الجنوبي الغربي من آسيا والجزء الشمالي الشرقي من العالم العربي.
• الموقع الفلكي: خطا طول 38° و48° شرقاً ودائرتا عرض 29° و37° شمالاً.
• الحدود البرية نحو 3462 كم والبحرية نحو 60 كم.
• يحد العراق شمالاً تركيا، وشرقاً إيران، وغرباً سوريا والأردن والسعودية.
• المنطقة المتموجة 15% من المساحة. أعلى قمة: جبل هلكرد (حصاروست).
• هضاب المنطقة الجبلية: بنجوين وبشدر وجوارته. تلال المتموجة: حمرين ومكحول. وديان الهضبة: حوران والأبيض.
• أوسع الأقاليم المناخية: الصحراوي. مناخ السهوب انتقالي بين مناخ البحر المتوسط شمالاً والصحراوي جنوباً.
• النباتات الصحراوية نحو 70%: حولية ومعمرة. المنخفضات الجوية من البحر المتوسط.
• رافد دجلة الوحيد من داخل العراق: العظيم. شط الهندية يتفرع إلى شط الكوفة وشط الشامية.
• على دجلة: الثرثار والموصل ودوكان ودربندخان وحمرين والعظيم وسدات سامراء والكوت وغيرها.

صح أم خطأ (مع التصحيح):
• البحر الأحمر من أكثر البحار تأثيراً في مناخ العراق: خطأ، تأثيره محدود (والمتوسط أكثر تأثيراً).
• يكثر سقوط الأمطار صيفاً: خطأ، تسقط في الشتاء وتنعدم صيفاً.
• نباتات السهوب 25%: خطأ، 15%.
• إقليم البحر المتوسط في السهل الرسوبي: خطأ، في المنطقة الجبلية.
• الرياح الجنوبية الغربية تلطف الحرارة: خطأ، الشمالية الغربية هي التي تلطف.
• دوكان على الزاب الكبير: خطأ، على الزاب الصغير.
• دجلة والفرات يكونان شط العرب عند الناصرية: خطأ، عند القرنة.
• الأهوار الكبيرة في واسط والمثنى: خطأ، البصرة وميسان وذي قار.
• سدة سامراء على الفرات: خطأ، على دجلة.
• سدة ديالى على الزاب الصغير: خطأ، على رافد ديالى.

أسئلة للمراجعة:
1) حدد الموقع الجغرافي والفلكي للعراق وأهميته.
2) تكلم عن الأهوار والمستنقعات وفوائدها.
3) اذكر أقسام المنطقة شبه الجبلية مع أمثلة.
4) كيف تكوّن السهل الرسوبي؟
5) وضّح سلسلتي المنطقة الجبلية مع الأمثلة.
6) صف حدود الدول المحيطة بالعراق مع نسبها.
7) تكلم عن شكل العراق ومزاياه.
8) حدد حدود الهضبة الصحراوية الغربية.
9) عدد نطاقات النبات الطبيعي والأقاليم المناخية.
10) بيّن فوائد النبات الطبيعي ونباتات الأهوار.
11) عدد مشاريع السيطرة والخزن على دجلة وعلى الفرات.
12) ما الفرق بين السد والسدة؟
13) ارسم خريطة العراق وحدد عليها (حصاروست، هلكرد، حمرين، مقلوب، وادي حوران، سهل الحويجة...) والأقاليم المناخية ودجلة وروافده والفرات.'''),
  ]),
  Chapter('الفصل الثاني: الخصائص البشرية لجغرافية العراق', [
    Section('الملخص', Icons.notes, '''أولاً: السكان
1) نمو السكان: التغير في حجم السكان زيادة أو نقصاناً خلال مدة محددة، ويعتمد على ثلاثة عوامل: الولادات والوفيات والهجرة.
• بلغ عدد السكان عام 1957 نحو 6,339,960 نسمة بمعدل نمو 2.7%، وارتفع إلى 39,127,889 نسمة عام 2019 بمعدل 2.6%. سبب الارتفاع: ارتفاع الخصوبة وتحسن الأوضاع الاقتصادية والصحية والمعيشية.
• جدول السكان (نسمة ومعدل النمو): 1947: 4,816,185 — 1957: 6,339,960 (2.7%) — 1965: 8,097,230 (3%) — 1977: 12,000,497 (3.2%) — 1987: 16,335,199 (3%) — 1997: 22,026,244 (3%) — 2019: 39,127,889 (2.6%).

2) توزيع السكان: تتحكم فيه العوامل الآتية:
أ) الطبيعية: التضاريس والمناخ والموارد المائية. يفضل السكان السهول (سهولة التنقل والتربة الخصبة والزراعة). السهل الرسوبي (الفيضي) في الوسط والجنوب أكثر المناطق سكاناً: نحو ثلثي السكان. في الشمال يتوزع السكان على سهول المنطقة المتموجة والجبلية، وفي الهضبة الغربية حول الواحات ومراكز الوحدات الإدارية. يتركز أغلب السكان قرب دجلة والفرات، وسكان الهضبة على المياه الجوفية والأمطار.
ب) الاقتصادية: تحدد استعمالات الأرض: الزراعة تجذب السكان حول النهرين، والمناطق الصناعية ترتفع فيها الكثافة (بغداد والموصل)، والنفط يحول مناطقه إلى مراكز استقرار (البصرة وكركوك ونينوى وميسان)، والمنافذ التجارية وطرق النقل.
جـ) الإدارية والدينية: مراكز المدن الإدارية تجذب السكان (فرص العمل)، والمراقد الدينية المقدسة (النجف وكربلاء وسامراء والكاظمية) تجذب الزوار والمستقرين فيزداد النشاط التجاري والعمران.
د) التاريخية: يتناسب عدد السكان طردياً مع قدم الاستيطان، فالقرى الزراعية على دجلة والفرات كانت النواة الأولى لمدن الموصل وسامراء وبغداد والبصرة.
• بحسب الخريطة (15) توزعت المحافظات على خمسة نطاقات سكانية، وجاءت بغداد أولى في عدد السكان، وأقلها المثنى وميسان وكربلاء.

3) تركيب السكان: دراسة خصائص السكان من حيث النوع والعمر وحجم الأسرة والحالة الزوجية والتعليم.
أ) التركيب العمري: وصف الحالة العمرية للمجتمع وتقسيمها إلى فئات (لكل سنة أو خمس سنوات). أهميته: التخطيط المستقبلي للتعليم والعمل والصحة والسكن (فئة 6 – 18 سنة تحدد حاجة الكتب والمقاعد والمدرسين)، ووصف المجتمع فتياً أم كهلاً (نسبة القوى العاملة والأطفال والشيوخ). تميز تركيب العراق عام 2019 بفتوة عالية تدل عليها القاعدة العريضة للهرم السكاني لارتفاع الخصوبة وتحسن المعيشة.
ب) التركيب النوعي: تقسيم السكان إلى ذكور وإناث وإيجاد النسبة بينهما (عدد الذكور إلى كل مئة من الإناث). أهميته: حجم القوة العاملة ومعدلات الخصوبة والوفيات واتجاه النمو والمشكلات الناجمة عن زيادة أحد الجنسين. تقل نسبة الذكور في الحالات غير الطبيعية لتعرضهم لمخاطر العمل والحروب أكثر من الإناث.
جـ) التركيب البيئي: توزيع السكان بين الحضر (سكان المدن: تجارة وصناعة، 27,338,005 نسمة عام 2019) والريف (زراعة وتربية حيوانات، 11,789,884 نسمة). سبب قلة سكان الريف: الهجرة إلى المدن لتوفر الخدمات وأسباب اقتصادية وسياسية واجتماعية.

4) كثافة السكان: عدد السكان ÷ مساحة الدولة. كثافة العراق العامة نحو 90 نسمة/كم² (435,052 كم² و39,127,889 نسمة)، ولا تعكس الحقيقة لعدم توزع السكان بالتساوي (مساحات شبه خالية كالهضبة الغربية وبادية الجزيرة).

5) الحركة المكانية (الهجرة): الانتقال الجغرافي للسكان من مكان لآخر بصرف النظر عن الأسباب والمسافة. من أهم نتائجها تغير التركيب النوعي والعمري (يهاجر الذكور الشباب فتقل الأيدي العاملة).
• نوعاها: الهجرة الداخلية (داخل حدود الدولة) والخارجية (خارج الحدود السياسية).
• أسبابها: اقتصادية (البطالة وقلة العمل وأهمها)، اجتماعية وسياسية (النزاعات والتهجير القسري والنزوح)، خدمية (قلة الخدمات التعليمية والصحية والترفيهية في الريف).

ثانياً: الزراعة
• العراق النواة الأولى للزراعة (بلاد ما بين النهرين، بلاد الرافدين، أرض السواد). أسباب نجاحها: الأراضي الصالحة والتربة الخصبة والمناخ الملائم والموارد المائية والأيدي العاملة.
• أهميتها: تحقق الأمن الغذائي، مصدر دخل للفلاحين، أعلاف للثروة الحيوانية، مواد أولية للصناعة، تسهم في الدخل الوطني بعد النفط.
• المحاصيل ثلاثة أقسام: غذائية وصناعية وعلف.

1) المحاصيل الغذائية:
• الحبوب: 
- القمح والشعير: شتويان، في منطقتين: المطرية (الديمية) في سهول الشمال (هضبة الجزيرة جنوب سنجار، السندي، سهل أربيل، هضبة كركوك، سهل شهرزور): إنتاج القمح 947 ألف طن (2019). والإروائية: ضفاف دجلة والفرات والفرات الأوسط: القمح 3396 ألف طن. تجود الزراعة في التربة المزيجية الجيدة الصرف ووفرة المياه. المرتبة الأولى بالقمح: نينوى ثم ديالى ثم واسط، وبالشعير: نينوى ثم القادسية.
- الرز: محصول صيفي يحتاج مياهاً وفيرة وحرارة مرتفعة وخبرة، فاقتصر على السهل الرسوبي الإروائي (الوسط والجنوب). 21 ألف دونم و18 ألف طن (2018)، وأولى المحافظات النجف ثم القادسية. مناطقه: الكوفة والشامية، جنوب الغراف، بين علي الغربي والقرنة. أنواعه: العنبر (الفرات الأوسط: الشامية والمشخاب)، النعيمة والحويزاوي (ميسان وذي قار)، النكازه (الشمال).
- الذرة الصفراء: صيفي، غذاء وزيوت وعلف، 55 ألف دونم و63 ألف طن، المرتبة الأولى كركوك ثم صلاح الدين. ومحاصيل أخرى: العدس والماش والباقلاء والحمص.
• المحاصيل الزيتية: زهرة الشمس (بغداد وبابل)، السمسم (بغداد والقادسية والأنبار وبابل)، فستق الحقل (ديالى)، ومنها فول الصويا والكتان والدخن.
• الخضروات: قرب المدن، صيفية وشتوية، والزراعة المحمية (المغطاة) ساعدت على زراعتها في غير موسمها، والإنتاج لا يكفي للاستهلاك فيُستورد (الطماطة والباميا والباذنجان وغيرها).
• الفواكه: في المنطقة الوسطى (مناخ وتربة وماء وأيدٍ عاملة وسوق). الحمضيات: البرتقال والنارنج واليوسفي والليمون والكريب فروت.
• النخيل: من أهم المحاصيل ونقدي، في السهل الرسوبي حول الأنهار. 15,139,076 نخلة (2018) وإنتاج 646 ألف طن، الأولى بغداد ثم بابل ثم كربلاء. 
• مشكلات النخيل: الرياح الجافة صيفاً، الآفات (الدوباس)، رواسب الأنهار والمد والجزر وارتفاع الأملاح (شط العرب)، هجرة المزارعين، مشكلات تسويق التمور، التوسع الحضري على حساب البساتين.

2) المحاصيل الصناعية: القطن (نسيج وزيوت وعلف)، التبغ (السليمانية) والتنباك (الوسط والجنوب)، البنجر وقصب السكر (صناعة السكر).
3) محاصيل العلف: الجت والبرسيم والتبن وبعض سيقان الذرة والسمسم والقصب.

ثالثاً: الثروة الحيوانية
• أهميتها: غذاء (لحوم وحليب وبيض)، مواد أولية للصناعة (جلود وأصواف وشعر)، دخل قومي وإضافي للمزارعين، أسمدة عضوية، وسائط نقل في الصحراء والجبال. تتنوع: أغنام وماعز وأبقار وجاموس وجمال ودواجن وأسماك ونحل، وتتركز في المنطقة المتموجة وهضبة الجزيرة.

مشاكل القطاع الزراعي والحيواني:
1) الطرائق التقليدية وقلة التكنولوجيا الحديثة (المكننة والمبيدات والأسمدة والبذور المحسنة).
2) قلة التخصيصات الاستثمارية.
3) ضعف القدرة التنافسية أمام المستورد (ارتفاع التكاليف).
4) ضعف الإمكانات المالية والفنية والتسويقية للقطاع الخاص.
5) التملح والتغدق: 75% من الأراضي المروية تعاني الملوحة (سوء التشغيل وانعدام شبكة البزل).
6) شحة المياه بسبب سدود الدول المجاورة.
7) تدني الإنتاج الحيواني (علاجه بزراعة العلف وتوفير الأطباء ومكافحة الأمراض ومنع الصيد الجائر والعناية بالمحميات).

رابعاً: الثروات المعدنية والصناعة
• اعتمد الاقتصاد قديماً على الزراعة والتجارة، واليوم على الثروات المعدنية (النفط والغاز ثم الكبريت والفوسفات). الصناعات الاستخراجية: استخراج المواد الخام من باطن الأرض.

1) النفط الخام (الذهب الأسود): أصله بقايا كائنات حية دُفنت بطبقات الرمل والطين وتحولت بالضغط والحرارة والبكتريا إلى سائل أسود، وتجمع في مكامن بفعل الالتواءات والانكسارات (حقول النفط).
• حقول النفط في ثلاث مناطق:
- الشمالية: نينوى (عين زالة وبطمة والكيارة)، كركوك (بابا كركر وباي حسن وجمبور وخباز)، صلاح الدين (تكريت وعجيل وبلد)، إقليم كردستان (طق طق وطاوكي وخورماله).
- الوسطى: شرقي بغداد (بغداد)، نفط خانة (ديالى)، بدرة والأحدب (واسط).
- الجنوبية: البصرة (الرميلة الشمالي والجنوبي، مجنون، غرب القرنة، الزبير)، ميسان (بزركان وأبو غراب والحلفاية والفكة)، ذي قار (الناصرية والغراف والرافدين).
• الاحتياطي المؤكد 147 مليار برميل (10% من العالمي): الخامس عالمياً والثاني عربياً بعد السعودية. متوسط الإنتاج 2019 أكثر من 4 ملايين برميل يومياً.
• أوبك (OPEC) أسست في بغداد عام 1960. أوابك (OAPEC) منظمة عربية أُسست في بيروت عام 1968.
• طرق نقل النفط: 
أ) الأنابيب: إلى الخليج العربي (ثلاثة أنابيب من الحقول الجنوبية إلى موانئ الفاو والبصرة والعمية والعميق)، إلى البحر المتوسط عبر الخط التركي إلى ميناء جيهان (بديل للخط العراقي السوري إلى بانياس وطرابلس)، والخط العراقي السعودي إلى ينبع (متوقف). والخط الاستراتيجي يربط الحقول الجنوبية بالشمالية (كركوك إلى حديثة ومنها للمتوسط أو للخليج).
ب) السفن: ناقلات النفط أفضل الوسائل لإيصاله إلى أماكن الاستهلاك البعيدة.
جـ) النقل البري: قاطرات السكك الحديد والسيارات الحوضية (التانكرات).
• المصافي: الدورة (بغداد، 165 ألف برميل/يوم، من كركوك)، بيجي (صلاح الدين، 310 ألف، من كركوك)، البصرة (210 ألف، من الرميلة)، وأخرى صغيرة (الوند في ديالى، كركوك، حديثة، الموصل، الناصرية، النجف).

2) الغاز الطبيعي: الوقود الأنظف وأقل إصداراً للملوثات، ومادة أولية للبتروكيمياويات، وأهم مصادر الطاقة البديلة للنفط. حقوله: كور مور (السليمانية)، خشم الأحمر والمنصورية (ديالى)، السيبة (البصرة)، عكاس (الأنبار). الاحتياطي 3744 مليار م³: الخامس عربياً (6% من العربي) والعاشر عالمياً (1.9%). يُحرق جزء كبير منه هدراً لأنه مصاحب لاستخراج النفط.

3) الكبريت الحر: نينوى وصلاح الدين من جنوب الموصل (المشراق والفتحة). الاحتياطي نحو 600 مليون طن والإنتاج نحو مليون طن سنوياً. يستعمل في الثقاب والمفرقعات ومعادلة قلوية التربة وتحضير حامض الكبريتيك والأصباغ والدهانات والورق والمنسوجات.
4) الفوسفات: الصحراء الغربية (الأنبار) في عكاشات بين القائم والرطبة. الاحتياطي أكثر من 10 مليار طن والإنتاج نحو مليوني طن سنوياً. يستعمل لتحضير الفسفور وحامض الفسفوريك ومعظمه لصناعة الأسمدة.
5) معادن أخرى: القار والملح والكلس والرخام والجص والرمال (الأنبار والنجف وكربلاء والمثنى والبصرة)، وفي الشمال الحديد والمنغنيز والرصاص والخارصين والكروم والنيكل والمرمر.

الصناعات التحويلية: تحويل المواد الأولية إلى منتجات وسيطة أو نهائية:
1) الغذائية: الزيوت (بغداد وميسان وبابل)، السكر (نينوى والسليمانية وميسان وبابل)، الألبان (بغداد والمثنى وأربيل ونينوى والبصرة)، التعليب (كربلاء وديالى وأربيل ودهوك).
2) النسيجية والجلود: غزل ونسيج قطني (بغداد ونينوى وواسط)، صوفي (بغداد وذي قار وأربيل)، حريري (بابل)، الملابس والسجاد والجلود (معظم المحافظات).
3) الإنشائية: الإسمنت (بغداد ونينوى والسليمانية وبابل وكربلاء والنجف والأنبار والمثنى)، الطابوق (معظم المحافظات).
4) الكيمياوية: تكرير النفط والغاز والبتروكيماويات (بغداد وكركوك والبصرة)، الأدوية (صلاح الدين وبغداد ونينوى)، الزجاج (الأنبار)، الورق (بغداد وميسان والبصرة).
5) المعدنية الأساسية: الحديد والصلب والألمنيوم (البصرة وذي قار)، تجميع السيارات (بابل)، الأثاث المنزلي (بغداد)، الكهربائية (بغداد وديالى وذي قار).

خامساً: النقل والمواصلات
1) البرية: طرق السيارات (بغداد نواة الطرق، وترتبط بدول الجوار الأردن وسوريا والكويت عبر منافذ حدودية) والسكك الحديد (أول قطار 1914، رخيصة ولا تتأثر بالطقس، سلبيتها عدم المرونة).
2) الجوية: المطارات الدولية: بغداد، الموصل، البصرة، أربيل، السليمانية، النجف الأشرف. وصغيرة (الناصرية وكربلاء ودهوك).
3) المائية: أسهل وأرخص وسائط النقل. 
• النهري الداخلي: دجلة والفرات وشط العرب. تواجهه صعوبات: قلة المناسيب صيفاً والجزر النهرية.
• البحري الخارجي: الخليج العربي (ساحل 60 كم) وشط العرب. موانئ شط العرب: أبو فلوس (أبو الخصيب)، المعقل (يبعد 135 كم عن الخليج). موانئ الخليج: الفاو وخور الزبير وأم قصر (أهم الموانئ التجارية).

سادساً: النشاط التجاري
• التجارة: نقل السلع والخدمات من منطقة إلى أخرى.
1) التجارة الداخلية: عوامل نشاطها: الموقع الجغرافي (بغداد والبصرة والموصل وميسان وأربيل)، تخصص المنتجات (التمور: البصرة وكربلاء، الحمضيات: بغداد وديالى، الحبوب: نينوى وواسط وكركوك)، تباين توزيع السكان.
2) التجارة الخارجية: تتركز صادراتها في النفط الخام فيوصف الاقتصاد العراقي بأنه أحادي الجانب. خصائصها: تنوع السلع، انفتاح على العالم، اختلال الميزان التجاري (قلة الصادرات أمام الواردات).

سابعاً: السياحة والاصطياف
• السياحة: حركة السكان لمدة من يوم إلى سنة لقضاء وقت الفراغ أو التسوق أو التجارة أو العلاج أو الزيارات الدينية أو استكشاف الإرث الحضاري. الاصطياف: زيارة الأماكن السياحية.
1) البيئية: الأماكن الطبيعية (شلالات الشمال مثل كلي علي بك في أربيل، الجبال والبحيرات، ضفاف دجلة والفرات، الأهوار).
2) الأثرية: العراق مهد الحضارات: برج بابل وبوابة عشتار (بابل)، زقورة أور (ذي قار)، الوركاء (المثنى)، نفر (الديوانية)، الحضر (نينوى)، الملوية (سامراء)، طاق كسرى والمدرسة المستنصرية (بغداد).
3) الدينية: الكنائس والأديرة والأضرحة ومراقد الأئمة والأولياء (النجف وكربلاء وبغداد وسامراء والبصرة والموصل).
• أهميتها: اقتصادية (عملات صعبة)، ثقافية (تعارف الشعوب)، ترفيهية (تنشيط الصناعات الشعبية)، إعلامية.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• نمو السكان: التغير في حجم السكان زيادة أو نقصاناً خلال مدة محددة.
• التركيب العمري: وصف الحالة العمرية للسكان وتقسيمهم إلى فئات عمرية.
• التركيب النوعي: تقسيم السكان إلى ذكور وإناث وإيجاد النسبة بينهما.
• التوزيع البيئي (التركيب البيئي): توزيع السكان بين الحضر والريف.
• كثافة السكان: عدد السكان مقسوماً على مساحة الدولة.
• الحركة المكانية (الهجرة): الانتقال الجغرافي للسكان من مكان لآخر بصرف النظر عن الأسباب والمسافة.
• الزراعة المحمية: الزراعة في بيوت مغطاة تمكن من زراعة الخضروات في غير مواسمها.
• المحاصيل الزيتية: محاصيل تدخل في صناعة الزيوت النباتية وهي غذاء للسكان (زهرة الشمس والسمسم).
• العنبر: نوع من الرز تكثر زراعته في الفرات الأوسط (الشامية والمشخاب).
• الصناعات الاستخراجية: استخراج المواد الخام من باطن الأرض (النفط والغاز والمعادن).
• الصناعات التحويلية: صناعات تقتصر على تحويل المواد الأولية إلى منتجات وسيطة أو نهائية.
• الخط الاستراتيجي: منظومة لتصدير النفط الخام تربط الحقول الجنوبية بالشمالية.
• بابا كركر: حقل نفطي في محافظة كركوك.
• عكاشات: منطقة الفوسفات في الصحراء الغربية (الأنبار) بين القائم والرطبة.
• المشراق: منطقة الكبريت جنوب الموصل.
• ميناء أبو فلوس: ميناء في شط العرب في أبو الخصيب بالبصرة. ميناء أم قصر: ميناء على الخليج العربي.
• التجارة: عملية نقل السلع والخدمات من منطقة إلى أخرى.
• التجارة الخارجية: تبادل المنتجات بين العراق ودول أخرى.
• النقل المائي: أسهل وأرخص وسائط النقل (نهري وبحري).
• السياحة: حركة السكان لمدة من يوم إلى سنة لأغراض متعددة. الاصطياف: زيارة الأماكن السياحية.
• السياحة الدينية: زيارة المراقد والأضرحة والكنائس والأديرة. البيئية: الأماكن الطبيعية. الأثرية: المواقع الأثرية.

التعاليل:
• لدراسة التركيب العمري أهمية كبيرة: للتخطيط المستقبلي للتعليم والعمل والصحة والسكن ولمعرفة المجتمع فتياً أم كهلاً.
• الحركة المكانية من أبرز مشكلات المجتمعات: لنتائجها الديموغرافية في تركيب السكان النوعي والعمري وتوزيعهم وكثافتهم.
• تباين مناطق زراعة القمح والشعير في المروية: لاختلاف نوعية التربة وكمية المياه.
• الكثافة العامة لا تعكس الحقيقة: لعدم توزع السكان بالتساوي ووجود مساحات شبه خالية (الهضبة الغربية وبادية الجزيرة).
• انخفاض عدد الذكور عن الإناث في الحالات غير الطبيعية: لتعرض الذكور لمخاطر العمل والمهن والحروب أكثر من الإناث.
• إنتاج الخضروات لا يكفي للحاجة المحلية: لأنه لا يتناسب مع النمو السكاني وارتفاع المستوى المعيشي في المدن.
• للقطن استعمالات متعددة: مادة أولية للمنسوجات القطنية وبذوره للزيوت وعلف للحيوانات.
• للمد والجزر تأثير سلبي في النخيل: لارتفاع نسبة الأملاح في المياه.
• ارتفاع النمو السكاني في العراق: لارتفاع الخصوبة وتحسن الأوضاع الاقتصادية والصحية والمعيشية.
• لدراسة التركيب النوعي أهمية: للتعرف على حجم القوة العاملة ومعدلات الخصوبة والوفيات واتجاه النمو والمشكلات.
• تتركز زراعة الرز في السهل الرسوبي الإروائي: لحاجته إلى مياه وفيرة وحرارة مرتفعة.
• تزرع الخضروات قرب المدن: لقرب الأسواق وسهولة النقل وحاجة السكان اليومية.
• تطور طرق النقل الجوية: لموقع العراق الاستراتيجي ومناخه الجاف وسمائه الصافية.
• النقل المائي أسهل وأرخص: لانخفاض تكاليفه وقدرته على استيعاب الشحنات الكبيرة وعدم حاجته لصيانة الطرق.
• لسكك الحديد أهمية: رخيصة ولا تخضع لقواعد المرور ولا تتأثر بتقلبات الطقس.
• يتمتع العراق بمقومات السياحة البيئية: لوجود الشلالات والجبال والبحيرات في الشمال والأنهار والأهوار في الجنوب.
• للسياحة أهمية اقتصادية: لما توفره من عملات صعبة.
• العراق مهد الحضارات: لكثرة الآثار والحضارات (السومرية والبابلية والآشورية والإسلامية).
• يوصف الاقتصاد العراقي بأحادي الجانب: لاعتماده على سلعة واحدة هي النفط الخام.
• تتركز السياحة الدينية في النجف وكربلاء: لوجود المراقد المقدسة.'''),
    Section('أرقام للحفظ', Icons.calculate, '''السكان:
• 1947: 4,816,185 — 1957: 6,339,960 — 1965: 8,097,230 — 1977: 12,000,497 — 1987: 16,335,199 — 1997: 22,026,244 — 2019: 39,127,889.
• معدل النمو: 2.7% (1957) ← 3% ← 3.2% (1977) ← 3% ← 3% ← 2.6% (2019).
• الحضر 27,338,005 نسمة، الريف 11,789,884 نسمة (2019).
• كثافة السكان العامة: 90 نسمة/كم² (المساحة 435,052 كم²).
• السهل الرسوبي يضم نحو ثلثي السكان. بغداد الأولى بالسكان، وأقلها المثنى وميسان وكربلاء.

الزراعة (إنتاج):
• القمح (2019): المطري 947 ألف طن، الإروائي 3396 ألف طن. أولى المحافظات: نينوى ثم ديالى ثم واسط.
• الشعير: الأولى نينوى ثم القادسية.
• الرز (2018): 21 ألف دونم و18 ألف طن. الأولى النجف ثم القادسية.
• الذرة (2018): 55 ألف دونم و63 ألف طن. الأولى كركوك ثم صلاح الدين.
• زهرة الشمس: 135 دونماً و69 طناً. السمسم: 889 دونماً و198 طناً. فستق الحقل: 2518 دونماً و1503 أطنان (2018).
• النخيل: 15,139,076 نخلة، إنتاج 646 ألف طن (2018). الأولى بغداد ثم بابل ثم كربلاء.
• الأراضي المروية المتأثرة بالملوحة: 75%.

النفط والغاز والمعادن:
• احتياطي النفط 147 مليار برميل (10% من العالمي): الخامس عالمياً والثاني عربياً. الإنتاج أكثر من 4 ملايين برميل/يوم (2019).
• أوبك: بغداد 1960. أوابك: بيروت 1968.
• المصافي: الدورة 165 ألف برميل/يوم، بيجي 310 ألف، البصرة 210 ألف.
• الغاز: 3744 مليار م³ (الخامس عربياً 6%، العاشر عالمياً 1.9%).
• الكبريت: احتياطي 600 مليون طن، إنتاج مليون طن/سنة.
• الفوسفات: احتياطي أكثر من 10 مليار طن، إنتاج مليونا طن/سنة.

النقل: أول قطار في العراق 1914. بعد المعقل عن الخليج 135 كم. ساحل العراق البحري 60 كم. المطارات الدولية 6: بغداد والموصل والبصرة وأربيل والسليمانية والنجف.

مقارنات سريعة:
• المحاصيل: غذائية (حبوب وخضروات وفواكه ونخيل)، صناعية (قطن وتبغ وبنجر)، علف (جت وبرسيم).
• النقل: برية (سيارات وسكك) وجوية ومائية (نهري وبحري).
• التجارة: داخلية وخارجية.
• السياحة: بيئية وأثرية ودينية.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أجوبة أسئلة الفراغات (من الكتاب):
• زهرة الشمس تزرع في بغداد وبابل. أولى المحافظات بالشعير: نينوى ثم القادسية.
• أسباب نجاح الزراعة: التربة الخصبة والمناخ الملائم والموارد المائية (والأيدي العاملة والأراضي الصالحة).
• القمح والشعير في المنطقتين المطرية (الديمية) والإروائية.
• يتحدد نمو السكان بالولادات والوفيات والهجرة.
• أولى المحافظات بالقمح: نينوى ثم ديالى. وبالرز: النجف.
• موانئ شط العرب: أبو فلوس والمعقل. موانئ الخليج: الفاو وخور الزبير وأم قصر.
• النقل النهري: دجلة والفرات وشط العرب.
• المطارات: بغداد والموصل والبصرة وأربيل والسليمانية والنجف.
• الفوسفات في عكاشات. صناعة الزجاج في الأنبار وتجميع السيارات في بابل.
• الكبريت جنوب الموصل في المشراق والفتحة.
• بوابة عشتار في بابل وزقورة أور في ذي قار.

صح أم خطأ (مع التصحيح):
• الاقتصاد العراقي أحادي الجانب يعتمد على التجارة: خطأ، يعتمد على سلعة واحدة هي النفط الخام.
• تباين التوزيع أدى إلى تفاوت الاستهلاك والقوة الشرائية: صح.
• النقل النهري الأطول والأوسع انتشاراً: خطأ، الطرق البرية هي الأوسع انتشاراً وطولاً.
• احتياطي الغاز 3170 مليون م³: خطأ، 3744 مليار م³ (الخامس عربياً).
• من استعمالات الفوسفات تحضير حامض الكبريتيك: خطأ، يحضر منه الفسفور وحامض الفسفوريك (والكبريت لحامض الكبريتيك).
• احتياطي النفط 48 مليار برميل: خطأ، 147 مليار برميل (الخامس عالمياً).
• مدينة الحضر في سامراء: خطأ، في محافظة نينوى.
• السياحة البيئية ترتبط بالأماكن الدينية: خطأ، ترتبط بالأماكن الطبيعية.

أسئلة للمراجعة:
1) اشرح دور العوامل الطبيعية والاقتصادية والإدارية والدينية والتاريخية في توزيع السكان.
2) ما أهمية التركيب العمري والنوعي؟
3) كيف نحسب الكثافة العامة؟ وكم بلغت في العراق؟
4) عدد أسباب تدني إنتاج النخيل ومشكلات الزراعة.
5) عدد المطارات الدولية وعوامل التجارة الداخلية وخصائص التجارة الخارجية.
6) عدد طرق نقل النفط العراقي.
7) عدد الصناعات الكيمياوية وأماكنها.
8) عدد أهمية السياحة والاصطياف والمواقع الأثرية والبيئية.
9) ارسم خريطة العراق وحدد السكك الحديد وحقول النفط والمواقع السياحية.
10) ما الفرق بين الهجرة الداخلية والخارجية؟ وما أسبابها؟'''),
  ]),
];

const List<Chapter> socialCivics = [
  Chapter('الفصل الأول: القيم الوطنية والاجتماعية', [
    Section('الملخص', Icons.notes, '''مفهوم القيم:
• القيم: مجموعة من المعايير والمبادئ والتعاليم والضوابط الأخلاقية التي توجه سلوك الفرد وترسم له الطريق السليم الذي يجنبه الوقوع في الخطأ أو فعل ما يتنافى مع مبادئه وأخلاقه.
• أهدافها: تقوية الروابط الاجتماعية، ترسيخ العدالة الاجتماعية، تحقيق الاستقرار، تعزيز المساواة، إشاعة السلم بين أبناء المجتمع بغض النظر عن الجنس والدين والقومية واللغة والعرق.
• أنواعها: القيم الوطنية والاجتماعية والدينية والسياسية وغيرها.

أولاً: القيم الوطنية
• مجموعة من المبادئ والضوابط التي تحدد سلوك المواطن في المجتمع الذي ينتمي إليه، وتتمثل في: المواطنة الصالحة، حب الوطن، الإخلاص، الانتماء، الولاء، التضحية في سبيله، والالتزام بالقواعد والقوانين.

1) المواطنة: كلمة مشتقة من الوطن، تعبر عن المكان الذي يعيش فيه الإنسان، وتتحدد بموجبها الحقوق والواجبات. وبموجبها يحصل المواطنون على امتيازات تضمن حياة كريمة: الحق في التعليم، الحق في العمل، الحق في المشاركة السياسية (الترشح للمناصب، والانتخاب والتصويت)، والتمتع بالحريات الفردية التي يكفلها الدستور كحرية الرأي وحرية المعتقد.

2) الانتماء: حالة يشعر فيها الشخص بانضمامه إلى مجموعة معينة تربطه بها علاقة تنعكس إيجابياً على سلوكه. والانتماء للوطن يقوي علاقة الأفراد بمجتمعهم ووطنهم ويجعل العدو يتخوف من المساس بأمنه. وسائله:
أ) الامتثال للأحكام والقواعد العامة والحفاظ على الممتلكات العامة ونظافة المرافق والأماكن العامة والشوارع، والمشاركة في الأعمال التطوعية والخيرية.
ب) اعتماد الحوار الواعي عند الخلافات والابتعاد عن العنف وسيلة لحل المشكلات، وعدم التعاون مع الأعداء للإضرار بمصلحة الوطن، والالتزام بالقوانين وعدم سرقة الأموال العامة.
جـ) الانتماء يزيد الترابط وحب الوطن والسعي لنهضته، ويحقق للإنسان الاستقرار والراحة واحترام الآخرين.

3) المشاركة السياسية: إعطاء الحق الديمقراطي والدستوري لأفراد المجتمع البالغين كافة في المشاركة في صنع القرار السياسي، بطريقة مباشرة (الترشح للانتخابات أو الانضمام لمؤسسة من مؤسسات المجتمع المدني أو تولي المناصب التنفيذية والتشريعية) أو غير مباشرة (الإدلاء بأصواتهم لأحد المرشحين).

4) العمل التطوعي: أن يخصص الإنسان جزءاً من وقته للقيام بعمل عام برغبة ذاتية ومن دون مقابل لأهداف إنسانية أو اجتماعية. فوائده: إشاعة التعاون وتقوية المحبة والألفة، تطوير شخصية الفرد وزيادة ثقته بنفسه، واستثمار الوقت فيما هو مفيد. مجالاته: الاجتماعي (الأعمال الخيرية)، التربوي (حملات محو الأمية والدروس التوعوية)، والبيئي (حملات تنظيف الأحياء والشوارع والحدائق).

ثانياً: القيم الاجتماعية
• مجموعة من المبادئ المكتسبة التي تحدد تعامل الفرد مع غيره، القائمة على الأخلاق الحميدة والاحترام والإنسانية والتسامح والصدق والتكافل الاجتماعي بغض النظر عن الدين والمذهب والعرق والجنس واللون.

العلاقات الاجتماعية: الروابط القائمة بين الأفراد أو عامة المجتمع، وتنقسم إلى:
• رسمية: مثل علاقة التلميذ بإدارة المدرسة وعلاقة الموظف بدائرته.
• غير رسمية: مثل علاقة الإنسان بعائلته وجيرانه وأقاربه.
• وقد تكون إيجابية (ود ومحبة وتكاتف وتعاون) أو سلبية (كره وحسد وخصومات وعداوة).

أنواع العلاقات الاجتماعية:
1) العلاقات الأسرية: روابط بين أفراد تربطهم صلات عائلية (الوالدان وأبناؤهما). صفاتها: الود والمحبة والتعاطف والتماسك والتآزر والتعاون والتضحية. لا تخلو من خلافات تُحل بالتفاهم والتعاون، لأن استمرارها يؤدي إلى تفكك الأسرة وهو يضر بأمن الفرد والمجتمع. وتُحمى باحترام الأبناء لآبائهم وعطف الآباء على أبنائهم.
2) العلاقة مع الجيران: حاجة لا يمكن الاستغناء عنها للتعاون في مواجهة صعوبات الحياة. تُدام بالمحبة والتسامح والابتعاد عن الخلافات والتغاضي عن العيوب وكسب الاحترام والثقة. وعلاقات الجيرة في المجتمع العراقي صادقة قائمة على المحبة والتآزر والتعاون وبعيدة عن التعصب للدين أو المذهب أو العشيرة أو القومية.
3) العلاقة بين الأصدقاء: روابط بين أفراد متقاربين في السن أو المستوى الدراسي أو الاهتمامات. أسسها: الهوايات المشتركة وتشابه السلوك الاجتماعي والألفة والتعاطف وكيفية قضاء وقت الفراغ. وهي من أكثر العلاقات تأثيراً في حياة الفرد، ولذلك يحرص الأهل على متابعة أصدقاء أبنائهم لحمايتهم من أخطاء الأصدقاء السيئين.
4) العلاقة بين أفراد المجتمع: صلات تنظمها القوانين والعادات. الإنسان كائن اجتماعي يحتاج إلى مجتمعه. تقوم على احترام عادات المجتمع وآدابه العامة وقوانينه.

أسس العلاقات الاجتماعية:
1) الاحترام المتبادل: تقبل كل فرد أو جماعة أفكار الآخرين وآراءهم بصرف النظر عن الجنس أو اللون أو النسب (مفتاح نجاح العلاقات). أمثلته: احترام المعتقدات الدينية، احترام المناسبات القومية والمحلية، احترام حقوق الآخرين.
2) الثقة المتبادلة: شعور متبادل بالإيمان بصدق الآخرين وأمانتهم وإخلاصهم. أهم أسسها: الاحترام وحب الخير والابتعاد عن سوء الظن. وانعدامها يؤدي إلى تفكك العلاقات وغياب الاستقرار.
3) التفاهم واعتماد مبدأ الحوار: لا يخلو مجتمع من خلافات (الأسرة والمدرسة والعمل والمحلة)، والحل الأمثل بالحوار والتفاهم لأن العقل يميز الإنسان. فوائده: تقوية العلاقات، حل الخلافات والمشكلات، الصبر، حسن الإصغاء، الاحترام، الابتعاد عن الغضب، عدم التجاوز على الآخرين.
4) التواصل الاجتماعي: حاجة الإنسان لأخيه الإنسان في الأفراح والأحزان. أمثلته: زيارة المرضى، مساعدة المحتاجين وإعانة الفقراء، زيارة الأقارب، توفير التسهيلات لذوي الاحتياجات الخاصة. فوائده: تقوية العلاقات الاجتماعية، شعور الأفراد بالأمن، زيادة التعاون، استمرار الألفة والمحبة.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• القيم: مجموعة من المعايير والمبادئ والضوابط الأخلاقية التي توجه سلوك الفرد.
• القيم الوطنية: مبادئ وضوابط تحدد سلوك المواطن في مجتمعه (المواطنة الصالحة وحب الوطن والإخلاص والانتماء والولاء).
• المواطنة: صفة يتميز بها الأفراد الذين يعيشون على أرض دولة ما، وبموجبها تتحدد حقوقهم وواجباتهم.
• الانتماء: حالة شعور الشخص بانضمامه إلى مجموعة تربطه بها علاقة إيجابية تنعكس على سلوكه.
• المشاركة السياسية: إعطاء أفراد المجتمع البالغين الحق في المشاركة في صنع القرار السياسي.
• العمل التطوعي: تخصيص الإنسان جزءاً من وقته لعمل عام برغبة ذاتية ومن دون مقابل لأهداف إنسانية أو اجتماعية.
• القيم الاجتماعية: مبادئ مكتسبة تحدد تعامل الفرد مع غيره (الأخلاق والاحترام والتسامح والصدق والتكافل).
• العلاقات الاجتماعية: الروابط الاجتماعية القائمة بين الأفراد أو عامة المجتمع.
• العلاقة الأسرية: روابط تربط الأفراد ذوي الصلات العائلية (الوالدان وأبناؤهما).
• العلاقة بين الأصدقاء: روابط اجتماعية تربط الفرد بغيره المتقاربين معه في السن أو المستوى أو الاهتمامات.
• الاحترام المتبادل: تعامل الناس بطريقة حسنة وتقبل كل فرد أو جماعة أفكار الآخرين.
• الثقة المتبادلة: شعور متبادل بالإيمان بصدق الآخرين وأمانتهم وإخلاصهم.

التعاليل:
• يجب حماية العلاقة الأسرية من الخلافات المستمرة: لأن استمرارها يؤدي إلى تفكك الأسرة وهو يضر بأمن الفرد والمجتمع.
• لا يمكن الاستغناء عن العلاقة مع الجيران: للتعاون في مواجهة صعوبات الحياة ومساعدة الآخرين.
• يحرص الأهل على متابعة أصدقاء أبنائهم: لحمايتهم من الأخطاء والمشكلات التي قد يسببها الأصدقاء السيئون، فالأصدقاء أكثر العلاقات تأثيراً.
• الانتماء للوطن مهم: لأنه يقوي علاقة الأفراد بمجتمعهم ووطنهم ويجعل العدو يتخوف من المساس بأمنه.
• تسعى المجتمعات إلى زرع الثقة المتبادلة: لتحقيق الأمن والاستقرار وتقدم المجتمع ورفاهية أفراده.
• الحوار هو الحل الأمثل للخلافات: لأن العقل هو الذي يميز الإنسان فبه نتبادل الآراء ونتصرف تصرفاً سليماً.
• لا يستطيع الإنسان الاستغناء عن أخيه الإنسان: لحاجته إلى مساعدة الآخرين في جميع مجالات الحياة، وخاصة في الأفراح والأحزان.
• بناء علاقة أسرية سليمة وناجحة يعني بناء مجتمع واع وطموح.'''),
    Section('مقارنات وأسس', Icons.calculate, '''مقارنات للحفظ:
• العلاقات الرسمية: التلميذ مع إدارة المدرسة، الموظف مع دائرته. غير الرسمية: العائلة والجيران والأقارب.
• العلاقات الإيجابية: ود ومحبة وتكاتف وتعاون. السلبية: كره وحسد وخصومات وعداوة.
• المشاركة السياسية المباشرة: الترشح، الانضمام لمؤسسة مجتمع مدني، تولي منصب. غير المباشرة: الإدلاء بالصوت لمرشح.
• مجالات العمل التطوعي: اجتماعي (خيري)، تربوي (محو الأمية)، بيئي (تنظيف الأحياء).

أنواع العلاقات الاجتماعية الأربعة: أسرية، جيران، أصدقاء، أفراد المجتمع.
أسس العلاقات الاجتماعية الأربعة: احترام متبادل، ثقة متبادلة، تفاهم وحوار، تواصل اجتماعي.

صفات العلاقة الأسرية: الود والمحبة والتعاطف والتماسك والتآزر والتعاون والتضحية.
أسس الصداقة: الهوايات المشتركة، تشابه السلوك الاجتماعي، الألفة والتعاطف، قضاء وقت الفراغ.
فوائد الحوار: تقوية العلاقات، حل الخلافات، الصبر، الاحترام، حسن الإصغاء، الابتعاد عن الغضب، عدم التجاوز على الآخرين.
فوائد التواصل: تقوية العلاقات، شعور بالأمن، زيادة التعاون، استمرار الألفة والمحبة.
وسائل تجسيد الانتماء: الامتثال للقواعد، الحوار بدل العنف، الأعمال التطوعية، الحفاظ على الممتلكات العامة.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة للمراجعة:
1) عرّف: القيم الوطنية، المواطنة، الانتماء، المشاركة السياسية.
2) املأ الفراغات:
• تقسم العلاقات الاجتماعية إلى علاقات رسمية وغير رسمية.
• للحوار والتفاهم فوائد أهمها: تقوية العلاقات وحل الخلافات.
• من امتيازات المواطنة: الحق في التعليم والحق في العمل والحق في المشاركة السياسية.
3) علل:
• تسعى كثير من المجتمعات إلى زرع الثقة المتبادلة بين أفرادها.
• يجب حماية العلاقة الأسرية من الخلافات المستمرة.
• يحرص الأهل على متابعة أصدقاء أبنائهم.
4) هنالك طرق عديدة تجسد الانتماء إلى الوطن، عددها معززاً إجابتك بالأمثلة.
5) ما المقصود بالعلاقات الاجتماعية وما أنواعها؟ وضح بالأمثلة.
6) ما المقصود بالثقة المتبادلة؟ وضح بالأمثلة.
7) للتواصل الاجتماعي فوائد عديدة، عددها.
8) عدد أسس العلاقات الاجتماعية.
9) ما المقصود بالعمل التطوعي؟ وما مجالاته؟
10) ماذا نعني بالاحترام المتبادل؟ أعط أمثلة.'''),
  ]),
  Chapter('الفصل الثاني: قضايا اجتماعية عامة', [
    Section('الملخص', Icons.notes, '''أولاً: طلب العلم والمعرفة
• العلم ضرورة لا يمكن الاستغناء عنها في أي مجتمع. به اخترع الإنسان الكهرباء والسيارات والقطارات والطائرات والحاسوب، ووصل إلى الفضاء، واكتشف خيرات الطبيعة، وقضى على كثير من الأمراض.
• سعت جميع الأمم إلى الاهتمام بالعلم لأنه أساس بناء كل مجتمع ووسيلة لرفاهية الإنسان وبه ترتقي الأمم سلم النجاح والتفوق. وبه نعرف حقوقنا وواجباتنا وحقوق الآخرين وواجباتهم ونتغلب على المشكلات.

ثانياً: المواطن بين الحقوق والواجبات
• الفرد هو اللبنة الأساسية في المجتمع، فالعلاقة بينه وبين المجتمع متبادلة: يتمتع بالحقوق ويؤدي الواجبات. بقدر التزامه بواجباته يضمن حقوقه. الحقوق ترفع من قدر الفرد وحريته، والواجبات تعبر عن احترامه لحريته وحرية الآخرين.

1) حقوق الإنسان: مجموعة من المبادئ الأخلاقية أو المعايير الاجتماعية التي تصف السلوك البشري وتترجم إلى حقوق أساسية لا يجوز المس بها، مستحقة وأصيلة لكل شخص لمجرد كونه إنساناً بصرف النظر عن هويته أو مكان وجوده أو لغته أو ديانته أو أصله العرقي. وهي متطورة ومتنوعة.
أنواعها:
أ) من حيث الأهمية:
• أساسية: ضرورية لاستمرار حياة الإنسان، لا يمكن المس بها أو مخالفتها، وتأمينها شرط لتحقق بقية الحقوق (حق الحرية والحياة والمساواة وحرية التعبير والرأي).
• غير أساسية: مرتبطة برفاهية الإنسان وسعادته وتؤمن له عيشاً أفضل (حرية التملك وحرية إنشاء الجمعيات والانتماء السياسي).
ب) من حيث المستفيدين:
• فردية: يتمتع بها الفرد وتسعى الدولة لتوفيرها (حق الحياة وعدم التعرض للتعذيب، الحق في الفكر، التعليم، العمل، الانتماء).
• جماعية: تخص المجتمع أو مجموعة من الأفراد ولا تخص فرداً بعينه (الخدمات العامة).
جـ) من حيث موضوعها:
• الحقوق المدنية والسياسية (مرتبطة بالحريات): حق الدين والعقيدة، الحق في الحياة والأمان والحرية الفكرية وعدم التعرض للتعنيف، المشاركة السياسية، حرية الرأي والتعبير، حرية الاشتراك في منظمات المجتمع المدني، العيش بكرامة، التنقل والسفر، العدل والمساواة، التعليم، الدفاع عن النفس.
• الحقوق الاقتصادية والاجتماعية (مرتبطة بالأمن): العمل واختيار نوعه، العيش بحياة كريمة، المسكن واختيار مكانه، الرعاية الصحية والاجتماعية، الملكية، الزواج وتكوين أسرة.
• الحقوق البيئية والتنموية (مرتبطة بالبيئة): العيش في بيئة نظيفة، التنمية الثقافية والسياسية والاقتصادية، العيش في بيئة خالية من الفساد.

2) الواجبات: كل ما يتعين على الإنسان فعله في شؤونه الخاصة أو تجاه وطنه. تقسم بحسب طبيعة العلاقة إلى ثلاثة:
• علاقة الإنسان مع الآخر: احترام الجار والرأي الآخر وكرامة الإنسان وأداء الحقوق لأصحابها (الدين والميراث والوصية) في الأسرة والمجتمع.
• علاقة الإنسان في محيط عمله: الطالب في مدرسته، المعلم، العامل (إتقان عمله)، الجندي في معسكره، الطبيب في مشفاه.
• علاقته مواطناً تجاه وطنه: الحفاظ عليه والدفاع عنه والالتزام بالأنظمة والقوانين واحترامها والمحافظة على الممتلكات العامة.

توعية: ابتعد عن المناطق التي تغطيها الأحراش والنباتات والقواعد العسكرية السابقة لاحتوائها على أسلحة ومتفجرات، وانتبه إلى العلامات التحذيرية للمناطق الملوثة بالألغام (لا تقترب، لا تلمس، احذر، ابتعد، بلّغ).

ثالثاً: البيئة والتلوث البيئي
• تلوث البيئة من أبرز التحديات نتيجة التطور الصناعي الهائل وما يرافقه من ملوثات (غازية أو سائلة أو صلبة).
• البيئة: المكان الذي تعيش فيه الكائنات الحية إضافة إلى العناصر والمكونات غير الحية (الماء والهواء والتربة والمعادن) والتأثير المتبادل بينها لضمان استمرار الحياة.
سبل المحافظة على البيئة:
1) استعمال مصادر الطاقة النظيفة والمتجددة (الكهربائية والرياح والشمسية) بديلاً للطاقة الملوثة (الفحم والنفط).
2) سن القوانين والأنظمة التي تحد من التلوث.
3) تشجيع الرياضة (المشي وركوب الدراجات) والتقليل من استعمال السيارات.
4) نشر الوعي عبر وسائل الإعلام.
5) إبعاد المؤسسات التعليمية والمستشفيات عن مصادر التلوث الضوضائي (الشوارع العامة ووسائط النقل والمناطق الصناعية).
6) معالجة مياه الصرف الصناعي والصحي قبل طرحها في المصادر المائية.
7) المحافظة على الغطاء النباتي والحد من انجراف التربة بزراعة المساحات الخضراء والأشجار ومنع قطعها.
8) إلزام المصانع بوضع مرشحات للغازات والملوثات.
• التلوث الضوضائي (السمعي أو الضجيجي): التعرض المستمر لأصوات عالية غير مرغوبة، يرتبط بالمناطق الصناعية ويسبب أضراراً صحية.

رابعاً: التنمية المستدامة
• موارد العراق الطبيعية وثرواته حق مشروع لجميع أبناء الوطن وليست مقتصرة على فئة، ولذلك ينبغي المحافظة عليها والانتفاع بها بشكل منظم بما يضمن حقوق الأجيال القادمة.
كيفية المحافظة على الموارد الطبيعية:
1) ترشيد استعمال الموارد الطبيعية والبشرية (الماء والتربة والثروات الاقتصادية) وصيانتها (منع تلوث الأنهار).
2) المحافظة على ديمومتها بترشيد استهلاكها وعدم الإضرار بها.
3) استعمال تقنية التدوير وإعادة استعمال الموارد القابلة للتدوير بشكل سليم وآمن.

خامساً: النظافة الشخصية والعامة
• النظافة عامل أساسي لكل فرد، مصدر الصحة والسلامة ودليل تقدم المجتمعات، وأكدتها جميع الأديان والحضارات.
1) النظافة الشخصية: العناية بنظافة الجسم والطعام والشراب والملابس والكتب والمظهر العام. قواعدها لتجنب العدوى: غسل اليدين بالماء والصابون بصورة متكررة مدة 20 ثانية على الأقل، نظافة المرافق الصحية، تجنب لمس العينين أو الفم أو الوجه إذا كانت اليد غير نظيفة، استعمال المناديل الورقية عند العطاس، استعمال المطهر عند الخروج من الحمامات والغرف الصفية والممرات وبعد اللعب، تنظيف المدرسة وتطهيرها مرة واحدة يومياً على الأقل (الأسطح التي يلمسها كثيرون: طاولات الطعام والمعدات الرياضية ومقابض الأبواب)، والتخلص من النفايات يومياً في مكان آمن.
2) النظافة العامة: المحافظة على نظافة البيئة التي يعيش فيها الإنسان (المنزل والمدرسة والأماكن العامة وممتلكات المدرسة). فوائد نظافة المدرسة: تزيد التعاون والمحبة بين الطلبة، تحافظ على الصحة العامة، وتوفر بيئة سليمة للنجاح والتفوق.

سادساً: التوعية المرورية
• أن يكون جميع مستعملي الطرق (سائقون، مشاة، راكبو الدراجات) على علم تام بقواعد المرور لسلامة الراكب والمشاة.
• السلامة المرورية: اتباع الإجراءات الوقائية للحد من الحوادث: الفحص الدوري الشامل للمركبات (الصيانة)، اتباع الإرشادات وعلامات السير الصادرة من رجال المرور، والحصول على رخص القيادة.

سابعاً: تأثير التكنولوجيا والإنترنت في المجتمع
• الإنترنت سلاح ذو حدين: يرفع مستوى ثقافة الفرد لكنه عالم مفتوح بلا قيود. سلبياته:
1) ضياع الوقت (الدردشة وتصفح المواقع غير المفيدة والألعاب الإلكترونية).
2) الاختراق والتجسس على خصوصيات الآخرين (يجب الحيطة وإخبار الجهات الرسمية).
3) مشاكل صحية: العيون والعمود الفقري والمفاصل والأعصاب، وزيادة الوزن والسمنة لقلة الحركة.
4) الترويج للأفكار السيئة: تضليل الشباب وتشريع العمليات الإرهابية وتشجيع العلاقات غير الصحيحة.
5) تزوير الحقائق: أسماء مستعارة لتشويه السمعة والتشهير والابتزاز، ونقل أخبار غير صادقة. وللأجهزة الأمنية إجراءات للقبض على مروجي الإشاعات والمبتزين.

ثامناً: المحافظة على الممتلكات العامة
• الممتلكات العامة: جميع الممتلكات العائدة للدولة والمجتمع، وليست ملكاً لأحد بل لجميع المواطنين. المحافظة عليها واجب وطني وديني، لأن جميع الأديان أكدت حرمة الاعتداء عليها أو تخريبها أو سرقتها.
• أمثلتها: المستشفيات العامة، المدارس والمعاهد والجامعات، الشوارع والطرق والجسور، الحدائق والمتنزهات العامة، وأبنية المؤسسات والدوائر وأثاثها وأجهزتها.
• المحافظة عليها صفة المجتمعات المتقدمة ودليل وعي المواطن وأمانته وإخلاصه للوطن.'''),
    Section('التعاريف والتعاليل', Icons.menu_book, '''التعاريف:
• حقوق الإنسان: مجموعة من المبادئ الأخلاقية أو المعايير الاجتماعية تترجم إلى حقوق أساسية لا يجوز المس بها وأصيلة لكل شخص لكونه إنساناً.
• الحقوق الأساسية: حقوق ضرورية لاستمرار حياة الإنسان (الحرية والحياة والمساواة وحرية التعبير).
• الحقوق الفردية: حقوق يتمتع بها الفرد وتسعى الدولة لتوفيرها. الجماعية: تخص المجتمع أو مجموعة أفراد.
• الواجبات: كل ما يتعين على الإنسان فعله في شؤونه الخاصة أو تجاه وطنه.
• البيئة: المكان الذي تعيش فيه الكائنات الحية مع العناصر غير الحية (الماء والهواء والتربة).
• التلوث الضوضائي: التعرض المستمر لأصوات عالية غير مرغوبة.
• التنمية المستدامة: الانتفاع المنظم بموارد الوطن بما يضمن حقوق الأجيال القادمة.
• التوعية المرورية: أن يكون جميع مستعملي الطرق على علم تام بقواعد المرور.
• السلامة المرورية: اتباع الإجراءات الوقائية للحد من الحوادث المرورية.
• الممتلكات العامة: جميع الممتلكات العائدة للدولة والمجتمع.
• تقنية التدوير: إعادة استعمال الموارد القابلة للتدوير بشكل سليم وآمن.

التعاليل:
• أكدت جميع الأديان حرمة الاعتداء على الممتلكات العامة: لأنها وجدت لخدمة جميع الناس.
• لا يمكن للإنسان أن يعيش حياة سليمة من دون النظافة: لأنها مصدر صحته وسلامته ودليل تقدم المجتمعات.
• ينبغي الاهتمام بطلب العلم: لأنه طريق النجاح وبه نعرف حقوقنا وواجباتنا ونتغلب على المشكلات.
• سعت المجتمعات إلى الاهتمام بالعلم: لأنه أساس بناء كل مجتمع ووسيلة للرفاهية.
• يعد الإنترنت سلاحاً ذا حدين: لأنه يرفع مستوى الثقافة لكن فيه سلبيات كثيرة وهو عالم مفتوح بلا قيود.
• تعد المحافظة على الممتلكات العامة واجباً وطنياً ودينياً: لأنها ملك لجميع المواطنين وهي دليل على وعي المواطن وأمانته.
• تبعد المؤسسات التعليمية والمستشفيات عن مصادر الضوضاء: لحماية الطلبة والمرضى من أضرارها الصحية.
• تعالج مياه الصرف قبل طرحها: لمنع تلوث المصادر المائية.
• يلزم وضع مرشحات في المصانع: للحد من الغازات والملوثات المنبعثة.
• يعد غسل اليدين 20 ثانية مهماً: لتجنب العدوى والأمراض.
• يجب الابتعاد عن مناطق الأحراش والقواعد العسكرية السابقة: لاحتوائها على أسلحة ومواد متفجرة وألغام.'''),
    Section('قوائم للحفظ', Icons.calculate, '''أنواع حقوق الإنسان:
• من حيث الأهمية: أساسية وغير أساسية.
• من حيث المستفيدين: فردية وجماعية.
• من حيث الموضوع: مدنية وسياسية، اقتصادية واجتماعية، بيئية وتنموية.

أقسام الواجبات (3): علاقة الإنسان مع الآخر، في محيط عمله، مواطناً تجاه وطنه.

سبل المحافظة على البيئة (8): طاقة نظيفة، قوانين، رياضة وتقليل السيارات، توعية إعلامية، إبعاد المدارس والمستشفيات عن الضوضاء، معالجة مياه الصرف، حماية الغطاء النباتي، مرشحات للمصانع.

المحافظة على الموارد الطبيعية (3): الترشيد، ديمومة الموارد، التدوير.

النظافة الشخصية (7 قواعد): غسل اليدين 20 ثانية، المرافق الصحية، عدم لمس الوجه، المناديل الورقية، المطهر، تنظيف المدرسة يومياً، التخلص من النفايات.

فوائد نظافة المدرسة (3): زيادة التعاون والمحبة، الصحة العامة، بيئة النجاح والتفوق.

سلامة المرور (3): فحص المركبات دورياً، اتباع إرشادات وعلامات السير، رخص القيادة.

سلبيات الإنترنت (5): ضياع الوقت، الاختراق والتجسس، مشاكل صحية، الترويج للأفكار السيئة، تزوير الحقائق.

أمثلة الممتلكات العامة: المستشفيات والمدارس والمعاهد والجامعات والشوارع والجسور والحدائق والمتنزهات.

قضايا الفصل الثمانية: العلم، الحقوق والواجبات، البيئة والتلوث، التنمية المستدامة، النظافة، التوعية المرورية، التكنولوجيا والإنترنت، الممتلكات العامة.'''),
    Section('أسئلة مهمة', Icons.assignment, '''أسئلة للمراجعة (من الكتاب):
1) عرّف: البيئة، حقوق الإنسان، القيم الوطنية، المواطنة، الانتماء، المشاركة السياسية، التوعية المرورية.
2) املأ الفراغات:
• للنظافة العامة فوائد: زيادة التعاون والمحبة، الحفاظ على الصحة العامة، توفير بيئة للنجاح.
• تقسم حقوق الإنسان من حيث المستفيدين إلى: فردية وجماعية.
• من امتيازات المواطنة: الحق في التعليم والعمل والمشاركة السياسية.
• تقسم العلاقات الاجتماعية إلى علاقات رسمية وغير رسمية.
• للحوار والتفاهم فوائد: تقوية العلاقات وحل الخلافات.
3) علل:
• أكدت جميع الأديان حرمة الاعتداء على الممتلكات العامة.
• لا يمكن للإنسان أن يعيش حياة سليمة من دون المحافظة على النظافة.
• تسعى المجتمعات إلى زرع الثقة المتبادلة بين أفرادها.
4) عدد أنواع حقوق الإنسان من حيث موضوعها.
5) عدد أقسام واجبات الإنسان بحسب طبيعة العلاقات.
6) عدد أهم السبل للمحافظة على البيئة.
7) عدد أهم النقاط الواجب اتباعها للمحافظة على الموارد الطبيعية.
8) عدد القواعد الواجب اتباعها للمحافظة على النظافة الشخصية لتجنب العدوى.
9) عدد الطرق التي تجسد الانتماء إلى الوطن معززاً بالأمثلة.
10) ما المقصود بالعلاقات الاجتماعية وما أنواعها؟
11) ما المقصود بالثقة المتبادلة؟
12) للتواصل الاجتماعي فوائد عديدة، عددها.
13) يعد الإنترنت سلاحاً ذا حدين، عدد أهم سلبياته.'''),
  ]),
];

