• film test — اختبار تمثيل
• role / part — دور
• actor / actress — ممثل / ممثلة
• wax museum — متحف الشمع
• ringmaster — مقدّم السيرك
• profit — ربح
• loan — قرض
• customers — زبائن
• rescue — ينقذ

أنواع الكتب والأفلام:
• adventure — مغامرات
• comedy — كوميديا
• fiction — قصة خيالية
• horror — رعب
• travel — أدب الرحلات
• factual — وثائقي
• musical — غنائي
