• artificial reed islands — جزر قصب اصطناعية
• mashhoof / tarrada — القارب المشحوف / الطرّادة
• migratory birds — طيور مهاجرة
• flamingo / pelican / heron — فلامنجو / بجع / مالك الحزين
• wetland — أرض رطبة
• at risk — معرّض للخطر
