• mountain — جبل
• desert — صحراء
• volcano — بركان
• crowded — مزدحم
• flat — مسطح (أرض)
• extremely — للغاية

دول وجنسيات:
• country — دولة
• continent — قارة
• capital — عاصمة
• population — عدد السكان
• area — مساحة
