class SocialStudiesPage extends StatelessWidget {
  const SocialStudiesPage({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('الاجتماعيات')),
      body: ListView(
        padding: const EdgeInsets.all(12),
        children: [
          _sectionCard(
            context,
            'التاريخ',
            'العراق في العهد العثماني والحرب العالمية الأولى وما بعدها',
            Icons.history_edu,
            socialHistory,
            const {},
          ),
          _sectionCard(
            context,
            'الجغرافية',
            'الخصائص الطبيعية والبشرية لجغرافية العراق مع الخرائط',
            Icons.public,
            socialGeography,
            geographyFigures,
          ),
          _sectionCard(
            context,
            'التربية الوطنية',
            'القيم الوطنية والاجتماعية وقضايا اجتماعية عامة',
            Icons.flag,
            socialCivics,
            const {},
          ),
        ],
      ),
    );
  }

  Widget _sectionCard(
    BuildContext context,
    String title,
    String subtitle,
    IconData icon,
    List<Chapter> chapters,
    Map<int, List<Figure>> figures,
  ) {
    return Card(
      child: ListTile(
        leading: Icon(icon, color: gold),
        title: Text(title),
        subtitle: Text(subtitle),
        trailing: const Icon(Icons.arrow_forward_ios, size: 14),
        onTap: () {
          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (_) => ChaptersPage(
                title: title,
                subtitle: subtitle,
                icon: icon,
                chapters: chapters,
                figures: figures,
              ),
            ),
          );
        },
      ),
    );
  }
}

class ChaptersPage extends StatelessWidget {
  final String title;
  final String subtitle;
  final IconData icon;
  final List<Chapter> chapters;
  final Map<int, List<Figure>> figures;
  const ChaptersPage({
    super.key,
    required this.title,
    required this.subtitle,
    required this.icon,
    required this.chapters,
    required this.figures,
  });

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(title)),
      body: ListView(
        padding: const EdgeInsets.all(12),
        children: [
          Card(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                children: [
                  Icon(icon, size: 42, color: gold),
                  const SizedBox(height: 10),
                  Text(title,
                      style: const TextStyle(
                          fontSize: 20, fontWeight: FontWeight.bold)),
                  const SizedBox(height: 6),
                  Text(subtitle,
                      textAlign: TextAlign.center,
                      style: const TextStyle(color: Colors.white60)),
                ],
              ),
            ),
          ),
          const SizedBox(height: 8),
          ...chapters.asMap().entries.map((entry) {
            final chapter = entry.value;
            return Card(
              child: ExpansionTile(
                key: PageStorageKey<String>('$title${chapter.title}'),
                leading: CircleAvatar(
                  backgroundColor: gold,
                  foregroundColor: Colors.black,
                  child: Text('${entry.key + 1}'),
                ),
                title: Text(chapter.title,
                    style: const TextStyle(fontWeight: FontWeight.w600)),
                children: [
                  ...chapter.sections.map((section) {
                    return ListTile(
                      leading: Icon(section.icon, color: gold),
                      title: Text(section.title),
                      trailing:
                          const Icon(Icons.arrow_forward_ios, size: 14),
                      onTap: () {
                        Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder: (_) => ContentPage(
                              chapter: chapter.title,
                              section: section,
                            ),
                          ),
                        );
                      },
                    );
                  }),
                  if (figures.containsKey(entry.key))
                    ListTile(
                      leading:
                          const Icon(Icons.image_outlined, color: gold),
                      title: const Text('الخرائط والرسومات المهمة'),
                      subtitle: Text('${figures[entry.key]!.length} خريطة ورسم'),
                      trailing:
                          const Icon(Icons.arrow_forward_ios, size: 14),
                      onTap: () {
                        Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder: (_) => FiguresPage(
                              chapter: chapter.title,
                              figures: figures[entry.key]!,
                            ),
                          ),
                        );
                      },
                    ),
                ],
              ),
            );
          }),
        ],
      ),
    );
  }
}

class FiguresPage extends StatelessWidget {
  final String chapter;
  final List<Figure> figures;
  const FiguresPage({super.key, required this.chapter, required this.figures});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('الرسومات المهمة')),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          Text(chapter,
              style: const TextStyle(
                  color: gold, fontSize: 16, fontWeight: FontWeight.bold)),
          const SizedBox(height: 8),
          const Text('اضغط على الرسم لتكبيره.',
              style: TextStyle(color: Colors.white54)),
          const SizedBox(height: 12),
          ...figures.map((f) {
            return Card(
              child: Padding(
                padding: const EdgeInsets.all(12),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(f.caption,
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                            fontSize: 16, fontWeight: FontWeight.bold)),
                    const SizedBox(height: 10),
                    GestureDetector(
                      onTap: () {
                        Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder: (_) => FullImagePage(figure: f),
                          ),
                        );
                      },
                      child: Container(
                        color: Colors.white,
                        child: FigureImage(figureKey: f.key),
                      ),
                    ),
                  ],
                ),
              ),
            );
          }),
        ],
      ),
    );
  }
}

class FigureImage extends StatelessWidget {
  final String figureKey;
  const FigureImage({super.key, required this.figureKey});

  @override
  Widget build(BuildContext context) {
    final data = allFigureData[figureKey];
    if (data == null) {
      return const SizedBox(
        height: 80,
        child: Center(
          child: Text('الرسم غير متوفر',
              style: TextStyle(color: Colors.black54)),
        ),
      );
    }
    return Image.memory(
      base64Decode(data),
      fit: BoxFit.contain,
      gaplessPlayback: true,
    );
  }
}

class FullImagePage extends StatelessWidget {
  final Figure figure;
  const FullImagePage({super.key, required this.figure});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(figure.caption, style: const TextStyle(fontSize: 15))),
      body: Container(
        color: Colors.white,
        child: Center(
          child: InteractiveViewer(
            minScale: 1,
            maxScale: 5,
            child: FigureImage(figureKey: figure.key),
          ),
        ),
      ),
    );
  }
}
